/// The source-table shape whose whole command is one Vulnerable application.
/// Fused/dynamic writers deliberately do not satisfy this predicate: they
/// retain command-local cursors or suffixes that this continuation does not
/// carry and must therefore fail the enclosing transaction if Vicious parks.
pub(crate) fn cardplay_plain_vulnerable_source_step_is_exact(
    row: &crate::content_tables::CardRow,
    index: usize,
) -> bool {
    row.steps.get(index).is_some_and(|step| {
        step.kind == StepKind::Vulnerable && matches!(step.args, [crate::content_tables::Arg::I(_)])
    })
}

/// Current exact card-program census whose body can publish a positive
/// player-applied monster Vulnerable change observed by Vicious. The boolean
/// result is source-derived; only the plain command above is resumable.
#[cfg(test)]
pub(crate) fn cardplay_vicious_vulnerable_producer_is_reachable(
    spec: &CardSpec,
    catalog: &Catalog,
) -> bool {
    spec.row.steps.iter().enumerate().any(|(index, step)| {
        cardplay_plain_vulnerable_source_step_is_exact(spec.row, index)
            || matches!(
                step.kind,
                StepKind::VulnerableThenStrengthCurrent
                    | StepKind::MoltenVuln
                    | StepKind::ThunderclapExact
                    | StepKind::ShockwaveExact
                    | StepKind::MiseryExact
            )
            || step.kind == StepKind::OstyBody
                && catalog.steps(spec).get(index).is_some_and(|compiled| {
                    catalog.args(compiled.args).iter().any(|arg| {
                        matches!(arg, CompiledArg::Word(crate::ids::StepWord::AoeVulnerable))
                    })
                })
    })
}

/// Resolve the live target shape of one mutable owned physical card.
///
/// Current v0.111.0 ARM64 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
/// `SovereignBlade::get_TargetType` RVA `0xebed7` returns `AllEnemies`
/// exactly while `HasSeekingEdge` RVA `0xec17e` observes a live positive
/// owner `SeekingEdgePower`; otherwise it returns `AnyEnemy`. Every action
/// producer and consumer uses this seam so legal actions, manual/direct
/// AutoPlay validation, Targets RNG, frozen identity capture, and the body
/// cannot silently disagree. `Shiv::get_TargetType` RVA `0xeb013` likewise
/// returns `AllEnemies` exactly while its live mutable owner has the unique
/// `FanOfKnivesPower`; `get_HasFanOfKnives` RVA `0xeb167` refuses to infer
/// ownership from a detached immutable card.
///
/// Branch on the card identity before touching the sparse power vector. The
/// ordinary path remains exactly the precompiled catalog predicate.
#[cold]
#[inline(never)]
pub(crate) fn effective_target_type(
    state: &HotState,
    catalog: &Catalog,
    spec: &CardSpec,
    source_uid: u32,
) -> Result<CardTargetType, EngineRefusal> {
    if !matches!(spec.identity.id, CardId::Shiv | CardId::SovereignBlade) {
        return Ok(spec.target_type);
    }
    if matches!(spec.identity.id, CardId::SovereignBlade) {
        if !crate::steps::regent_forge::sovereign_blade_program_is_exact(spec.row)
            || spec.target_type != CardTargetType::Dynamic
            || !spec.targeted
        {
            return Err(EngineRefusal::MalformedArgs(
                "Sovereign Blade dynamic target",
            ));
        }
        return match state.powers.get(PowerId::SeekingEdge) {
            None => Ok(CardTargetType::AnyEnemy),
            Some(slot) if slot.wire == SlotWire::Int && slot.value == 1 => {
                Ok(CardTargetType::AllEnemies)
            }
            Some(_) => Err(EngineRefusal::MalformedArgs("Seeking Edge power state")),
        };
    }
    let (pile, index) = unique_live_card_location(state, source_uid)?.ok_or(
        EngineRefusal::ActiveCardNotUnique {
            uid: source_uid,
            matches: 0,
        },
    )?;
    let source = state.piles.get(pile).as_slice()[index];
    if source.flags & CARD_FLAG_LEGACY != 0 || catalog.spec(source.atom) != Some(spec) {
        return Err(EngineRefusal::MalformedArgs("dynamic target source"));
    }
    if !crate::steps::silent_special::shiv_program_is_exact(spec.row)
        || spec.target_type != CardTargetType::Dynamic
        || !spec.targeted
        || !spec.is_attack
        || !spec.row.exhausts
        || !spec.playable
    {
        return Err(EngineRefusal::MalformedArgs("Shiv dynamic target"));
    }
    match state.powers.get(PowerId::FanOfKnives) {
        None => Ok(CardTargetType::AnyEnemy),
        Some(slot) if slot.wire == SlotWire::Int && slot.value == 1 => {
            Ok(CardTargetType::AllEnemies)
        }
        Some(_) => Err(EngineRefusal::MalformedArgs("Fan of Knives power state")),
    }
}

/// The only immutable enchanted card identity admitted by the R38 slice.
/// Inky is non-stackable in the shipped build, and both canonical Shiv rows
/// share the exact dynamic-target body authenticated by `shiv_program_is_exact`.
pub(crate) fn inky_shiv_identity_is_exact(spec: &CardSpec) -> bool {
    matches!(
        (
            spec.identity.id,
            spec.identity.upgrade,
            spec.identity.enchantment
        ),
        (
            CardId::Shiv,
            0 | 1,
            Some(crate::catalog::CardEnchantment {
                id: EnchantmentId::Inky,
                amount: 1
            })
        )
    ) && crate::steps::silent_special::shiv_program_is_exact(spec.row)
        && crate::content_tables::card_row(spec.identity.id, spec.identity.upgrade)
            == Some(spec.row)
}

/// The replay-changing enchantments admitted by R40.
///
/// **Glam on a Power (#3135).** v0.111.0 `sts2.dll` (sha256 `9cb4f1ad…`),
/// re-read for this arm. `Glam` has no card-type test anywhere in its method
/// set: `EnchantPlayCount` `0xd5f94` returns `playCount` when
/// `UsedThisCombat` (IL_0001-000a), else `playCount + DynamicVars["Times"]
/// .IntValue` (IL_000b-0022); `AfterCardPlayed` `0xd5fb7` returns when already
/// used (IL_0001-000e) or when `cardPlay.Card != this.Card` (IL_000f-0022),
/// then writes `UsedThisCombat = true` (IL_0023-002a) and `Status = 1`
/// (IL_002b-002c). Glam declares no `CanEnchant`/`CanEnchantCardType`, so the
/// base `EnchantmentModel::CanEnchant` `0x7f40c` governs: it refuses only
/// `Type - 4 <= 2` (IL_0013-0022: Status 4, Curse 5, Quest 6; `CardType`
/// constants `Power = 3`), so Power is a native Glam carrier.
///
/// The CardPlay loop is type-agnostic apart from presentation.
/// `CardModel/<OnPlayWrapper>d__339::MoveNext` `0x31b8d0` freezes the result
/// location (`GetResultLocationForCardPlay` IL_0259, `ModifyCardPlayResultLocation`
/// IL_027f) and then the play count (`GeneratePlayCount` IL_034a, stored in
/// `<playCount>5__4` at IL_03ac) before body 0, so Glam's spend after body 0
/// cannot shrink the running series. `<GeneratePlayCount>d__340` `0x31b5e0`
/// is `GetEnchantedReplayCount() + 1` (IL_001f-0026), and
/// `CardModel::GetEnchantedReplayCount` `0x7ca38` is
/// `Enchantment.EnchantPlayCount(BaseReplayCount)` (IL_0012-001d). The only
/// card-type test inside the body loop (IL_041c-0909) is IL_0443-044a
/// (`Type == 3`), which gates `PlayPowerCardFlyVfx` IL_044d through IL_04aa:
/// presentation only. After the loop a Power resolves through
/// `GetResultLocationForCardPlay` `0x7e018` IL_0014-002a to
/// `CardLocation(owner, None, Bottom)`, i.e. `RemoveFromCombat` (IL_0ba9) —
/// the existing [`CardResultRoute::RemoveBottom`]. The corpus's Glam Powers
/// (Stone Armor `<OnPlay>d__5` `0x3bf43c` IL_0050 `Apply<PlatingPower>`,
/// Monarch's Gaze `<OnPlay>d__6` `0x3add38` IL_00d1, Void Form
/// `<OnPlay>d__5` `0x3c69e8` IL_00d1 then `PlayerCmd.EndTurn` IL_0131,
/// Spectrum Shift `<OnPlay>d__3` `0x3bd9ac` IL_00cc) read no play index or
/// count; every admitted Power body already executes serial replays under
/// BaseReplayCount and Signal Boost, which Glam's count feeds identically.
///
/// The Status member of the Glam arm is native over-admission (Status can
/// never carry Glam per `CanEnchant` above) and is deliberately left as is:
/// tightening it is a separate behaviour change.
pub(crate) fn replay_enchantment_identity_is_exact(spec: &CardSpec) -> bool {
    let Some(enchantment) = spec.identity.enchantment else {
        return false;
    };
    match enchantment.id {
        EnchantmentId::Glam => {
            enchantment.amount > 0
                && !spec.native_unplayable
                && matches!(
                    spec.card_type,
                    crate::content_tables::CardType::Attack
                        | crate::content_tables::CardType::Skill
                        | crate::content_tables::CardType::Power
                        | crate::content_tables::CardType::Status
                )
        }
        EnchantmentId::Spiral => {
            enchantment.amount >= 0
                && matches!(
                    spec.identity.id,
                    CardId::StrikeDefect
                        | CardId::StrikeIronclad
                        | CardId::StrikeNecrobinder
                        | CardId::StrikeRegent
                        | CardId::StrikeSilent
                        | CardId::DefendDefect
                        | CardId::DefendIronclad
                        | CardId::DefendNecrobinder
                        | CardId::DefendRegent
                        | CardId::DefendSilent
                )
        }
        _ => false,
    }
}

/// Static enchantments whose current Rust primitive fold is identical to the
/// native base body plus one authenticated per-body additive.
pub(crate) fn static_body_enchantment_identity_is_exact(spec: &CardSpec) -> bool {
    let Some(enchantment) = spec.identity.enchantment else {
        return false;
    };
    enchantment.amount > 0
        && !spec.native_unplayable
        && matches!(
            (enchantment.id, spec.card_type, spec.row.nimble_eligible),
            (
                EnchantmentId::Sharp,
                crate::content_tables::CardType::Attack,
                _
            ) | (EnchantmentId::Nimble, _, true)
        )
}

/// Enchantments whose represented effect is an immutable keyword delta.
/// Their identities affect the effective keyword readers, not the OnPlay body.
///
/// Current v0.111.0 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
/// `Enchantments.Steady::OnEnchant` RVA `0xd65b4` is exactly
/// `this.Card.AddKeyword(5)` — `CardKeyword.Retain`, the same value
/// `RoyallyApproved::OnEnchant` RVA `0xd62c9` adds beside `3` (Innate) and
/// `Steady::get_ExtraHoverTips` RVA `0xd65a7` advertises. `Steady` declares no
/// other method: no `CanEnchant` override, no `OnPlay`, no `AfterCardPlayed`,
/// no `EnchantDamage*`/`EnchantBlockAdditive`, no `ModifyShuffleOrder`, and no
/// mutable field (its `.ctor` RVA `0xd65c2` only chains the base ctor). Python
/// mirrors that as a derived union member rather than a stored slot-3 keyword:
/// `_keyword_delta_enchantment` (frozen Python, deleted #2827) validates the exact
/// amount-1 payload and `card_effective_keywords` adds
/// `CARD_KEYWORD_RETAIN`, so the keyword follows the enchantment through every
/// upgrade, pile move and clone for free.
///
/// SoulsPower::OnEnchant (0xd64a9) removes Exhaust, represented in the
/// compiled CardSpec rather than a mutable per-card flag. CanEnchant (0xd647d)
/// requires Exhaust; an upgraded source can have lost the canonical keyword.
///
/// ROYALLY_APPROVED (#3178) is Steady's shape with a second keyword.
/// `Enchantments.RoyallyApproved` declares exactly four methods and no field:
///
/// * `CanEnchantCardType` RVA `0xd6290` — `(uint)(cardType - 1) <= 1`
///   (`IL_000c`-`IL_0019`): Attack (1) or Skill (2) only, which is the
///   card-type half of the payload gate below;
/// * `get_ExtraHoverTips` RVA `0xd62aa` — the Innate (3) and Retain (5)
///   keyword tips, display only;
/// * `OnEnchant` RVA `0xd62c9` — `Card.AddKeyword(3)` then
///   `Card.AddKeyword(5)`, folded into [`CardSpec::innate`] and
///   [`CardSpec::retain`] by [`crate::catalog::royally_approved_adds_innate_and_retain`];
/// * `.ctor` RVA `0xd62e3` — the base ctor only.
///
/// So no `OnPlay` (the base `EnchantmentModel::OnPlay` RVA `0x7f493` is
/// `Task.CompletedTask`), no `EnchantPlayCount`, no `EnchantDamage*`/
/// `EnchantBlock*`, no `AfterCardPlayed`, no `ShouldStartAtBottomOfDrawPile`,
/// no `Status` write and no async state machine. With no field there is no
/// `[SavedProperty]`, so the base `ToSerializable` RVA `0x7f6c5` writes only
/// `Id` and `Amount` — the canonical `["ROYALLY_APPROVED", amount]` pair.
/// Nothing reads `Amount`; every captured payload carries `1`, and any other
/// amount stays refused under the enchantment's own name rather than being
/// admitted unobserved.
///
/// A sweep of every `Keywords.Contains(3)` call in the DLL finds two Innate
/// readers: the combat-start draw-pile fixup lambda
/// `<>c::<SetupPlayerTurn>b__102_1` RVA `0x3f256f` IL_0008, which the opening
/// owns (`entry::opening`'s `turn_one_fixup_order`), and Jeweled Mask's
/// `<>c::<BeforeHandDraw>b__2_1` RVA `0x3272e1` IL_0008, which filters Powers
/// only — and this enchantment cannot sit on a Power. Retain's readers are the
/// effective-Retain paths ([`crate::engine::cards::effective_retain`]).
pub(crate) fn keyword_delta_enchantment_identity_is_exact(spec: &CardSpec) -> bool {
    matches!(
        spec.identity.enchantment,
        Some(crate::catalog::CardEnchantment {
            id: EnchantmentId::Steady,
            amount: 1,
        })
    ) || (matches!(
        spec.identity.enchantment,
        Some(crate::catalog::CardEnchantment {
            id: EnchantmentId::RoyallyApproved,
            amount: 1,
        })
    ) && matches!(
        spec.card_type,
        crate::content_tables::CardType::Attack | crate::content_tables::CardType::Skill
    )) || (crate::catalog::souls_power_removes_exhaust(spec.identity)
        && (spec.row.exhausts
            || crate::content_tables::card_row(spec.identity.id, 0)
                .is_some_and(|row| row.exhausts)))
}

/// Enchantments whose entire represented effect is one `EnchantmentModel.
/// OnPlay` command that runs after a complete native card body — plus, for
/// `CORRUPTED`, one damage listener the shared powered-attack fold already has
/// a slot for. None of the four edits the compiled step program.
///
/// Current v0.111.0 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`:
///
/// * `Enchantments.Sown` declares only `get_HasExtraCardText`, `OnPlay` RVA
///   `0xd64cc` and its `.ctor` RVA `0xd650f` — no `CanEnchant`/
///   `CanEnchantCardType` override, no `EnchantDamage*`/
///   `EnchantBlockAdditive`, no `EnchantPlayCount`, no `AfterCardPlayed`, no
///   `ModifyShuffleOrder`, and no field of its own. Its state machine
///   `Sown/<OnPlay>d__2::MoveNext` RVA `0x3884d4` is
///   `if (Status != 0) return; Status = 1; await PlayerCmd.GainEnergy((int)
///   Amount, Card.Owner);` (IL_001d-004c).
/// * `Enchantments.Swift` adds only `get_ShowAmount` RVA `0xd65cd`; its
///   `Swift/<OnPlay>d__4::MoveNext` RVA `0x3885c0` is the identical
///   `if (Status != 0) return; Status = 1;` prologue followed by
///   `await CardPileCmd.Draw(choiceContext, (int)Amount, Card.Owner, false)`
///   (IL_001d-0053; the trailing `ldc.i4.0` is `fromHandDraw`).
/// * `Enchantments.Corrupted` declares `CanEnchantCardType` RVA `0xd5eaf`
///   (`cardType == 1`, Attack), `EnchantDamageMultiplicative` RVA `0xd5eb5`
///   (`IsPoweredAttack(cardPlay) ? new Decimal(15, 0, 0, 0, 1) : Decimal.One`
///   — exactly `3/2`), a static `_damageAmount` set to `2` by `.cctor` RVA
///   `0xd5f2b`, and `Corrupted/<OnPlay>d__5::MoveNext` RVA `0x3881bc`, which
///   awaits `CreatureCmd.Damage(Card.Owner.Creature, 2m, 14, this.Card,
///   cardPlay)` — the ordinary props-14 card-sourced owner hit.
/// * `Enchantments.Adroit` (#3220) declares exactly `get_HasExtraCardText`
///   RVA `0xd5e19`, `get_ShowAmount` RVA `0xd5e1c`, `get_CanonicalVars` RVA
///   `0xd5e1f` (one `BlockVar(Decimal.Zero, 8)`: ValueProp 8 is `Move`, so
///   the Block is powered card Block), `OnPlay` RVA `0xd5e34`,
///   `RecalculateValues` RVA `0xd5e7f` (`DynamicVars.Block.BaseValue =
///   Amount`, IL_0001-001c) and its `.ctor` RVA `0xd5e9c` — no `CanEnchant`/
///   `CanEnchantCardType` override (the base `EnchantmentModel::CanEnchant`
///   RVA `0x7f40c` IL_000c-0023 already rejects Status/Curse/Quest owners), no
///   `EnchantDamage*`/`EnchantBlock*`, no `EnchantPlayCount`, no
///   `AfterCardPlayed`, no field and no `Status` write. Its state machine
///   `Adroit/<OnPlay>d__6::MoveNext` RVA `0x3880d8` IL_001d-003f is one
///   unconditional `await CreatureCmd.GainBlock(Card.Owner.Creature,
///   DynamicVars.Block, cardPlay, false)`, and that BlockVar overload's
///   `<GainBlock>d__17::MoveNext` RVA `0x3eadd8` IL_0016-003e forwards
///   `(blockVar.BaseValue, blockVar.Props, cardPlay, fast)` to the amount
///   overload, whose `<GainBlock>d__18::MoveNext` RVA `0x3eaec0` IL_0032 owns
///   the IsOverOrEnding gate. So every complete body — each replay included —
///   gains `Amount` powered card Block through the same `Hook.ModifyBlock`
///   fold, same CardPlay window (Unmovable) and same `AfterBlockGained` walk
///   as the card's own Block; see [`apply_enchantment_on_play`].
///
/// The payload gates mirror Python exactly rather than re-deriving the native
/// `CanEnchant` walk: `_validate_closed_card_enchantment` (frozen Python, deleted #2827) admits `SOWN`/`SWIFT` at any non-negative amount, and
/// `_validated_attack_damage_enchantment` additionally requires an
/// Attack owner for `CORRUPTED`. Being stricter here would refuse a state
/// Python runs; being looser would answer one it refuses.
pub(crate) fn onplay_enchantment_identity_is_exact(spec: &CardSpec) -> bool {
    let Some(enchantment) = spec.identity.enchantment else {
        return false;
    };
    match enchantment.id {
        EnchantmentId::Sown | EnchantmentId::Swift => enchantment.amount >= 0,
        EnchantmentId::Corrupted => enchantment.amount >= 0 && spec.is_attack,
        // Stricter than the base CanEnchant only in refusing a Status/Curse
        // owner outright, which that gate already makes unreachable.
        EnchantmentId::Adroit => enchantment.amount >= 0 && !spec.is_status_curse,
        _ => false,
    }
}

/// GOOPY (#2874, slice 4 of #2502): a per-play-growing block additive plus
/// a derived Exhaust keyword. None of it edits the compiled step program.
///
/// Current v0.111.0 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`.
/// `Enchantments.Goopy` declares exactly:
///
/// * `get_HasExtraCardText` `0xd5ff6`, `get_ExtraHoverTips` `0xd5ff9` —
///   display only;
/// * `CanEnchant` `0xd6006` — base `CanEnchant`, then
///   `Card.Tags.Contains(CardTag.Defend)` (`IL_000a`-`IL_0016`), i.e.
///   [`crate::catalog::goopy_card_is_eligible`];
/// * `OnEnchant` `0xd601f` — `Card.AddKeyword(1)` (Exhaust), folded into
///   `CardSpec::exhausts` from slot 2;
/// * `AfterCardPlayed` `0xd6030` — returns unless `cardPlay.Card == Card`
///   (`IL_000c`-`IL_0018`), then `Amount += 1` (`IL_0020`-`IL_002b`) and, when
///   `Card.DeckVersion != null`, `DeckVersion.Enchantment.Amount += 1`
///   (`IL_0030`-`IL_0057`); see [`goopy_after_card_played`];
/// * `EnchantBlockAdditive` `0xd6092` — `Amount - 1` (`IL_0001`-`IL_0009`),
///   read unconditionally by `Hook::ModifyBlock` `0x104c30`
///   (`IL_0014`-`IL_0036`) for any card-sourced block, powered or not;
/// * `.ctor` `0xd60a1` — base ctor only. No `OnPlay`, no
///   `EnchantPlayCount`, no `EnchantDamage*`, no `ModifyShuffleOrder`.
///
/// The payload gate mirrors Python's `_batch61_enchantment`: the audited
/// Defend allowlist, a playable non-Status/Curse owner, and a non-negative
/// amount. The amount must also be one the catalog closure grows from
/// ([`crate::catalog::GOOPY_AMOUNT_CEILING`]).
pub(crate) fn goopy_identity_is_exact(spec: &CardSpec) -> bool {
    crate::catalog::goopy_amount(spec.identity).is_some_and(|amount| {
        (0..=crate::catalog::GOOPY_AMOUNT_CEILING).contains(&amount)
            && crate::catalog::goopy_card_is_eligible(spec.identity.id)
            && spec.playable
            && !spec.native_unplayable
            && !spec.is_status_curse
    })
}

/// VIGOROUS (#3275): a one-shot powered-attack damage additive whose spent
/// bit is the native `EnchantmentModel.Status`, carried in slot 5.
///
/// Current v0.111.0 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`
/// (`dump_type.py Vigorous`). `Enchantments.Vigorous` declares exactly:
///
/// * `CanEnchantCardType` RVA `0xd669b` — `cardType == 1` (IL_0001-0005):
///   Attack owners only, the card-type half of the gate below;
/// * `get_ShowAmount` RVA `0xd66a1` — `true`, display only;
/// * `EnchantDamageAdditive` RVA `0xd66a4` — `if (Status != 0) return 0`
///   (IL_0001-000e), `if (!IsPoweredAttack(props)) return 0` (IL_000f-001c),
///   else `(decimal)Amount` (IL_001d-0028): Sharp's body (`Sharp::
///   EnchantDamageAdditive` RVA `0xd62f4`) behind a Status gate. The one
///   caller is `Hook::ModifyDamage` RVA `0x10511c` IL_0015-0046, which adds
///   `cardSource.Enchantment.EnchantDamageAdditive` directly (not through a
///   listener walk) whenever the damage has a card source with an
///   enchantment, so it lands in the same additive slot Sharp does in
///   [`crate::engine::damage`]'s powered-attack fold;
/// * `AfterCardPlayed` RVA `0xd66cd` — `if (cardPlay.Card != Card) return`
///   (IL_0001-0014), then `Status = 1` (IL_0015-0017); see
///   [`vigorous_after_card_played`];
/// * `.ctor` RVA `0xd66ef` — the base ctor only.
///
/// No `OnPlay` (the base `EnchantmentModel::OnPlay` RVA `0x7f493` is
/// `Task.CompletedTask`), no `EnchantPlayCount`, no `EnchantBlock*`, no
/// `EnchantDamageMultiplicative`, no `OnEnchant`, no field of its own and no
/// async state machine. `EnchantmentModel::set_Status` RVA `0x7f4dd` stores
/// `_status` and invokes `StatusChanged` (presentation); `get_Status` RVA
/// `0x7f4d5` reads it back. `EnchantmentModel::ToSerializable` RVA `0x7f6c5`
/// writes only `Id`, `Props` and `Amount`, and no Enchantment member carries
/// `[SavedProperty]`, so a saved deck card enters every combat unspent (the
/// full clone argument is on `entry::opening`'s `entry_enchantment_state`,
/// which seeds `["VIGOROUS", 0]`). Within a fight the Rust carrier is slot 5:
/// `Some(0)` unspent, `Some(1)` spent, and the boundary spells both as the
/// `["VIGOROUS", n]` state row; clones copy it with the rest of the instance
/// state, as `MemberwiseClone` copies `_status`.
///
/// The amount gate is `>= 0`: the additive of a zero-amount copy is zero,
/// which the fold computes exactly.
pub(crate) fn vigorous_identity_is_exact(spec: &CardSpec) -> bool {
    matches!(
        spec.identity.enchantment,
        Some(crate::catalog::CardEnchantment {
            id: EnchantmentId::Vigorous,
            amount,
        }) if amount >= 0
    ) && spec.card_type == crate::content_tables::CardType::Attack
        && !spec.native_unplayable
}

/// TEZCATARAS_EMBER (#3413): a zero base cost plus a fixed powered-attack
/// damage additive of 3.
///
/// Current v0.111.0 DLL SHA-256
/// `9cb4f1ad8c9f284aa8fec3122ffd6d780bbf543d875c817abdd12ff63fbf12b4`
/// (`dump_type.py TezcatarasEmber`). `Enchantments.TezcatarasEmber` declares
/// exactly:
///
/// * `get_ExtraHoverTips` RVA `0xd6623` — the Eternal hover tip, display only;
/// * `get_CanonicalVars` RVA `0xd6630` — one `DamageVar(3m, 8)`
///   (IL_0001-000d);
/// * `OnEnchant` RVA `0xd6643` — zero the energy `_base` and add Eternal,
///   folded into the catalog's spec cost by
///   [`crate::catalog::tezcataras_ember_base_cost`];
/// * `EnchantDamageAdditive` RVA `0xd6673` — `if (!IsPoweredAttack(props))
///   return 0` (IL_0001-000e), else `DynamicVars.Damage.BaseValue`
///   (IL_000f-001f): Sharp's body (`Sharp::EnchantDamageAdditive` RVA
///   `0xd62f4`) with the constant 3 in place of `Amount`. Nothing rewrites
///   the enchantment's own vars: `get_DynamicVars` RVA `0x7f49a` builds them
///   once from `CanonicalVars`, and `RecalculateValues` is the base no-op
///   RVA `0x7f6c3`, which TezcatarasEmber does not override. The one caller
///   is `Hook::ModifyDamage` RVA `0x10511c`, as for Sharp, so it joins the
///   same additive slot in [`crate::engine::damage`]'s powered-attack fold;
/// * `.ctor` RVA `0xd6693` — the base ctor only.
///
/// No `CanEnchantCardType` override (the base RVA `0x7f403` returns true),
/// no `OnPlay`, no `AfterCardPlayed`, no `EnchantPlayCount`, no
/// `EnchantBlock*`, no `EnchantDamageMultiplicative`, no `Status` write and no
/// field of its own, so the identity is immutable and needs no slot-5 row.
/// `Amount` is never read.
///
/// The gate is the one source's exact shape. `NutritiousSoup::AfterObtained`
/// RVA `0x979c4` enchants each Deck card with `Rarity == 1` (Basic,
/// IL_0033-003a) and the Strike tag (`CardTag` 1, IL_003c-0048) that
/// `CanEnchant` accepts, at `Decimal.One` (IL_0057-005d). No other code path
/// names the type. The Basic Strike-tagged rows are the five character
/// Strikes, each a fixed cost-1 Attack at both upgrade levels, so every
/// upgrade keeps the zero `_base` and no cost-lowering upgrade clamp is
/// reachable.
pub(crate) fn tezcataras_ember_identity_is_exact(spec: &CardSpec) -> bool {
    matches!(
        spec.identity.enchantment,
        Some(crate::catalog::CardEnchantment {
            id: EnchantmentId::TezcatarasEmber,
            amount: 1,
        })
    ) && matches!(
        spec.identity.id,
        CardId::StrikeDefect
            | CardId::StrikeIronclad
            | CardId::StrikeNecrobinder
            | CardId::StrikeRegent
            | CardId::StrikeSilent
    ) && matches!(spec.identity.upgrade, 0 | 1)
        && spec.card_type == crate::content_tables::CardType::Attack
        && !spec.x_cost
        && spec.row.cost >= 0
        && spec.cost == 0
        && !spec.native_unplayable
}

/// `Vigorous::AfterCardPlayed` RVA `0xd66cd` for the played card's own
/// enchantment listener: `if (cardPlay.Card != Card) return; Status = 1;`.
///
/// It runs at the same point as [`goopy_after_card_played`], the other
/// `cardPlay.Card == Card` enchantment listener, in the captured player
/// card-pile walk after powers and relics and before the enemy suffix, once
/// per replay body (native `CardModel/<OnPlayWrapper>d__339::MoveNext` RVA
/// `0x31b8d0` fires `Hook::AfterCardPlayed` at IL_0874 inside the body loop).
/// So body 0 reads `Status == 0` and gets the additive, and every later body
/// of the same series — and every later play — reads `Status == 1`. The only
/// reader of this `Status` is this card's own `EnchantDamageAdditive`, and no
/// admitted AfterCardPlayed listener deals powered damage sourced from the
/// played card, so its place inside the walk is not observable beyond the
/// body boundary.
///
/// An enchantment receives combat hooks only through its card
/// (`EnchantmentModel::get_ShouldReceiveCombatHooks` RVA `0x7f378`
/// IL_000c-001e, `CardModel::get_ShouldReceiveCombatHooks` RVA `0x7e29c`:
/// `Pile?.IsCombatPile`), and hook listeners are skipped once the owner's
/// hooks deactivate; a card that has left every pile has no reader, and is
/// skipped as Goopy's is. A second `Status = 1` write is `set_Status`'s
/// same-value early return (IL_0008-0010), a no-op.
///
/// A Vigorous card without a slot-5 row cannot be placed on either side of
/// the gate and refuses by name; so does any value other than 0/1.
fn vigorous_after_card_played(
    state: &mut HotState,
    catalog: &Catalog,
    played_uid: u32,
) -> Result<(), EngineRefusal> {
    if state.fanouts.player_hooks_deactivated() {
        return Ok(());
    }
    let Some((pile, index)) = unique_live_card_location(state, played_uid)? else {
        return Ok(());
    };
    let card = state.piles.get(pile).as_slice()[index];
    let spec = catalog
        .spec(card.atom)
        .ok_or(EngineRefusal::UnknownAtom(card.atom))?;
    if !spec
        .identity
        .enchantment
        .is_some_and(|enchantment| matches!(enchantment.id, EnchantmentId::Vigorous))
    {
        return Ok(());
    }
    if !vigorous_identity_is_exact(spec) {
        return Err(EngineRefusal::MalformedArgs("VIGOROUS owner"));
    }
    let mut instance = state.card_states.get(played_uid);
    match instance.enchantment_state.get() {
        Some(0) => {}
        Some(1) => return Ok(()),
        _ => return Err(EngineRefusal::MalformedArgs("VIGOROUS status")),
    }
    instance.enchantment_state = crate::hot::OptionalNonNegativeI32::from_option(Some(1))
        .expect("one is a valid enchantment state");
    state.card_states.set(played_uid, instance);
    if !state.exact_piles && super::cards::live_cards_need_exact_piles(state, catalog)? {
        state.exact_piles = true;
    }
    Ok(())
}

/// The live card a generated replay body plays after an earlier body's
/// AfterCardPlayed upgraded it (#3207).
///
/// Native v0.111.0 (`sts2.dll` sha256 9cb4f1ad…):
/// `CardModel/<OnPlayWrapper>d__339::MoveNext` (RVA `0x31b8d0`) runs every
/// replay body against the same `this`: `CardPlay::set_Card` (IL_0532),
/// `Hook::BeforeCardPlayed` (IL_05a1), `CardModel::OnPlay` (IL_0659), then
/// `Hook::AfterCardPlayed` (IL_0874) before the next body. Razor Tooth's
/// `AfterCardPlayed` (RVA `0x9a1b8`, IL_0059-IL_0060) calls
/// `CardCmd.Upgrade(cardPlay.Card)` synchronously, and a body reads its
/// values from that live model — e.g. `Glacier/<OnPlay>d__7::MoveNext`
/// (RVA `0x3a1354`) reads `CardModel::get_DynamicVars().Block` at
/// IL_00b2-IL_00b7, which `Glacier::OnUpgrade` (RVA `0xe1247`) raised by 3.
/// So under Burst a Glacier's second body gains the upgraded 9 Block.
///
/// Returns `None` when the live card is still the frozen atom (the ordinary
/// path). A live card that differs only in upgrade level is played with its
/// live spec. The play's Energy value is the frozen `CardPlay.Resources`
/// (IL_0567) and is untouched here; what moves is the body's live
/// `Card.EnergyCost.GetResolved` (e.g. Bullet Time 3 -> 2), which the
/// before-card listeners read. The cost modifiers it resolves against are
/// only cleaned after the whole series (`CardEnergyCost::AfterCardPlayedCleanup`
/// IL_0d73), so it is the upgraded card's resolved cost under the same
/// modifiers — returned only when re-resolving the frozen card reproduces
/// the play's own `frozen_resolved` cost, else the live resolution is not
/// trusted and it refuses by name, as does a cost change on an Energy-X
/// card (no v0.111.0 upgrade does either). Any other identity change keeps
/// the frozen path.
fn replay_body_upgraded_live_card(
    state: &HotState,
    catalog: &Catalog,
    uid: u32,
    frozen: HotCard,
    frozen_resolved: i64,
) -> Result<Option<(HotCard, CardSpec, i64)>, EngineRefusal> {
    let Some((pile, index)) = unique_live_card_location(state, uid)? else {
        return Ok(None);
    };
    let live = state.piles.get(pile).as_slice()[index];
    if live.atom == frozen.atom {
        return Ok(None);
    }
    let frozen_spec = *catalog
        .spec(frozen.atom)
        .ok_or(EngineRefusal::UnknownAtom(frozen.atom))?;
    let live_spec = *catalog
        .spec(live.atom)
        .ok_or(EngineRefusal::UnknownAtom(live.atom))?;
    if live_spec.identity.id != frozen_spec.identity.id
        || live_spec.identity.enchantment != frozen_spec.identity.enchantment
        || live_spec.identity.upgrade <= frozen_spec.identity.upgrade
    {
        return Ok(None);
    }
    if live_spec.cost == frozen_spec.cost && live_spec.x_cost == frozen_spec.x_cost {
        return Ok(Some((live, live_spec, frozen_resolved)));
    }
    if live_spec.x_cost
        || frozen_spec.x_cost
        || resolved_energy_cost(state, frozen, &frozen_spec) != frozen_resolved
    {
        return Err(EngineRefusal::MalformedArgs(
            "replay body upgraded Energy cost unresolvable",
        ));
    }
    Ok(Some((
        live,
        live_spec,
        resolved_energy_cost(state, live, &live_spec),
    )))
}

/// `Goopy::AfterCardPlayed` for the played card's own enchantment listener.
///
/// Native RVA `0xd6030`: `if (cardPlay.Card != Card) return;` then
/// `Amount = Amount + 1` and, when `Card.DeckVersion != null`, the same
/// increment on `DeckVersion.Enchantment`. Python
/// `_physical_cards_after_card_played` (frozen, deleted #2827) runs it in the captured
/// player-card-pile walk after powers and relics and before the enemy
/// suffix, rewriting the exact physical UID to `("GOOPY", amount + 1)`
/// through `_enchantment_after_card_played`. Rust runs it at the same
/// point, immediately after Banshee's Cry / Pinpoint: those write only their
/// own local cost rows and this writes only the played card's identity, so
/// the two are order-free.
///
/// The amount lives in the immutable slot-2 identity (a new interned atom
/// per amount, like Python's rewrite) rather than in mutable slot 5: every
/// identity-keyed reader — the exact-piles dedup, the boundary's
/// `(GOOPY, amount)` payload and `live_cards_need_exact_piles`' divergent
/// tie set — then sees the same value Python's payload carries, and the
/// boundary round trip stays bijective. The successor atom is pre-interned by
/// the catalog closure; growth past [`crate::catalog::GOOPY_AMOUNT_CEILING`]
/// refuses.
///
/// DeckVersion: within a fight the run-deck copy is represented only by
/// Thieving Hopper's persistent master rows, which carry the DeckVersion
/// payload a Swipe steals and returns. When the played card owns such a row
/// its payload grows in lockstep, exactly as `IL_0030`-`IL_0057` writes
/// `DeckVersion.Enchantment.Amount`; a row whose payload is not the card's
/// pre-growth identity refuses (the same stale-master guard as
/// `monsters::update_hopper_scythe_master`). Python leaves that row one play
/// behind, which is an oracle gap, not native behavior. Everywhere else the
/// DeckVersion write takes effect after combat and has no in-combat reader.
///
/// The played card is always the listener, and nothing admitted can change
/// its enchantment between the AfterCardPlayed capture and this point, so
/// reading the live card here is the captured-listener semantics. A card that
/// has left every pile has no observable recipient and is skipped.
fn goopy_after_card_played(
    state: &mut HotState,
    catalog: &Catalog,
    played_uid: u32,
) -> Result<(), EngineRefusal> {
    if state.fanouts.player_hooks_deactivated() {
        return Ok(());
    }
    let Some((pile, index)) = unique_live_card_location(state, played_uid)? else {
        return Ok(());
    };
    let card = state.piles.get(pile).as_slice()[index];
    let spec = catalog
        .spec(card.atom)
        .ok_or(EngineRefusal::UnknownAtom(card.atom))?;
    let Some(amount) = crate::catalog::goopy_amount(spec.identity) else {
        return Ok(());
    };
    if !goopy_identity_is_exact(spec) {
        return Err(EngineRefusal::MalformedArgs("GOOPY owner"));
    }
    let grown = crate::catalog::CardIdentity {
        enchantment: Some(crate::catalog::CardEnchantment {
            id: EnchantmentId::Goopy,
            amount: amount
                .checked_add(1)
                .ok_or(EngineRefusal::CounterOverflow("GOOPY amount"))?,
        }),
        ..spec.identity
    };
    let atom = catalog
        .atom(&grown)
        .ok_or(EngineRefusal::UnknownMintIdentity(grown))?;
    if let Some(deck) = state.card_states.hopper_mut() {
        let mut rows = deck
            .master
            .iter_mut()
            .filter(|row| row.card.uid == played_uid);
        match (rows.next(), rows.next()) {
            (None, _) => {}
            (Some(row), None) if row.card.atom == card.atom => row.card.atom = atom,
            _ => return Err(EngineRefusal::MalformedArgs("Hopper GOOPY master row")),
        }
    }
    state.piles.get_mut(pile).make_mut()[index].atom = atom;
    if !state.exact_piles && super::cards::live_cards_need_exact_piles(state, catalog)? {
        state.exact_piles = true;
    }
    Ok(())
}

/// Whether an active card's immutable enchantment leaves its compiled base
/// body unchanged in the represented slice.
///
/// Glam and Spiral contribute only to native GeneratePlayCount. Their
/// CardPlay bodies remain the exact generated base row, so body-local row
/// authenticators must accept these two identities while continuing to
/// reject every unmodeled enchantment. Steady and Royally Approved
/// contribute only effective keywords, which are likewise not a body edit — see
/// [`keyword_delta_enchantment_identity_is_exact`] and the effective-Retain
/// reader in [`crate::engine::cards::effective_retain`]. Sown, Swift, Adroit and
/// Corrupted contribute only a post-body `OnPlay` command (and Corrupted one
/// damage-listener factor), which is likewise not a body edit — see
/// [`onplay_enchantment_identity_is_exact`] and [`apply_enchantment_on_play`].
/// Slither contributes only a draw-time cost roll (#2926), see
/// [`super::draw::slither_identity_is_exact`]. Vigorous contributes only a
/// Status-gated damage additive in the shared powered-attack fold (#3275),
/// see [`vigorous_identity_is_exact`]. TezcatarasEmber contributes a zero
/// spec cost and a fixed additive in the same fold (#3413), see
/// [`tezcataras_ember_identity_is_exact`]. Imbued changes nothing a play reads
/// (#3381): its one effect is a turn-one AutoPre listener, which admission
/// gates on its own ([`imbued_identity_is_inert`]).
pub(crate) fn body_enchantment_is_exact(spec: &CardSpec) -> bool {
    spec.identity.enchantment.is_none()
        || replay_enchantment_identity_is_exact(spec)
        || static_body_enchantment_identity_is_exact(spec)
        || keyword_delta_enchantment_identity_is_exact(spec)
        || onplay_enchantment_identity_is_exact(spec)
        || super::draw::perfect_fit_identity_is_exact(spec)
        || super::draw::slither_identity_is_exact(spec)
        || goopy_identity_is_exact(spec)
        || vigorous_identity_is_exact(spec)
        || tezcataras_ember_identity_is_exact(spec)
        || imbued_skill_identity(spec)
}

/// An `IMBUED` Skill, the only card type `Imbued::CanEnchantCardType`
/// (`0xd60a9`, `CardType == 2`) admits. See [`imbued_identity_is_inert`] for
/// the IL of the type's members, none of which reads or edits a play.
fn imbued_skill_identity(spec: &CardSpec) -> bool {
    imbued_identity(spec) && spec.card_type == crate::content_tables::CardType::Skill
}

/// Exact current-build CardPlay body step whose single Draw result is ignored.
///
/// Python's `_run_steps_inner` stores the remaining body program on the
/// CardPlay frame and calls `draw_cards(..., caller="none")`; the `none`
/// handler has no locals and does no suffix work.  Keep the source-row match
/// deliberately closed: fused kinds are admitted only for the one mode that
/// really has this ownership shape, never merely because they can draw.
pub(crate) fn cardplay_no_result_draw_source_step_is_exact(
    row: &crate::content_tables::CardRow,
    index: usize,
) -> bool {
    use crate::content_tables::Arg;
    // A generated row: a `CARD_ROWS` entry or a ported Mad Science variant
    // row (#2942), whose Wisdom rider is a plain `Draw` (`<ExecuteRider>d__57`
    // `0x3aa9c4` IL_0295-IL_02bb, `CardPileCmd.Draw(WisdomCards)`).
    if !crate::content_tables::is_generated_card_row(row) {
        return false;
    }
    let Some(step) = row.steps.get(index) else {
        return false;
    };
    matches!((step.kind, step.args), (StepKind::Draw, [Arg::I(amount)]) if *amount >= 0)
        || matches!(
            (row.id, row.upgrade, step.kind, step.args),
            (CardId::DrumOfBattle, 0 | 1, StepKind::DrumOfBattleExact, [])
                | (
                    CardId::CompileDriver,
                    0,
                    StepKind::CompileDriverUniqueOrbExact,
                    [Arg::I(7)]
                )
                | (
                    CardId::CompileDriver,
                    1,
                    StepKind::CompileDriverUniqueOrbExact,
                    [Arg::I(10)]
                )
                | (
                    CardId::Fetch,
                    0,
                    StepKind::OstyBody,
                    [Arg::S("fetch"), Arg::I(3), Arg::I(1)]
                )
                | (
                    CardId::Fetch,
                    1,
                    StepKind::OstyBody,
                    [Arg::S("fetch"), Arg::I(6), Arg::I(1)]
                )
                | (
                    CardId::Ftl,
                    0,
                    StepKind::SameTurnHistoryBody,
                    [Arg::S("ftl"), Arg::I(5), Arg::I(3)]
                )
                | (
                    CardId::Ftl,
                    1,
                    StepKind::SameTurnHistoryBody,
                    [Arg::S("ftl"), Arg::I(6), Arg::I(4)]
                )
                | (
                    CardId::Scrawl,
                    0 | 1,
                    StepKind::HandCapBody,
                    [Arg::S("draw_space")]
                )
                | (
                    CardId::SpoilsOfBattle,
                    0,
                    StepKind::ForgeFamilyExact,
                    [Arg::S("spoils_of_battle"), Arg::I(6), Arg::I(2)]
                )
                | (
                    CardId::SpoilsOfBattle,
                    1,
                    StepKind::ForgeFamilyExact,
                    [Arg::S("spoils_of_battle"), Arg::I(9), Arg::I(2)]
                )
                | (
                    CardId::Impatience,
                    0,
                    StepKind::DrawIfNoHandAttacks,
                    [Arg::I(2)]
                )
                | (
                    CardId::Impatience,
                    1,
                    StepKind::DrawIfNoHandAttacks,
                    [Arg::I(3)]
                )
                | (CardId::BurningPact, 0, StepKind::ExhaustDraw, [Arg::I(2)])
                | (CardId::BurningPact, 1, StepKind::ExhaustDraw, [Arg::I(3)])
        )
}

pub(crate) fn cardplay_no_result_draw_program_is_exact(spec: &CardSpec, catalog: &Catalog) -> bool {
    if spec.identity.id != spec.row.id || spec.identity.upgrade != spec.row.upgrade {
        return false;
    }
    body_enchantment_is_exact(spec)
        && catalog.steps(spec).len() == spec.row.steps.len()
        && spec
            .row
            .steps
            .iter()
            .enumerate()
            .any(|(index, _)| cardplay_no_result_draw_step_is_exact(spec, catalog, index))
}

fn cardplay_owned_draw_program_is_exact(spec: &CardSpec, catalog: &Catalog) -> bool {
    cardplay_no_result_draw_program_is_exact(spec, catalog)
        || spec
            .row
            .steps
            .iter()
            .enumerate()
            .any(|(index, _)| cardplay_owned_draw_tail_step_is_exact(spec, catalog, index))
}

pub(crate) fn cardplay_no_result_draw_step_is_exact(
    spec: &CardSpec,
    catalog: &Catalog,
    index: usize,
) -> bool {
    if !body_enchantment_is_exact(spec)
        || spec.identity.id != spec.row.id
        || spec.identity.upgrade != spec.row.upgrade
        || catalog.steps(spec).len() != spec.row.steps.len()
        || !cardplay_no_result_draw_source_step_is_exact(spec.row, index)
    {
        return false;
    }
    catalog
        .steps(spec)
        .get(index)
        .zip(spec.row.steps.get(index))
        .is_some_and(|(compiled, source)| compiled.kind == source.kind)
}

/// Draw steps whose remaining command suffix is reconstructed from the
/// authenticated CardPlay record when the nested Draw returns.  Unlike the
/// ordinary no-result family, these rows have source-specific work after the
/// Draw and must never be resumed by the generic cursor-only path.
pub(crate) fn cardplay_owned_draw_tail_step_is_exact(
    spec: &CardSpec,
    catalog: &Catalog,
    index: usize,
) -> bool {
    use crate::content_tables::Arg;
    if !body_enchantment_is_exact(spec)
        || spec.identity.id != spec.row.id
        || spec.identity.upgrade != spec.row.upgrade
        || crate::content_tables::card_row(spec.identity.id, spec.identity.upgrade)
            != Some(spec.row)
        || catalog.steps(spec).len() != spec.row.steps.len()
    {
        return false;
    }
    let Some((compiled, source)) = catalog
        .steps(spec)
        .get(index)
        .zip(spec.row.steps.get(index))
    else {
        return false;
    };
    cardplay_owned_draw_tail_source_step_is_exact(spec.row, index)
        && compiled.kind == source.kind
        && catalog.args(compiled.args).len() == source.args.len()
        && (catalog
            .args(compiled.args)
            .iter()
            .zip(source.args)
            .all(|(compiled, source)| {
                matches!((compiled, source), (CompiledArg::I(left), Arg::I(right)) if left == right)
            })
            // The BigBang forge-writer word compiles from its opaque source
            // string; the source row above already pins both spellings.
            || matches!(spec.row.id, CardId::BigBang)
                && catalog.args(compiled.args)
                    == [CompiledArg::Word(crate::ids::StepWord::BigBang), CompiledArg::I(5)])
}

/// Source-table half of the awaited CardPlay-owned Draw classifier. Catalog
/// construction uses this same closed family before compiled argument handles
/// exist, while runtime rechecks both this row and its compiled operands.
pub(crate) fn cardplay_owned_draw_tail_source_step_is_exact(
    row: &crate::content_tables::CardRow,
    index: usize,
) -> bool {
    use crate::content_tables::Arg;
    let Some(source) = row.steps.get(index) else {
        return false;
    };
    matches!(
        (row.id, row.upgrade, source.kind, source.args),
        (
            CardId::Constellation,
            0,
            StepKind::ConstellationExact,
            [Arg::I(1), Arg::I(1), Arg::I(9)],
        ) | (
            CardId::Constellation,
            1,
            StepKind::ConstellationExact,
            [Arg::I(1), Arg::I(1), Arg::I(12)],
        ) | (CardId::HuddleUp, 0, StepKind::HuddleUpExact, [Arg::I(2)])
            | (CardId::HuddleUp, 1, StepKind::HuddleUpExact, [Arg::I(3)])
            | (
                CardId::Scrape,
                0,
                StepKind::ScrapeExact,
                [Arg::I(7), Arg::I(4)]
            )
            | (
                CardId::Scrape,
                1,
                StepKind::ScrapeExact,
                [Arg::I(10), Arg::I(5)]
            )
            | (
                CardId::BigBang,
                0,
                StepKind::ForgeFamilyExact,
                [Arg::S("big_bang"), Arg::I(5)]
            )
            | (
                CardId::BigBang,
                1,
                StepKind::ForgeFamilyExact,
                [Arg::S("big_bang"), Arg::I(5)]
            )
            | (
                CardId::EscapePlan,
                0,
                StepKind::EscapePlanExact,
                [Arg::I(3)]
            )
            | (
                CardId::EscapePlan,
                1,
                StepKind::EscapePlanExact,
                [Arg::I(5)]
            )
            | (CardId::Expertise, 0, StepKind::ExpertiseExact, [Arg::I(2)])
            | (CardId::Expertise, 1, StepKind::ExpertiseExact, [Arg::I(3)])
            | (CardId::CalculatedGamble, 0, StepKind::DiscardHandDraw, [])
            | (CardId::CalculatedGamble, 1, StepKind::DiscardHandDraw, [])
            | (
                CardId::Glimmer,
                0,
                StepKind::GlimmerExact,
                [Arg::I(3), Arg::I(1)]
            )
            | (
                CardId::Glimmer,
                1,
                StepKind::GlimmerExact,
                [Arg::I(4), Arg::I(1)]
            )
    )
}

#[inline]
pub(crate) fn cardplay_owned_draw_step_is_exact(
    spec: &CardSpec,
    catalog: &Catalog,
    index: usize,
) -> bool {
    cardplay_no_result_draw_step_is_exact(spec, catalog, index)
        || cardplay_owned_draw_tail_step_is_exact(spec, catalog, index)
}

/// Issue the local Draw of a source-specific awaited card body. The caller
/// commits its CardPlay cursor before entering this helper; the same record
/// therefore authenticates the exact tail at return without another frame.
pub(crate) fn draw_cardplay_owned_tail(
    ctx: &mut StepCtx<'_>,
    count: usize,
) -> Result<bool, EngineRefusal> {
    let Some(Frame::CardPlay { record }) = ctx.state.frames.top() else {
        return Ok(false);
    };
    let owner = ctx
        .state
        .frames
        .card_play(record)
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    let index = usize::try_from(owner.next_step)
        .ok()
        .and_then(|next| next.checked_sub(1))
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    if owner.uid != ctx.source_uid
        || owner.stage != CardPlayStage::Body
        || owner.pending_choice
        || !cardplay_owned_draw_tail_step_is_exact(ctx.spec, ctx.catalog, index)
    {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    Ok(super::draw::draw_cards_for_potion(
        ctx.state,
        ctx.catalog,
        count,
        crate::hot::DrawCaller::CardPlay,
        ctx.events,
    )? == super::draw::PotionDrawResult::Suspended)
}

/// Issue Calculated Gamble's paired Draw with its frozen program attached
/// (#2667). Same cursor contract as [`draw_cardplay_owned_tail`]: the caller
/// commits its CardPlay cursor first, and the Sly batch replays only after
/// the Draw fully returns — never on the suspending path.
pub(crate) fn draw_gamble_paired_tail(
    ctx: &mut StepCtx<'_>,
    paired: crate::hot::GamblePaired,
) -> Result<bool, EngineRefusal> {
    let Some(Frame::CardPlay { record }) = ctx.state.frames.top() else {
        return Ok(false);
    };
    let owner = ctx
        .state
        .frames
        .card_play(record)
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    let index = usize::try_from(owner.next_step)
        .ok()
        .and_then(|next| next.checked_sub(1))
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    if owner.uid != ctx.source_uid
        || owner.stage != CardPlayStage::Body
        || owner.pending_choice
        || ctx.spec.identity.id != CardId::CalculatedGamble
        || !cardplay_owned_draw_tail_step_is_exact(ctx.spec, ctx.catalog, index)
    {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    Ok(
        super::draw::draw_cards_for_gamble_tail(ctx.state, ctx.catalog, paired, ctx.events)?
            == super::draw::PotionDrawResult::Suspended,
    )
}

pub(crate) fn draw_cardplay_owned_result(
    ctx: &mut StepCtx<'_>,
    count: usize,
) -> Result<super::draw::CardDrawResult, EngineRefusal> {
    let Some(Frame::CardPlay { record }) = ctx.state.frames.top() else {
        return Err(EngineRefusal::ContinuationNotModeled);
    };
    let owner = ctx
        .state
        .frames
        .card_play(record)
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    let index = usize::try_from(owner.next_step)
        .ok()
        .and_then(|next| next.checked_sub(1))
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    if owner.uid != ctx.source_uid
        || owner.stage != CardPlayStage::Body
        || owner.pending_choice
        || !matches!(
            ctx.spec.identity.id,
            CardId::Scrape | CardId::EscapePlan | CardId::Expertise
        )
        || !cardplay_owned_draw_tail_step_is_exact(ctx.spec, ctx.catalog, index)
    {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    super::draw::draw_cards_for_card_result(
        ctx.state,
        ctx.catalog,
        count,
        crate::hot::DrawCaller::CardPlay,
        ctx.events,
    )
}

/// The sole Draw nested in an ordinary AfterCardExhausted return program.
/// Burning Pact's captured owner resumes this printed tail only after its
/// selected card's complete Dark/FNP/relic hook has returned.
pub(crate) fn cardplay_owned_after_card_exhausted_draw_step_is_exact(
    spec: &CardSpec,
    catalog: &Catalog,
    index: usize,
) -> bool {
    if !body_enchantment_is_exact(spec)
        || spec.identity.id != CardId::BurningPact
        || !matches!(spec.identity.upgrade, 0 | 1)
        || crate::content_tables::card_row(spec.identity.id, spec.identity.upgrade)
            != Some(spec.row)
        || catalog.steps(spec).len() != spec.row.steps.len()
    {
        return false;
    }
    catalog
        .steps(spec)
        .get(index)
        .zip(spec.row.steps.get(index))
        .is_some_and(|(compiled, source)| {
            compiled.kind == StepKind::ExhaustDraw
                && compiled.kind == source.kind
                && matches!(
                    catalog.args(compiled.args),
                    [CompiledArg::I(draws)]
                        if *draws == 2 + i64::from(spec.identity.upgrade)
                )
        })
}

/// Exact result-bearing Draw programs whose ordered return payload or finite
/// command counter is resumed by the surrounding persisted CardPlay.
pub(crate) fn cardplay_result_draw_source_step_is_exact(
    row: &crate::content_tables::CardRow,
    index: usize,
) -> bool {
    use crate::content_tables::Arg;
    if crate::content_tables::card_row(row.id, row.upgrade) != Some(row) {
        return false;
    }
    let Some(step) = row.steps.get(index) else {
        return false;
    };
    matches!(
        (row.id, row.upgrade, step.kind, step.args),
        (CardId::Pillage, 0, StepKind::PillageExact, [Arg::I(6)])
            | (CardId::Pillage, 1, StepKind::PillageExact, [Arg::I(9)])
            | (
                CardId::Restlessness,
                0,
                StepKind::RestlessnessExact,
                [Arg::I(2)]
            )
            | (
                CardId::Restlessness,
                1,
                StepKind::RestlessnessExact,
                [Arg::I(3)]
            )
    )
}

pub(crate) fn cardplay_result_draw_step_is_exact(
    spec: &CardSpec,
    catalog: &Catalog,
    index: usize,
) -> bool {
    if !body_enchantment_is_exact(spec)
        || catalog.steps(spec).len() != spec.row.steps.len()
        || !cardplay_result_draw_source_step_is_exact(spec.row, index)
    {
        return false;
    }
    let Some((compiled, source)) = catalog
        .steps(spec)
        .get(index)
        .zip(spec.row.steps.get(index))
    else {
        return false;
    };
    compiled.kind == source.kind
        && match (spec.identity.id, spec.identity.upgrade, compiled.kind) {
            (CardId::Pillage, 0 | 1, StepKind::PillageExact) => {
                matches!(catalog.args(compiled.args), [CompiledArg::I(damage)]
                    if *damage == 6 + 3 * i64::from(spec.identity.upgrade))
            }
            (CardId::Restlessness, 0 | 1, StepKind::RestlessnessExact) => {
                matches!(catalog.args(compiled.args), [CompiledArg::I(amount)]
                    if *amount == 2 + i64::from(spec.identity.upgrade))
            }
            _ => false,
        }
}

/// Issue one exact no-result body Draw, using the surrounding persisted
/// CardPlay as the return owner when replay can expose a continuation.
pub(crate) fn draw_cardplay_no_result(
    ctx: &mut StepCtx<'_>,
    count: usize,
) -> Result<(), EngineRefusal> {
    let Some(Frame::CardPlay { record }) = ctx.state.frames.top() else {
        return super::draw::draw_cards(
            ctx.state,
            ctx.catalog,
            count,
            super::draw::DrawSource::Command,
            ctx.events,
        );
    };
    let owner = ctx
        .state
        .frames
        .card_play(record)
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    // An inline AutoPlay child (Havoc's draw-top flip, run without its own
    // frame because `autoplay_child_requires_suspension` was false) executes
    // beneath its parent's persisted CardPlay. When no Draw hook in this
    // fight can suspend, its Draw can never park, so it has no continuation
    // to return to any owner and is exactly the frameless command Draw above
    // (#3197). Both forms are `DrawSource::Command`, the
    // `CardPileCmd.Draw(fromHandDraw: false)` overload.
    if owner.uid != ctx.source_uid && !ctx.catalog.cardplay_draw_hook_can_suspend() {
        return super::draw::draw_cards(
            ctx.state,
            ctx.catalog,
            count,
            super::draw::DrawSource::Command,
            ctx.events,
        );
    }
    let index = usize::try_from(owner.next_step)
        .ok()
        .and_then(|next| next.checked_sub(1))
        .ok_or(EngineRefusal::ContinuationNotModeled)?;
    if owner.uid != ctx.source_uid
        || owner.stage != CardPlayStage::Body
        || owner.pending_choice
        || !cardplay_no_result_draw_step_is_exact(ctx.spec, ctx.catalog, index)
    {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    let _ = super::draw::draw_cards_for_potion(
        ctx.state,
        ctx.catalog,
        count,
        crate::hot::DrawCaller::CardPlay,
        ctx.events,
    )?;
    Ok(())
}

/// Whether the current persistent CardPlay owns one complete, single-command
/// Vulnerable step. Its step cursor is committed before the awaited command,
/// so an AfterPowerAmountChanged child may park and return directly to the
/// next card-program step without retaining any step-local suffix.
pub(crate) fn cardplay_vulnerable_step_can_suspend(state: &HotState, catalog: &Catalog) -> bool {
    let Some(Frame::CardPlay { record }) = state.frames.top() else {
        return false;
    };
    let Some(owner) = state.frames.card_play(record) else {
        return false;
    };
    let Ok((_, spec, _)) = persisted_card_play_context(state, catalog, owner) else {
        return false;
    };
    let Some(index) = usize::try_from(owner.next_step)
        .ok()
        .and_then(|next| next.checked_sub(1))
    else {
        return false;
    };
    owner.stage == CardPlayStage::Body
        && !owner.pending_choice
        && catalog.steps(&spec).get(index).is_some_and(|step| {
            step.kind == StepKind::Vulnerable
                && cardplay_plain_vulnerable_source_step_is_exact(spec.row, index)
        })
}

/// Whether adding a physical BaseReplayCount can stay on the exact repeated
/// body surface for this immutable enchantment.
pub(crate) fn repeatable_enchantment_identity_is_exact(spec: &CardSpec) -> bool {
    body_enchantment_is_exact(spec) || inky_shiv_identity_is_exact(spec)
}

/// Run Inky's post-body Weak command for the exact current-build Shiv carveout.
///
/// The base attack already consumed the frozen CardPlay target. Ordinary Shiv
/// therefore resolves the same physical monster identity here (and skips a
/// dead/removed/replaced target), while live Fan of Knives takes a fresh
/// living-roster snapshot after the complete attack. Each Weak application
/// flows through the shared card Type-2 path, preserving Artifact-before-Lamp
/// order and acquisition-ordered AfterPowerAmountChanged listeners.
fn apply_inky_shiv_after_body(
    state: &mut HotState,
    catalog: &Catalog,
    spec: &CardSpec,
    source_uid: u32,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    if body_enchantment_is_exact(spec) {
        return Ok(());
    }
    if !inky_shiv_identity_is_exact(spec)
        || state.inky_attack_damage != 0
        || state.multiplayer_ally_key != 0
    {
        return Err(EngineRefusal::MalformedArgs("exact Inky Shiv"));
    }
    let frozen_target =
        active_card_target_identity(source_uid).ok_or(EngineRefusal::ContinuationNotModeled)?;
    let target_type = effective_target_type(state, catalog, spec, source_uid)?;
    let targets = match target_type {
        CardTargetType::AnyEnemy => {
            let identity = frozen_target.ok_or(EngineRefusal::TargetMismatch { required: true })?;
            let mut matches = state
                .monsters
                .iter()
                .enumerate()
                .filter_map(|(index, monster)| {
                    ((monster.slot, monster.uid) == identity).then_some(index)
                });
            let target = matches.next();
            if matches.next().is_some() {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            target.into_iter().collect::<Vec<_>>()
        }
        CardTargetType::AllEnemies => {
            if frozen_target.is_some() {
                return Err(EngineRefusal::TargetMismatch { required: false });
            }
            state
                .monsters
                .iter()
                .enumerate()
                .filter_map(|(index, monster)| (monster.hp > 0).then_some(index))
                .collect::<Vec<_>>()
        }
        _ => return Err(EngineRefusal::MalformedArgs("Inky Shiv target type")),
    };
    for target in targets {
        super::damage::apply_card_monster_debuff(
            state,
            target,
            PowerId::Weak,
            crate::hot::MiseryToken::Weak,
            1,
            events,
        )?;
    }
    Ok(())
}

/// The static owner HP loss `Corrupted.<OnPlay>d__5` deals after each complete
/// native body. `Corrupted::.cctor` RVA `0xd5f2b` sets the type's static
/// `_damageAmount` to `new Decimal(2)` and nothing else writes it.
const CORRUPTED_SELF_DAMAGE: i64 = 2;

/// Publish one physical Sown/Swift instance's spent identity.
///
/// Native writes `EnchantmentModel.Status = 1` *before* awaiting its command
/// (`<OnPlay>d__2` IL_002a, `<OnPlay>d__4` IL_002a). Python latches the new
/// payload in a local and republishes the physical CardModel through
/// `_set_active_play_card` (frozen Python, deleted #2827) only after the
/// command returns, so the Play-pile copy still reads the unspent id while the
/// GainEnergy/Draw runs. This mirrors Python, not the raw IL order, because
/// Python is the lockstep authority and the one observable that differs —
/// `exact_piles` promotion — is computed by that same publisher against the
/// piles the command left behind.
///
/// Slot 5 carries the spent bit exactly as it does for Glam (see
/// [`spend_glam`]): the interned slot-2 identity stays `SOWN`/`SWIFT`, and the
/// boundary re-spells it `SOWN_USED`/`SWIFT_USED` on the way out. Both ids are
/// already in `engine::cards`' divergent-enchantment tie set, so the promotion
/// below is the same predicate `_has_distinguishable_sort_ties` applies.
fn publish_spent_onplay_enchantment(
    state: &mut HotState,
    catalog: &Catalog,
    uid: u32,
) -> Result<(), EngineRefusal> {
    let mut spent = state.card_states.get(uid);
    if spent.enchantment_state.is_some() {
        return Err(EngineRefusal::MalformedArgs("spent enchantment snapshot"));
    }
    spent.enchantment_state = crate::hot::OptionalNonNegativeI32::from_option(Some(1))
        .expect("one is a valid enchantment state");
    state.card_states.set(uid, spent);
    if !state.exact_piles && super::cards::live_cards_need_exact_piles(state, catalog)? {
        state.exact_piles = true;
    }
    Ok(())
}

/// Run `EnchantmentModel.OnPlay` for the modeled post-body run enchantments.
///
/// Python: `_enchantment_on_play` (frozen, deleted #2827), invoked from
/// `_advance_card_play_frame`'s `after_body` arm — once per replay,
/// after a pending native body has fully resumed and before
/// `CardPlayFinished`. The returned Rupture batch is written straight back
/// into the CardPlay latch, which is what `rupture_batch` is here.
///
/// The four modeled ids and their IL are enumerated on
/// [`onplay_enchantment_identity_is_exact`]. Ordering notes that are not
/// visible in the match below:
///
/// * A `SOWN`/`SWIFT` whose `Status` is already set returns at IL_0025 before
///   touching anything — `_enchantment_on_play` (frozen Python, deleted #2827) reaches the same
///   conclusion by having rewritten the payload to `SOWN_USED`/`SWIFT_USED`
///   and early-returning on it.
/// * `PlayerCmd.GainEnergy` is gated by combat ending and `NoEnergyGainPower`
///   in `_enchantment_on_play`; `CardPileCmd.Draw` owns its own
///   IsEnding/NoDraw/hand-cap/reshuffle semantics, so Swift hands the whole
///   amount to the draw command unconditionally.
/// * Corrupted's hit is **not** ending-gated: it still executes after a native
///   body that killed the last enemy. `_enchantment_on_play` calls
///   player_hp_loss, which has no `s.over` branch. Only owner death suppresses
///   what comes after it, and the caller's `state.hp <= 0` check does that.
fn apply_enchantment_on_play(
    state: &mut HotState,
    catalog: &Catalog,
    spec: &CardSpec,
    uid: u32,
    rupture_registered: bool,
    rupture_batch: &mut i32,
    events: &mut Vec<Event>,
) -> Result<(), EngineRefusal> {
    let Some(enchantment) = spec.identity.enchantment else {
        return Ok(());
    };
    if !matches!(
        enchantment.id,
        EnchantmentId::Sown
            | EnchantmentId::Swift
            | EnchantmentId::Corrupted
            | EnchantmentId::Adroit
    ) {
        return Ok(());
    }
    if !onplay_enchantment_identity_is_exact(spec) {
        return Err(EngineRefusal::MalformedArgs("OnPlay enchantment owner"));
    }
    match enchantment.id {
        EnchantmentId::Sown => {
            if state.card_states.get(uid).enchantment_state.is_some() {
                return Ok(());
            }
            if !state.history.over && !state.fanouts.no_energy_gain() {
                let amount: i16 = enchantment
                    .amount
                    .try_into()
                    .map_err(|_| EngineRefusal::CounterOverflow("Sown energy"))?;
                state.energy = state
                    .energy
                    .checked_add(amount)
                    .ok_or(EngineRefusal::CounterOverflow("Sown energy"))?;
            }
            publish_spent_onplay_enchantment(state, catalog, uid)?;
        }
        EnchantmentId::Swift => {
            if state.card_states.get(uid).enchantment_state.is_some() {
                return Ok(());
            }
            let amount = usize::try_from(enchantment.amount)
                .map_err(|_| EngineRefusal::CounterOverflow("Swift draw"))?;
            // `Swift/<OnPlay>d__4::MoveNext` RVA `0x3885c0` publishes
            // `Status = 1` before it awaits the Draw (IL_001d-0053), so a
            // parked Draw already projects SWIFT_USED (#3115). The Draw is
            // receipt-owned: a Hellraiser or Stratagem choice inside it parks
            // the whole action on its ActionReplay receipt (`engine::puzzle`).
            publish_spent_onplay_enchantment(state, catalog, uid)?;
            super::puzzle::receipt_owned_draw(
                state,
                catalog,
                amount,
                crate::hot::DrawCaller::SwiftEnchantment,
                events,
            )?;
            // The Draw moved cards between piles; the exact-pile promotion is
            // monotone, so re-evaluating it on the settled piles is the same
            // predicate the old post-Draw publication applied.
            if !state.exact_piles && super::cards::live_cards_need_exact_piles(state, catalog)? {
                state.exact_piles = true;
            }
        }
        EnchantmentId::Corrupted => {
            let (_, hp_lost) = super::damage::damage_player_from_active_card_even_if_ending(
                state,
                catalog,
                uid,
                CORRUPTED_SELF_DAMAGE,
                false,
                events,
            )?;
            if rupture_registered && hp_lost > 0 {
                let rupture = state.powers.value(PowerId::Rupture);
                if rupture > 0 {
                    *rupture_batch = rupture_batch
                        .checked_add(rupture)
                        .ok_or(EngineRefusal::CounterOverflow("rupture batch"))?;
                }
            }
        }
        EnchantmentId::Adroit => {
            // `Adroit/<OnPlay>d__6::MoveNext` RVA `0x3880d8` IL_001d-003f:
            // `GainBlock(owner, DynamicVars.Block /* = Amount, props 8 */,
            // cardPlay)`, no Status gate. The card is the CardPlay's source,
            // so the powered card-Block fold (Dexterity, Fasten on a Defend,
            // Unmovable's own-play window, Frail, NoBlock) applies exactly as
            // to the body's own Block, and the gain joins this play's window.
            super::damage::gain_powered_card_block(
                state,
                catalog,
                spec,
                i64::from(enchantment.amount),
                events,
            )?;
        }
        _ => unreachable!("the match above admits exactly four ids"),
    }
    Ok(())
}

#[inline(always)]
pub(crate) fn target_type_requires_choice(spec: &CardSpec, target_type: CardTargetType) -> bool {
    if !matches!(spec.identity.id, CardId::Shiv | CardId::SovereignBlade) {
        return spec.targeted;
    }
    matches!(
        target_type,
        CardTargetType::AnyEnemy | CardTargetType::AnyAlly
    )
}

thread_local! {
    /// Native `Data.activeCards`, scoped to one synchronous Rust call stack.
    /// This is deliberately not canonical state: every entry is pushed only
    /// while one CardPlay is executing and is removed by RAII on every
    /// success/refusal unwind. `play_index` authenticates native
    /// `CardPlay.CurrentPlayIndex` for physical-source readers; it is set
    /// immediately before each synchronous body (including a resumed body)
    /// and never enters canonical state.
    static ACTIVE_PLAYS: RefCell<Vec<ActivePlayContext>> = const { RefCell::new(Vec::new()) };

    /// Test-only source-derived replay evidence. Recording `(uid, index)`
    /// rather than a count is stable across ActionReplay authentication,
    /// which intentionally re-executes the predecessor transcript.
    #[cfg(test)]
    static TEST_BODY_STARTS: RefCell<Vec<(u32, u8)>> = const { RefCell::new(Vec::new()) };
}

#[cfg(test)]
fn record_test_body_start(uid: u32, play_index: u8) {
    TEST_BODY_STARTS.with(|starts| starts.borrow_mut().push((uid, play_index)));
}

#[cfg(test)]
fn reset_test_body_starts() {
    TEST_BODY_STARTS.with(|starts| starts.borrow_mut().clear());
}

#[cfg(test)]
fn test_body_started(uid: u32, play_index: u8) -> bool {
    TEST_BODY_STARTS.with(|starts| starts.borrow().contains(&(uid, play_index)))
}

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
struct ActivePlayContext {
    uid: u32,
    source: CardPlaySource,
    play_index: Option<u8>,
    /// Native `CardPlay.Target` freezes both the roster slot and physical
    /// CreatureModel identity before resources or the first body execute.
    /// Stock can replace a lethal target in the same slot, so consumers must
    /// compare both halves rather than retaining only the compact index.
    target_identity: Option<(i32, u32)>,
    /// Native `CardPlay.Resources.EnergySpent`, captured once by
    /// `SpendResources` and retained across every replay body. Like
    /// `play_index`, this execution-only value is serialized only when a
    /// suspended [`PendingSelection`] owns the continuation.
    spent: Option<i16>,
    /// Pen Nib's result for the current generated CardPlay. Native
    /// `Hook.BeforeCardPlayed` runs once per replay body, so each body
    /// recomputes it and every damage command in that body reads that bit.
    pen_double: bool,
    /// Unsettling Lamp's card-instance latch. Native stores the triggering
    /// CardPlay object; this synchronous context is the exact Rust identity.
    unsettling_lamp_triggered: bool,
    /// Positive card-Block gains recorded by the current generated CardPlay
    /// (one replay body). Unmovable's window excludes exactly these: see
    /// [`active_play_own_block_gains`]. `None` means the body resumed from a
    /// persisted frame mid-way, so its pre-suspension gains are unknown.
    body_block_gains: Option<i16>,
    /// Rupture's `playedCards` entry for this body when no persisted
    /// CardPlay record owns it (#3298). See [`ActiveRuptureBatch`].
    rupture: ActiveRuptureBatch,
}

/// Native `RupturePower.Data.playedCards[card]` for one synchronous CardPlay
/// body that runs without a persisted CardPlay frame (#3298).
///
/// `RupturePower::BeforeCardPlayed` RVA `0xa6e9c` IL_000c-IL_005a adds the
/// played CardModel with value 0 when the card's owner is the power's owner
/// and it is the owner's side. `<AfterDamageReceived>d__9::MoveNext` RVA
/// `0x342fec` IL_0063-IL_0081 tests `playedCards.ContainsKey(cardSource)` for
/// a positive unblocked owner result; a hit adds the live `Amount` to that
/// entry at IL_00fc-IL_0122 and applies nothing, a miss (or a null
/// `cardSource`) applies Strength immediately at IL_0083-IL_00a2.
/// `<AfterCardPlayed>d__10::MoveNext` RVA `0x342ec4` IL_0042-IL_0080 removes
/// the entry and applies its total. The body's own HP loss therefore reaches
/// the owner as one Strength application at AfterCardPlayed, which the
/// ordinary path folds into `CardPlayedPowerLatch::rupture_batch`.
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
enum ActiveRuptureBatch {
    /// No `playedCards` entry: Rupture was absent at BeforeCardPlayed, or the
    /// fan-out has not run yet. HP loss applies Strength immediately.
    Unregistered,
    /// The entry exists and holds this running total.
    Registered(i32),
    /// A persisted CardPlay record owns the entry
    /// (`CardPlayRecord::rupture_batch`), not this execution-only context.
    Persisted,
}

pub(super) struct ActivePlayGuard(u32);

impl ActivePlayGuard {
    #[cfg(test)]
    pub(super) fn enter(uid: u32) -> Result<Self, EngineRefusal> {
        Self::enter_with_source(uid, CardPlaySource::Auto)
    }

    fn enter_with_source(uid: u32, source: CardPlaySource) -> Result<Self, EngineRefusal> {
        ACTIVE_PLAYS.with(|active| {
            let mut active = active.borrow_mut();
            if active.iter().any(|entry| entry.uid == uid) {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            active.push(ActivePlayContext {
                uid,
                source,
                play_index: None,
                target_identity: None,
                spent: None,
                pen_double: false,
                unsettling_lamp_triggered: false,
                body_block_gains: Some(0),
                rupture: ActiveRuptureBatch::Unregistered,
            });
            Ok(Self(uid))
        })
    }

    pub(super) fn set_play_index(&self, play_index: u8) -> Result<(), EngineRefusal> {
        ACTIVE_PLAYS.with(|active| {
            let mut active = active.borrow_mut();
            let Some(current) = active.last_mut() else {
                return Err(EngineRefusal::ContinuationNotModeled);
            };
            if current.uid != self.0 {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            current.play_index = Some(play_index);
            // Each body is a fresh native CardPlay object (see
            // `active_play_own_block_gains`).
            current.body_block_gains = Some(0);
            Ok(())
        })
    }

    pub(super) fn set_spent(&self, spent: i16) -> Result<(), EngineRefusal> {
        ACTIVE_PLAYS.with(|active| {
            let mut active = active.borrow_mut();
            let Some(current) = active.last_mut() else {
                return Err(EngineRefusal::ContinuationNotModeled);
            };
            if current.uid != self.0 || current.spent.is_some() || spent < 0 {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            current.spent = Some(spent);
            Ok(())
        })
    }

    /// Publish this body's Rupture `playedCards` registration, as decided by
    /// the BeforeCardPlayed fan-out's `rupture_registered` latch.
    fn set_rupture_registered(&self, registered: bool) -> Result<(), EngineRefusal> {
        ACTIVE_PLAYS.with(|active| {
            let mut active = active.borrow_mut();
            let Some(current) = active.last_mut() else {
                return Err(EngineRefusal::ContinuationNotModeled);
            };
            if current.uid != self.0 || current.rupture == ActiveRuptureBatch::Persisted {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            current.rupture = if registered {
                ActiveRuptureBatch::Registered(0)
            } else {
                ActiveRuptureBatch::Unregistered
            };
            Ok(())
        })
    }

    /// Take this body's batched Rupture total, leaving the entry
    /// unregistered until the next body's BeforeCardPlayed fan-out.
    fn take_rupture_batch(&self) -> Result<i32, EngineRefusal> {
        ACTIVE_PLAYS.with(|active| {
            let mut active = active.borrow_mut();
            let Some(current) = active.last_mut() else {
                return Err(EngineRefusal::ContinuationNotModeled);
            };
            if current.uid != self.0 {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            let batch = match current.rupture {
                ActiveRuptureBatch::Registered(batch) => batch,
                ActiveRuptureBatch::Unregistered => 0,
                ActiveRuptureBatch::Persisted => {
                    return Err(EngineRefusal::ContinuationNotModeled);
                }
            };
            current.rupture = ActiveRuptureBatch::Unregistered;
            Ok(batch)
        })
    }

    fn set_pen_double(&self, pen_double: bool) -> Result<(), EngineRefusal> {
        ACTIVE_PLAYS.with(|active| {
            let mut active = active.borrow_mut();
            let Some(current) = active.last_mut() else {
                return Err(EngineRefusal::ContinuationNotModeled);
            };
            if current.uid != self.0 {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            current.pen_double = pen_double;
            Ok(())
        })
    }

    pub(super) fn set_target_identity(
        &self,
        target_identity: Option<(i32, u32)>,
    ) -> Result<(), EngineRefusal> {
        ACTIVE_PLAYS.with(|active| {
            let mut active = active.borrow_mut();
            let Some(current) = active.last_mut() else {
                return Err(EngineRefusal::ContinuationNotModeled);
            };
            if current.uid != self.0 || current.target_identity.is_some() {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            current.target_identity = target_identity;
            Ok(())
        })
    }
}

/// Whether the innermost physical CardPlay already triggered Unsettling Lamp.
pub(crate) fn active_card_lamp_triggered() -> Option<bool> {
    ACTIVE_PLAYS.with(|active| {
        active
            .borrow()
            .last()
            .map(|entry| entry.unsettling_lamp_triggered)
    })
}

/// Whether any live synchronous or persisted CardPlay owns Unsettling Lamp.
pub(crate) fn active_card_lamp_owner_exists(state: &HotState) -> bool {
    ACTIVE_PLAYS.with(|active| {
        active
            .borrow()
            .iter()
            .any(|entry| entry.unsettling_lamp_triggered)
    }) || state.frames.as_slice().iter().any(|frame| {
        let crate::frame::Frame::CardPlay { record } = *frame else {
            return false;
        };
        state
            .frames
            .card_play(record)
            .is_some_and(|play| play.lamp_owner)
    })
}

struct PersistedActivePlayGuard {
    depth: usize,
    /// Synchronous plays already active below this guard's persisted ones.
    /// Zero except for an inline Centennial Puzzle resume (#3114).
    base: usize,
}

impl PersistedActivePlayGuard {
    fn enter(state: &HotState) -> Result<Self, EngineRefusal> {
        Self::enter_frames(state, None)
    }

    /// Activate only the CardPlay frames above a Centennial Puzzle Draw at
    /// frame `puzzle_depth`, on top of the synchronous plays whose Rust
    /// bodies are still running beneath the Puzzle's damage caller (#3114).
    fn enter_above(state: &HotState, puzzle_depth: usize) -> Result<Self, EngineRefusal> {
        Self::enter_frames(state, Some(puzzle_depth))
    }

    fn enter_frames(state: &HotState, puzzle_depth: Option<usize>) -> Result<Self, EngineRefusal> {
        ACTIVE_PLAYS.with(|active| {
            let base = active.borrow().len();
            if puzzle_depth.is_none() && base != 0 {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            if !state
                .frames
                .continuation_store_is_valid(state.pending.as_deref())
            {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            let skip = puzzle_depth.unwrap_or(0);
            let mut lamp_owners = 0_usize;
            let mut active_uids = active
                .borrow()
                .iter()
                .map(|entry| entry.uid)
                .collect::<Vec<_>>();
            for frame in state.frames.as_slice().iter().skip(skip) {
                let crate::frame::Frame::CardPlay { record } = *frame else {
                    continue;
                };
                let play = state
                    .frames
                    .card_play(record)
                    .ok_or(EngineRefusal::ContinuationNotModeled)?;
                if state.card_play_physical_owner(play).is_none() {
                    return Err(EngineRefusal::ContinuationNotModeled);
                }
                if active_uids.contains(&play.uid) {
                    return Err(EngineRefusal::ContinuationNotModeled);
                }
                active_uids.push(play.uid);
                lamp_owners += usize::from(play.lamp_owner);
                let _: u8 = play
                    .play_index
                    .try_into()
                    .map_err(|_| EngineRefusal::ContinuationNotModeled)?;
                let _: i16 = play
                    .spent
                    .try_into()
                    .map_err(|_| EngineRefusal::ContinuationNotModeled)?;
            }
            if lamp_owners > 1 || lamp_owners == 1 && !state.fanouts.unsettling_lamp_available() {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            let mut active = active.borrow_mut();
            for frame in state.frames.as_slice().iter().skip(skip) {
                let crate::frame::Frame::CardPlay { record } = *frame else {
                    continue;
                };
                let play = state
                    .frames
                    .card_play(record)
                    .expect("validated immutable CardPlay record");
                active.push(ActivePlayContext {
                    uid: play.uid,
                    source: play.source,
                    play_index: Some(
                        play.play_index
                            .try_into()
                            .expect("validated CardPlay play index"),
                    ),
                    target_identity: play.target.map(|(slot, uid, _)| (slot, uid)),
                    spent: Some(
                        play.spent
                            .try_into()
                            .expect("validated CardPlay spent amount"),
                    ),
                    pen_double: play.pen_double,
                    unsettling_lamp_triggered: play.lamp_owner,
                    // The persisted wire does not carry the resumed body's
                    // earlier Block gains; a StartBody resume resets this
                    // in `set_top_play_index`.
                    body_block_gains: None,
                    rupture: ActiveRuptureBatch::Persisted,
                });
            }
            let depth = active.len();
            Ok(Self { depth, base })
        })
    }

    fn set_top_play_index(&self, uid: u32, play_index: u8) -> Result<(), EngineRefusal> {
        ACTIVE_PLAYS.with(|active| {
            let mut active = active.borrow_mut();
            let current = active
                .last_mut()
                .ok_or(EngineRefusal::ContinuationNotModeled)?;
            if current.uid != uid {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            current.play_index = Some(play_index);
            current.body_block_gains = Some(0);
            Ok(())
        })
    }

    fn set_top_pen_double(&self, uid: u32, pen_double: bool) -> Result<(), EngineRefusal> {
        ACTIVE_PLAYS.with(|active| {
            let mut active = active.borrow_mut();
            let current = active
                .last_mut()
                .ok_or(EngineRefusal::ContinuationNotModeled)?;
            if current.uid != uid {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            current.pen_double = pen_double;
            Ok(())
        })
    }

    fn pop_top(&self, uid: u32) -> Result<(), EngineRefusal> {
        ACTIVE_PLAYS.with(|active| {
            let mut active = active.borrow_mut();
            if active.last().is_none_or(|current| current.uid != uid) {
                return Err(EngineRefusal::ContinuationNotModeled);
            }
            active.pop();
            Ok(())
        })
    }
}

impl Drop for PersistedActivePlayGuard {
    fn drop(&mut self) {
        ACTIVE_PLAYS.with(|active| {
            let mut active = active.borrow_mut();
            debug_assert!(active.len() <= self.depth);
            active.truncate(self.base);
        });
    }
}

/// Latch Unsettling Lamp to the innermost physical CardPlay.
pub(crate) fn trigger_active_card_lamp() -> Result<(), EngineRefusal> {
    ACTIVE_PLAYS.with(|active| {
        let mut active = active.borrow_mut();
        let current = active
            .last_mut()
            .ok_or(EngineRefusal::ContinuationNotModeled)?;
        current.unsettling_lamp_triggered = true;
        Ok(())
    })
}

/// Run a cold command rehearsal without publishing execution-only CardPlay
/// state.
///
/// [`HotState`] cloning cannot capture `ACTIVE_PLAYS`. In particular, a
/// rehearsed card-sourced Type-2 command can latch Unsettling Lamp on the
/// innermost physical play before a later Draw refusal. Snapshot the complete
/// synchronous stack, require the rehearsal to preserve its execution shape,
/// and restore every latch on both success and refusal before the real command
/// is allowed to run.
pub(crate) fn rehearse_preserving_active_plays<T>(
    operation: impl FnOnce() -> Result<T, EngineRefusal>,
) -> Result<T, EngineRefusal> {
    let snapshot = ACTIVE_PLAYS.with(|active| active.borrow().clone());
    let result = operation();
    let shape_is_exact = ACTIVE_PLAYS.with(|active| {
        let mut active = active.borrow_mut();
        let exact = active.len() == snapshot.len()
            && active
                .iter()
                .zip(&snapshot)
                .enumerate()
                .all(|(index, (current, saved))| {
                    current.uid == saved.uid
                        && current.play_index == saved.play_index
                        && current.target_identity == saved.target_identity
                        && current.spent == saved.spent
                        && current.pen_double == saved.pen_double
                        && (index + 1 == snapshot.len()
                            || current.unsettling_lamp_triggered == saved.unsettling_lamp_triggered)
                });
        *active = snapshot;
        exact
    });
    if !shape_is_exact {
        return Err(EngineRefusal::ContinuationNotModeled);
    }
    result
}

/// Native `UnsettlingLamp.AfterCardPlayed`: consume the relic and clear the
/// per-play latch before a possible replay body begins.
fn finish_unsettling_lamp(state: &mut HotState) -> Result<(), EngineRefusal> {
    if state.fanouts.player_hooks_deactivated() {
        return Ok(());
    }
    ACTIVE_PLAYS.with(|active| {
        let mut active = active.borrow_mut();
        let current = active
            .last_mut()
            .ok_or(EngineRefusal::ContinuationNotModeled)?;
        if current.unsettling_lamp_triggered {
            current.unsettling_lamp_triggered = false;
            state.fanouts.set_unsettling_lamp_available(false);
        }
        Ok(())
    })
}

impl Drop for ActivePlayGuard {
    fn drop(&mut self) {
        ACTIVE_PLAYS.with(|active| {
            let popped = active.borrow_mut().pop().map(|entry| entry.uid);
            debug_assert_eq!(popped, Some(self.0));
        });
    }
}

/// Whether any synchronous native CardPlay frame owns `uid`.
///
/// Unlike [`active_card_current_context`], this deliberately searches the
/// complete nested stack. Commands that move physical cards must not detach a
/// suspended parent merely because a child CardPlay is currently innermost.
pub(crate) fn active_play_stack_contains_uid(uid: u32) -> bool {
    ACTIVE_PLAYS.with(|active| active.borrow().iter().any(|entry| entry.uid == uid))
}

/// Whether execution is currently below an authenticated CardPlay boundary.
///
/// Public catalogless listener helpers use this only to distinguish their
/// direct fail-closed API from a nested call whose outer CardPlay already
/// authenticated Dampen and owns the whole-action checkpoint.
pub(crate) fn active_play_transaction_is_running() -> bool {
    ACTIVE_PLAYS.with(|active| !active.borrow().is_empty())
}

pub(crate) fn active_play_current_uid() -> Option<u32> {
    ACTIVE_PLAYS.with(|active| active.borrow().last().map(|entry| entry.uid))
}

pub(crate) fn active_play_pen_double() -> bool {
    ACTIVE_PLAYS.with(|active| active.borrow().last().is_some_and(|entry| entry.pen_double))
}

/// Which of this turn's card-Block gains belong to the current CardPlay.
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub(crate) enum OwnBlockGains {
    /// No CardPlay is executing (a direct body call): native's `cardPlay`
    /// argument is null and nothing is excluded.
    NoPlay,
    /// The innermost generated CardPlay has recorded this many gains.
    Known(i16),
    /// The innermost body resumed from a persisted frame mid-way.
    Unknown,
}

/// Unmovable's exclusion set: the innermost CardPlay's own Block gains.
///
/// `UnmovablePower::ModifyBlockMultiplicative` (RVA `0xaa578`,
/// IL_005b–0096) counts this turn's `BlockGainedEntry` rows through the
/// filter `<ModifyBlockMultiplicative>b__0` (RVA `0x34a534`), whose last
/// conjunct (IL_0051–0062) is `entry.CardPlay != cardPlay`: gains recorded by
/// the play now gaining Block never close the window. A replay body is a
/// separate CardPlay object: `CardModel/<OnPlayWrapper>d__339::MoveNext`
/// (RVA `0x31b8d0`) runs `newobj CardPlay::.ctor` at IL_052b inside the
/// `PlayIndex` loop (back edge IL_0909 → IL_0428), so an earlier body's
/// gains do count against a later body.
pub(crate) fn active_play_own_block_gains() -> OwnBlockGains {
    ACTIVE_PLAYS.with(|active| match active.borrow().last() {
        None => OwnBlockGains::NoPlay,
        Some(entry) => entry
            .body_block_gains
            .map_or(OwnBlockGains::Unknown, OwnBlockGains::Known),
    })
}

/// Record one positive card-Block gain against the innermost CardPlay.
pub(crate) fn note_active_play_block_gain() -> Result<(), EngineRefusal> {
    ACTIVE_PLAYS.with(|active| {
        let mut active = active.borrow_mut();
        if let Some(current) = active.last_mut()
            && let Some(gains) = current.body_block_gains
        {
            current.body_block_gains = Some(
                gains
                    .checked_add(1)
                    .ok_or(EngineRefusal::CounterOverflow("card_block_gains"))?,
            );
        }
        Ok(())
    })
}

/// Whether the synchronous/persisted play stack is a descendant of exactly
/// one Sly card selected by the live Tools effect.
pub(crate) fn active_tools_sly_descendant(selected_uids: &[u32]) -> bool {
    ACTIVE_PLAYS.with(|active| {
        active
            .borrow()
            .iter()
            .filter(|entry| {
                entry.source == CardPlaySource::SlyDiscard && selected_uids.contains(&entry.uid)
            })
            .count()
            == 1
    })
}

fn auto_play_uid_is_active(uid: u32) -> bool {
    active_play_stack_contains_uid(uid)
}

/// Return native `CardPlay.CurrentPlayIndex` only for the uniquely active
/// physical source. A `None` result is deliberately distinct from index zero:
/// physical-source consumers must refuse rather than reconstruct this
/// noncanonical execution context from unrelated history counters.
pub(crate) fn active_card_play_index(uid: u32) -> Option<u8> {
    ACTIVE_PLAYS.with(|active| {
        active
            .borrow()
            .iter()
            .find(|entry| entry.uid == uid)
            .and_then(|entry| entry.play_index)
    })
}

/// Return the frozen native target identity only for the uniquely active
/// physical CardPlay. The outer `Option` authenticates the active source;
/// its inner value distinguishes a non-targeted play from a targeted one.
pub(crate) fn active_card_target_identity(uid: u32) -> Option<Option<(i32, u32)>> {
    ACTIVE_PLAYS.with(|active| {
        active
            .borrow()
            .iter()
            .find(|entry| entry.uid == uid)
            .map(|entry| entry.target_identity)
    })
}

/// Whether a concrete roster entry is still the Creature captured by the
/// current CardPlay. A missing active context is reserved for private body
/// tests and non-CardPlay callers; an active non-targeted play likewise has
/// no identity constraint.
pub(crate) fn active_card_target_is_current(
    state: &HotState,
    source_uid: u32,
    target: usize,
) -> bool {
    let Some(Some(identity)) = active_card_target_identity(source_uid) else {
        return true;
    };
    state
        .monsters
        .get(target)
        .is_some_and(|monster| (monster.slot, monster.uid) == identity)
}

/// Compact read-only snapshot of one current CardPlay frame.
pub(crate) type ActiveCardCurrentContext = (Option<u8>, Option<(i32, u32)>);

/// Return the innermost native CardPlay's body index and frozen target only
/// when that current frame belongs to `uid`. Unlike the older individual
/// readers, this deliberately does not search through suspended parent plays.
pub(crate) fn active_card_current_context(uid: u32) -> Option<ActiveCardCurrentContext> {
    ACTIVE_PLAYS.with(|active| {
        active.borrow().last().and_then(|current| {
            (current.uid == uid).then_some((current.play_index, current.target_identity))
        })
    })
}

/// Native `CardPlay.Resources.EnergyValue` of one play, as distinct from
/// `EnergySpent` (#3124).
///
/// v0.111.0 (DLL 9cb4f1ad): exactly two sites write `ResourceInfo`
/// (`set_EnergyValue` RVA `0x11f54e` has no other caller).
/// `PlayCardAction/<ExecuteAction>d__25::MoveNext` RVA `0x3d5458`
/// IL_0342-IL_0357 stores `SpendResources`' paid Energy (tuple `Item1`) as
/// both `EnergySpent` and `EnergyValue`. `CardCmd/<AutoPlay>d__0::MoveNext`
/// RVA `0x3df9d4` IL_05b7-IL_05de stores `EnergySpent = 0` but
/// `EnergyValue = card.EnergyCost.GetAmountToSpend()`, read after
/// `Hook.BeforeCardAutoPlayed` (IL_055a, whose only listener is the
/// `SkillSilent1Achievement` achievement). `CardEnergyCost::GetAmountToSpend`
/// RVA `0x11e162` returns the owner's live Energy for a CostsX card
/// (IL_0001-IL_0024) and otherwise `Max(0, GetWithModifiers(All))`
/// (IL_0025-IL_0032), which is [`resolved_energy_cost`] clamped at zero.
/// `OnPlayWrapper` hands that one `ResourceInfo` to every replay body, so the
/// value is captured once here, beside `EnergySpent`.
///
/// The represented reader is Intimidating Helmet's `BeforeCardPlayed`
/// (`<BeforeCardPlayed>d__6::MoveNext` RVA `0x326e4c` IL_003d-IL_0060:
/// `Resources.EnergyValue >= DynamicVars.Energy(2)`), so an auto-played
/// 2-cost card grants its Block although it paid nothing.
///
/// An AutoPlay value past `i16::MAX` (a forged or modded cost row; the
/// engine keeps costs as `i64`) saturates rather than refusing: the only
/// reader compares it with 2, which saturation preserves exactly.
fn card_play_energy_value(
    manual: bool,
    spec: &CardSpec,
    spent: i16,
    resolved_cost: i64,
    auto_x_value: i64,
) -> i16 {
    if manual {
        return spent;
    }
    let value = if spec.x_cost {
        auto_x_value
    } else {
        resolved_cost
    };
    i16::try_from(value.clamp(0, i64::from(i16::MAX))).unwrap_or(i16::MAX)
}

/// `CardPlay.Resources.EnergyValue` recovered from a persisted play record,
/// or `None` when the record cannot carry it (#3168).
///
/// A manual play's `EnergyValue` is its `EnergySpent`, which the record keeps
/// as `spent`. An AutoPlay's is the cost it resolved at its entry
/// ([`card_play_energy_value`]), which no persisted field carries; each
/// resumed reader refuses by name when it would read `None`.
fn persisted_card_play_energy_value(
    record: &crate::hot::CardPlayRecord,
) -> Result<Option<i16>, EngineRefusal> {
    if record.source != CardPlaySource::Manual {
        return Ok(None);
    }
    i16::try_from(record.spent)
        .map(Some)
        .map_err(|_| EngineRefusal::ContinuationNotModeled)
}

/// Return native `CardPlay.Resources.EnergySpent` only for the uniquely
/// active physical source. The value is captured after resource resolution,
/// never reconstructed from printed or currently modified card cost.
pub(super) fn active_card_energy_spent(uid: u32) -> Option<i16> {
    ACTIVE_PLAYS.with(|active| {
        active
            .borrow()
            .iter()
            .find(|entry| entry.uid == uid)
            .and_then(|entry| entry.spent)
    })
}

/// Authenticate the synchronous active-card shape at Apotheosis's public
/// pre-action seam.
///
/// A top-level manual/direct AutoPlay enters with no active parent. Nested
/// AutoPlay is also exact because every parent entry is an engine-private
/// [`ActivePlayGuard`] with a resolved body index: the outer [`CardSpec`] and
/// compiled program were copied before the child began, exactly matching the
/// native async state's frozen continuation when Apotheosis upgrades that
/// outer physical object. The child must still be a different, uniquely live
/// physical uid before any resources or events can publish.
pub(crate) fn apotheosis_incoming_context_is_exact(
    state: &HotState,
    _catalog: &Catalog,
    source_uid: u32,
) -> bool {
    ACTIVE_PLAYS.with(|active| {
        let active = active.borrow();
        active.is_empty()
            || (active
                .iter()
                .all(|parent| parent.play_index.is_some() && parent.uid != source_uid)
                && unique_live_card_location(state, source_uid)
                    .is_ok_and(|located| located.is_some()))
    })
}

/// Repeat Apotheosis's active-card authentication at its body seam.
pub(crate) fn apotheosis_body_context_is_exact(
    state: &HotState,
    _catalog: &Catalog,
    source_uid: u32,
) -> bool {
    ACTIVE_PLAYS.with(|active| {
        let active = active.borrow();
        active.last().is_some_and(|current| {
            current.uid == source_uid
                && current.play_index.is_some()
                && active[..active.len() - 1]
                    .iter()
                    .all(|parent| parent.play_index.is_some() && parent.uid != source_uid)
                && unique_live_card_location(state, source_uid)
                    .is_ok_and(|located| located.is_some())
        })
    })
}

