    /// A body-zero `StartBody` record never comes from this engine, and its
    /// Pen Nib counter provenance is ambiguous: an owned Pen Nib refuses it,
    /// while the identical record without Pen Nib starts its body.
    #[test]
    fn pen_nib_refuses_a_body_zero_persisted_start_body_attack() {
        let strike = identity(CardId::StrikeIronclad, 0);
        for pen_nib in [false, true] {
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(strike).unwrap();
            if pen_nib {
                builder.set_relics(&[RelicId::RelicPenNib]).unwrap();
            }
            let catalog = builder.build();
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.next_card_uid = 2;
            assert!(state.fanouts.set_pen_nib(3));
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 100));
            state.piles.get_mut(PileId::Play).make_mut().push(HotCard {
                uid: 1,
                atom,
                flags: 0,
            });
            let mut record = finished_driver_record(1);
            record.stage = CardPlayStage::StartBody;
            record.latch_kind = CardPlayLatchKind::Empty;
            record.next_step = 0;
            record.source = CardPlaySource::Auto;
            record.target = Some((0, 0, None));
            state.frames.push_card_play(&record).unwrap();
            let active = PersistedActivePlayGuard::enter(&state).unwrap();
            let result = advance_top_card_play_one(&mut state, &catalog, &mut Vec::new(), &active);
            if pen_nib {
                assert_eq!(result, Err(EngineRefusal::ContinuationNotModeled));
            } else {
                result.unwrap();
                assert_eq!(state.fanouts.pen_nib(), 3);
            }
        }
    }

    /// #3124: a resumed `StartBody` keeps only `EnergySpent`. A manual play's
    /// `EnergyValue` is that same payment, so Intimidating Helmet reads it;
    /// an AutoPlay's `EnergyValue` (its entry-time resolved cost) is not
    /// persisted, so an owned Helmet refuses the resumed body by name before
    /// anything moves.
    #[test]
    fn intimidating_helmet_resumed_start_body_uses_manual_payment_or_refuses_autoplay() {
        let defend = identity(CardId::DefendIronclad, 0);
        for source in [CardPlaySource::Manual, CardPlaySource::Auto] {
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(defend).unwrap();
            builder
                .set_relics(&[RelicId::RelicIntimidatingHelmet])
                .unwrap();
            let catalog = builder.build();
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.next_card_uid = 2;
            state.piles.get_mut(PileId::Play).make_mut().push(HotCard {
                uid: 1,
                atom,
                flags: 0,
            });
            let mut record = finished_driver_record(1);
            record.stage = CardPlayStage::StartBody;
            record.latch_kind = CardPlayLatchKind::Empty;
            record.next_step = 0;
            record.plays = 2;
            record.play_index = 1;
            record.spent = 2;
            record.source = source;
            state.frames.push_card_play(&record).unwrap();
            let active = PersistedActivePlayGuard::enter(&state).unwrap();
            let result = advance_top_card_play_one(&mut state, &catalog, &mut Vec::new(), &active);
            if source == CardPlaySource::Manual {
                result.unwrap();
                // One step runs StartBody's BeforeCardPlayed walk, not the
                // body: this is Helmet's 4 alone, gated by the payment.
                assert_eq!(
                    state.block, 4,
                    "manual EnergyValue is the persisted payment"
                );
            } else {
                assert_eq!(
                    result,
                    Err(EngineRefusal::HookNotModeled {
                        relic: RelicId::RelicIntimidatingHelmet,
                        event: HookEvent::BeforeCardPlayed,
                    })
                );
                assert_eq!(state.block, 0);
            }
        }
    }

    /// #3124: Intimidating Helmet gates on native `CardPlay.Resources
    /// .EnergyValue`, not `EnergySpent`. A manual play's value is what it paid;
    /// an AutoPlay pays nothing but carries `GetAmountToSpend` — the resolved
    /// cost, or the live Energy for an X card. The corpus witness is Beat
    /// Down auto-playing a 2-cost Strike (`faba5a5e39e4b9b9`, Block 32 -> 36).
    #[test]
    fn intimidating_helmet_reads_energy_value_for_manual_and_autoplay() {
        // (card, manual, starting energy, expected Helmet Block)
        let cases = [
            (CardId::Bash, true, 3, 4),
            (CardId::Bash, false, 0, 4),
            (CardId::StrikeIronclad, true, 3, 0),
            (CardId::StrikeIronclad, false, 3, 0),
            (CardId::Whirlwind, true, 2, 4),
            (CardId::Whirlwind, false, 2, 4),
            (CardId::Whirlwind, false, 1, 0),
        ];
        for (id, manual, energy, block) in cases {
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(identity(id, 0)).unwrap();
            builder
                .set_relics(&[RelicId::RelicIntimidatingHelmet])
                .unwrap();
            let catalog = builder.build();
            let card = HotCard {
                uid: 7,
                atom,
                flags: 0,
            };
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.energy = energy;
            state.next_card_uid = 8;
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 200));
            let target = catalog.spec(atom).unwrap().targeted.then_some(0);
            let source = if manual {
                PileId::Hand
            } else {
                PileId::Discard
            };
            state.piles.get_mut(source).make_mut().push(card);
            let mut events = Vec::new();
            if manual {
                play_card(&mut state, &catalog, card.uid, target, None, &mut events).unwrap();
            } else {
                play_card_with_work(
                    &mut state,
                    &catalog,
                    card.uid,
                    target,
                    None,
                    &mut events,
                    PlaySource {
                        pile: source,
                        provenance: PlayProvenance::Auto,
                        force_exhaust: false,
                        frozen: Some(card),
                        allow_dead_target: false,
                    },
                )
                .unwrap();
            }
            assert_eq!(state.block, block, "{id:?} manual={manual} energy={energy}");
            if !manual {
                assert_eq!(state.energy, energy, "{id:?}: AutoPlay spends nothing");
            }
        }
    }

    /// #3124: `EnergyValue` is the payment for a manual play, the resolved
    /// cost (clamped at zero) or live X for an AutoPlay, and an AutoPlay cost
    /// past `i16::MAX` saturates, which Helmet's `>= 2` gate reads exactly.
    #[test]
    fn card_play_energy_value_arms() {
        let mut builder = CatalogBuilder::new();
        let bash = builder.intern(identity(CardId::Bash, 0)).unwrap();
        let whirlwind = builder.intern(identity(CardId::Whirlwind, 0)).unwrap();
        let catalog = builder.build();
        let bash = catalog.spec(bash).unwrap();
        let whirlwind = catalog.spec(whirlwind).unwrap();
        assert_eq!(card_play_energy_value(true, bash, 1, 2, 0), 1);
        assert_eq!(card_play_energy_value(false, bash, 0, 2, 0), 2);
        assert_eq!(card_play_energy_value(false, bash, 0, -1, 0), 0);
        assert_eq!(
            card_play_energy_value(false, bash, 0, i64::MAX, 0),
            i16::MAX
        );
        assert_eq!(card_play_energy_value(false, whirlwind, 0, 0, 3), 3);
        assert_eq!(card_play_energy_value(true, whirlwind, 3, 0, 0), 3);
    }

    /// Play `uid` manually from Hand, or as a direct AutoPlay from Discard.
    fn play_manual_or_auto_3168(
        state: &mut HotState,
        catalog: &Catalog,
        uid: u32,
        target: Option<u8>,
        manual: bool,
        events: &mut Vec<Event>,
    ) -> Result<(), EngineRefusal> {
        if manual {
            return play_card(state, catalog, uid, target, None, events);
        }
        let card = *state
            .piles
            .get(PileId::Discard)
            .as_slice()
            .iter()
            .find(|card| card.uid == uid)
            .expect("AutoPlay source is in Discard");
        play_card_with_work(
            state,
            catalog,
            uid,
            target,
            None,
            events,
            PlaySource {
                pile: PileId::Discard,
                provenance: PlayProvenance::Auto,
                force_exhaust: false,
                frozen: Some(card),
                allow_dead_target: false,
            },
        )
    }

    /// #3168: Ivory Tile gates on `EnergyValue >= 3`, not `EnergySpent`. A
    /// manual 3-cost play and an AutoPlay of the same card (which pays
    /// nothing) both gain the Energy; a 1-cost card never does; an X card
    /// auto-played reads the live Energy.
    #[test]
    fn ivory_tile_reads_energy_value_for_manual_and_autoplay() {
        // (card, manual, starting energy, expected final energy)
        let cases = [
            (CardId::Bludgeon, true, 3, 1),
            (CardId::Bludgeon, false, 0, 1),
            (CardId::StrikeIronclad, true, 3, 2),
            (CardId::StrikeIronclad, false, 3, 3),
            (CardId::Whirlwind, false, 3, 4),
            (CardId::Whirlwind, false, 2, 2),
        ];
        for (id, manual, energy, expected) in cases {
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(identity(id, 0)).unwrap();
            builder.set_relics(&[RelicId::RelicIvoryTile]).unwrap();
            let catalog = builder.build();
            let card = HotCard {
                uid: 7,
                atom,
                flags: 0,
            };
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.energy = energy;
            state.next_card_uid = 8;
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 500));
            let target = catalog.spec(atom).unwrap().targeted.then_some(0);
            let source = if manual {
                PileId::Hand
            } else {
                PileId::Discard
            };
            state.piles.get_mut(source).make_mut().push(card);
            play_manual_or_auto_3168(
                &mut state,
                &catalog,
                card.uid,
                target,
                manual,
                &mut Vec::new(),
            )
            .unwrap();
            assert_eq!(
                state.energy, expected,
                "{id:?} manual={manual} energy={energy}"
            );
        }
    }

    /// #3168: Right Hand Hand returns from Discard on `EnergyValue >= 2`. An
    /// auto-played 2-cost Bash pays nothing but still returns it; a 1-cost
    /// Strike does not, manual or auto.
    #[test]
    fn right_hand_hand_reads_energy_value_for_manual_and_autoplay() {
        // (card, manual, Right Hand Hand returns)
        let cases = [
            (CardId::Bash, true, true),
            (CardId::Bash, false, true),
            (CardId::StrikeIronclad, true, false),
            (CardId::StrikeIronclad, false, false),
        ];
        for (id, manual, returns) in cases {
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(identity(id, 0)).unwrap();
            let right_hand = builder.intern(identity(CardId::RightHandHand, 0)).unwrap();
            let catalog = builder.build();
            let card = HotCard {
                uid: 7,
                atom,
                flags: 0,
            };
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.energy = 3;
            state.next_card_uid = 9;
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 500));
            state
                .piles
                .get_mut(PileId::Discard)
                .make_mut()
                .push(HotCard {
                    uid: 8,
                    atom: right_hand,
                    flags: 0,
                });
            let source = if manual {
                PileId::Hand
            } else {
                PileId::Discard
            };
            state.piles.get_mut(source).make_mut().push(card);
            play_manual_or_auto_3168(
                &mut state,
                &catalog,
                card.uid,
                Some(0),
                manual,
                &mut Vec::new(),
            )
            .unwrap();
            let in_hand = state
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .any(|card| card.uid == 8);
            assert_eq!(in_hand, returns, "{id:?} manual={manual}");
            if !manual {
                assert_eq!(state.energy, 3, "{id:?}: AutoPlay spends nothing");
            }
        }
    }

    /// #3168: Feral's result-location gate and its zero-Energy start counter
    /// both read `EnergyValue`. An auto-played 1-cost Strike pays nothing but
    /// has `EnergyValue` 1, so it neither returns to Hand nor counts. An
    /// auto-played Whirlwind's `EnergyValue` is the live Energy: at zero it
    /// returns and counts, at three it does neither. A manual Strike returns
    /// and counts only when Free Attack makes it pay nothing.
    #[test]
    fn feral_reads_energy_value_for_manual_and_autoplay() {
        let feral = identity(CardId::Feral, 0);
        // (card, manual, energy, Free Attack, returns to Hand)
        let cases = [
            (CardId::StrikeIronclad, true, 3, true, true),
            (CardId::StrikeIronclad, true, 3, false, false),
            (CardId::StrikeIronclad, false, 3, false, false),
            (CardId::Whirlwind, false, 0, false, true),
            (CardId::Whirlwind, false, 3, false, false),
        ];
        for (id, manual, energy, free_attack, returns) in cases {
            let attack = identity(id, 0);
            let mut builder = CatalogBuilder::new();
            builder.intern(feral).unwrap();
            let atom = builder.intern(attack).unwrap();
            let catalog = builder.build();
            let mut state = state_with_card(&catalog, feral, 90);
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 500));
            play_card(&mut state, &catalog, 90, None, None, &mut Vec::new()).unwrap();
            assert_eq!(state.powers.value(PowerId::Feral), 1);
            assert_eq!(state.powers.value(PowerId::FeralUsed), 0);
            state.energy = energy;
            if free_attack {
                state.powers.set(PowerId::FreeAttack, SlotWire::Int, 1);
            }
            let source = if manual {
                PileId::Hand
            } else {
                PileId::Discard
            };
            state.piles.get_mut(source).make_mut().push(HotCard {
                uid: 91,
                atom,
                flags: 0,
            });
            let target = catalog.spec(atom).unwrap().targeted.then_some(0);
            play_manual_or_auto_3168(&mut state, &catalog, 91, target, manual, &mut Vec::new())
                .unwrap_or_else(|refusal| panic!("{id:?} manual={manual}: {refusal:?}"));
            let label = format!("{id:?} manual={manual} energy={energy}");
            let in_hand = state
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .any(|card| card.uid == 91);
            assert_eq!(in_hand, returns, "{label}");
            assert_eq!(
                state.powers.value(PowerId::FeralUsed),
                i32::from(returns),
                "{label}"
            );
            assert_eq!(
                state.history.zero_energy_attack_plays_started_this_turn,
                i16::from(returns),
                "{label}: the counter reads EnergyValue"
            );
            if !manual {
                assert_eq!(state.energy, energy, "{label}: AutoPlay spends nothing");
            }
        }
    }

    /// #3168: a persisted record carries `EnergyValue` only for a manual play
    /// (its `spent`); an AutoPlay's is not persisted.
    #[test]
    fn persisted_card_play_energy_value_arms() {
        let mut record = finished_driver_record(1);
        record.spent = 3;
        record.source = CardPlaySource::Manual;
        assert_eq!(persisted_card_play_energy_value(&record), Ok(Some(3)));
        record.spent = i32::from(i16::MAX) + 1;
        assert_eq!(
            persisted_card_play_energy_value(&record),
            Err(EngineRefusal::ContinuationNotModeled)
        );
        record.source = CardPlaySource::Auto;
        record.spent = 0;
        assert_eq!(persisted_card_play_energy_value(&record), Ok(None));
    }

    /// #3168: a resumed AfterCardPlayed walk reads Ivory Tile's gate from
    /// the persisted payment for a manual play and refuses by name for an
    /// AutoPlay, whose `EnergyValue` is not persisted. Without Ivory Tile
    /// the AutoPlay resumes.
    #[test]
    fn ivory_tile_resumed_after_card_played_uses_manual_payment_or_refuses_autoplay() {
        let defend = identity(CardId::DefendIronclad, 0);
        for (source, ivory) in [
            (CardPlaySource::Manual, true),
            (CardPlaySource::Auto, true),
            (CardPlaySource::Auto, false),
        ] {
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(defend).unwrap();
            if ivory {
                builder.set_relics(&[RelicId::RelicIvoryTile]).unwrap();
            }
            let catalog = builder.build();
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.energy = 0;
            state.next_card_uid = 2;
            state.piles.get_mut(PileId::Play).make_mut().push(HotCard {
                uid: 1,
                atom,
                flags: 0,
            });
            let mut record = finished_driver_record(1);
            record.stage = CardPlayStage::AfterImitation;
            record.after_card_played_power_snapshot_captured = true;
            record.after_card_played_power_phase = 3;
            record.spent = if source == CardPlaySource::Manual {
                3
            } else {
                0
            };
            record.source = source;
            state.frames.push_card_play(&record).unwrap();
            let active = PersistedActivePlayGuard::enter(&state).unwrap();
            let result = advance_top_card_play_one(&mut state, &catalog, &mut Vec::new(), &active);
            match (source, ivory) {
                (CardPlaySource::Manual, _) => {
                    result.unwrap();
                    assert_eq!(state.energy, 1, "manual EnergyValue is the payment");
                }
                (_, true) => assert_eq!(
                    result,
                    Err(EngineRefusal::HookNotModeled {
                        relic: RelicId::RelicIvoryTile,
                        event: HookEvent::AfterCardPlayed,
                    })
                ),
                (_, false) => {
                    result.unwrap();
                    assert_eq!(state.energy, 0);
                }
            }
        }
    }

    /// #3168: a resumed AfterNormalHook step returns a Discard Right Hand
    /// Hand on a manual 2-Energy payment and refuses for an AutoPlay, whose
    /// `EnergyValue` is not persisted, only while one sits in Discard.
    #[test]
    fn right_hand_hand_resumed_late_uses_manual_payment_or_refuses_autoplay() {
        let defend = identity(CardId::DefendIronclad, 0);
        let right_hand = identity(CardId::RightHandHand, 0);
        for (source, in_discard) in [
            (CardPlaySource::Manual, true),
            (CardPlaySource::Auto, true),
            (CardPlaySource::Auto, false),
        ] {
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(defend).unwrap();
            let right_hand = builder.intern(right_hand).unwrap();
            let catalog = builder.build();
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.next_card_uid = 3;
            state.piles.get_mut(PileId::Play).make_mut().push(HotCard {
                uid: 1,
                atom,
                flags: 0,
            });
            let pile = if in_discard {
                PileId::Discard
            } else {
                PileId::Draw
            };
            state.piles.get_mut(pile).make_mut().push(HotCard {
                uid: 2,
                atom: right_hand,
                flags: 0,
            });
            let mut record = finished_driver_record(1);
            record.spent = if source == CardPlaySource::Manual {
                2
            } else {
                0
            };
            record.source = source;
            state.frames.push_card_play(&record).unwrap();
            let active = PersistedActivePlayGuard::enter(&state).unwrap();
            let result = advance_top_card_play_one(&mut state, &catalog, &mut Vec::new(), &active);
            match (source, in_discard) {
                (CardPlaySource::Manual, _) => {
                    result.unwrap();
                    assert_eq!(state.piles.get(PileId::Hand).as_slice()[0].uid, 2);
                }
                (_, true) => {
                    assert_eq!(result, Err(EngineRefusal::ContinuationNotModeled));
                }
                (_, false) => {
                    result.unwrap();
                    assert_eq!(state.piles.get(PileId::Draw).as_slice()[0].uid, 2);
                }
            }
        }
    }

    /// #3168: a resumed Attack StartBody counts a zero-Energy start from the
    /// persisted manual payment. For an AutoPlay the count's `EnergyValue` is
    /// not persisted: with a Feral card interned the body refuses before
    /// anything moves; without one the counter has no reader and it resumes.
    #[test]
    fn feral_counter_resumed_start_body_uses_manual_payment_or_refuses_autoplay() {
        let attack = identity(CardId::Breakthrough, 0);
        for (source, spent, feral, counted) in [
            (CardPlaySource::Manual, 0, true, Some(true)),
            (CardPlaySource::Manual, 1, true, Some(false)),
            (CardPlaySource::Auto, 0, true, None),
            (CardPlaySource::Auto, 0, false, Some(true)),
        ] {
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(attack).unwrap();
            if feral {
                builder.intern(identity(CardId::Feral, 0)).unwrap();
            }
            let catalog = builder.build();
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.next_card_uid = 2;
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 500));
            state.piles.get_mut(PileId::Play).make_mut().push(HotCard {
                uid: 1,
                atom,
                flags: 0,
            });
            let mut record = finished_driver_record(1);
            record.stage = CardPlayStage::StartBody;
            record.latch_kind = CardPlayLatchKind::Empty;
            record.next_step = 0;
            record.plays = 2;
            record.play_index = 1;
            record.spent = spent;
            record.source = source;
            state.frames.push_card_play(&record).unwrap();
            let before = state.clone();
            let active = PersistedActivePlayGuard::enter(&state).unwrap();
            let result = advance_top_card_play_one(&mut state, &catalog, &mut Vec::new(), &active);
            match counted {
                Some(counted) => {
                    result.unwrap();
                    assert_eq!(
                        state.history.zero_energy_attack_plays_started_this_turn,
                        i16::from(counted),
                        "{source:?} spent={spent} feral={feral}"
                    );
                }
                None => {
                    assert_eq!(result, Err(EngineRefusal::ContinuationNotModeled));
                    assert_eq!(state, before, "the refusal precedes every write");
                }
            }
        }
    }

    #[test]
    fn continuation_driver_commits_card_play_stages_and_empty_power_snapshot_phases() {
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(defend).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.next_card_uid = 2;
        state.piles.get_mut(PileId::Play).make_mut().push(HotCard {
            uid: 1,
            atom,
            flags: 0,
        });
        let mut record = finished_driver_record(1);
        record.stage = CardPlayStage::StartBody;
        record.latch_kind = CardPlayLatchKind::Empty;
        record.next_step = 0;
        state.frames.push_card_play(&record).unwrap();
        let active = PersistedActivePlayGuard::enter(&state).unwrap();
        let mut events = Vec::new();
        let top_stage = |state: &HotState| match state.frames.top().unwrap() {
            crate::frame::Frame::CardPlay { record } => {
                state.frames.card_play(record).unwrap().stage
            }
            _ => unreachable!(),
        };

        advance_top_card_play_one(&mut state, &catalog, &mut events, &active).unwrap();
        assert_eq!(top_stage(&state), CardPlayStage::Body);
        advance_top_card_play_one(&mut state, &catalog, &mut events, &active).unwrap();
        assert_eq!(top_stage(&state), CardPlayStage::AfterBody);
        advance_top_card_play_one(&mut state, &catalog, &mut events, &active).unwrap();
        assert_eq!(top_stage(&state), CardPlayStage::AfterEnchantment);
        advance_top_card_play_one(&mut state, &catalog, &mut events, &active).unwrap();
        assert_eq!(top_stage(&state), CardPlayStage::AfterImitation);
        advance_top_card_play_one(&mut state, &catalog, &mut events, &active).unwrap();
        assert_eq!(top_stage(&state), CardPlayStage::AfterImitation);
        let crate::frame::Frame::CardPlay { record } = state.frames.top().unwrap() else {
            unreachable!()
        };
        let view = state.frames.card_play(record).unwrap();
        assert!(view.after_card_played_power_snapshot_captured);
        assert_eq!(view.after_card_played_power_snapshot().len(), 0);
        assert_eq!(view.after_card_played_power_phase, 3);
        advance_top_card_play_one(&mut state, &catalog, &mut events, &active).unwrap();
        assert_eq!(top_stage(&state), CardPlayStage::AfterNormalHook);
        advance_top_card_play_one(&mut state, &catalog, &mut events, &active).unwrap();
        assert!(state.frames.is_empty());
        assert_eq!(state.piles.get(PileId::Discard).as_slice()[0].uid, 1);
    }

    /// #3041: a persisted play resumed at `StartBody` after combat ended
    /// routes like the inline and body-end paths: result Add/Exhaust no-op
    /// after ending (CardCmd.Exhaust 0x3e06c8 IL_0020–0034), so the card
    /// stays in Play instead of reaching Discard or vanishing from Exhaust.
    #[test]
    fn persisted_start_body_after_combat_end_leaves_the_card_in_play() {
        let defend = identity(CardId::DefendIronclad, 0);
        for route in [
            CardResultRoute::DiscardBottom,
            CardResultRoute::ExhaustBottom,
        ] {
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(defend).unwrap();
            let catalog = builder.build();
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.next_card_uid = 2;
            let card = HotCard {
                uid: 1,
                atom,
                flags: 0,
            };
            state.piles.get_mut(PileId::Play).make_mut().push(card);
            let mut record = finished_driver_record(1);
            record.stage = CardPlayStage::StartBody;
            record.latch_kind = CardPlayLatchKind::Empty;
            record.next_step = 0;
            record.result_route = route;
            state.frames.push_card_play(&record).unwrap();
            state.history.over = true;
            let active = PersistedActivePlayGuard::enter(&state).unwrap();

            advance_top_card_play_one(&mut state, &catalog, &mut Vec::new(), &active).unwrap();

            assert!(state.frames.is_empty(), "{route:?}");
            assert_eq!(
                state.piles.get(PileId::Play).as_slice(),
                &[card],
                "{route:?}"
            );
            assert!(state.piles.get(PileId::Discard).is_empty(), "{route:?}");
            assert!(state.piles.get(PileId::Exhaust).is_empty(), "{route:?}");
        }
    }

