    #[test]
    fn continuation_driver_consumes_only_the_current_persisted_lamp_owner() {
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(defend).unwrap();
        let catalog = builder.build();

        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.next_card_uid = 2;
        state.fanouts.set_unsettling_lamp_available(true);
        state.piles.get_mut(PileId::Play).make_mut().push(HotCard {
            uid: 1,
            atom,
            flags: 0,
        });
        let mut owner = finished_driver_record(1);
        owner.stage = CardPlayStage::AfterImitation;
        owner.lamp_owner = true;
        state.frames.push_card_play(&owner).unwrap();

        assert_eq!(persisted_card_play_stack_is_exact(&state, &catalog), Ok(()));
        assert_eq!(
            drive_until_depth(&mut state, &catalog, &mut Vec::new(), 0),
            Ok(DriveStop::Depth)
        );
        assert!(state.frames.is_empty());
        assert!(!state.fanouts.unsettling_lamp_available());
        assert!(!active_play_stack_contains_uid(1));
        assert_eq!(state.piles.get(PileId::Discard).as_slice()[0].uid, 1);

        let mut nested = HotState::at_defaults();
        nested.hp = 50;
        nested.next_card_uid = 3;
        nested.fanouts.set_unsettling_lamp_available(true);
        nested.piles.get_mut(PileId::Play).make_mut().extend([
            HotCard {
                uid: 1,
                atom,
                flags: 0,
            },
            HotCard {
                uid: 2,
                atom,
                flags: 0,
            },
        ]);
        let mut parent = finished_driver_record(1);
        parent.stage = CardPlayStage::AfterImitation;
        parent.lamp_owner = true;
        nested.frames.push_card_play(&parent).unwrap();
        nested
            .frames
            .push_card_play(&finished_driver_record(2))
            .unwrap();

        assert_eq!(
            persisted_card_play_stack_is_exact(&nested, &catalog),
            Ok(())
        );
        assert_eq!(
            drive_until_depth(&mut nested, &catalog, &mut Vec::new(), 1),
            Ok(DriveStop::Depth)
        );
        assert!(nested.fanouts.unsettling_lamp_available());
        assert_eq!(nested.frames.len(), 1);
        let parent_index = match nested.frames.top().unwrap() {
            crate::frame::Frame::CardPlay { record } => record,
            _ => unreachable!(),
        };
        assert!(nested.frames.card_play(parent_index).unwrap().lamp_owner);
        assert_eq!(
            persisted_card_play_stack_is_exact(&nested, &catalog),
            Ok(())
        );
        assert!(!active_play_stack_contains_uid(1));
        assert!(!active_play_stack_contains_uid(2));
    }

    #[test]
    fn parked_player_power_walk_preserves_lamp_until_the_relic_suffix() {
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(defend).unwrap();
        builder
            .set_relics(&[crate::ids::RelicId::RelicUnsettlingLamp])
            .unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.next_card_uid = 2;
        state.fanouts.set_unsettling_lamp_available(true);
        state.piles.get_mut(PileId::Play).make_mut().push(HotCard {
            uid: 1,
            atom,
            flags: 0,
        });
        install_after_card_played_scalar(&mut state, PowerId::Afterimage, 1);
        let mut owner = finished_driver_record(1);
        owner.stage = CardPlayStage::AfterImitation;
        owner.afterimage = 1;
        owner.lamp_owner = true;
        state.frames.push_card_play(&owner).unwrap();
        let active = PersistedActivePlayGuard::enter(&state).unwrap();

        advance_top_card_play_one(&mut state, &catalog, &mut Vec::new(), &active).unwrap();
        assert_eq!(state.block, 1, "the ordinary player callback ran first");
        assert!(state.fanouts.unsettling_lamp_available());
        let Frame::CardPlay { record } = state.frames.top().unwrap() else {
            unreachable!()
        };
        let parked = state.frames.card_play(record).unwrap();
        assert!(parked.lamp_owner);
        assert_eq!(parked.after_card_played_power_phase, 2);
        assert_eq!(parked.after_card_played_power_cursor, 1);

        advance_top_card_play_one(&mut state, &catalog, &mut Vec::new(), &active).unwrap();
        assert!(state.fanouts.unsettling_lamp_available());
        advance_top_card_play_one(&mut state, &catalog, &mut Vec::new(), &active).unwrap();
        assert!(!state.fanouts.unsettling_lamp_available());
        let Frame::CardPlay { record } = state.frames.top().unwrap() else {
            unreachable!()
        };
        let after_relic = state.frames.card_play(record).unwrap();
        assert_eq!(after_relic.stage, CardPlayStage::AfterNormalHook);
        assert!(!after_relic.lamp_owner);
    }

    #[test]
    fn continuation_driver_stops_at_an_authenticated_pending_child_without_mutation() {
        let (catalog, mut state) = two_persisted_defends();
        let child_index = match state.frames.top().unwrap() {
            crate::frame::Frame::CardPlay { record } => record,
            _ => unreachable!(),
        };
        let mut child = state.frames.card_play(child_index).unwrap().to_owned();
        child.stage = CardPlayStage::Body;
        child.latch_kind = CardPlayLatchKind::Raw;
        child.pending_choice = true;
        child.selection_kind = Some(PendingSelectionKind::Program);
        state.frames.replace_top_card_play(&child).unwrap();
        state.pending = Some(std::sync::Arc::new(crate::hot::PendingSelection {
            frame_uid: child.uid,
            frame_record: child_index,
        }));
        let before = state.clone();
        let mut events = vec![Event::CardResolved {
            uid: 99,
            pile: PileId::Draw,
        }];

        let driven = drive_until_depth(&mut state, &catalog, &mut events, 0);
        assert_eq!(driven, Ok(DriveStop::Blocked), "{state:#?}");
        assert_eq!(state, before);
        assert_eq!(events.len(), 1);
    }

    #[test]
    fn continuation_driver_refuses_malformed_or_unsupported_tops_atomically() {
        let (catalog, mut malformed) = two_persisted_defends();
        let child_index = match malformed.frames.top().unwrap() {
            crate::frame::Frame::CardPlay { record } => record,
            _ => unreachable!(),
        };
        let mut child = malformed.frames.card_play(child_index).unwrap().to_owned();
        child.source = CardPlaySource::Hellraiser;
        malformed.frames.replace_top_card_play(&child).unwrap();
        let before = malformed.clone();
        assert_eq!(
            drive_until_depth(&mut malformed, &catalog, &mut Vec::new(), 0),
            Err(EngineRefusal::ContinuationNotModeled)
        );
        assert_eq!(malformed, before);

        let mut unsupported = HotState::at_defaults();
        unsupported.frames.push(crate::frame::Frame::JossSideEnd);
        let before = unsupported.clone();
        assert_eq!(
            drive_until_depth(&mut unsupported, &catalog, &mut Vec::new(), 0),
            Err(EngineRefusal::ContinuationNotModeled)
        );
        assert_eq!(unsupported, before);
    }

