    #[test]
    fn persisted_parent_and_child_contexts_keep_lamp_ownership_on_the_parent() {
        let mut state = HotState::at_defaults();
        state.next_card_uid = 3;
        state.fanouts.set_unsettling_lamp_available(true);
        state.piles.get_mut(PileId::Play).make_mut().extend([
            HotCard {
                uid: 1,
                atom: 0,
                flags: 0,
            },
            HotCard {
                uid: 2,
                atom: 0,
                flags: 0,
            },
        ]);
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 20));

        let mut parent = crate::hot::CardPlayRecord::pending_for_test(1);
        parent.pending_choice = false;
        parent.selection_kind = None;
        parent.lamp_owner = true;
        state.frames.push_card_play(&parent).unwrap();
        let child = crate::hot::CardPlayRecord::pending_for_test(2);
        let child_index = state.frames.push_card_play(&child).unwrap();
        state.pending = Some(std::sync::Arc::new(crate::hot::PendingSelection {
            frame_uid: 2,
            frame_record: child_index,
        }));

        let guard = PersistedActivePlayGuard::enter(&state).unwrap();
        assert!(active_play_stack_contains_uid(1));
        assert!(active_play_stack_contains_uid(2));
        assert_eq!(active_card_lamp_triggered(), Some(false));
        let mut events = Vec::new();
        assert_eq!(
            crate::engine::damage::card_monster_type_two_amount(&mut state, 0, 3, &mut events),
            Ok(Some(3)),
            "the child neither doubles nor steals its ancestor's Lamp"
        );
        finish_unsettling_lamp(&mut state).unwrap();
        assert!(state.fanouts.unsettling_lamp_available());
        assert!(
            state
                .frames
                .card_play(parent_index(&state))
                .unwrap()
                .lamp_owner
        );
        drop(guard);

        let mut false_in_play = state.clone();
        let mut forged = false_in_play
            .frames
            .card_play(child_index)
            .unwrap()
            .to_owned();
        forged.source = CardPlaySource::Auto;
        forged.active_play_member = false;
        false_in_play.frames.replace_top_card_play(&forged).unwrap();
        assert!(matches!(
            PersistedActivePlayGuard::enter(&false_in_play),
            Err(EngineRefusal::ContinuationNotModeled)
        ));

        let mut true_outside_play = state.clone();
        let child_card = true_outside_play
            .piles
            .get_mut(PileId::Play)
            .make_mut()
            .pop()
            .unwrap();
        true_outside_play
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .push(child_card);
        let mut forged = true_outside_play
            .frames
            .card_play(child_index)
            .unwrap()
            .to_owned();
        forged.source = CardPlaySource::Auto;
        forged.source_pile = PileId::Draw;
        true_outside_play
            .frames
            .replace_top_card_play(&forged)
            .unwrap();
        assert!(matches!(
            PersistedActivePlayGuard::enter(&true_outside_play),
            Err(EngineRefusal::ContinuationNotModeled)
        ));

        fn parent_index(state: &HotState) -> crate::hot::WordRecordIndex {
            let crate::frame::Frame::CardPlay { record } = state.frames.as_slice()[0] else {
                unreachable!()
            };
            record
        }
    }

    #[test]
    fn native_targeted_suspension_records_duplicate_fallback_before_projection() {
        let mut builder = CatalogBuilder::new();
        let headbutt = builder.intern(identity(CardId::Headbutt, 0)).unwrap();
        let strike = builder.intern(identity(CardId::StrikeIronclad, 0)).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 70;
        state.energy = 3;
        state.next_card_uid = 4;
        for _ in 0..2 {
            let mut monster = HotMonster::new(MonsterKind::Toadpole, 40);
            monster.uid = 77;
            monster.slot = 0;
            state.monsters_mut().push(monster);
        }
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 1,
            atom: headbutt,
            flags: 0,
        });
        state.piles.get_mut(PileId::Discard).make_mut().extend([
            HotCard {
                uid: 2,
                atom: strike,
                flags: 0,
            },
            HotCard {
                uid: 3,
                atom: strike,
                flags: 0,
            },
        ]);

        play_card(&mut state, &catalog, 1, Some(1), None, &mut Vec::new()).unwrap();
        let record = pending_record(&state);
        assert_eq!(record.target, Some((0, 77, Some(1))));
        assert_eq!(
            record.choice_kind,
            crate::hot::CardPlayChoiceKind::SignedInt
        );
        assert_eq!(record.choice_i32, 1);

        let canonical = HotBoundary::to_canonical(&state, &catalog);
        let reloaded = HotBoundary::from_canonical(&canonical, &catalog).unwrap();
        assert_eq!(reloaded, state);
        assert_eq!(pending_record(&reloaded).target, Some((0, 77, Some(1))));

        let mut auto = canonical;
        auto.continuations[0]
            .fields
            .insert("source".to_owned(), serde_json::json!("auto"));
        auto.continuations[0]
            .fields
            .insert("choice".to_owned(), serde_json::Value::Null);
        let auto_reloaded = HotBoundary::from_canonical(&auto, &catalog).unwrap();
        let auto_record = pending_record(&auto_reloaded);
        assert_eq!(auto_record.target, Some((0, 77, Some(1))));
        assert_eq!(auto_record.choice_kind, CardPlayChoiceKind::None);
        assert_eq!(HotBoundary::to_canonical(&auto_reloaded, &catalog), auto);
    }

