    fn heirloom_fixture(upgrade: u8, colorless: &[CardId]) -> (HotState, Catalog, HotCard) {
        let hammer = identity(CardId::HeirloomHammer, upgrade);
        let mut builder = CatalogBuilder::new();
        let hammer_atom = builder.intern(hammer).unwrap();
        for id in colorless {
            builder.intern(identity(*id, 0)).unwrap();
        }
        builder.intern(identity(CardId::StrikeIronclad, 0)).unwrap();
        builder.intern_monster(MonsterKind::Axebot).unwrap();
        builder.intern_monster(MonsterKind::Mawler).unwrap();
        let catalog = builder.build();
        let source = HotCard {
            uid: 10,
            atom: hammer_atom,
            flags: 0,
        };
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.energy = 9;
        state.next_card_uid = 100;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        state.monsters_mut()[0].uid = 70;
        state.piles.get_mut(PileId::Hand).make_mut().push(source);
        for (offset, id) in colorless.iter().enumerate() {
            state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
                uid: 20 + offset as u32,
                atom: catalog.atom(&identity(*id, 0)).unwrap(),
                flags: if offset == 0 {
                    CARD_FLAG_DEFAULT_PHYSICAL_STATE
                } else {
                    0
                },
            });
        }
        if !colorless.is_empty() {
            state.card_states.set(
                20,
                CardInstanceState {
                    local_retain: true,
                    ..CardInstanceState::default()
                },
            );
        }
        (state, catalog, source)
    }

    #[test]
    fn stampede_selecting_child_persists_exact_phase_live_cardplay_stack() {
        let (mut state, catalog, source) =
            heirloom_fixture(0, &[CardId::Alchemize, CardId::BeatDown]);
        assert!(state.fanouts.set_potion_belt(
            vec![Some(crate::ids::PotionId::BlockPotion)],
            true,
            false,
            false,
            false,
            true,
        ));
        state.rng.set(
            RngStream::PotionGeneration,
            crate::hot::RngStreamState {
                words: [1, 2, 3, 4],
                counter: 0,
            },
        );
        let mut mawler = HotMonster::new(MonsterKind::Mawler, 100);
        assert!(
            mawler
                .random_ai
                .set_next(Some(crate::engine::admission::MAWLER_CLAW_INDEX))
        );
        assert!(
            mawler
                .random_ai
                .set_log(&[crate::engine::admission::MAWLER_CLAW_INDEX])
        );
        mawler.uid = 70;
        state.monsters_mut()[0] = mawler;
        state.player_phase = crate::engine::turn::PHASE_AUTO_POST;
        state.powers.set(PowerId::Stampede, SlotWire::Int, 1);
        state
            .frames
            .push_auto_post_phase(&crate::hot::AutoPostPhaseRecord {
                cursor: 1,
                listeners: vec![AutoPostListener::Stampede],
            })
            .unwrap();
        state
            .frames
            .push_stampede_live(StampedeLiveRecord {
                cursor: 0,
                iterations: 1,
            })
            .unwrap();
        let rng_before = state.rng.get(RngStream::Rng).counter;
        let mut events = Vec::new();
        assert!(persisted_card_play_stack_is_exact(&state, &catalog).is_ok());

        let driven = drive_until_depth(&mut state, &catalog, &mut events, 0);
        assert_eq!(driven, Ok(DriveStop::Blocked), "{state:#?}");
        assert_eq!(state.frames.len(), 3);
        assert_eq!(state.rng.get(RngStream::Rng).counter, rng_before + 1);
        let pending = state
            .pending
            .as_deref()
            .expect("Heirloom choice is pending");
        let record = pending.record(&state.frames).unwrap();
        assert_eq!(record.uid, source.uid);
        assert_eq!(record.source, CardPlaySource::Stampede);
        assert_eq!(record.source_pile, PileId::Play);
        assert_eq!(record.stage, CardPlayStage::Body);
        assert!(record.pending_choice);
        assert!(persisted_card_play_stack_is_exact(&state, &catalog).is_ok());

        let canonical = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        assert_eq!(
            canonical
                .continuations
                .iter()
                .map(|frame| frame.frame_type.as_str())
                .collect::<Vec<_>>(),
            ["PhaseFrame", "LiveListenerFrame", "CardPlayFrame"]
        );
        assert_eq!(canonical.continuations[2].fields["source"], "Stampede");
        assert_eq!(
            HotBoundary::from_canonical(&canonical, &catalog).unwrap(),
            state
        );
        assert!(!crate::engine::legal_actions(&state, &catalog).is_empty());
        crate::engine::admit(&canonical, &state, &catalog).unwrap();
    }

    #[test]
    fn action_replay_rooted_auto_post_authenticates_stampede_topology() {
        let (mut state, catalog, _) = heirloom_fixture(0, &[CardId::Alchemize, CardId::BeatDown]);
        let mut mawler = HotMonster::new(MonsterKind::Mawler, 100);
        assert!(
            mawler
                .random_ai
                .set_next(Some(crate::engine::admission::MAWLER_CLAW_INDEX))
        );
        assert!(
            mawler
                .random_ai
                .set_log(&[crate::engine::admission::MAWLER_CLAW_INDEX])
        );
        mawler.uid = 70;
        state.monsters_mut()[0] = mawler;
        state.player_phase = crate::engine::turn::PHASE_AUTO_POST;
        state.powers.set(PowerId::Stampede, SlotWire::Int, 1);
        state
            .frames
            .push_auto_post_phase(&crate::hot::AutoPostPhaseRecord {
                cursor: 1,
                listeners: vec![AutoPostListener::Stampede],
            })
            .unwrap();
        state
            .frames
            .push_stampede_live(StampedeLiveRecord {
                cursor: 0,
                iterations: 1,
            })
            .unwrap();
        assert_eq!(
            drive_until_depth(&mut state, &catalog, &mut Vec::new(), 0),
            Ok(DriveStop::Blocked)
        );
        state
            .install_action_replay_root(&crate::hot::ActionReplayRecord {
                predecessor_json: b"{}".to_vec(),
                action: crate::hot::ActionReplayRootAction::EndTurn,
                answers: Vec::new(),
            })
            .unwrap();
        let crate::frame::Frame::ActionReplay { record } = state.frames.as_slice()[0] else {
            unreachable!()
        };
        assert_eq!(
            replay_rooted_stack_is_exact(&state, &catalog, state.frames.as_slice(), record),
            Ok(())
        );

        let mut wrong_source = state.clone();
        let crate::frame::Frame::CardPlay { record } = wrong_source.frames.top().unwrap() else {
            unreachable!()
        };
        let mut child = wrong_source.frames.card_play(record).unwrap().to_owned();
        child.source = CardPlaySource::Auto;
        wrong_source.frames.replace_top_card_play(&child).unwrap();
        assert_eq!(
            replay_rooted_stack_is_exact(
                &wrong_source,
                &catalog,
                wrong_source.frames.as_slice(),
                match wrong_source.frames.as_slice()[0] {
                    crate::frame::Frame::ActionReplay { record } => record,
                    _ => unreachable!(),
                },
            ),
            Err(EngineRefusal::ContinuationNotModeled)
        );

        let mut wrong_iterations = state.clone();
        wrong_iterations
            .powers
            .set(PowerId::Stampede, SlotWire::Int, 2);
        assert_eq!(
            replay_rooted_stack_is_exact(
                &wrong_iterations,
                &catalog,
                wrong_iterations.frames.as_slice(),
                match wrong_iterations.frames.as_slice()[0] {
                    crate::frame::Frame::ActionReplay { record } => record,
                    _ => unreachable!(),
                },
            ),
            Err(EngineRefusal::ContinuationNotModeled)
        );

        let mut hybrid = state.clone();
        hybrid.pending = None;
        while hybrid.frames.len() > 1 {
            hybrid.frames.pop();
        }
        hybrid.frames.push_auto_pre_mayhem_phase().unwrap();
        hybrid
            .frames
            .push_stampede_live(StampedeLiveRecord {
                cursor: 0,
                iterations: 1,
            })
            .unwrap();
        assert_eq!(
            replay_rooted_stack_is_exact(
                &hybrid,
                &catalog,
                hybrid.frames.as_slice(),
                match hybrid.frames.as_slice()[0] {
                    crate::frame::Frame::ActionReplay { record } => record,
                    _ => unreachable!(),
                },
            ),
            Err(EngineRefusal::ContinuationNotModeled),
            "AutoPre Mayhem cannot own a rooted Stampede live suffix"
        );

        let crate::frame::Frame::ActionReplay { record: root_index } = state.frames.as_slice()[0]
        else {
            unreachable!()
        };
        let root = state.frames.action_replay(root_index).unwrap().to_owned();
        let crate::frame::Frame::CardPlay {
            record: child_index,
        } = state.frames.top().unwrap()
        else {
            unreachable!()
        };
        let stampede_child = state.frames.card_play(child_index).unwrap().to_owned();

        let mut auto_pre_direct = state.clone();
        let mut auto_child = stampede_child.clone();
        auto_child.source = CardPlaySource::Auto;
        let mut auto_pre_frames = crate::hot::Frames::new();
        let auto_pre_root = auto_pre_frames.push_action_replay(&root).unwrap();
        auto_pre_frames.push_auto_pre_mayhem_phase().unwrap();
        let auto_pre_child = auto_pre_frames.push_card_play(&auto_child).unwrap();
        auto_pre_direct.frames = auto_pre_frames;
        auto_pre_direct.pending = Some(std::sync::Arc::new(crate::hot::PendingSelection {
            frame_uid: auto_child.uid,
            frame_record: auto_pre_child,
        }));
        assert_eq!(
            replay_rooted_stack_is_exact(
                &auto_pre_direct,
                &catalog,
                auto_pre_direct.frames.as_slice(),
                auto_pre_root,
            ),
            Err(EngineRefusal::ContinuationNotModeled),
            "Mayhem AutoPre cannot directly own an ordinary Auto CardPlay without its DrawPileFlip batch"
        );

        let mut howl = state.clone();
        auto_child.source_pile = PileId::Play;
        auto_child.active_play_member = true;
        let make_howl_frames = |listener_uid: u32, source: CardPlaySource, cursor: u32| {
            let mut frames = crate::hot::Frames::new();
            let root_index = frames.push_action_replay(&root).unwrap();
            frames
                .push_auto_post_phase(&crate::hot::AutoPostPhaseRecord {
                    cursor,
                    listeners: vec![
                        AutoPostListener::Stampede,
                        AutoPostListener::Howl { uid: listener_uid },
                    ],
                })
                .unwrap();
            let mut child = auto_child.clone();
            child.source = source;
            let child_index = frames.push_card_play(&child).unwrap();
            (frames, root_index, child_index)
        };
        let (frames, root_index, child_index) =
            make_howl_frames(auto_child.uid, CardPlaySource::Auto, 2);
        howl.frames = frames;
        howl.pending = Some(std::sync::Arc::new(crate::hot::PendingSelection {
            frame_uid: auto_child.uid,
            frame_record: child_index,
        }));
        assert_eq!(
            replay_rooted_stack_is_exact(&howl, &catalog, howl.frames.as_slice(), root_index),
            Ok(()),
            "the completed physical Howl callback owns its exact Auto child"
        );
        for (label, uid, source, cursor) in [
            ("listener uid", auto_child.uid + 1, CardPlaySource::Auto, 2),
            ("source", auto_child.uid, CardPlaySource::Stampede, 2),
            ("cursor", auto_child.uid, CardPlaySource::Auto, 1),
        ] {
            let mut malformed = howl.clone();
            let (frames, root_index, child_index) = make_howl_frames(uid, source, cursor);
            malformed.frames = frames;
            malformed.pending = Some(std::sync::Arc::new(crate::hot::PendingSelection {
                frame_uid: auto_child.uid,
                frame_record: child_index,
            }));
            assert_eq!(
                replay_rooted_stack_is_exact(
                    &malformed,
                    &catalog,
                    malformed.frames.as_slice(),
                    root_index,
                ),
                Err(EngineRefusal::ContinuationNotModeled),
                "Howl {label} drift is not an authenticated AutoPost owner"
            );
        }
    }

    /// 70022CD6G3J0 node 27: Thinking Ahead is a `ColorlessCardPool` member
    /// whose generated row names no pool. Heirloom Hammer's filter reads
    /// `VisualCardPool.IsColorless` (`<OnPlay>b__3_0` RVA `0x3a46c2`), so it is
    /// a clone candidate; a character-visual Event card (Clash) is not.
    #[test]
    fn heirloom_hammer_filter_is_the_visual_card_pool() {
        let (mut state, catalog, source) = heirloom_fixture(0, &[CardId::ThinkingAhead]);
        let selected = state.piles.get(PileId::Hand).as_slice()[1];
        play_card(
            &mut state,
            &catalog,
            source.uid,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        let hand = state.piles.get(PileId::Hand).as_slice();
        assert_eq!(hand.len(), 2, "the Thinking Ahead is cloned");
        assert_eq!(hand[1].atom, selected.atom);

        let (mut clash, catalog, source) = heirloom_fixture(0, &[CardId::Clash]);
        play_card(
            &mut clash,
            &catalog,
            source.uid,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(
            clash.piles.get(PileId::Hand).len(),
            1,
            "Clash's VisualCardPool is IroncladCardPool: no candidate"
        );
    }

    #[test]
    fn heirloom_hammer_attacks_then_clones_one_exact_colorless_source() {
        for (upgrade, expected_hp) in [(0, 80), (1, 75)] {
            let (mut state, catalog, source) = heirloom_fixture(upgrade, &[CardId::Alchemize]);
            let selected = state.piles.get(PileId::Hand).as_slice()[1];

            play_card(
                &mut state,
                &catalog,
                source.uid,
                Some(0),
                None,
                &mut Vec::new(),
            )
            .unwrap();

            assert_eq!(state.monsters[0].hp, expected_hp);
            assert_eq!(state.energy, 7);
            assert!(state.pending.is_none());
            assert_eq!(state.history.owner_generated_cards_combat, 1);
            assert_eq!(state.next_generated_hook_uid, 1);
            let hand = state.piles.get(PileId::Hand).as_slice();
            assert_eq!(hand.len(), 2);
            assert_eq!(hand[0], selected, "the selected source remains live");
            assert_eq!(hand[1].uid, 100);
            assert_eq!(
                (hand[1].atom, hand[1].flags),
                (selected.atom, selected.flags)
            );
            assert_eq!(
                state.card_states.get(hand[1].uid),
                state.card_states.get(selected.uid),
                "the generated clone copies the complete physical payload"
            );
            assert!(
                state
                    .piles
                    .get(PileId::Discard)
                    .as_slice()
                    .contains(&source)
            );
        }

        let (mut joined, catalog, source) = heirloom_fixture(0, &[CardId::Alchemize]);
        joined.powers.set(PowerId::Arsenal, SlotWire::Int, 2);
        assert!(
            joined
                .fanouts
                .set_local_generated_power_order(&[PowerId::Arsenal])
        );
        play_card(
            &mut joined,
            &catalog,
            source.uid,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(joined.powers.value(PowerId::Strength), 2);

        let (mut empty, catalog, source) = heirloom_fixture(0, &[]);
        play_card(
            &mut empty,
            &catalog,
            source.uid,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(empty.monsters[0].hp, 80);
        assert_eq!(empty.history.owner_generated_cards_combat, 0);

        let (mut lethal, catalog, source) = heirloom_fixture(0, &[CardId::Alchemize]);
        lethal.monsters_mut()[0].hp = 20;
        lethal.monsters_mut()[0].max_hp = 20;
        play_card(
            &mut lethal,
            &catalog,
            source.uid,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert!(lethal.history.over);
        assert_eq!(lethal.history.owner_generated_cards_combat, 0);
        assert!(lethal.piles.get(PileId::Play).as_slice().contains(&source));
    }

    #[test]
    fn heirloom_hammer_selection_round_trips_and_freezes_target_identity() {
        let (mut state, catalog, source) =
            heirloom_fixture(0, &[CardId::Alchemize, CardId::BeatDown]);
        play_card(
            &mut state,
            &catalog,
            source.uid,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(state.monsters[0].hp, 80);
        let original_target_uid = state.monsters[0].uid;
        let pending = state.pending.as_deref().unwrap();
        let record = pending.record(&state.frames).unwrap();
        assert_eq!(record.target.map(|target| target.0), Some(0));
        assert_eq!(
            record.target.map(|target| target.1),
            Some(original_target_uid)
        );

        let canonical = HotBoundary::to_canonical(&state, &catalog);
        let mut resumed = HotBoundary::from_canonical(&canonical, &catalog).unwrap();
        assert_eq!(resumed, state);
        resume_selection(
            &mut resumed,
            &catalog,
            crate::engine::SelectionAnswer::OptionIndex(0),
            &mut Vec::new(),
        )
        .unwrap();
        assert!(resumed.pending.is_none());
        assert_eq!(
            resumed.monsters[0].hp, 80,
            "the attack prefix is not replayed"
        );
        assert_eq!(resumed.history.owner_generated_cards_combat, 1);

        let mut replaced = state;
        replaced.monsters_mut()[0].uid = original_target_uid + 1;
        let before = replaced.clone();
        assert_eq!(
            resume_selection(
                &mut replaced,
                &catalog,
                crate::engine::SelectionAnswer::OptionIndex(0),
                &mut Vec::new(),
            ),
            Err(EngineRefusal::ContinuationNotModeled)
        );
        assert_eq!(replaced, before);

        let (mut stock, stock_catalog, stock_source) =
            heirloom_fixture(0, &[CardId::Alchemize, CardId::BeatDown]);
        let mut axebot = HotMonster::new(MonsterKind::Axebot, 20);
        axebot.max_hp = 86;
        axebot.uid = 1;
        axebot.powers.set(PowerId::Stock, SlotWire::Int, 1);
        stock.monsters_mut()[0] = axebot;
        let before = stock.clone();
        assert_eq!(
            play_card(
                &mut stock,
                &stock_catalog,
                stock_source.uid,
                Some(0),
                None,
                &mut Vec::new(),
            ),
            Err(EngineRefusal::MalformedArgs(
                "Heirloom Hammer Axebot Stock target identity"
            ))
        );
        assert_eq!(
            stock, before,
            "a lethal Stock replacement refuses before publishing a stale target continuation"
        );
    }

    /// #2966: `OnPlayWrapper` (0x31b8d0) awaits `Hook::BeforeCardPlayed`
    /// once per generated CardPlay (IL_05a1 inside the IL_08ec-IL_0909
    /// loop), so Pen Nib advances on every replay body and doubles only the
    /// body that reaches zero. The action-level model this replaces would
    /// give 88/9 and 76/0 for the two replayed rows below.
    #[test]
    fn pen_nib_advances_and_doubles_per_replay_body() {
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(strike).unwrap();
        builder.set_relics(&[RelicId::RelicPenNib]).unwrap();
        let catalog = builder.build();
        for (counter, one_two_punch, expected_hp, expected_counter) in [
            (8, 1, 100 - 6 - 12, 0),
            (9, 1, 100 - 12 - 6, 1),
            (9, 0, 100 - 12, 0),
            (7, 1, 100 - 6 - 6, 9),
        ] {
            let mut state = state_with_card(&catalog, strike, 41);
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 100));
            assert!(state.fanouts.set_pen_nib(counter));
            state
                .powers
                .set(PowerId::OneTwoPunch, SlotWire::Int, one_two_punch);
            hydrate_side_end_order(&mut state);
            play_card(&mut state, &catalog, 41, Some(0), None, &mut Vec::new()).unwrap();
            assert_eq!(
                (state.monsters[0].hp, state.fanouts.pen_nib()),
                (expected_hp, expected_counter),
                "counter {counter}, One-Two Punch {one_two_punch}"
            );
        }
    }

    fn razor_tooth_catalog(id: CardId, razor_tooth: bool) -> Catalog {
        let mut builder = CatalogBuilder::new();
        builder.intern(identity(id, 0)).unwrap();
        builder.intern(identity(id, 1)).unwrap();
        if razor_tooth {
            builder.set_relics(&[RelicId::RelicRazorTooth]).unwrap();
        }
        builder.build()
    }

    /// #3207: `OnPlayWrapper` (0x31b8d0) runs Razor Tooth's AfterCardPlayed
    /// (IL_0874; `RazorTooth::AfterCardPlayed` 0x9a1b8 IL_0059-IL_0060
    /// upgrades `cardPlay.Card`) before the next body's `OnPlay` (IL_0659),
    /// and Glacier's body reads the live `DynamicVars.Block`
    /// (`<OnPlay>d__7` 0x3a1354 IL_00b2-IL_00b7). Under Burst the second
    /// body therefore gains Glacier+'s 9, not the frozen 6 (fight
    /// f868c4c4bb535569: native 74 where the frozen spec gave 71).
    #[test]
    fn razor_tooth_upgrade_feeds_the_next_replay_body() {
        for (razor_tooth, expected_block, expected_upgrade) in [(true, 6 + 9, 1), (false, 6 + 6, 0)]
        {
            let catalog = razor_tooth_catalog(CardId::Glacier, razor_tooth);
            let mut state = state_with_card(&catalog, identity(CardId::Glacier, 0), 41);
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            // Four slots hold both bodies' two Frost with no evoke.
            state.orbs.set_base_slots(4);
            state.orbs.set_slots(4);
            state.powers.set(PowerId::Burst, SlotWire::Int, 1);
            hydrate_side_end_order(&mut state);
            play_card(&mut state, &catalog, 41, None, None, &mut Vec::new()).unwrap();
            assert_eq!(state.block, expected_block, "Razor Tooth {razor_tooth}");
            let routed = state.piles.get(PileId::Discard).as_slice()[0];
            assert_eq!(
                catalog.spec(routed.atom).unwrap().identity.upgrade,
                expected_upgrade
            );
        }
    }

    /// #3208: the #3207 live re-read is source-blind. A Duplication replay
    /// body (`DuplicationPower::ModifyCardPlayCount` `0xa1dd9`) runs through
    /// the same `OnPlayWrapper` loop, so its second Glacier body also gains
    /// the Razor-Tooth-upgraded 9 Block, and one Duplication stack is spent.
    #[test]
    fn razor_tooth_upgrade_feeds_a_duplication_replay_body() {
        for (razor_tooth, expected_block, expected_upgrade) in [(true, 6 + 9, 1), (false, 6 + 6, 0)]
        {
            let catalog = razor_tooth_catalog(CardId::Glacier, razor_tooth);
            let mut state = state_with_card(&catalog, identity(CardId::Glacier, 0), 41);
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            // Four slots hold both bodies' two Frost with no evoke.
            state.orbs.set_base_slots(4);
            state.orbs.set_slots(4);
            assert!(state.fanouts.set_duplication(2));
            hydrate_side_end_order(&mut state);
            play_card(&mut state, &catalog, 41, None, None, &mut Vec::new()).unwrap();
            assert_eq!(state.block, expected_block, "Razor Tooth {razor_tooth}");
            assert_eq!(state.fanouts.duplication(), 1);
            let routed = state.piles.get(PileId::Discard).as_slice()[0];
            assert_eq!(
                catalog.spec(routed.atom).unwrap().identity.upgrade,
                expected_upgrade
            );
        }
    }

    /// #3207: the same live re-read is what the second Bullet Time body's
    /// source guard (`bullet_time_exact` source) authenticates against, so
    /// Razor Tooth + Burst plays both bodies instead of refusing, and the
    /// upgraded body resolves Bullet Time+'s printed cost (3 -> 2).
    #[test]
    fn razor_tooth_upgraded_bullet_time_replays_with_its_live_cost() {
        let catalog = razor_tooth_catalog(CardId::BulletTime, true);
        let mut state = state_with_card(&catalog, identity(CardId::BulletTime, 0), 41);
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.powers.set(PowerId::Burst, SlotWire::Int, 1);
        hydrate_side_end_order(&mut state);
        play_card(&mut state, &catalog, 41, None, None, &mut Vec::new()).unwrap();
        assert_eq!(state.powers.value(PowerId::NoDraw), 2);

        let frozen = HotCard {
            uid: 41,
            atom: catalog.atom(&identity(CardId::BulletTime, 0)).unwrap(),
            flags: 0,
        };
        let mut upgraded = state_with_card(&catalog, identity(CardId::BulletTime, 1), 41);
        let (live, live_spec, cost) =
            replay_body_upgraded_live_card(&upgraded, &catalog, 41, frozen, 3)
                .unwrap()
                .expect("an upgraded live card is re-read");
        assert_eq!(
            (live.atom, live_spec.identity.upgrade, cost),
            (
                catalog.atom(&identity(CardId::BulletTime, 1)).unwrap(),
                1,
                2
            )
        );
        // A frozen cost the live resolver cannot reproduce is not trusted.
        assert_eq!(
            replay_body_upgraded_live_card(&upgraded, &catalog, 41, frozen, 1),
            Err(EngineRefusal::MalformedArgs(
                "replay body upgraded Energy cost unresolvable"
            ))
        );
        // The frozen atom itself is the ordinary path.
        upgraded.piles.get_mut(PileId::Hand).make_mut()[0].atom = frozen.atom;
        assert_eq!(
            replay_body_upgraded_live_card(&upgraded, &catalog, 41, frozen, 3),
            Ok(None)
        );
    }

    /// #3100: every replay source the retired opening gate named feeds the
    /// one native play count, so each advances Pen Nib once per body.
    /// Duplicator's `OnUse` (`0x34d154` IL_003a) applies `DuplicationPower`,
    /// whose `ModifyCardPlayCount` (`0xa1dd9` IL_0016-IL_0018) adds 1; Echo
    /// Form's (`0xa1f0c` IL_004d-IL_004f) adds 1 while fewer than `Amount`
    /// first-in-series plays started this turn; Glam's `EnchantPlayCount` (`0xd5f94` IL_000b-IL_0021)
    /// adds `Times` until used and Spiral's (`0xd6586` IL_0001-IL_0017) adds
    /// `Times` always. `GeneratePlayCount` (`0x31b5e0` IL_001f-IL_0041) sums
    /// them and `OnPlayWrapper` (`0x31b8d0` IL_05a1) awaits BeforeCardPlayed
    /// per body. Counter 8: body 0 reaches 9, body 1 reaches 0 and doubles;
    /// counter 9: body 0 doubles and body 1 reaches 1.
    #[test]
    fn pen_nib_advances_per_body_for_every_replay_source() {
        #[derive(Clone, Copy, Debug)]
        enum Source {
            Duplication,
            EchoForm,
            Glam,
            Spiral,
        }
        for source in [
            Source::Duplication,
            Source::EchoForm,
            Source::Glam,
            Source::Spiral,
        ] {
            let enchantment = match source {
                Source::Glam => Some(crate::catalog::CardEnchantment {
                    id: EnchantmentId::Glam,
                    amount: 1,
                }),
                Source::Spiral => Some(crate::catalog::CardEnchantment {
                    id: EnchantmentId::Spiral,
                    amount: 0,
                }),
                Source::Duplication | Source::EchoForm => None,
            };
            let strike = CardIdentity {
                id: CardId::StrikeIronclad,
                upgrade: 0,
                enchantment,
            };
            let mut builder = CatalogBuilder::new();
            builder.intern(strike).unwrap();
            builder.set_relics(&[RelicId::RelicPenNib]).unwrap();
            let catalog = builder.build();
            for (counter, expected_hp, expected_counter) in [
                (8, 100 - 6 - 12, 0),
                (9, 100 - 12 - 6, 1),
                (7, 100 - 6 - 6, 9),
            ] {
                let mut state = state_with_card(&catalog, strike, 41);
                state
                    .monsters_mut()
                    .push(HotMonster::new(MonsterKind::Toadpole, 100));
                assert!(state.fanouts.set_pen_nib(counter));
                match source {
                    Source::Duplication => assert!(state.fanouts.set_duplication(1)),
                    Source::EchoForm => state.powers.set(PowerId::EchoForm, SlotWire::Int, 1),
                    Source::Glam | Source::Spiral => {}
                }
                hydrate_side_end_order(&mut state);
                play_card(&mut state, &catalog, 41, Some(0), None, &mut Vec::new()).unwrap();
                assert_eq!(
                    (state.monsters[0].hp, state.fanouts.pen_nib()),
                    (expected_hp, expected_counter),
                    "{source:?}, counter {counter}"
                );
            }
        }
    }

    /// The persisted `StartBody` driver is the gap between two generated
    /// CardPlays, so it runs that body's own Pen Nib BeforeCardPlayed.
    /// Heirloom Hammer parks after each body's damage; body 1 starts from
    /// the persisted record.
    #[test]
    fn pen_nib_persisted_replay_body_advances_its_own_counter() {
        for (counter, expected_hp, expected_counter, body_one_doubled) in
            [(8, 100 - 20 - 40, 0, true), (9, 100 - 40 - 20, 1, false)]
        {
            let (mut state, _, source) =
                heirloom_fixture(0, &[CardId::Alchemize, CardId::BeatDown]);
            let mut builder = CatalogBuilder::new();
            builder.intern(identity(CardId::HeirloomHammer, 0)).unwrap();
            builder.intern(identity(CardId::Alchemize, 0)).unwrap();
            builder.intern(identity(CardId::BeatDown, 0)).unwrap();
            builder.intern(identity(CardId::StrikeIronclad, 0)).unwrap();
            builder.intern_monster(MonsterKind::Axebot).unwrap();
            builder.intern_monster(MonsterKind::Mawler).unwrap();
            builder.set_relics(&[RelicId::RelicPenNib]).unwrap();
            let catalog = builder.build();
            assert!(state.fanouts.set_pen_nib(counter));
            state.powers.set(PowerId::OneTwoPunch, SlotWire::Int, 1);
            hydrate_side_end_order(&mut state);

            play_card(
                &mut state,
                &catalog,
                source.uid,
                Some(0),
                None,
                &mut Vec::new(),
            )
            .unwrap();
            resume_selection(
                &mut state,
                &catalog,
                crate::engine::SelectionAnswer::OptionIndex(0),
                &mut Vec::new(),
            )
            .unwrap();
            let body_one = pending_record(&state);
            assert_eq!(body_one.play_index, 1);
            assert_eq!(body_one.pen_double, body_one_doubled, "counter {counter}");
            resume_selection(
                &mut state,
                &catalog,
                crate::engine::SelectionAnswer::OptionIndex(0),
                &mut Vec::new(),
            )
            .unwrap();
            assert!(state.pending.is_none());
            assert_eq!(
                (state.monsters[0].hp, state.fanouts.pen_nib()),
                (expected_hp, expected_counter),
                "counter {counter}"
            );
        }
    }

    #[test]
    fn heirloom_hammer_replay_reselects_and_redirects_a_full_hand_clone() {
        let (mut state, catalog, source) =
            heirloom_fixture(0, &[CardId::Alchemize, CardId::BeatDown]);
        let strike_atom = catalog.atom(&identity(CardId::StrikeIronclad, 0)).unwrap();
        for uid in 30..=36 {
            state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
                uid,
                atom: strike_atom,
                flags: 0,
            });
        }
        assert_eq!(state.piles.get(PileId::Hand).len(), 10);
        state.powers.set(PowerId::OneTwoPunch, SlotWire::Int, 1);
        hydrate_side_end_order(&mut state);

        play_card(
            &mut state,
            &catalog,
            source.uid,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(state.monsters[0].hp, 80);
        assert_eq!(
            state
                .pending
                .as_deref()
                .unwrap()
                .record(&state.frames)
                .unwrap()
                .play_index,
            0
        );
        resume_selection(
            &mut state,
            &catalog,
            crate::engine::SelectionAnswer::OptionIndex(0),
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(state.monsters[0].hp, 60);
        assert_eq!(
            state
                .pending
                .as_deref()
                .unwrap()
                .record(&state.frames)
                .unwrap()
                .play_index,
            1
        );
        assert_eq!(state.piles.get(PileId::Hand).len(), 10);
        resume_selection(
            &mut state,
            &catalog,
            crate::engine::SelectionAnswer::OptionIndex(0),
            &mut Vec::new(),
        )
        .unwrap();

        assert!(state.pending.is_none());
        assert_eq!(state.history.owner_generated_cards_combat, 2);
        assert_eq!(state.piles.get(PileId::Hand).len(), 10);
        let discard = state.piles.get(PileId::Discard).as_slice();
        assert_eq!(
            discard[0].uid, 101,
            "the second clone redirects at Hand cap"
        );
        assert_eq!(discard[1], source);
        assert_eq!(state.history.card_plays_finished_combat, 2);
        assert_eq!(state.powers.value(PowerId::OneTwoPunch), 0);
    }

    #[test]
    fn heirloom_hammer_rehearses_every_late_clone_branch_atomically() {
        for field in [
            "next_card_uid",
            "owner_generated_cards_combat",
            "next_generated_hook_uid",
            "generated power batch",
        ] {
            let (mut state, catalog, source) =
                heirloom_fixture(0, &[CardId::Alchemize, CardId::BeatDown]);
            match field {
                "next_card_uid" => state.next_card_uid = u32::MAX,
                "owner_generated_cards_combat" => {
                    state.history.owner_generated_cards_combat = i32::MAX
                }
                "next_generated_hook_uid" => state.next_generated_hook_uid = i32::MAX,
                "generated power batch" => {
                    state
                        .powers
                        .set(PowerId::PillarOfCreation, SlotWire::Int, 1);
                    state.block = 999_999_999;
                    assert!(
                        state
                            .fanouts
                            .set_local_generated_power_order(&[PowerId::PillarOfCreation])
                    );
                }
                _ => unreachable!(),
            }
            let before = state.clone();
            let mut events = Vec::new();
            let refusal = play_card(&mut state, &catalog, source.uid, Some(0), None, &mut events)
                .unwrap_err();
            assert!(matches!(refusal, EngineRefusal::CounterOverflow(name) if name == field));
            assert_eq!(
                state, before,
                "{field} publishes no attack/spend/source prefix"
            );
            assert!(events.is_empty());
        }
    }

    #[test]
    fn heirloom_hammer_zero_option_rehearsal_authenticates_pending_ownership() {
        let (mut valid, catalog, source) =
            heirloom_fixture(0, &[CardId::Alchemize, CardId::BeatDown]);
        play_card(
            &mut valid,
            &catalog,
            source.uid,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert!(valid.pending.is_some());
        valid.piles.get_mut(PileId::Hand).make_mut().clear();
        assert_eq!(
            rehearse_heirloom_hammer_continuations(valid.clone(), &catalog, 0),
            Ok(()),
            "the authenticated zero-option continuation remains a valid rehearsal"
        );

        let frame_uid = valid.pending.as_deref().unwrap().frame_uid;
        let mut malformed = Vec::new();

        let mut missing = valid.clone();
        missing.frames = crate::hot::Frames::new();
        malformed.push(("missing owner", missing));

        let mut wrong_uid = valid.clone();
        wrong_uid.frames = crate::hot::Frames::new();
        let wrong_record = crate::hot::CardPlayRecord::pending_for_test(frame_uid + 1);
        let record = wrong_uid
            .frames
            .push_card_play(&wrong_record)
            .expect("valid wrong-uid record");
        std::sync::Arc::make_mut(wrong_uid.pending.as_mut().unwrap()).frame_record = record;
        malformed.push(("wrong uid owner", wrong_uid));

        let mut non_top = valid.clone();
        non_top.frames.push(crate::frame::Frame::JossSideEnd);
        malformed.push(("non-top owner", non_top));

        let mut stale = valid;
        std::sync::Arc::make_mut(stale.pending.as_mut().unwrap()).frame_record =
            crate::hot::WordRecordIndex::from_raw_for_test(99);
        malformed.push(("stale record index", stale));

        for (name, candidate) in malformed {
            assert_eq!(
                rehearse_heirloom_hammer_continuations(candidate, &catalog, 0),
                Err(EngineRefusal::ContinuationNotModeled),
                "{name} must refuse before the zero-count success path"
            );
        }
    }

    /// Dual Wield (#3374) root: the source at uid 10, then `others` in Hand
    /// from uid 20. The first card carries a mutable physical payload so a
    /// clone's copy of it is observable.
    fn dual_wield_fixture(upgrade: u8, others: &[CardId]) -> (HotState, Catalog, HotCard) {
        let mut builder = CatalogBuilder::new();
        let source_atom = builder
            .intern(identity(CardId::DualWield, upgrade))
            .unwrap();
        for id in others {
            builder.intern(identity(*id, 0)).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let source = HotCard {
            uid: 10,
            atom: source_atom,
            flags: 0,
        };
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.energy = 9;
        state.next_card_uid = 100;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        state.monsters_mut()[0].uid = 70;
        state.piles.get_mut(PileId::Hand).make_mut().push(source);
        for (offset, id) in others.iter().enumerate() {
            state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
                uid: 20 + offset as u32,
                atom: catalog.atom(&identity(*id, 0)).unwrap(),
                flags: if offset == 0 {
                    CARD_FLAG_DEFAULT_PHYSICAL_STATE
                } else {
                    0
                },
            });
        }
        if !others.is_empty() {
            state.card_states.set(
                20,
                CardInstanceState {
                    local_retain: true,
                    ..CardInstanceState::default()
                },
            );
        }
        (state, catalog, source)
    }

    #[test]
    fn dual_wield_clones_the_chosen_attack_or_power_one_plus_upgrade_times() {
        for upgrade in 0..=1u8 {
            let copies = usize::from(upgrade) + 1;
            for choice in 0..2u32 {
                let (mut state, catalog, source) = dual_wield_fixture(
                    upgrade,
                    &[
                        CardId::StrikeIronclad,
                        CardId::DefendIronclad,
                        CardId::Inflame,
                    ],
                );
                play_card(
                    &mut state,
                    &catalog,
                    source.uid,
                    None,
                    None,
                    &mut Vec::new(),
                )
                .unwrap();
                assert_eq!(state.energy, 8);
                assert!(state.pending.is_some(), "two eligible cards park a choice");
                let spec = catalog.spec(source.atom).unwrap();
                assert_eq!(
                    crate::engine::selection::option_count(&state, &catalog, spec, 0).unwrap(),
                    2,
                    "the Skill is not an Attack-or-Power candidate"
                );
                let hand_before = state.piles.get(PileId::Hand).as_slice().to_vec();
                resume_selection(
                    &mut state,
                    &catalog,
                    crate::engine::SelectionAnswer::OptionIndex(choice),
                    &mut Vec::new(),
                )
                .unwrap();
                assert!(state.pending.is_none());
                let hand = state.piles.get(PileId::Hand).as_slice();
                assert_eq!(hand.len(), hand_before.len() + copies);
                assert_eq!(
                    &hand[..hand_before.len()],
                    hand_before.as_slice(),
                    "the selected source is never removed"
                );
                let clones = &hand[hand_before.len()..];
                let chosen = hand_before
                    .iter()
                    .copied()
                    .find(|card| card.atom == clones[0].atom)
                    .unwrap();
                assert_ne!(
                    catalog.spec(chosen.atom).unwrap().identity.id,
                    CardId::DefendIronclad
                );
                for (index, clone) in clones.iter().enumerate() {
                    assert_eq!(clone.uid, 100 + index as u32, "fresh uid per clone");
                    assert_eq!((clone.atom, clone.flags), (chosen.atom, chosen.flags));
                    assert_eq!(
                        state.card_states.get(clone.uid),
                        state.card_states.get(chosen.uid),
                        "each clone copies the complete physical payload"
                    );
                }
                assert_eq!(state.history.owner_generated_cards_combat, copies as i32);
                assert_eq!(state.next_generated_hook_uid, copies as i32);
                assert_eq!(state.piles.get(PileId::Discard).as_slice(), &[source]);
            }
        }
    }

    #[test]
    fn dual_wield_auto_takes_one_candidate_and_no_ops_on_zero() {
        for upgrade in 0..=1u8 {
            let copies = usize::from(upgrade) + 1;
            let (mut one, catalog, source) =
                dual_wield_fixture(upgrade, &[CardId::Inflame, CardId::DefendIronclad]);
            play_card(&mut one, &catalog, source.uid, None, None, &mut Vec::new()).unwrap();
            assert!(one.pending.is_none(), "one candidate is auto-taken");
            let hand = one.piles.get(PileId::Hand).as_slice();
            assert_eq!(hand.len(), 2 + copies);
            assert!(hand[2..].iter().all(|clone| clone.atom == hand[0].atom));
            assert_eq!(one.history.owner_generated_cards_combat, copies as i32);

            let (mut zero, catalog, source) =
                dual_wield_fixture(upgrade, &[CardId::DefendIronclad]);
            play_card(&mut zero, &catalog, source.uid, None, None, &mut Vec::new()).unwrap();
            assert!(zero.pending.is_none());
            assert_eq!(zero.piles.get(PileId::Hand).len(), 1);
            assert_eq!(zero.history.owner_generated_cards_combat, 0);
            assert_eq!(zero.next_card_uid, 100);
            assert_eq!(zero.piles.get(PileId::Discard).as_slice(), &[source]);
        }
    }

    #[test]
    fn dual_wield_plus_redirects_the_second_clone_at_the_hand_cap() {
        let mut others = vec![CardId::StrikeIronclad];
        others.extend([CardId::DefendIronclad; 8]);
        let (mut state, catalog, source) = dual_wield_fixture(1, &others);
        assert_eq!(state.piles.get(PileId::Hand).len(), 10);
        play_card(
            &mut state,
            &catalog,
            source.uid,
            None,
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert!(state.pending.is_none(), "the lone Strike is auto-taken");
        let hand = state.piles.get(PileId::Hand).as_slice();
        assert_eq!(hand.len(), 10);
        assert_eq!(hand[9].uid, 100, "the first clone fills the nine-card Hand");
        let discard = state.piles.get(PileId::Discard).as_slice();
        assert_eq!(
            discard[0].uid, 101,
            "the second clone redirects at Hand cap"
        );
        assert_eq!(discard[0].atom, hand[0].atom);
        assert_eq!(discard[1], source);
        assert_eq!(state.history.owner_generated_cards_combat, 2);
    }

    #[test]
    fn dual_wield_parked_selection_round_trips_and_resumes_identically() {
        for upgrade in 0..=1u8 {
            let (mut state, catalog, source) =
                dual_wield_fixture(upgrade, &[CardId::StrikeIronclad, CardId::Inflame]);
            play_card(
                &mut state,
                &catalog,
                source.uid,
                None,
                None,
                &mut Vec::new(),
            )
            .unwrap();
            assert!(state.pending.is_some());
            let canonical = HotBoundary::to_canonical(&state, &catalog);
            let mut imported = HotBoundary::from_canonical(&canonical, &catalog).unwrap();
            assert_eq!(imported, state);
            for choice in 0..2u32 {
                let mut direct = state.clone();
                let mut resumed = imported.clone();
                for branch in [&mut direct, &mut resumed] {
                    resume_selection(
                        branch,
                        &catalog,
                        crate::engine::SelectionAnswer::OptionIndex(choice),
                        &mut Vec::new(),
                    )
                    .unwrap();
                }
                assert_eq!(resumed, direct);
            }
            assert!(
                resume_selection(
                    &mut imported,
                    &catalog,
                    crate::engine::SelectionAnswer::OptionIndex(2),
                    &mut Vec::new(),
                )
                .is_err()
            );
        }
    }

    #[test]
    fn dual_wield_rehearses_the_late_second_clone_atomically() {
        // With two candidates the choice parks, so only the whole-action
        // rehearsal can see the second clone's overflow before the
        // spend/source/CardPlayed prefix publishes.
        for (field, parked) in [
            ("owner_generated_cards_combat", true),
            ("next_generated_hook_uid", true),
            ("owner_generated_cards_combat", false),
        ] {
            let others: &[CardId] = if parked {
                &[CardId::StrikeIronclad, CardId::Inflame]
            } else {
                &[CardId::StrikeIronclad]
            };
            let (mut state, catalog, source) = dual_wield_fixture(1, others);
            match field {
                "owner_generated_cards_combat" => {
                    state.history.owner_generated_cards_combat = i32::MAX - 1
                }
                "next_generated_hook_uid" => state.next_generated_hook_uid = i32::MAX - 1,
                _ => unreachable!(),
            }
            let before = state.clone();
            let mut events = Vec::new();
            let refusal =
                play_card(&mut state, &catalog, source.uid, None, None, &mut events).unwrap_err();
            assert!(matches!(refusal, EngineRefusal::CounterOverflow(name) if name == field));
            assert_eq!(state, before, "{field}: no spend/source/clone prefix");
            assert!(events.is_empty());
        }
    }

    #[test]
    fn debilitate_attack_power_artifact_lamp_and_replay_are_one_atomic_play() {
        for upgrade in 0..=1 {
            let identity = identity(CardId::Debilitate, upgrade);
            let mut builder = CatalogBuilder::new();
            builder.intern(identity).unwrap();
            builder
                .set_relics(&[crate::ids::RelicId::RelicUnsettlingLamp])
                .unwrap();
            let catalog = builder.build();
            let mut state = state_with_card(&catalog, identity, 41);
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 100));
            state.fanouts.set_unsettling_lamp_available(true);
            let mut events = Vec::new();

            play_card(&mut state, &catalog, 41, Some(0), None, &mut events).unwrap();

            assert_eq!(
                state.monsters[0].hp,
                100 - if upgrade == 0 { 10 } else { 12 }
            );
            assert_eq!(
                state.monsters[0].powers.value(PowerId::Debilitate),
                if upgrade == 0 { 4 } else { 6 }
            );
            assert!(!state.fanouts.unsettling_lamp_available());
            assert_eq!(
                state.monsters[0].misery_debuff_order.as_slice(),
                &[crate::hot::MiseryToken::Debilitate]
            );
        }

        let identity = identity(CardId::Debilitate, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(identity).unwrap();
        builder
            .set_relics(&[crate::ids::RelicId::RelicUnsettlingLamp])
            .unwrap();
        let catalog = builder.build();
        let mut blocked = state_with_card(&catalog, identity, 42);
        blocked
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        blocked.monsters_mut()[0]
            .powers
            .set(PowerId::Artifact, SlotWire::Int, 1);
        blocked.fanouts.set_unsettling_lamp_available(true);
        play_card(&mut blocked, &catalog, 42, Some(0), None, &mut Vec::new()).unwrap();
        assert_eq!(blocked.monsters[0].hp, 90);
        assert_eq!(blocked.monsters[0].powers.value(PowerId::Artifact), 0);
        assert_eq!(blocked.monsters[0].powers.value(PowerId::Debilitate), 0);
        assert!(blocked.fanouts.unsettling_lamp_available());

        let mut replay = state_with_card(&catalog, identity, 43);
        replay
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        replay.fanouts.set_unsettling_lamp_available(true);
        replay.powers.set(PowerId::OneTwoPunch, SlotWire::Int, 1);
        hydrate_side_end_order(&mut replay);
        play_card(&mut replay, &catalog, 43, Some(0), None, &mut Vec::new()).unwrap();
        assert_eq!(replay.monsters[0].hp, 80);
        assert_eq!(replay.monsters[0].powers.value(PowerId::Debilitate), 6);
        assert!(!replay.fanouts.unsettling_lamp_available());

        let mut lethal = state_with_card(&catalog, identity, 45);
        lethal
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 10));
        lethal.monsters_mut()[0]
            .powers
            .set(PowerId::Artifact, SlotWire::Int, 1);
        lethal.fanouts.set_unsettling_lamp_available(true);
        play_card(&mut lethal, &catalog, 45, Some(0), None, &mut Vec::new()).unwrap();
        assert_eq!(lethal.monsters[0].hp, 0);
        assert_eq!(lethal.monsters[0].powers.value(PowerId::Artifact), 0);
        assert_eq!(lethal.monsters[0].powers.value(PowerId::Debilitate), 0);
        assert!(lethal.fanouts.unsettling_lamp_available());

        let mut stock = state_with_card(&catalog, identity, 46);
        let mut axebot = HotMonster::new(MonsterKind::Axebot, 10);
        axebot.max_hp = 86;
        axebot.uid = 1;
        axebot.powers.set(PowerId::Stock, SlotWire::Int, 1);
        stock.monsters_mut().push(axebot);
        let before = stock.clone();
        assert_eq!(
            play_card(&mut stock, &catalog, 46, Some(0), None, &mut Vec::new()),
            Err(EngineRefusal::MalformedArgs(
                "Debilitate Axebot Stock target identity"
            ))
        );
        assert_eq!(stock, before);
    }

    #[test]
    fn knockdown_attacks_then_appends_distinct_lamp_artifact_and_replay_instances() {
        for upgrade in 0..=1 {
            let identity = identity(CardId::Knockdown, upgrade);
            let mut builder = CatalogBuilder::new();
            builder.intern(identity).unwrap();
            builder
                .set_relics(&[crate::ids::RelicId::RelicUnsettlingLamp])
                .unwrap();
            let catalog = builder.build();
            let mut state = state_with_card(&catalog, identity, 71 + u32::from(upgrade));
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 100));
            state.fanouts.set_unsettling_lamp_available(true);

            play_card(
                &mut state,
                &catalog,
                71 + u32::from(upgrade),
                Some(0),
                None,
                &mut Vec::new(),
            )
            .unwrap();

            assert_eq!(
                state.monsters[0].hp,
                100 - if upgrade == 0 { 10 } else { 14 }
            );
            assert_eq!(
                state.monsters[0].misery_debuff_order.knockdown(),
                if upgrade == 0 { &[4][..] } else { &[6][..] }
            );
            assert_eq!(
                state.monsters[0].misery_debuff_order.as_slice(),
                &[crate::hot::MiseryToken::Knockdown]
            );
            assert!(!state.fanouts.unsettling_lamp_available());
        }

        let identity = identity(CardId::Knockdown, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(identity).unwrap();
        builder
            .set_relics(&[crate::ids::RelicId::RelicUnsettlingLamp])
            .unwrap();
        let catalog = builder.build();
        let mut artifact = state_with_card(&catalog, identity, 73);
        artifact
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        artifact.monsters_mut()[0]
            .powers
            .set(PowerId::Artifact, SlotWire::Int, 1);
        // This legacy scalar combination has no uniquely reconstructible
        // Misery acquisition order. Artifact suppresses Knockdown before
        // Misery can observe it, so the ordinary play remains admissible.
        artifact.monsters_mut()[0]
            .powers
            .set(PowerId::Weak, SlotWire::Int, 2);
        artifact.monsters_mut()[0]
            .powers
            .set(PowerId::Vuln, SlotWire::Int, 3);
        artifact.fanouts.set_unsettling_lamp_available(true);
        play_card(&mut artifact, &catalog, 73, Some(0), None, &mut Vec::new()).unwrap();
        assert_eq!(artifact.monsters[0].hp, 85);
        assert_eq!(artifact.monsters[0].powers.value(PowerId::Artifact), 0);
        assert_eq!(artifact.monsters[0].powers.value(PowerId::Weak), 2);
        assert_eq!(artifact.monsters[0].powers.value(PowerId::Vuln), 3);
        assert!(
            artifact.monsters[0]
                .misery_debuff_order
                .knockdown()
                .is_empty()
        );
        assert!(artifact.fanouts.unsettling_lamp_available());

        let mut replay = state_with_card(&catalog, identity, 74);
        replay
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        replay.powers.set(PowerId::OneTwoPunch, SlotWire::Int, 1);
        hydrate_side_end_order(&mut replay);
        play_card(&mut replay, &catalog, 74, Some(0), None, &mut Vec::new()).unwrap();
        assert_eq!(replay.monsters[0].hp, 80);
        assert_eq!(replay.monsters[0].misery_debuff_order.knockdown(), [2, 2]);
        assert_eq!(
            replay.monsters[0].misery_debuff_order.as_slice(),
            [
                crate::hot::MiseryToken::Knockdown,
                crate::hot::MiseryToken::Knockdown,
            ]
        );

        let mut lethal = state_with_card(&catalog, identity, 75);
        lethal
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 10));
        lethal.fanouts.set_unsettling_lamp_available(true);
        play_card(&mut lethal, &catalog, 75, Some(0), None, &mut Vec::new()).unwrap();
        assert_eq!(lethal.monsters[0].hp, 0);
        assert!(
            lethal.monsters[0]
                .misery_debuff_order
                .knockdown()
                .is_empty()
        );
        assert!(lethal.fanouts.unsettling_lamp_available());

        let mut stock = state_with_card(&catalog, identity, 76);
        let mut axebot = HotMonster::new(MonsterKind::Axebot, 10);
        axebot.max_hp = 86;
        axebot.uid = 1;
        axebot.powers.set(PowerId::Stock, SlotWire::Int, 1);
        stock.monsters_mut().push(axebot);
        play_card(&mut stock, &catalog, 76, Some(0), None, &mut Vec::new()).unwrap();
        assert_eq!(stock.monsters[0].uid, 2);
        assert!(stock.monsters[0].misery_debuff_order.knockdown().is_empty());
    }

    #[test]
    fn knockdown_late_power_listener_and_replay_failure_restore_the_public_play() {
        let knockdown = identity(CardId::Knockdown, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let knockdown_atom = builder.intern(knockdown).unwrap();
        let defend_atom = builder.intern(defend).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.energy = 9;
        state.next_card_uid = 80;
        state.powers.set(PowerId::OneTwoPunch, SlotWire::Int, 1);
        hydrate_side_end_order(&mut state);
        state.powers.set(PowerId::Vicious, SlotWire::Int, 1);
        assert!(
            state
                .fanouts
                .set_after_power_amount_changed_order(&[PowerId::Vicious])
        );
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 77,
            atom: knockdown_atom,
            flags: 0,
        });
        state.piles.get_mut(PileId::Draw).make_mut().extend([
            HotCard {
                uid: 78,
                atom: u16::MAX,
                flags: 0,
            },
            HotCard {
                uid: 79,
                atom: defend_atom,
                flags: 0,
            },
        ]);
        let before = state.clone();
        let mut events = vec![Event::TurnBegan { turn: 81 }];
        let events_before = events.clone();

        assert_eq!(
            play_card(&mut state, &catalog, 77, Some(0), None, &mut events),
            Err(EngineRefusal::UnknownAtom(u16::MAX))
        );
        assert_eq!(state, before);
        assert_eq!(events, events_before);
    }

