    #[test]
    fn strangle_suffix_is_unpowered_unblockable_and_uid_authenticated() {
        let catalog = CatalogBuilder::new().build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        let mut owner = HotMonster::new(MonsterKind::Toadpole, 20);
        owner.uid = 7;
        owner.block = 99;
        owner.powers.set(PowerId::Strangle, SlotWire::Int, 3);
        owner
            .misery_debuff_order
            .push(crate::hot::MiseryToken::Strangle);
        state.monsters_mut().push(owner);
        let latch = CardPlayedPowerLatch {
            strangle_latches: vec![(7, 3)],
            ..Default::default()
        };
        apply_strangle_after_card_played(&mut state, &catalog, &latch, &mut Vec::new()).unwrap();
        assert_eq!(state.monsters[0].hp, 17);
        assert_eq!(state.monsters[0].block, 99);

        state.monsters_mut()[0].uid = 8;
        apply_strangle_after_card_played(&mut state, &catalog, &latch, &mut Vec::new()).unwrap();
        assert_eq!(
            state.monsters[0].hp, 17,
            "a replacement cannot inherit the latch"
        );
    }

    #[test]
    fn enemy_suffix_runs_native_then_strangle_for_each_owner_in_roster_order() {
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(strike).unwrap();
        builder
            .intern_monster(MonsterKind::LouseProgenitor)
            .unwrap();
        let catalog = builder.build();
        let spec = catalog.spec(atom).unwrap();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.piles.get_mut(PileId::Play).make_mut().push(HotCard {
            uid: 41,
            atom,
            flags: 0,
        });
        for (uid, amount) in [(7, 2), (8, 3)] {
            let mut owner = HotMonster::new(MonsterKind::LouseProgenitor, 30);
            owner.uid = uid;
            owner.curl_up_card_uid = 41;
            owner.powers.set(PowerId::CurlUp, SlotWire::Int, 18);
            owner.powers.set(PowerId::Strangle, SlotWire::Int, amount);
            owner
                .misery_debuff_order
                .push(crate::hot::MiseryToken::Strangle);
            state.monsters_mut().push(owner);
        }
        let latch = CardPlayedPowerLatch {
            strangle_latches: vec![(7, 2), (8, 3)],
            ..Default::default()
        };
        let shared_roster = state.monsters.clone();
        let mut events = Vec::new();

        after_card_played_enemy_suffix(&mut state, &catalog, spec, 41, false, &latch, &mut events)
            .unwrap();

        assert!(!std::sync::Arc::ptr_eq(&state.monsters, &shared_roster));
        let owner_suffix: Vec<_> = events
            .iter()
            .filter_map(|event| match event {
                Event::PowerChanged {
                    subject: Subject::Monster(uid),
                    power: PowerId::CurlUp,
                    amount: 0,
                } => Some((*uid, "curl")),
                Event::MonsterDamaged {
                    uid,
                    blocked: 0,
                    unblocked,
                    ..
                } if *unblocked == 2 || *unblocked == 3 => Some((*uid, "strangle")),
                _ => None,
            })
            .collect();
        assert_eq!(
            owner_suffix,
            [(7, "curl"), (7, "strangle"), (8, "curl"), (8, "strangle")]
        );
    }

    #[test]
    fn oblivion_first_cast_recast_and_callback_artifact_are_exact() {
        let oblivion = identity(CardId::Oblivion, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(oblivion).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, oblivion, 61);
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 62,
            atom,
            flags: 0,
        });
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));

        play_card(&mut state, &catalog, 61, Some(0), None, &mut Vec::new()).unwrap();
        assert_eq!(state.monsters[0].powers.value(PowerId::Oblivion), 3);
        assert_eq!(state.monsters[0].powers.value(PowerId::Doom), 0);
        assert_eq!(
            state.monsters[0].misery_debuff_order.as_slice(),
            &[crate::hot::MiseryToken::Oblivion]
        );

        play_card(&mut state, &catalog, 62, Some(0), None, &mut Vec::new()).unwrap();
        assert_eq!(state.monsters[0].powers.value(PowerId::Oblivion), 6);
        assert_eq!(state.monsters[0].powers.value(PowerId::Doom), 3);
        assert_eq!(
            state.monsters[0].misery_debuff_order.as_slice(),
            &[
                crate::hot::MiseryToken::Oblivion,
                crate::hot::MiseryToken::Doom,
            ]
        );

        let mut callback_blocked = CardPlayedPowerLatch::default();
        callback_blocked
            .oblivion_latches
            .push((state.monsters[0].uid, 6));
        state.monsters_mut()[0]
            .powers
            .set(PowerId::Artifact, SlotWire::Int, 1);
        apply_oblivion_after_card_played_owner(&mut state, 0, &callback_blocked, &mut Vec::new())
            .unwrap();
        assert_eq!(state.monsters[0].powers.value(PowerId::Artifact), 0);
        assert_eq!(state.monsters[0].powers.value(PowerId::Doom), 3);

        let mut party = state_with_card(&catalog, oblivion, 63);
        party.multiplayer_ally_key = 1;
        party
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        let before = party.clone();
        let mut events = Vec::new();
        assert_eq!(
            play_card(&mut party, &catalog, 63, Some(0), None, &mut events),
            Err(EngineRefusal::MalformedArgs(
                "Oblivion local applier identity"
            ))
        );
        assert_eq!(party, before);
        assert!(events.is_empty());
    }

    #[test]
    fn oblivion_and_strangle_callbacks_follow_exact_misery_acquisition_order() {
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(strike).unwrap();
        let catalog = builder.build();
        let spec = catalog.spec(atom).unwrap();

        for (order, doom_before_damage) in [
            (
                [
                    crate::hot::MiseryToken::Oblivion,
                    crate::hot::MiseryToken::Strangle,
                ],
                true,
            ),
            (
                [
                    crate::hot::MiseryToken::Strangle,
                    crate::hot::MiseryToken::Oblivion,
                ],
                false,
            ),
        ] {
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.piles.get_mut(PileId::Play).make_mut().push(HotCard {
                uid: 71,
                atom,
                flags: 0,
            });
            let mut owner = HotMonster::new(MonsterKind::Toadpole, 40);
            owner.uid = 5;
            owner.powers.set(PowerId::Oblivion, SlotWire::Int, 3);
            owner.powers.set(PowerId::Strangle, SlotWire::Int, 2);
            for token in order {
                owner.misery_debuff_order.push(token);
            }
            state.monsters_mut().push(owner);
            let latch = CardPlayedPowerLatch {
                oblivion_latches: vec![(5, 3)],
                strangle_latches: vec![(5, 2)],
                ..Default::default()
            };
            let mut events = Vec::new();

            after_card_played_enemy_suffix(
                &mut state,
                &catalog,
                spec,
                71,
                false,
                &latch,
                &mut events,
            )
            .unwrap();

            let doom_index = events
                .iter()
                .position(|event| {
                    matches!(
                        event,
                        Event::PowerChanged {
                            subject: Subject::Monster(5),
                            power: PowerId::Doom,
                            amount: 3,
                        }
                    )
                })
                .unwrap();
            let damage_index = events
                .iter()
                .position(|event| {
                    matches!(
                        event,
                        Event::MonsterDamaged {
                            uid: 5,
                            unblocked: 2,
                            ..
                        }
                    )
                })
                .unwrap();
            assert_eq!(doom_index < damage_index, doom_before_damage);
        }
    }

