    #[test]
    fn the_ball_grows_and_moves_to_remote_draw_with_two_ordered_rng_draws() {
        let ball = identity(CardId::TheBall, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(ball).unwrap();
        builder.intern(identity(CardId::TheBall, 1)).unwrap();
        builder.intern(defend).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, ball, 17);
        state.piles.get_mut(PileId::Hand).make_mut()[0].flags = CARD_FLAG_DEFAULT_PHYSICAL_STATE;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        state.rng.set(
            RngStream::Targets,
            RngStreamState {
                words: [41, 42, 43, 44],
                counter: 0,
            },
        );
        state.multiplayer_ally_key = 1;
        state.fanouts.set_multiplayer_ally(MultiplayerAllyState {
            key: 1,
            draw: std::sync::Arc::new(vec![MultiplayerAllyCard::immutable(defend).unwrap()]),
            shuffle_rng: Some(RngStreamState {
                words: [31, 32, 33, 34],
                counter: 0,
            }),
            ..MultiplayerAllyState::default()
        });
        let targets_before = state.rng.get(RngStream::Targets).counter;
        let shuffle_before = state
            .fanouts
            .multiplayer_ally()
            .shuffle_rng
            .unwrap()
            .counter;

        let mut events = Vec::new();
        play_card(&mut state, &catalog, 17, Some(0), None, &mut events).unwrap();

        assert_eq!(state.monsters[0].hp, 90);
        assert_eq!(
            state.rng.get(RngStream::Targets).counter,
            targets_before + 1
        );
        let ally = state.fanouts.multiplayer_ally();
        assert_eq!(ally.shuffle_rng.unwrap().counter, shuffle_before + 1);
        let remote = ally
            .draw
            .iter()
            .copied()
            .find(|card| matches!(card.identity.id, CardId::TheBall))
            .unwrap();
        assert_eq!(remote.the_ball_growth(), Some(10));
        assert!(PileId::ALL.into_iter().all(|pile| {
            !state
                .piles
                .get(pile)
                .as_slice()
                .iter()
                .any(|card| card.uid == 17)
        }));
        assert_eq!(state.card_states.get(17), CardInstanceState::default());
        assert!(
            !events
                .iter()
                .any(|event| matches!(event, Event::CardResolved { uid: 17, .. }))
        );
    }

    fn the_ball_play_fixture(
        upgrade: u8,
        growth: i32,
        remote_draw: Vec<MultiplayerAllyCard>,
    ) -> (Catalog, HotState) {
        let ball = identity(CardId::TheBall, upgrade);
        let mut builder = CatalogBuilder::new();
        builder.intern(identity(CardId::TheBall, 0)).unwrap();
        builder.intern(identity(CardId::TheBall, 1)).unwrap();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, ball, 17);
        state.exact_piles = true;
        state.piles.get_mut(PileId::Hand).make_mut()[0].flags = CARD_FLAG_DEFAULT_PHYSICAL_STATE;
        state.card_states.set(
            17,
            CardInstanceState {
                damage_growth: growth,
                ..CardInstanceState::default()
            },
        );
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 200);
        monster.max_hp = 200;
        state.monsters_mut().push(monster);
        state.rng.set(
            RngStream::Targets,
            RngStreamState {
                words: [41, 42, 43, 44],
                counter: 0,
            },
        );
        state.multiplayer_ally_key = 1;
        state.fanouts.set_multiplayer_ally(MultiplayerAllyState {
            key: 1,
            draw: std::sync::Arc::new(remote_draw),
            shuffle_rng: Some(RngStreamState {
                words: [31, 32, 33, 34],
                counter: 0,
            }),
            ..MultiplayerAllyState::default()
        });
        (catalog, state)
    }

    #[test]
    fn the_ball_upgraded_empty_remote_and_autoplay_preserve_rng_order() {
        let (catalog, mut upgraded) = the_ball_play_fixture(1, 30, Vec::new());
        play_card(&mut upgraded, &catalog, 17, Some(0), None, &mut Vec::new()).unwrap();
        assert_eq!(upgraded.monsters[0].hp, 160);
        let remote = upgraded.fanouts.multiplayer_ally();
        assert_eq!(remote.draw[0].the_ball_growth(), Some(45));
        assert_eq!(remote.shuffle_rng.unwrap().counter, 1);

        let (catalog, mut autoplay) = the_ball_play_fixture(0, 0, Vec::new());
        let source = autoplay.piles.get(PileId::Hand).as_slice()[0];
        autoplay_collected_cards(&mut autoplay, &catalog, &[source], &mut Vec::new()).unwrap();
        assert_eq!(autoplay.rng.get(RngStream::Targets).counter, 2);
        assert_eq!(
            autoplay
                .fanouts
                .multiplayer_ally()
                .shuffle_rng
                .unwrap()
                .counter,
            1
        );
        assert_eq!(
            autoplay.fanouts.multiplayer_ally().draw[0].the_ball_growth(),
            Some(10)
        );
    }

    #[test]
    fn the_ball_requires_exact_target_and_transfer_stream_authority() {
        let (catalog, exact) = the_ball_play_fixture(0, 0, Vec::new());
        let source = exact.piles.get(PileId::Hand).as_slice()[0];
        let spec = catalog.spec(source.atom).unwrap();
        assert!(can_play(&catalog, &exact, source, spec));

        let mut missing_targets = exact.clone();
        missing_targets
            .rng
            .set(RngStream::Targets, RngStreamState::default());
        assert!(!can_play(&catalog, &missing_targets, source, spec));
        let before = missing_targets.clone();
        let mut events = Vec::new();
        assert!(
            play_card(
                &mut missing_targets,
                &catalog,
                17,
                Some(0),
                None,
                &mut events
            )
            .is_err()
        );
        assert_eq!(missing_targets, before);
        assert!(events.is_empty());

        let mut malformed_targets = exact.clone();
        malformed_targets.rng.set(
            RngStream::Targets,
            RngStreamState {
                words: [0; 4],
                counter: 1,
            },
        );
        assert!(!can_play(&catalog, &malformed_targets, source, spec));
        let before = malformed_targets.clone();
        let mut events = Vec::new();
        assert!(
            play_card(
                &mut malformed_targets,
                &catalog,
                17,
                Some(0),
                None,
                &mut events
            )
            .is_err()
        );
        assert_eq!(malformed_targets, before);
        assert!(events.is_empty());

        let mut missing_shuffle = exact.clone();
        missing_shuffle.fanouts.multiplayer_ally_mut().shuffle_rng = None;
        assert!(!can_play(&catalog, &missing_shuffle, source, spec));
        let before = missing_shuffle.clone();
        assert!(
            play_card(
                &mut missing_shuffle,
                &catalog,
                17,
                Some(0),
                None,
                &mut Vec::new()
            )
            .is_err()
        );
        assert_eq!(missing_shuffle, before);

        let mut malformed_shuffle = exact.clone();
        malformed_shuffle.fanouts.multiplayer_ally_mut().shuffle_rng = Some(RngStreamState {
            words: [0; 4],
            counter: 1,
        });
        assert!(!can_play(&catalog, &malformed_shuffle, source, spec));
        let before = malformed_shuffle.clone();
        let mut events = Vec::new();
        assert!(
            play_card(
                &mut malformed_shuffle,
                &catalog,
                17,
                Some(0),
                None,
                &mut events
            )
            .is_err()
        );
        assert_eq!(malformed_shuffle, before);
        assert!(events.is_empty());

        let mut dupe = exact;
        dupe.piles.get_mut(PileId::Hand).make_mut()[0].flags |= crate::hot::CARD_FLAG_DUPE;
        dupe.fanouts.multiplayer_ally_mut().shuffle_rng = None;
        let source = dupe.piles.get(PileId::Hand).as_slice()[0];
        assert!(can_play(&catalog, &dupe, source, spec));
        play_card(&mut dupe, &catalog, 17, Some(0), None, &mut Vec::new()).unwrap();
        assert!(dupe.fanouts.multiplayer_ally().shuffle_rng.is_none());
        assert_eq!(dupe.rng.get(RngStream::Targets).counter, 1);
    }

