    #[test]
    fn the_ball_terminal_paths_keep_the_grown_local_uid_without_shuffle() {
        for owner_death in [false, true] {
            let (catalog, mut state) = the_ball_play_fixture(0, 0, Vec::new());
            if owner_death {
                state.hp = 1;
                state.monsters_mut()[0]
                    .powers
                    .set(PowerId::Thorns, SlotWire::Int, 1);
            } else {
                state.monsters_mut()[0].hp = 5;
            }
            let mut events = Vec::new();
            play_card(&mut state, &catalog, 17, Some(0), None, &mut events).unwrap();
            assert!(state.history.over);
            assert_eq!(state.rng.get(RngStream::Targets).counter, 1);
            assert_eq!(
                state
                    .fanouts
                    .multiplayer_ally()
                    .shuffle_rng
                    .unwrap()
                    .counter,
                0
            );
            assert!(state.fanouts.multiplayer_ally().draw.is_empty());
            assert_eq!(state.piles.get(PileId::Play).as_slice()[0].uid, 17);
            assert_eq!(state.card_states.get(17).damage_growth, 10);
            assert!(
                !events
                    .iter()
                    .any(|event| matches!(event, Event::CardResolved { uid: 17, .. }))
            );
            assert_eq!(
                state.history.card_plays_finished_combat,
                if owner_death { 0 } else { 1 }
            );
        }
    }

