    #[test]
    fn the_ball_post_route_card_finish_roundtrips_and_rejects_forged_pairs() {
        let identities = [
            identity(CardId::TheBall, 0),
            identity(CardId::TheBall, 1),
            identity(CardId::PommelStrike, 0),
            identity(CardId::SeekerStrike, 0),
            identity(CardId::DefendIronclad, 0),
            identity(CardId::Bash, 0),
            identity(CardId::Anger, 0),
        ];
        let mut builder = CatalogBuilder::new();
        for identity in identities {
            builder.intern_reachable(identity).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        builder
            .set_relics(&[crate::ids::RelicId::RelicUnceasingTop])
            .unwrap();
        builder.mark_persistent_action_replay_required();
        let catalog = builder.build();
        let atom = |id| catalog.atom(&identity(id, 0)).unwrap();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.energy = 3;
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.next_card_uid = 6;
        state.exact_piles = true;
        for stream in [RngStream::Sel, RngStream::Rng, RngStream::Targets] {
            state.rng.set(
                stream,
                RngStreamState {
                    words: [1, 2, 3, 4],
                    counter: 0,
                },
            );
        }
        assert!(
            state
                .fanouts
                .set_potion_belt(vec![None], false, false, false, false, true)
        );
        state.fanouts.set_unceasing_top(true);
        state.powers.set(PowerId::Hellraiser, SlotWire::Int, 1);
        state.multiplayer_ally_key = 1;
        state.fanouts.set_multiplayer_ally(MultiplayerAllyState {
            key: 1,
            shuffle_rng: Some(RngStreamState {
                words: [31, 32, 33, 34],
                counter: 0,
            }),
            ..MultiplayerAllyState::default()
        });
        hydrate_side_end_order(&mut state);
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 0,
            atom: atom(CardId::TheBall),
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        });
        for (uid, id) in [
            (1, CardId::PommelStrike),
            (2, CardId::SeekerStrike),
            (3, CardId::DefendIronclad),
            (4, CardId::Bash),
            (5, CardId::Anger),
        ] {
            state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
                uid,
                atom: atom(id),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            });
        }
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 1_000);
        monster.max_hp = 1_000;
        state.monsters_mut().push(monster);

        let start = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&start).unwrap();
        let state = HotBoundary::from_canonical(&start, &catalog).unwrap();
        crate::engine::admit(&start, &state, &catalog).unwrap();
        let parked = crate::engine::apply_action(
            &state,
            &catalog,
            &crate::engine::Action::Play {
                uid: 0,
                target: Some(0),
                selection: crate::engine::SelectionRef::NONE,
            },
        )
        .unwrap()
        .state;
        let crate::frame::Frame::CardFinish { record } = parked.frames.as_slice()[1] else {
            panic!("The Ball post-route Top owner must be CardFinish")
        };
        let finish = parked.frames.card_finish(record).unwrap();
        assert_eq!(finish.result_route, CardResultRoute::RemoteDrawRandom);
        assert_eq!(finish.routed_uid, None);
        assert_eq!(
            parked.fanouts.multiplayer_ally().draw[0].the_ball_growth(),
            Some(10)
        );
        let mut wrong_source = finish.clone();
        wrong_source.payload.card.atom = atom(CardId::DefendIronclad);
        assert!(!card_finish_the_ball_route_is_exact(
            &parked,
            &catalog,
            &wrong_source
        ));

        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        assert_eq!(
            wire.continuations[1].fields["result_location"],
            serde_json::json!(["the_ball_remote_draw", 1])
        );
        for (field, value) in [
            ("result_location", serde_json::json!(["discard", "bottom"])),
            ("routed_uid", serde_json::json!(0)),
        ] {
            let mut forged = wire.clone();
            forged.continuations[1]
                .fields
                .insert(field.to_owned(), value);
            let forged_catalog = HotBoundary::catalog_from_canonical(&forged).unwrap();
            assert!(HotBoundary::from_canonical(&forged, &forged_catalog).is_err());
        }
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let rebuilt = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        crate::engine::admit(&wire, &rebuilt, &rebuilt_catalog).unwrap();
        let answer = crate::engine::legal_actions(&rebuilt, &rebuilt_catalog)[0];
        let completed = crate::engine::apply_action(&rebuilt, &rebuilt_catalog, &answer)
            .unwrap()
            .state;
        assert!(completed.frames.is_empty() && completed.pending.is_none());
        assert_eq!(
            completed
                .fanouts
                .multiplayer_ally()
                .draw
                .iter()
                .filter(|card| matches!(card.identity.id, CardId::TheBall))
                .count(),
            1
        );
    }

