    fn demonic_shield_routes_post_loss_owner_block_locally_or_remotely_at_both_levels() {
        for upgrade in 0..=1 {
            let identity = identity(CardId::DemonicShield, upgrade);
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(identity).unwrap();
            let catalog = builder.build();
            for target in [0, 1] {
                let mut state = state_with_card(&catalog, identity, 17);
                // A live enemy keeps `damage_combat_is_ending` false (#3218).
                state.monsters_mut().push(crate::hot::HotMonster::new(
                    crate::ids::MonsterKind::Toadpole,
                    99,
                ));
                state.hp = 9;
                state.block = 4;
                state.multiplayer_ally_key = 1;
                state.fanouts.set_multiplayer_ally(MultiplayerAllyState {
                    key: 1,
                    block: 3,
                    ..MultiplayerAllyState::default()
                });

                play_card(
                    &mut state,
                    &catalog,
                    17,
                    Some(target),
                    None,
                    &mut Vec::new(),
                )
                .unwrap();

                assert_eq!(state.hp, 8, "upgrade {upgrade}, target {target}");
                assert_eq!(state.block, if target == 0 { 8 } else { 4 });
                assert_eq!(
                    state.fanouts.multiplayer_ally().block,
                    if target == 1 { 7 } else { 3 }
                );
                let result = if upgrade == 0 {
                    PileId::Exhaust
                } else {
                    PileId::Discard
                };
                assert_eq!(
                    state.piles.get(result).as_slice(),
                    &[HotCard {
                        uid: 17,
                        atom,
                        flags: 0,
                    }]
                );
            }
        }
    }

    /// #3218: Demonic Shield's Block is `CreatureCmd::GainBlock`
    /// (`DemonicShield/<OnPlay>d__9` 0x3989f0 IL_0113), which returns at
    /// IsOverOrEnding (`<GainBlock>d__18` 0x3eaec0 IL_0032). With the only
    /// primary dead and a live secondary, before history.over latches, the
    /// play still loses its HP (the `Damage` at IL_007b) but neither Player
    /// gains Block; an Adaptable veto keeps combat live and the Block lands.
    #[test]
    fn demonic_shield_block_skips_while_combat_is_ending_before_the_over_latch() {
        let identity = identity(CardId::DemonicShield, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(identity).unwrap();
        let catalog = builder.build();
        for (vetoed, target) in [(false, 0), (false, 1), (true, 0), (true, 1)] {
            let mut state = state_with_card(&catalog, identity, 17);
            state.hp = 9;
            state.block = 4;
            state.multiplayer_ally_key = 1;
            state.fanouts.set_multiplayer_ally(MultiplayerAllyState {
                key: 1,
                block: 3,
                ..MultiplayerAllyState::default()
            });
            let mut dead = crate::hot::HotMonster::new(crate::ids::MonsterKind::Toadpole, 0);
            if vetoed {
                dead.powers.set(PowerId::Adaptable, SlotWire::Int, 1);
            }
            state.monsters_mut().push(dead);
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::GasBomb,
                10,
            ));
            assert!(!state.history.over);
            assert_eq!(
                crate::engine::damage::damage_combat_is_ending(&state),
                !vetoed
            );

            play_card(
                &mut state,
                &catalog,
                17,
                Some(target),
                None,
                &mut Vec::new(),
            )
            .unwrap();

            assert_eq!(state.hp, 8, "vetoed {vetoed}, target {target}");
            let expected = match (vetoed, target) {
                (false, _) => (4, 3),
                (true, 0) => (8, 3),
                (true, _) => (4, 7),
            };
            assert_eq!(
                (state.block, state.fanouts.multiplayer_ally().block),
                expected,
                "vetoed {vetoed}, target {target}"
            );
        }
    }

