    /// #3160: each card's trailing `PowerCmd.Apply<T>` after its own attack
    /// is skipped at ``PowerCmd/<Apply>d__1`1::MoveNext`` (RVA `0x3ef988`)
    /// IL_0020-0x0034 when that attack ended combat; a non-lethal play still
    /// applies the grant.
    fn trailing_grant_after_attack(card: CardId, upgrade: u8, monster_hp: i32) -> (HotState, i32) {
        let identity = identity(card, upgrade);
        let mut builder = CatalogBuilder::new();
        builder.intern(identity).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, identity, 7);
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, monster_hp));
        play_card(&mut state, &catalog, 7, Some(0), None, &mut Vec::new()).unwrap();
        let focus = state.orbs.temp_focus();
        (state, focus)
    }

    #[test]
    fn lethal_attack_skips_its_trailing_free_cost_grant() {
        for (card, power) in [
            (CardId::Unrelenting, PowerId::FreeAttack),
            (CardId::Pounce, PowerId::FreeSkill),
            (CardId::Synthesis, PowerId::FreePower),
            (CardId::Veilpiercer, PowerId::FreeEthereal),
        ] {
            for upgrade in [0, 1] {
                let (lethal, _) = trailing_grant_after_attack(card, upgrade, 1);
                assert!(lethal.history.over, "{card:?}+{upgrade} ends combat");
                assert_eq!(
                    lethal.powers.value(power),
                    0,
                    "{card:?}+{upgrade}: IsEnding skips the grant"
                );
                let (alive, _) = trailing_grant_after_attack(card, upgrade, 200);
                assert!(!alive.history.over);
                assert_eq!(
                    alive.powers.value(power),
                    1,
                    "{card:?}+{upgrade}: a non-lethal play still grants"
                );
            }
        }
    }

    /// Predator (`0x3b34c4`: Attack IL_004c, `Apply<DrawCardsNextTurnPower>`
    /// IL_00fe), Salvo (`0x3b8390`: IL_004c, `Apply<RetainHandPower>`
    /// IL_00fd) and Hegemony (`0x3a44ec`: IL_004c, `Apply<EnergyNextTurnPower>`
    /// IL_0111) all reach their power through `PowerCmd.Apply<T>`, which
    /// returns at its IsEnding gate (RVA `0x3ef988` IL_0020-0x0034) once the
    /// attack has killed the last enemy (#3183).
    #[test]
    fn lethal_attack_skips_its_trailing_player_power_apply() {
        for (card, power, amounts) in [
            (CardId::Predator, PowerId::DrawNextTurn, [2, 2]),
            (CardId::Salvo, PowerId::RetainHand, [1, 1]),
            (CardId::Hegemony, PowerId::EnergyNextTurn, [2, 3]),
        ] {
            for (upgrade, amount) in [(0_u8, amounts[0]), (1, amounts[1])] {
                let (lethal, _) = trailing_grant_after_attack(card, upgrade, 1);
                assert!(lethal.history.over, "{card:?}+{upgrade} ends combat");
                assert_eq!(
                    lethal.powers.value(power),
                    0,
                    "{card:?}+{upgrade}: IsEnding skips the apply"
                );
                let (alive, _) = trailing_grant_after_attack(card, upgrade, 200);
                assert!(!alive.history.over);
                assert_eq!(
                    alive.powers.value(power),
                    amount,
                    "{card:?}+{upgrade}: a non-lethal play still applies"
                );
            }
        }
    }

    #[test]
    fn lethal_focused_strike_skips_its_temporary_focus() {
        for (upgrade, amount) in [(0_u8, 1), (1, 2)] {
            let (lethal, temp_focus) =
                trailing_grant_after_attack(CardId::FocusedStrike, upgrade, 1);
            assert!(lethal.history.over);
            assert_eq!(temp_focus, 0, "Focused Strike+{upgrade} lethal");
            assert_eq!(lethal.powers.value(PowerId::Focus), 0);
            let (alive, temp_focus) =
                trailing_grant_after_attack(CardId::FocusedStrike, upgrade, 200);
            assert!(!alive.history.over);
            assert_eq!(temp_focus, amount, "Focused Strike+{upgrade} non-lethal");
        }
    }

