    #[test]
    fn serpent_form_freezes_old_amount_and_haunt_reads_live_soul_amount() {
        let serpent = identity(CardId::SerpentForm, 0);
        let haunt = identity(CardId::Haunt, 0);
        let soul = identity(CardId::Soul, 0);
        let mut builder = CatalogBuilder::new();
        for card in [serpent, haunt, soul] {
            builder.intern(card).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, serpent, 1);
        for (uid, card) in [(2, serpent), (3, haunt), (4, soul), (5, soul)] {
            state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
                uid,
                atom: catalog.atom(&card).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            });
        }
        state.next_card_uid = 6;
        let mut target = HotMonster::new(MonsterKind::Toadpole, 100);
        target.block = 3;
        target.powers.set(PowerId::Vulnerable, SlotWire::Int, 2);
        state.monsters_mut().push(target);
        let mut events = Vec::new();

        play_card(&mut state, &catalog, 1, None, None, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::SerpentForm), 4);
        assert_eq!(state.monsters[0].hp, 100, "first cast freezes zero");
        play_card(&mut state, &catalog, 2, None, None, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::SerpentForm), 8);
        assert_eq!((state.monsters[0].block, state.monsters[0].hp), (0, 99));

        prepare_after_card_played_scalar_write(&mut state, PowerId::SerpentForm, 8, 0).unwrap();
        state.powers.set(PowerId::SerpentForm, SlotWire::Int, 0);
        play_card(&mut state, &catalog, 3, None, None, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::HauntPower), 7);
        let target_draws = state.rng.get(crate::hot::RngStream::Targets).counter;
        play_card(&mut state, &catalog, 4, None, None, &mut events).unwrap();
        assert_eq!(state.monsters[0].hp, 92);
        assert_eq!(
            state.rng.get(crate::hot::RngStream::Targets).counter,
            target_draws + 1
        );

        state.monsters_mut()[0].hp = 0;
        let empty_draws = state.rng.get(crate::hot::RngStream::Targets).counter;
        play_card(&mut state, &catalog, 5, None, None, &mut events).unwrap();
        assert_eq!(
            state.rng.get(crate::hot::RngStream::Targets).counter,
            empty_draws
        );
    }

