    /// #3279: Haunt's hit kills the last enemy, and Devour Life, acquired
    /// after it, still summons (`DevourLifePower/<AfterCardPlayed>d__6`
    /// `0x338e98` IL_007b has no combat gate), under IsEnding: a live Osty
    /// grows MaxHp only, and an absent one refuses by name. Before #3279
    /// Rust skipped the summon at `history.over`.
    #[test]
    fn devour_life_after_a_killing_haunt_summons_under_ending() {
        use crate::hot::AfterCardPlayedPowerToken as Token;
        let soul = identity(CardId::Soul, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(soul).unwrap();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        for (osty, expected) in [
            (Some((3, 5)), Ok(Some((3, 7)))),
            (
                None,
                Err(EngineRefusal::EndingSummonNotModeled("Devour Life summon")),
            ),
        ] {
            let mut state = state_with_card(&catalog, soul, 7);
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 7));
            state.powers.set(PowerId::HauntPower, SlotWire::Int, 7);
            state.powers.set(PowerId::DevourLife, SlotWire::Int, 2);
            for token in [Token::HauntPower, Token::DevourLife] {
                state
                    .fanouts
                    .register_after_card_played_power(token, None)
                    .unwrap();
            }
            state.fanouts.set_osty(osty).unwrap();

            let result =
                play_card(&mut state, &catalog, 7, None, None, &mut Vec::new()).map(|()| {
                    assert!(state.history.over, "Haunt's hit ended the combat");
                    state
                        .fanouts
                        .pet()
                        .osty()
                        .map(|osty| (osty.hp(), osty.max_hp()))
                });
            assert_eq!(result, expected);
        }
    }

    /// #3261: Haunt and Serpent Form draw `CombatTargets` with no combat
    /// gate (`HauntPower/<AfterCardPlayed>d__4` `0x33be58` IL_008d,
    /// `SerpentFormPower/<AfterCardPlayed>d__13` `0x343ef4` IL_0128). At
    /// `history.over` with no live enemy the pick is the no-draw empty
    /// `NextItem`; a live enemy while ending (a state the secondary death
    /// cascade leaves unreachable) refuses by name instead of running
    /// `CreatureCmd.Damage` under IsEnding.
    #[test]
    fn haunt_and_serpent_form_picks_are_ungated_and_refuse_ending_damage() {
        use crate::hot::AfterCardPlayedPowerToken as Token;
        let soul = identity(CardId::Soul, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(soul).unwrap();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let spec = *catalog.spec(catalog.atom(&soul).unwrap()).unwrap();
        for (token, site) in [
            (Token::HauntPower, "Haunt damage"),
            (Token::SerpentForm, "Serpent Form damage"),
        ] {
            let run = |state: &mut HotState| {
                state.powers.set(PowerId::HauntPower, SlotWire::Int, 7);
                let mut latch = CardPlayedPowerLatch {
                    serpent_form: 4,
                    ..CardPlayedPowerLatch::default()
                };
                apply_keyed_after_card_played_object(
                    state,
                    &catalog,
                    &spec,
                    token,
                    &mut latch,
                    0,
                    false,
                    false,
                    7,
                    &mut Vec::new(),
                )
            };
            let draws = |state: &HotState| state.rng.get(crate::hot::RngStream::Targets).counter;

            // Over with every enemy dead: an empty pick, no draw, no refusal.
            let mut over = HotState::at_defaults();
            over.hp = 50;
            over.history.over = true;
            let mut dead = HotMonster::new(MonsterKind::Toadpole, 10);
            dead.hp = 0;
            over.monsters_mut().push(dead);
            let before = draws(&over);
            run(&mut over).unwrap();
            assert_eq!(
                draws(&over),
                before,
                "{token:?}: empty NextItem draws nothing"
            );

            // Over with a live secondary enemy: the draw happens (no
            // `history.over` gate), then the ending Damage refuses by name.
            let mut ending = HotState::at_defaults();
            ending.hp = 50;
            ending.history.over = true;
            let mut minion = HotMonster::new(MonsterKind::Toadpole, 10);
            minion.powers.set(PowerId::Secondary, SlotWire::Int, 1);
            ending.monsters_mut().push(minion);
            assert_eq!(
                run(&mut ending),
                Err(EngineRefusal::EndingDamageNotModeled(site)),
                "{token:?}"
            );
            assert_eq!(draws(&ending), before + 1, "{token:?}: the pick drew once");

            // A live primary enemy: not ending, the hit lands.
            let mut live = HotState::at_defaults();
            live.hp = 50;
            live.monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 10));
            run(&mut live).unwrap();
            assert!(live.monsters[0].hp < 10, "{token:?}: the live hit lands");
            assert_eq!(draws(&live), before + 1);
        }
    }

    fn globe_head_state(card: CardIdentity, ascension: u8) -> (HotState, Catalog) {
        let mut builder = CatalogBuilder::new();
        builder.intern(card).unwrap();
        builder.intern_monster(MonsterKind::GlobeHead).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, card, 7);
        assert!(state.fanouts.set_ascension(ascension));
        let mut head = HotMonster::new(MonsterKind::GlobeHead, 158);
        head.max_hp = 158;
        state.monsters_mut().push(head);
        (state, catalog)
    }

    /// #3300: a Power play against a live Globe Head takes Galvanic's live
    /// Amount (8 at A9+, 6 below) as blockable owner damage.
    #[test]
    fn globe_head_galvanic_hits_the_player_after_a_power_play() {
        for (ascension, amount) in [(10, 8), (8, 6)] {
            let (mut state, catalog) = globe_head_state(identity(CardId::Inflame, 0), ascension);
            state.block = 3;
            let mut events = Vec::new();

            play_card(&mut state, &catalog, 7, None, None, &mut events).unwrap();

            assert_eq!(state.block, 0, "A{ascension}: Block absorbs first");
            assert_eq!(state.hp, 50 - (amount - 3), "A{ascension}");
            assert_eq!(state.monsters[0].hp, 158, "the owner is untouched");
        }
    }

    /// #3300: only a Power carries Galvanized, so a Skill play is silent.
    #[test]
    fn globe_head_galvanic_ignores_a_non_power_play() {
        let (mut state, catalog) = globe_head_state(identity(CardId::DefendIronclad, 0), 10);
        play_card(&mut state, &catalog, 7, None, None, &mut Vec::new()).unwrap();
        assert_eq!(state.hp, 50);
    }

