        assert_eq!(events, before_events);

        let mut partial = HotState::at_defaults();
        partial.hp = 50;
        partial.energy = 3;
        partial.piles.get_mut(PileId::Hand).make_mut().push(source);
        partial.fanouts.forge_monologue_hook_flags_for_test(0b001);
