    #[test]
    fn card_play_target_uid_blocks_stock_replacement_hits_and_debuffs() {
        for (card_id, forbidden_power) in [
            (CardId::Bash, Some(PowerId::Vuln)),
            (CardId::PoisonedStab, Some(PowerId::Poison)),
            (CardId::TwinStrike, None),
        ] {
            let identity = identity(card_id, 0);
            let mut builder = CatalogBuilder::new();
            builder.intern(identity).unwrap();
            builder.intern_monster(MonsterKind::Axebot).unwrap();
            let catalog = builder.build();
            let mut state = state_with_card(&catalog, identity, 11);
            state.hp = 50;
            state.energy = 10;
            let mut axebot = HotMonster::new(MonsterKind::Axebot, 1);
            axebot.max_hp = 86;
            axebot.uid = 1;
            axebot.powers.set(PowerId::Stock, SlotWire::Int, 1);
            state.monsters_mut().push(axebot);

            play_card(&mut state, &catalog, 11, Some(0), None, &mut Vec::new()).unwrap();
            let replacement = &state.monsters[0];
            assert_ne!(replacement.uid, 1, "{card_id:?} must trigger Stock");
            assert_eq!(replacement.hp, replacement.max_hp);
            if let Some(power) = forbidden_power {
                assert_eq!(replacement.powers.value(power), 0);
            }
        }
    }

    /// #3023: an all-opponents `AttackCommand` re-reads `GetOpponentsOf`
    /// on every hit (`AttackCommand.<Execute>d__90::MoveNext` `0x3f19c0`
    /// IL_0168-IL_0196), so the fresh Axebot that Stock put in the killed
    /// one's place takes the command's second hit. (This pinned the opposite
    /// before #3023, inherited from the frozen Python snapshot.)
    #[test]
    fn all_opponents_attack_hits_the_stock_replacement_on_the_next_hit() {
        for (card_id, energy, damage) in [(CardId::Whirlwind, 2, 5), (CardId::DaggerSpray, 1, 4)] {
            let identity = identity(card_id, 0);
            let mut builder = CatalogBuilder::new();
            builder.intern(identity).unwrap();
            builder.intern_monster(MonsterKind::Axebot).unwrap();
            let catalog = builder.build();
            let mut state = state_with_card(&catalog, identity, 13);
            state.hp = 50;
            state.energy = energy;
            let mut axebot = HotMonster::new(MonsterKind::Axebot, 1);
            axebot.max_hp = 86;
            axebot.uid = 1;
            axebot.powers.set(PowerId::Stock, SlotWire::Int, 1);
            state.monsters_mut().push(axebot);
            play_card(&mut state, &catalog, 13, None, None, &mut Vec::new()).unwrap();
            let replacement = &state.monsters[0];
            assert_eq!(replacement.uid, 2, "{card_id:?} must trigger Stock");
            assert_eq!(replacement.hp, replacement.max_hp - damage, "{card_id:?}");
        }
    }

    #[test]
    fn replayed_block_then_attack_stock_replacement_refuses_atomically() {
        for card_id in [CardId::IronWave, CardId::Dash] {
            let identity = identity(card_id, 0);
            let mut builder = CatalogBuilder::new();
            builder.intern(identity).unwrap();
            builder.intern_monster(MonsterKind::Axebot).unwrap();
            let catalog = builder.build();
            let mut state = state_with_card(&catalog, identity, 12);
            state.hp = 50;
            state.energy = 10;
            state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
            state.piles.get_mut(PileId::Hand).make_mut()[0].flags |=
                CARD_FLAG_DEFAULT_PHYSICAL_STATE;
            state.powers.set(PowerId::Juggernaut, SlotWire::Int, 1);
            assert!(
                state
                    .fanouts
                    .set_after_block_gained_order(&[PowerId::Juggernaut])
            );
            let mut physical = state.card_states.get(12);
            physical.set_base_replay_count(Some(1)).unwrap();
            state.card_states.set(12, physical);
            let mut axebot = HotMonster::new(MonsterKind::Axebot, 1);
            axebot.max_hp = 86;
            axebot.uid = 1;
            axebot.powers.set(PowerId::Stock, SlotWire::Int, 1);
            state.monsters_mut().push(axebot);
            state.exact_piles = true;
            state.next_card_uid = 13;
            let document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
            let catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
            let mut state = HotBoundary::from_canonical(&document, &catalog).unwrap();
            crate::engine::admit(&document, &state, &catalog).unwrap();
            let before = state.clone();
            let mut events = Vec::new();

            assert_eq!(
                play_card(&mut state, &catalog, 12, Some(0), None, &mut events),
                Err(EngineRefusal::ContinuationNotModeled)
            );
            assert_eq!(state, before);
            assert!(events.is_empty());
        }
    }

    #[test]
    fn sealed_throne_refuses_live_rupture_and_juggling_peers() {
        for (card, peer) in [
            (identity(CardId::DefendIronclad, 0), PowerId::Rupture),
            (identity(CardId::StrikeIronclad, 0), PowerId::Juggling),
        ] {
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(card).unwrap();
            let catalog = builder.build();
            let spec = catalog.spec(atom).unwrap();
            let mut state = HotState::at_defaults();
            state.powers.set(PowerId::SealedThrone, SlotWire::Int, 1);
            state.powers.set(PowerId::BlackHole, SlotWire::Int, 1);
            state.powers.set(peer, SlotWire::Int, 1);
            if peer == PowerId::Juggling {
                state.powers.set(PowerId::JugglingAttacks, SlotWire::Int, 2);
            }

            assert!(matches!(
                before_card_played_fanouts(
                    &mut state,
                    &catalog,
                    HotCard {
                        uid: 1,
                        atom,
                        flags: 0,
                    },
                    spec,
                    0,
                    0,
                    &mut Vec::new(),
                ),
                Err(EngineRefusal::PowerOrderNotModeled(
                    "Sealed Throne and Black Hole BeforeCardPlayed order"
                ))
            ));
        }
    }

