    #[test]
    fn free_powers_zero_cost_and_consume_every_matching_listener() {
        let apparition = identity(CardId::Apparition, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(apparition).unwrap();
        let catalog = builder.build();
        let spec = catalog.spec(atom).unwrap();
        let card = HotCard {
            uid: 7,
            atom,
            flags: 0,
        };
        let mut state = state_with_card(&catalog, apparition, 7);
        state.powers.set(PowerId::FreeSkill, SlotWire::Int, 2);
        state.powers.set(PowerId::FreeEthereal, SlotWire::Int, 1);
        state.powers.set(PowerId::Corruption, SlotWire::Bool, 1);
        assert!(
            state
                .fanouts
                .set_result_location_power_order(&[PowerId::Corruption])
        );

        assert_eq!(resolved_energy_cost(&state, card, spec), 0);
        let mut events = Vec::new();
        before_card_played_fanouts(&mut state, &catalog, card, spec, 0, 0, &mut events).unwrap();

        assert_eq!(state.powers.value(PowerId::FreeSkill), 1);
        assert_eq!(state.powers.value(PowerId::FreeEthereal), 0);
        assert_eq!(events.len(), 2);

        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(strike).unwrap();
        let catalog = builder.build();
        let card = HotCard {
            uid: 8,
            atom,
            flags: 0,
        };
        let mut state = state_with_card(&catalog, strike, card.uid);
        state.exact_piles = true;
        state.piles.get_mut(PileId::Hand).make_mut()[0].flags |=
            CARD_FLAG_DEFAULT_PHYSICAL_STATE | crate::hot::CARD_FLAG_HEXED;
        state.powers.set(PowerId::HexPower, SlotWire::Int, 2);
        let mut flail = HotMonster::new(MonsterKind::FlailKnight, 108);
        flail.max_hp = 108;
        assert!(flail.random_ai.set_next(Some(2)));
        assert!(flail.random_ai.set_log(&[2]));
        let mut spectral = HotMonster::new(MonsterKind::SpectralKnight, 97);
        spectral.max_hp = 97;
        spectral.slot = 1;
        spectral.uid = 1;
        assert!(spectral.random_ai.set_next(Some(0)));
        assert!(spectral.random_ai.set_log(&[0]));
        let mut magi = HotMonster::new(MonsterKind::MagiKnight, 89);
        magi.max_hp = 89;
        magi.slot = 2;
        magi.uid = 2;
        state.monsters_mut().extend([flail, spectral, magi]);
        assert!(super::super::cards::hex_power_state_is_exact(&state));
        state.powers.set(PowerId::FreeEthereal, SlotWire::Int, 1);
        state.powers.set(PowerId::SpiritOfAsh, SlotWire::Int, 3);
        let spec = catalog.spec(atom).unwrap();

        assert_eq!(resolved_energy_cost(&state, card, spec), 0);
        before_card_played_fanouts(&mut state, &catalog, card, spec, 0, 0, &mut Vec::new())
            .unwrap();
        assert_eq!(state.powers.value(PowerId::FreeEthereal), 0);
        assert_eq!(state.block, 3, "Hexed fires the effective-Ethereal hooks");
    }

    #[test]
    fn last_free_stack_with_danse_refuses_before_any_mutation() {
        let bash = identity(CardId::Bash, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(bash).unwrap();
        let catalog = builder.build();
        let spec = catalog.spec(atom).unwrap();
        let card = HotCard {
            uid: 7,
            atom,
            flags: 0,
        };
        let mut state = state_with_card(&catalog, bash, 7);
        state.powers.set(PowerId::FreeAttack, SlotWire::Int, 1);
        state.powers.set(PowerId::DanseMacabre, SlotWire::Int, 4);
        let before = state.clone();
        let mut events = Vec::new();

        let error =
            match before_card_played_fanouts(&mut state, &catalog, card, spec, 0, 0, &mut events) {
                Ok(_) => panic!("last-stack ordering must refuse"),
                Err(error) => error,
            };
        assert_eq!(
            error,
            EngineRefusal::PowerOrderNotModeled(
                "Danse Macabre with last-stack applicable Free* power"
            )
        );
        assert_eq!(state, before);
        assert!(events.is_empty());
    }

    #[test]
    fn lethal_before_card_juggernaut_refuses_before_block_or_rng_mutation() {
        let bash = identity(CardId::Bash, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(bash).unwrap();
        let catalog = builder.build();
        let spec = catalog.spec(atom).unwrap();
        let mut state = state_with_card(&catalog, bash, 7);
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 8));
        state.powers.set(PowerId::DanseMacabre, SlotWire::Int, 4);
        state.powers.set(PowerId::Juggernaut, SlotWire::Int, 8);
        state
            .fanouts
            .set_after_block_gained_order(&[PowerId::Juggernaut]);
        let rng_before = state.rng.clone();
        let mut events = Vec::new();

        let error = match before_card_played_fanouts(
            &mut state,
            &catalog,
            HotCard {
                uid: 7,
                atom,
                flags: 0,
            },
            spec,
            2,
            2,
            &mut events,
        ) {
            Ok(_) => panic!("an unaudited post-ending body must refuse"),
            Err(error) => error,
        };

        assert_eq!(
            error,
            EngineRefusal::PowerOrderNotModeled(
                "lethal BeforeCardPlayed Juggernaut before unaudited OnPlay"
            )
        );
        assert_eq!(state.block, 0);
        assert_eq!(state.monsters[0].hp, 8);
        assert_eq!(state.rng, rng_before);
        assert!(events.is_empty());
    }

    #[test]
    fn terminal_preflight_sums_primaries_and_ignores_every_secondary_shape() {
        let mut base = HotState::at_defaults();
        base.powers.set(PowerId::Juggernaut, SlotWire::Int, 6);
        let mut first = HotMonster::new(MonsterKind::Toadpole, 7);
        first.block = 5;
        base.monsters_mut().push(first);
        base.monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 6));

        assert!(!juggernaut_block_can_end_combat(&base, 2));
        assert!(juggernaut_block_can_end_combat(&base, 3));

        for mut secondary in [
            HotMonster::new(MonsterKind::Toadpole, 100),
            HotMonster::new(MonsterKind::GasBomb, 100),
            HotMonster::new(MonsterKind::Parafright, 100),
            HotMonster::new(MonsterKind::EyeWithTeeth, 100),
        ] {
            if matches!(secondary.kind, MonsterKind::Toadpole) {
                secondary.powers.set(PowerId::Secondary, SlotWire::Bool, 1);
            }
            let mut state = HotState::at_defaults();
            state.powers.set(PowerId::Juggernaut, SlotWire::Int, 6);
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 6));
            state.monsters_mut().push(secondary);
            assert!(juggernaut_block_can_end_combat(&state, 1));
        }
    }

