    #[test]
    fn result_draw_classifier_is_exact_and_excludes_hellraiser_children() {
        let mut result_builder = CatalogBuilder::new();
        for id in [CardId::Pillage, CardId::Restlessness] {
            for upgrade in 0..=1 {
                result_builder
                    .intern_reachable(identity(id, upgrade))
                    .unwrap();
            }
        }
        let result_catalog = result_builder.build();
        let mut result_rows = Vec::new();
        for spec in result_catalog.reachable_specs() {
            for (index, _) in result_catalog.steps(spec).iter().enumerate() {
                if cardplay_result_draw_step_is_exact(spec, &result_catalog, index) {
                    result_rows.push((spec.identity.id, spec.identity.upgrade, index));
                }
            }
        }
        assert_eq!(
            result_rows,
            [
                (CardId::Pillage, 0, 0),
                (CardId::Pillage, 1, 0),
                (CardId::Restlessness, 0, 0),
                (CardId::Restlessness, 1, 0),
            ]
        );
        assert!(
            result_catalog
                .reachable_specs()
                .all(|spec| !spec.strike_tag),
            "the exact result-bearing Draw rows cannot be Hellraiser children"
        );
    }

