    #[test]
    fn after_card_played_live_carrier_census_requires_every_object_row() {
        use crate::hot::AfterCardPlayedPowerToken as Token;

        assert_eq!(
            Token::ALL.map(Token::as_str),
            [
                "withering",
                "rupture",
                "afterimage",
                "rage",
                "sneaky",
                "calamity",
                "subroutine",
                "storm",
                "haunt_power",
                "devour_life",
                "serpent_form",
                "pale_blue_dot",
                "smoggy",
                "black_hole",
                "master_planner",
                "tender",
                "void_form",
                "panache",
                "monologue",
            ]
        );
        assert_eq!(
            Token::ALL
                .into_iter()
                .filter(|token| token.is_instanced())
                .collect::<Vec<_>>(),
            [Token::Withering, Token::Panache, Token::Monologue]
        );
        let panache_state = || {
            let mut state = HotState::at_defaults();
            install_panache_instance(&mut state, 10, 5);
            state
        };
        for peer in [
            PowerId::Rupture,
            PowerId::Afterimage,
            PowerId::Rage,
            PowerId::Sneaky,
            PowerId::Calamity,
            PowerId::Subroutine,
            PowerId::Storm,
            PowerId::HauntPower,
            PowerId::DevourLife,
            PowerId::SerpentForm,
            PowerId::PaleBlueDot,
            PowerId::Smoggy,
            PowerId::BlackHole,
            PowerId::MasterPlanner,
        ] {
            let mut state = panache_state();
            state.powers.set(peer, SlotWire::Int, 1);
            assert!(
                !instanced_after_card_played_entry_is_exact(&state),
                "{peer:?}"
            );
        }
        let mut withering = panache_state();
        assert!(withering.fanouts.set_withering_cards_left(1));
        assert!(!instanced_after_card_played_entry_is_exact(&withering));
        let mut tender = panache_state();
        assert!(tender.fanouts.set_tender_state(true, 0));
        assert!(!instanced_after_card_played_entry_is_exact(&tender));
        let mut void_form = panache_state();
        void_form.fanouts.set_void_form_hooks_registered(true);
        assert!(!instanced_after_card_played_entry_is_exact(&void_form));
        let mut monologue = panache_state();
        let uid = monologue.fanouts.next_after_side_turn_end_power_uid();
        monologue
            .fanouts
            .set_next_after_side_turn_end_power_uid(uid + 1);
        assert!(
            monologue
                .fanouts
                .set_monologue_instances(&[MonologueInstance {
                    uid,
                    amount: 1,
                    power: 1,
                    strength_applied: 0,
                }])
        );
        monologue.powers.set(PowerId::Monologue, SlotWire::Int, 1);
        assert!(!instanced_after_card_played_entry_is_exact(&monologue));
    }

    #[test]
    fn imitation_reverse_acquisition_wall_and_exact_exclusions_are_pinned() {
        use crate::hot::AfterCardPlayedPowerToken as Token;

        let blocked = Token::ALL
            .into_iter()
            .filter(|token| token.blocks_later_imitation_acquisition())
            .collect::<Vec<_>>();
        assert_eq!(
            blocked,
            [
                Token::Withering,
                Token::Afterimage,
                Token::Rage,
                Token::Sneaky,
                Token::Subroutine,
                Token::Storm,
                Token::DevourLife,
                Token::SerpentForm,
                Token::PaleBlueDot,
                Token::Smoggy,
                Token::BlackHole,
                Token::MasterPlanner,
                Token::Tender,
                Token::Panache,
                Token::Monologue,
            ]
        );
        assert_eq!(
            Token::ALL
                .into_iter()
                .filter(|token| !token.blocks_later_imitation_acquisition())
                .collect::<Vec<_>>(),
            [
                Token::Rupture,
                Token::Calamity,
                Token::HauntPower,
                Token::VoidForm,
            ],
            "Rupture and Calamity are Attack-only, Haunt is Soul-only, and Void Form commutes"
        );
        assert!(
            crate::content_tables::CARD_ROWS.iter().all(|row| {
                !row.is_power
                    || row.card_type == crate::content_tables::CardType::Power
                        && row.id != CardId::Soul
            }),
            "every current Imitation target is neither an Attack nor Soul"
        );

        let imitation = identity(CardId::ImitationLearning, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(imitation).unwrap();
        let catalog = builder.build();
        let spec = catalog.spec(atom).unwrap();
        preflight_instanced_power_acquisition_transition(&HotState::at_defaults(), &catalog, spec)
            .expect("two merely reachable future objects do not create a blanket wall");

        for token in blocked {
            let mut state = HotState::at_defaults();
            match token {
                Token::Withering => {
                    assert!(state.fanouts.set_withering_cards_left(1));
                    state
                        .fanouts
                        .register_after_card_played_power(token, None)
                        .unwrap();
                }
                Token::Panache => {
                    install_panache_instance(&mut state, 10, 5);
                }
                Token::Monologue => {
                    install_monologue_instance(&mut state, 0);
                }
                Token::Tender => {
                    prepare_after_card_played_scalar_write(&mut state, PowerId::Tender, 0, 1)
                        .unwrap();
                    assert!(state.fanouts.set_tender_state(true, 0));
                }
                _ => {
                    let power = match token {
                        Token::Afterimage => PowerId::Afterimage,
                        Token::Rage => PowerId::Rage,
                        Token::Sneaky => PowerId::Sneaky,
                        Token::Subroutine => PowerId::Subroutine,
                        Token::Storm => PowerId::Storm,
                        Token::DevourLife => PowerId::DevourLife,
                        Token::SerpentForm => PowerId::SerpentForm,
                        Token::PaleBlueDot => PowerId::PaleBlueDot,
                        Token::Smoggy => PowerId::Smoggy,
                        Token::BlackHole => PowerId::BlackHole,
                        Token::MasterPlanner => PowerId::MasterPlanner,
                        _ => unreachable!(),
                    };
                    install_after_card_played_scalar(&mut state, power, 1);
                }
            }
            assert!(after_card_played_power_order_is_exact(&state), "{token:?}");
            assert_eq!(
                preflight_instanced_power_acquisition_transition(&state, &catalog, spec),
                Err(EngineRefusal::PowerOrderNotModeled(
                    "Imitation Learning AfterCardPlayed acquisition order"
                )),
                "{token:?}"
            );
        }

        for (token, power) in [
            (Token::Rupture, PowerId::Rupture),
            (Token::Calamity, PowerId::Calamity),
            (Token::HauntPower, PowerId::HauntPower),
            (Token::VoidForm, PowerId::VoidForm),
        ] {
            let mut state = HotState::at_defaults();
            install_after_card_played_scalar(&mut state, power, 1);
            if token == Token::VoidForm {
                state.fanouts.set_void_form_hooks_registered(true);
            }
            assert!(after_card_played_power_order_is_exact(&state), "{token:?}");
            preflight_instanced_power_acquisition_transition(&state, &catalog, spec)
                .unwrap_or_else(|error| panic!("{token:?}: {error:?}"));
        }
    }

    #[test]
    fn instanced_after_card_played_source_classifier_census_is_exact() {
        use sha2::{Digest, Sha256};

        let mut rows = crate::content_tables::CARD_ROWS
            .iter()
            .flat_map(|row| {
                row.steps.iter().filter_map(move |step| {
                    instanced_after_card_played_acquisition_class(step.kind)
                        .map(|_| format!("{:?}:{:?}+{}", step.kind, row.id, row.upgrade))
                })
            })
            .collect::<Vec<_>>();
        rows.sort();
        assert_eq!(rows.len(), 32);
        let wire = format!("{}\n", rows.join("\n"));
        assert_eq!(
            format!("{:x}", Sha256::digest(wire)),
            "0e6f690fac05ac59de56e1dbd36333c6527b874849d576709db189e23d519b36",
            "both levels of the complete Panache/Monologue/keyed CardPlay-writer inventory"
        );

        assert_eq!(
            MonsterKind::ALL
                .into_iter()
                .filter_map(|kind| {
                    instanced_after_card_played_non_card_keyed_writer(kind)
                        .map(|power| (kind, power))
                })
                .collect::<Vec<_>>(),
            [
                (
                    MonsterKind::Aeonglass,
                    InstancedAfterCardPlayedNonCardWriter::Withering,
                ),
                (
                    MonsterKind::HunterKiller,
                    InstancedAfterCardPlayedNonCardWriter::Tender,
                ),
                (
                    MonsterKind::LivingFog,
                    InstancedAfterCardPlayedNonCardWriter::Smoggy,
                ),
            ],
            "the only non-card sources are Aeonglass→Withering, HunterKiller→Tender, and LivingFog→Smoggy"
        );
    }

    #[test]
    fn ordinary_after_card_played_acquisition_is_closed_for_manual_auto_and_replay_sources() {
        let afterimage = identity(CardId::Afterimage, 0);
        let panache = identity(CardId::Panache, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let afterimage_atom = builder.intern(afterimage).unwrap();
        let panache_atom = builder.intern(panache).unwrap();
        let defend_atom = builder.intern(defend).unwrap();
        let catalog = builder.build();

        for (pile, provenance, replay) in [
            (PileId::Hand, PlayProvenance::Manual, false),
            (PileId::Draw, PlayProvenance::Auto, false),
            (PileId::Hand, PlayProvenance::Manual, true),
        ] {
            let source = HotCard {
                uid: 7,
                atom: afterimage_atom,
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            };
            let mut state = HotState::at_defaults();
            // A live enemy keeps `damage_combat_is_ending` false (#3183).
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                99,
            ));
            state.hp = 50;
            state.energy = 8;
            state.next_card_uid = 8;
            state.piles.get_mut(pile).make_mut().push(source);
            install_panache_instance(&mut state, 10, 5);
            if replay {
                let mut card_state = state.card_states.get(source.uid);
                card_state.set_base_replay_count(Some(1)).unwrap();
                state.card_states.set(source.uid, card_state);
            }
            let mut events = vec![Event::TurnBegan { turn: 52 }];
            let result = if provenance == PlayProvenance::Auto {
                autoplay_collected_cards(&mut state, &catalog, &[source], &mut events)
            } else {
                play_card(&mut state, &catalog, source.uid, None, None, &mut events)
            };
            result.unwrap_or_else(|error| {
                panic!("{pile:?}/{provenance:?}/replay={replay}: {error:?}")
            });
            assert!(after_card_played_power_order_is_exact(&state));
            assert_eq!(
                state
                    .fanouts
                    .after_card_played_power_order()
                    .iter()
                    .map(|entry| entry.token)
                    .collect::<Vec<_>>(),
                [
                    crate::hot::AfterCardPlayedPowerToken::Panache,
                    crate::hot::AfterCardPlayedPowerToken::Afterimage,
                ]
            );
            assert!(events.len() > 1);
        }

        let source = HotCard {
            uid: 9,
            atom: panache_atom,
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        };
        let mut keyed_then_panache = HotState::at_defaults();
        // A live enemy keeps `damage_combat_is_ending` false (#3183).
        keyed_then_panache
            .monsters_mut()
            .push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                99,
            ));
        keyed_then_panache.hp = 50;
        keyed_then_panache.energy = 8;
        keyed_then_panache.next_card_uid = 10;
        keyed_then_panache
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(source);
        keyed_then_panache
            .powers
            .set(PowerId::Afterimage, SlotWire::Int, 1);
        hydrate_after_card_played_power_order_for_test(&mut keyed_then_panache);
        play_card(
            &mut keyed_then_panache,
            &catalog,
            source.uid,
            None,
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert!(after_card_played_power_order_is_exact(&keyed_then_panache));
        assert_eq!(
            keyed_then_panache
                .fanouts
                .after_card_played_power_order()
                .iter()
                .map(|entry| entry.token)
                .collect::<Vec<_>>(),
            [
                crate::hot::AfterCardPlayedPowerToken::Afterimage,
                crate::hot::AfterCardPlayedPowerToken::Panache,
            ]
        );

        let mut successor = HotState::at_defaults();

        // A live enemy keeps `damage_combat_is_ending` false (#3183).

        successor.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            99,
        ));
        successor.hp = 50;
        successor.energy = 8;
        successor.next_card_uid = 12;
        successor
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(HotCard {
                uid: 11,
                atom: defend_atom,
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            });
        install_panache_instance(&mut successor, 10, 5);
        play_card(&mut successor, &catalog, 11, None, None, &mut Vec::new()).unwrap();
        assert!(instanced_after_card_played_entry_is_exact(&successor));
    }

    #[test]
    fn panache_false_bit_is_bound_to_the_exact_created_uid_and_cursor() {
        let panache = identity(CardId::Panache, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(panache).unwrap();
        let catalog = builder.build();
        let source = HotCard {
            uid: 43,
            atom,
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        };
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.next_card_uid = 44;
        state.piles.get_mut(PileId::Play).make_mut().push(source);
        state.fanouts.set_next_after_side_turn_end_power_uid(2);
        assert!(state.fanouts.set_panache_instances(&[
            PanacheInstance {
                uid: 0,
                amount: 10,
                cards_left: 5,
                already_applied: true,
            },
            PanacheInstance {
                uid: 1,
                amount: 10,
                cards_left: 5,
                already_applied: false,
            },
        ]));
        state.powers.set(PowerId::Panache, SlotWire::Int, 20);
        assert!(state.fanouts.set_after_side_turn_end_power_order(&[
            crate::hot::AfterSideTurnEndPowerEntry {
                token: crate::hot::AfterSideTurnEndPowerToken::Panache,
                uid: 0,
            },
            crate::hot::AfterSideTurnEndPowerEntry {
                token: crate::hot::AfterSideTurnEndPowerToken::Panache,
                uid: 1,
            },
        ]));
        assert!(state.fanouts.set_after_card_played_power_order(&[
            crate::hot::AfterCardPlayedPowerEntry {
                token: crate::hot::AfterCardPlayedPowerToken::Panache,
                uid: 0,
            },
            crate::hot::AfterCardPlayedPowerEntry {
                token: crate::hot::AfterCardPlayedPowerToken::Panache,
                uid: 1,
            },
        ]));
        let mut record = crate::hot::CardPlayRecord::pending_for_test(source.uid);
        record.pending_choice = false;
        record.selection_kind = None;
        record.stage = CardPlayStage::AfterEnchantment;
        record.latch_kind = CardPlayLatchKind::Raw;
        record.next_step = u32::try_from(catalog.steps(catalog.spec(atom).unwrap()).len()).unwrap();
        record.instanced_power_uid_at_before = Some(1);
        record.instanced_power_created_uid = Some(1);
        state.frames.push_card_play(&record).unwrap();
        assert!(panache_false_rows_are_rooted(&state, &catalog));
        assert_eq!(persisted_card_play_stack_is_exact(&state, &catalog), Ok(()));

        let mut swapped = state.clone();
        assert!(swapped.fanouts.set_panache_instances(&[
            PanacheInstance {
                uid: 0,
                amount: 10,
                cards_left: 5,
                already_applied: false,
            },
            PanacheInstance {
                uid: 1,
                amount: 10,
                cards_left: 5,
                already_applied: true,
            },
        ]));
        let checkpoint = swapped.clone();
        assert!(!panache_false_rows_are_rooted(&swapped, &catalog));
        assert_eq!(swapped, checkpoint, "authentication is read-only");

        let mut mixed_level = state.clone();
        assert!(mixed_level.fanouts.set_panache_instances(&[
            PanacheInstance {
                uid: 0,
                amount: 10,
                cards_left: 5,
                already_applied: true,
            },
            PanacheInstance {
                uid: 1,
                amount: 14,
                cards_left: 5,
                already_applied: false,
            },
        ]));
        mixed_level.powers.set(PowerId::Panache, SlotWire::Int, 24);
        assert!(!panache_false_rows_are_rooted(&mixed_level, &catalog));

        let mut cursor = state.clone();
        let mutate_top =
            |state: &mut HotState, mutator: &dyn Fn(&mut crate::hot::CardPlayRecord)| {
                let Frame::CardPlay { record: index } = state.frames.top().unwrap() else {
                    panic!("expected card-play frame")
                };
                let mut record = state.frames.card_play(index).unwrap().to_owned();
                mutator(&mut record);
                state.frames.replace_top_card_play(&record).unwrap();
            };
        mutate_top(&mut cursor, &|record| {
            record.stage = CardPlayStage::AfterImitation;
            record.latch_kind = CardPlayLatchKind::Post;
            record.after_card_played_power_snapshot_captured = true;
            record.after_card_played_power_snapshot = vec![0, 1];
            record.after_card_played_power_phase = 3;
            record.after_card_played_power_cursor = 1;
        });
        assert_eq!(
            persisted_card_play_stack_is_exact(&cursor, &catalog),
            Ok(())
        );

        let mut swapped_after_snapshot = cursor.clone();
        assert!(swapped_after_snapshot.fanouts.set_panache_instances(&[
            PanacheInstance {
                uid: 0,
                amount: 10,
                cards_left: 5,
                already_applied: false,
            },
            PanacheInstance {
                uid: 1,
                amount: 10,
                cards_left: 5,
                already_applied: true,
            },
        ]));
        assert!(persisted_card_play_stack_is_exact(&swapped_after_snapshot, &catalog).is_err());

        let mut mixed_after_snapshot = cursor.clone();
        assert!(mixed_after_snapshot.fanouts.set_panache_instances(&[
            PanacheInstance {
                uid: 0,
                amount: 10,
                cards_left: 5,
                already_applied: true,
            },
            PanacheInstance {
                uid: 1,
                amount: 14,
                cards_left: 5,
                already_applied: false,
            },
        ]));
        mixed_after_snapshot
            .powers
            .set(PowerId::Panache, SlotWire::Int, 24);
        assert!(persisted_card_play_stack_is_exact(&mixed_after_snapshot, &catalog).is_err());

        mutate_top(&mut cursor, &|record| {
            record.after_card_played_power_cursor = 2;
        });
        assert!(persisted_card_play_stack_is_exact(&cursor, &catalog).is_err());
    }

    #[test]
    fn monologue_watermark_rejects_omitted_and_reordered_dictionary_uids() {
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(defend).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.next_card_uid = 8;
        state.piles.get_mut(PileId::Play).make_mut().push(HotCard {
            uid: 7,
            atom,
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        });
        state.fanouts.set_next_after_side_turn_end_power_uid(2);
        assert!(state.fanouts.set_monologue_instances(&[
            MonologueInstance {
                uid: 0,
                amount: 1,
                power: 1,
                strength_applied: 0
            },
            MonologueInstance {
                uid: 1,
                amount: 1,
                power: 1,
                strength_applied: 0
            },
        ]));
        state.powers.set(PowerId::Monologue, SlotWire::Int, 2);

        let exact_record = || {
            let mut record = crate::hot::CardPlayRecord::pending_for_test(7);
            record.instanced_power_uid_at_before = Some(2);
            record.monologue = true;
            record.monologue_latches = vec![(0, 1), (1, 1)];
            record
        };
        let exact = exact_record();
        let mut frames = crate::hot::Frames::new();
        let index = frames.push_card_play(&exact).unwrap();
        assert!(instanced_card_play_receipt_is_exact(
            &state,
            frames.card_play(index).unwrap(),
            catalog.spec(atom).unwrap(),
        ));
        for latches in [vec![], vec![(0, 1)], vec![(1, 1)]] {
            let mut forged = exact_record();
            forged.monologue = !latches.is_empty();
            forged.monologue_latches = latches;
            let mut frames = crate::hot::Frames::new();
            let index = frames.push_card_play(&forged).unwrap();
            assert!(!instanced_card_play_receipt_is_exact(
                &state,
                frames.card_play(index).unwrap(),
                catalog.spec(atom).unwrap(),
            ));
        }
        for latches in [vec![(0, 1), (0, 1)], vec![(1, 1), (0, 1)]] {
            let mut forged = exact_record();
            forged.monologue_latches = latches;
            assert!(crate::hot::Frames::new().push_card_play(&forged).is_none());
        }

        let mut phase_two = exact_record();
        phase_two.pending_choice = false;
        phase_two.selection_kind = None;
        phase_two.stage = CardPlayStage::AfterImitation;
        phase_two.latch_kind = CardPlayLatchKind::Post;
        phase_two.after_card_played_power_snapshot_captured = true;
        phase_two.after_card_played_power_snapshot = vec![0, 1];
        phase_two.after_card_played_power_phase = 2;
        phase_two.after_card_played_power_cursor = 1;
        phase_two.monologue_latches = vec![(1, 1)];
        let mut frames = crate::hot::Frames::new();
        let index = frames.push_card_play(&phase_two).unwrap();
        assert!(instanced_card_play_receipt_is_exact(
            &state,
            frames.card_play(index).unwrap(),
            catalog.spec(atom).unwrap(),
        ));
        phase_two.monologue = false;
        phase_two.monologue_latches.clear();
        let mut frames = crate::hot::Frames::new();
        let index = frames.push_card_play(&phase_two).unwrap();
        assert!(!instanced_card_play_receipt_is_exact(
            &state,
            frames.card_play(index).unwrap(),
            catalog.spec(atom).unwrap(),
        ));
    }

