    #[test]
    fn unceasing_top_observes_post_apc_routing_and_terminal_state() {
        let defend = identity(CardId::DefendIronclad, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let defend_atom = builder.intern(defend).unwrap();
        let strike_atom = builder.intern(strike).unwrap();
        builder
            .set_relics(&[crate::ids::RelicId::RelicUnceasingTop])
            .unwrap();
        let catalog = builder.build();
        let base = || {
            let mut state = state_with_card(&catalog, defend, 7);
            state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
            state.next_card_uid = 9;
            state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
                uid: 8,
                atom: strike_atom,
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            });
            state.fanouts.set_unceasing_top(true);
            state
        };

        let mut routed = base();
        routed
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        install_after_card_played_scalar(&mut routed, PowerId::Afterimage, 1);
        play_card(&mut routed, &catalog, 7, None, None, &mut Vec::new()).unwrap();
        assert_eq!(routed.block, 6, "APC completed before the finish suffix");
        assert_eq!(routed.piles.get(PileId::Discard).as_slice()[0].uid, 7);
        assert_eq!(routed.piles.get(PileId::Hand).as_slice()[0].uid, 8);
        assert!(routed.piles.get(PileId::Draw).is_empty());
        assert_eq!(
            routed
                .fanouts
                .after_card_played_power_order()
                .iter()
                .map(|entry| entry.token)
                .collect::<Vec<_>>(),
            [crate::hot::AfterCardPlayedPowerToken::Afterimage],
            "relic inventory never aliases the player-power object ledger"
        );

        let mut terminal = base();
        terminal
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 10));
        install_panache_instance(&mut terminal, 10, 1);
        play_card(&mut terminal, &catalog, 7, None, None, &mut Vec::new()).unwrap();
        assert!(terminal.history.over);
        assert!(terminal.piles.get(PileId::Hand).is_empty());
        assert_eq!(terminal.piles.get(PileId::Draw).as_slice()[0].uid, 8);
        assert_eq!(terminal.piles.get(PileId::Play).as_slice()[0].uid, 7);
        assert_eq!(catalog.spec(defend_atom).unwrap().identity, defend);
    }

