    #[test]
    fn panache_and_pale_blue_dot_execute_in_both_ledger_permutations() {
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(defend).unwrap();
        let catalog = builder.build();
        for pale_first in [false, true] {
            let mut state = state_with_card(&catalog, defend, 7);
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 10));
            let (panache, pale) = if pale_first {
                let pale = install_after_card_played_scalar(&mut state, PowerId::PaleBlueDot, 1);
                let panache = install_panache_instance(&mut state, 10, 1);
                (panache, pale)
            } else {
                let panache = install_panache_instance(&mut state, 10, 1);
                let pale = install_after_card_played_scalar(&mut state, PowerId::PaleBlueDot, 1);
                (panache, pale)
            };
            state.history.owner_card_plays_finished_this_turn = 4;

            play_card(&mut state, &catalog, 7, None, None, &mut Vec::new()).unwrap();

            assert!(state.history.over);
            assert!(state.fanouts.pale_blue_dot_used());
            assert_eq!(
                state.powers.value(PowerId::DrawNextTurn),
                i32::from(pale_first),
                "Pale Blue Dot's delayed draw survives exactly when its UID precedes lethal Panache"
            );
            let expected = if pale_first {
                [
                    (crate::hot::AfterCardPlayedPowerToken::PaleBlueDot, pale),
                    (crate::hot::AfterCardPlayedPowerToken::Panache, panache),
                ]
            } else {
                [
                    (crate::hot::AfterCardPlayedPowerToken::Panache, panache),
                    (crate::hot::AfterCardPlayedPowerToken::PaleBlueDot, pale),
                ]
            };
            assert_eq!(
                state
                    .fanouts
                    .after_card_played_power_order()
                    .iter()
                    .map(|row| (row.token, row.uid))
                    .collect::<Vec<_>>(),
                expected
            );
        }
    }

