    #[test]
    fn newly_applied_after_play_powers_do_not_trigger_their_casting_play() {
        for (id, power, first_amount) in [
            (CardId::Afterimage, PowerId::Afterimage, 1),
            (CardId::Subroutine, PowerId::Subroutine, 1),
            (CardId::Panache, PowerId::Panache, 10),
        ] {
            let identity = identity(id, 0);
            let mut builder = CatalogBuilder::new();
            builder.intern(identity).unwrap();
            let catalog = builder.build();
            let mut state = state_with_card(&catalog, identity, 1);
            // A live enemy keeps `damage_combat_is_ending` false (#3183).
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                99,
            ));
            let atom = catalog.atom(&identity).unwrap();
            state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
                uid: 2,
                atom,
                flags: 0,
            });
            state.next_card_uid = 3;
            let cost = i16::try_from(catalog.spec(atom).unwrap().cost).unwrap();
            let mut events = Vec::new();

            play_card(&mut state, &catalog, 1, None, None, &mut events).unwrap();
            assert_eq!(state.powers.value(power), first_amount);
            assert_eq!(state.block, 0, "{id:?} triggered on its first cast");
            assert_eq!(state.fanouts.panache_left(), 5);
            assert_eq!(state.energy, 9 - cost);

            play_card(&mut state, &catalog, 2, None, None, &mut events).unwrap();
            assert_eq!(state.powers.value(power), first_amount * 2);
            match power {
                PowerId::Afterimage => assert_eq!(state.block, 1),
                PowerId::Subroutine => assert_eq!(state.energy, 9 - 2 * cost + 1),
                PowerId::Panache => {
                    assert_eq!(state.fanouts.panache_left(), 5);
                    assert_eq!(
                        state
                            .fanouts
                            .panache_instances()
                            .map(|instance| (instance.cards_left, instance.already_applied))
                            .collect::<Vec<_>>(),
                        [(4, true), (5, true)]
                    );
                }
                _ => unreachable!(),
            }
        }
    }

