    /// A combat that is ending but not over: the only primary is dead, a
    /// secondary (Gas Bomb) lives, and `history.over` has not latched.
    /// `vetoed` gives the dead primary an Adaptable `ShouldStopCombatFromEnding`
    /// listener, which keeps the same roster live.
    fn ending_before_the_over_latch(mut state: HotState, vetoed: bool) -> HotState {
        let mut primary = HotMonster::new(MonsterKind::Toadpole, 100);
        primary.hp = 0;
        if vetoed {
            primary.powers.set(PowerId::Adaptable, SlotWire::Int, 1);
        }
        state.monsters_mut().push(primary);
        let mut bomb = HotMonster::new(MonsterKind::GasBomb, 10);
        bomb.uid = 1;
        bomb.slot = 1;
        state.monsters_mut().push(bomb);
        assert!(!state.history.over);
        assert_eq!(
            super::super::damage::damage_combat_is_ending(&state),
            !vetoed
        );
        state
    }

    /// #3502: `CardModel/<OnPlayWrapper>d__339::MoveNext` (`0x31b8d0`) tests
    /// `IsOverOrEnding` at the loop head before every generated body
    /// (IL_0428-0432). An ending combat whose over latch has not fired stops
    /// the series after the first body, exactly as an over one does; the
    /// vetoed control runs both Echo Form bodies.
    #[test]
    fn a_replay_series_stops_while_the_combat_is_ending_before_the_over_latch() {
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(defend).unwrap();
        let catalog = builder.build();
        for (vetoed, expected) in [(false, 1), (true, 2)] {
            let mut state =
                ending_before_the_over_latch(state_with_card(&catalog, defend, 7), vetoed);
            state.powers.set(PowerId::EchoForm, SlotWire::Int, 1);

            play_card(&mut state, &catalog, 7, None, None, &mut Vec::new()).unwrap();

            assert_eq!(state.history.card_plays_finished_combat, expected);
            assert_eq!(state.history.plays_this_turn, 1);
            // `CreatureCmd.GainBlock` is ending-gated too (see
            // `damage::gain_card_block`): the ending body gains nothing.
            assert_eq!(state.block, if vetoed { 10 } else { 0 });
            assert!(!state.history.over);
        }
    }

    #[test]
    fn selecting_autoplay_moves_source_to_play_before_draw_and_discard() {
        let mut builder = CatalogBuilder::new();
        for id in [
            CardId::Catastrophe,
            CardId::Prepared,
            CardId::DefendIronclad,
            CardId::StrikeIronclad,
        ] {
            builder.intern_reachable(identity(id, 0)).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, identity(CardId::Catastrophe, 0), 1);
        state.max_hp = 50;
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.exact_piles = true;
        state.next_card_uid = 5;
        for (pile, uid, id) in [
            (PileId::Draw, 2, CardId::Prepared),
            (PileId::Hand, 3, CardId::DefendIronclad),
            (PileId::Hand, 4, CardId::StrikeIronclad),
        ] {
            state.piles.get_mut(pile).make_mut().push(HotCard {
                uid,
                atom: catalog.atom(&identity(id, 0)).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            });
        }
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 100);
        monster.max_hp = 100;
        state.monsters_mut().push(monster);
        let doc = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&doc).unwrap();
        let state = HotBoundary::from_canonical(&doc, &catalog).unwrap();
        crate::engine::admit(&doc, &state, &catalog).unwrap();
        let parked =
            crate::engine::apply_action(&state, &catalog, &synchronous_play_action(1, None))
                .unwrap()
                .state;
        assert_eq!(pending_record(&parked).uid, 2);
        assert_eq!(pending_record(&parked).source_pile, PileId::Play);
        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let state = HotBoundary::from_canonical(&wire, &catalog).unwrap();
        crate::engine::admit(&wire, &state, &catalog).unwrap();
        let actions = crate::engine::legal_actions(&state, &catalog);
        assert_eq!(actions.len(), 2);
        assert!(
            state
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .all(|card| card.uid != 2)
        );
        let completed = crate::engine::apply_action(&state, &catalog, &actions[0])
            .unwrap()
            .state;
        assert!(completed.pending.is_none());
        assert!(completed.frames.is_empty());
        assert_eq!(
            completed
                .piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .filter(|c| c.uid == 2)
                .count(),
            1
        );
        assert_eq!(completed.piles.get(PileId::Hand).as_slice()[0].uid, 3);
        assert_eq!(completed.block, 0);
        assert_eq!(completed.history.card_plays_finished_combat, 2);
    }

