    #[test]
    fn autoplay_x_captures_energy_without_spending_and_keeps_terminal_routing() {
        let whirlwind = identity(CardId::Whirlwind, 1);
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let whirlwind_atom = builder.intern(whirlwind).unwrap();
        let strike_atom = builder.intern(strike).unwrap();
        let catalog = builder.build();

        for (hp, expected_hp, expected_pile) in [(100, 76, PileId::Discard), (20, -4, PileId::Play)]
        {
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.energy = 3;
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, hp));
            state.piles.get_mut(PileId::Play).make_mut().extend([
                HotCard {
                    uid: 17,
                    atom: whirlwind_atom,
                    flags: 0,
                },
                HotCard {
                    uid: 18,
                    atom: strike_atom,
                    flags: 0,
                },
            ]);

            play_card_with_work(
                &mut state,
                &catalog,
                17,
                None,
                None,
                &mut Vec::new(),
                PlaySource {
                    pile: PileId::Play,
                    provenance: PlayProvenance::Auto,
                    force_exhaust: false,
                    frozen: None,
                    allow_dead_target: false,
                },
            )
            .unwrap();

            assert_eq!(state.energy, 3, "AutoPlay captures X but pays nothing");
            assert_eq!(state.history.energy_spent_this_turn, 0);
            assert_eq!(state.monsters[0].hp, expected_hp);
            assert!(
                state
                    .piles
                    .get(expected_pile)
                    .as_slice()
                    .iter()
                    .any(|card| card.uid == 17)
            );
            assert!(
                state
                    .piles
                    .get(PileId::Play)
                    .as_slice()
                    .iter()
                    .any(|card| card.uid == 18),
                "the sibling frozen child is untouched"
            );
            let expected_play: &[HotCard] = if expected_pile == PileId::Play {
                &[
                    HotCard {
                        uid: 18,
                        atom: strike_atom,
                        flags: 0,
                    },
                    HotCard {
                        uid: 17,
                        atom: whirlwind_atom,
                        flags: 0,
                    },
                ]
            } else {
                &[HotCard {
                    uid: 18,
                    atom: strike_atom,
                    flags: 0,
                }]
            };
            assert_eq!(
                state.piles.get(PileId::Play).as_slice(),
                expected_play,
                "an already-Play Mayhem child moves to Bottom without duplicating"
            );
            assert_eq!(state.history.over, hp == 20);
        }
    }

    #[test]
    fn volley_uses_captured_energy_x_for_one_random_attack_command_on_both_entry_paths() {
        for (upgrade, base_damage) in [(0, 10), (1, 14)] {
            let identity = identity(CardId::Volley, upgrade);
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(identity).unwrap();
            let catalog = builder.build();

            for manual in [true, false] {
                let card = HotCard {
                    uid: 17,
                    atom,
                    flags: 0,
                };
                let mut state = HotState::at_defaults();
                state.hp = 50;
                state.energy = 3;
                state.next_card_uid = 18;
                state.powers.set(PowerId::Vigor, SlotWire::Int, 2);
                state
                    .monsters_mut()
                    .push(HotMonster::new(MonsterKind::Toadpole, 100));
                state
                    .monsters_mut()
                    .push(HotMonster::new(MonsterKind::Toadpole, 100));
                let source = if manual {
                    PileId::Hand
                } else {
                    PileId::Discard
                };
                state.piles.get_mut(source).make_mut().push(card);
                let targets_before = state.rng.get(RngStream::Targets).counter;
                let mut events = Vec::new();

                if manual {
                    play_card(&mut state, &catalog, card.uid, None, None, &mut events).unwrap();
                } else {
                    autoplay_collected_cards(&mut state, &catalog, &[card], &mut events).unwrap();
                }

                assert_eq!(
                    state.monsters.iter().map(|monster| monster.hp).sum::<i32>(),
                    200 - 3 * (base_damage + 2),
                    "all three hits share the command's one Vigor snapshot"
                );
                assert_eq!(state.powers.value(PowerId::Vigor), 0);
                assert_eq!(
                    events
                        .iter()
                        .filter(|event| matches!(
                            event,
                            Event::PowerChanged {
                                subject: Subject::Player,
                                power: PowerId::Vigor,
                                amount: 0,
                            }
                        ))
                        .count(),
                    1,
                    "AfterAttack consumes Vigor once around the outer command"
                );
                assert_eq!(
                    state.rng.get(RngStream::Targets).counter,
                    targets_before + 3,
                    "one live Targets draw is consumed per executed hit"
                );
                assert_eq!(state.energy, if manual { 0 } else { 3 });
                assert_eq!(
                    state.history.energy_spent_this_turn,
                    if manual { 3 } else { 0 }
                );
                assert!(state.piles.get(PileId::Discard).as_slice().contains(&card));
            }
        }
    }

    #[test]
    fn stardust_captures_star_x_once_for_manual_autoplay_and_replays() {
        for (upgrade, base_damage) in [(0, 5), (1, 7)] {
            let identity = identity(CardId::Stardust, upgrade);
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(identity).unwrap();
            let catalog = builder.build();

            for manual in [true, false] {
                let card = HotCard {
                    uid: 19,
                    atom,
                    flags: 0,
                };
                let mut state = HotState::at_defaults();
                state.hp = 50;
                state.energy = 3;
                state.stars = 3;
                state.next_card_uid = 20;
                state.powers.set(PowerId::OneTwoPunch, SlotWire::Int, 1);
                hydrate_side_end_order(&mut state);
                state.powers.set(PowerId::ChildOfTheStars, SlotWire::Int, 2);
                state.card_states.set(
                    card.uid,
                    CardInstanceState {
                        free_star_cost_this_turn_or_played_rows: 1,
                        ..CardInstanceState::default()
                    },
                );
                state
                    .monsters_mut()
                    .push(HotMonster::new(MonsterKind::Toadpole, 200));
                state
                    .monsters_mut()
                    .push(HotMonster::new(MonsterKind::Toadpole, 200));
                let source = if manual {
                    PileId::Hand
                } else {
                    PileId::Discard
                };
                state.piles.get_mut(source).make_mut().push(card);
                let targets_before = state.rng.get(RngStream::Targets).counter;
                let mut events = Vec::new();

                if manual {
                    play_card(&mut state, &catalog, card.uid, None, None, &mut events).unwrap();
                } else {
                    play_card_with_work(
                        &mut state,
                        &catalog,
                        card.uid,
                        None,
                        None,
                        &mut events,
                        PlaySource {
                            pile: source,
                            provenance: PlayProvenance::Auto,
                            force_exhaust: false,
                            frozen: Some(card),
                            allow_dead_target: false,
                        },
                    )
                    .unwrap();
                }

                assert_eq!(
                    state.monsters.iter().map(|monster| monster.hp).sum::<i32>(),
                    400 - 6 * base_damage,
                    "the replay reuses the first three-Star capture"
                );
                assert_eq!(
                    state.rng.get(RngStream::Targets).counter,
                    targets_before + 6,
                    "two bodies each consume the frozen three-hit count"
                );
                assert_eq!(state.energy, 3, "Star-X never spends Energy");
                assert_eq!(state.stars, if manual { 0 } else { 3 });
                assert_eq!(state.block, if manual { 6 } else { 0 });
                assert_eq!(state.history.energy_spent_this_turn, 0);
                assert_eq!(state.powers.value(PowerId::OneTwoPunch), 0);
                assert!(
                    state.card_states.get_ref(card.uid).is_none(),
                    "the ignored Star-cost row still clears on play"
                );
                assert!(state.piles.get(PileId::Discard).as_slice().contains(&card));
            }
        }
    }

