    #[test]
    fn stardust_late_failures_restore_resources_rng_damage_piles_and_events() {
        let identity = identity(CardId::Stardust, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(identity).unwrap();
        let catalog = builder.build();
        let card = HotCard {
            uid: 29,
            atom,
            flags: 0,
        };

        for manual in [true, false] {
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.stars = 2;
            state.history.card_plays_finished_combat = i32::MAX;
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 100));
            let source = if manual {
                PileId::Hand
            } else {
                PileId::Discard
            };
            state.piles.get_mut(source).make_mut().push(card);
            let before = state.clone();
            let mut events = vec![Event::CardResolved {
                uid: 1,
                pile: PileId::Discard,
            }];
            let events_before = events.clone();

            let result = if manual {
                play_card(&mut state, &catalog, card.uid, None, None, &mut events)
            } else {
                play_card_with_work(
                    &mut state,
                    &catalog,
                    card.uid,
                    None,
                    None,
                    &mut events,
                    PlaySource {
                        pile: source,
                        provenance: PlayProvenance::Auto,
                        force_exhaust: false,
                        frozen: Some(card),
                        allow_dead_target: false,
                    },
                )
            };
            assert_eq!(
                result,
                Err(EngineRefusal::CounterOverflow("card_plays_finished_combat"))
            );
            assert_eq!(state, before, "manual={manual}");
            assert_eq!(events, events_before, "manual={manual}");
        }

        let mut spend_failure = HotState::at_defaults();
        spend_failure.hp = 50;
        spend_failure.stars = 1;
        spend_failure.block = i32::MAX;
        spend_failure
            .powers
            .set(PowerId::ChildOfTheStars, SlotWire::Int, 1);
        spend_failure
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        spend_failure
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(card);
        let before = spend_failure.clone();
        let mut events = Vec::new();
        assert!(
            play_card(
                &mut spend_failure,
                &catalog,
                card.uid,
                None,
                None,
                &mut events,
            )
            .is_err()
        );
        assert_eq!(spend_failure, before);
        assert!(events.is_empty());
    }

    #[test]
    fn lethality_observes_manual_first_play_replay_and_nonplay_autoplay_shape() {
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(strike).unwrap();
        let catalog = builder.build();
        let card = HotCard {
            uid: 31,
            atom,
            flags: 0,
        };

        let mut manual = HotState::at_defaults();
        manual.hp = 50;
        manual.energy = 3;
        manual.next_card_uid = 32;
        manual
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        manual.powers.set(PowerId::Lethality, SlotWire::Int, 50);
        manual.powers.set(PowerId::OneTwoPunch, SlotWire::Int, 1);
        hydrate_side_end_order(&mut manual);
        manual.piles.get_mut(PileId::Hand).make_mut().push(card);
        play_card(
            &mut manual,
            &catalog,
            card.uid,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(
            manual.monsters[0].hp, 85,
            "first body deals 9; replay deals 6"
        );
        assert_eq!(manual.history.owner_attack_plays_started_this_turn, 2);
        assert!(manual.piles.get(PileId::Discard).as_slice().contains(&card));

        let mut autoplay = HotState::at_defaults();
        autoplay.hp = 50;
        autoplay.energy = 3;
        autoplay.next_card_uid = 32;
        autoplay
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        autoplay.powers.set(PowerId::Lethality, SlotWire::Int, 50);
        autoplay
            .piles
            .get_mut(PileId::Discard)
            .make_mut()
            .push(card);
        autoplay_collected_cards(&mut autoplay, &catalog, &[card], &mut Vec::new()).unwrap();
        assert_eq!(
            autoplay.monsters[0].hp, 91,
            "the active Play source is excluded from prior Attack history, so the first AutoPlay gets Lethality"
        );
        assert_eq!(autoplay.history.owner_attack_plays_started_this_turn, 1);
        assert!(
            autoplay
                .piles
                .get(PileId::Discard)
                .as_slice()
                .contains(&card)
        );
    }

    #[test]
    fn damage_readers_reconstruct_play_index_and_spent_across_a_suspended_replay() {
        let dagger = identity(CardId::DaggerThrow, 0);
        let defend = identity(CardId::DefendSilent, 0);
        let mut builder = CatalogBuilder::new();
        let dagger_atom = builder.intern(dagger).unwrap();
        let defend_atom = builder.intern(defend).unwrap();
        let catalog = builder.build();
        let source = HotCard {
            uid: 1,
            atom: dagger_atom,
            flags: 0,
        };
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.energy = 1;
        state.next_card_uid = 5;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        state.powers.set(PowerId::Lethality, SlotWire::Int, 50);
        state.powers.set(PowerId::OneForAll, SlotWire::Int, 3);
        state.powers.set(PowerId::OneTwoPunch, SlotWire::Int, 1);
        hydrate_side_end_order(&mut state);
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            source,
            HotCard {
                uid: 2,
                atom: defend_atom,
                flags: 0,
            },
        ]);
        state.piles.get_mut(PileId::Draw).make_mut().extend([
            HotCard {
                uid: 3,
                atom: defend_atom,
                flags: 0,
            },
            HotCard {
                uid: 4,
                atom: defend_atom,
                flags: 0,
            },
        ]);

        play_card(
            &mut state,
            &catalog,
            source.uid,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(state.monsters[0].hp, 87, "first body receives 13");
        assert_eq!(pending_record(&state).play_index, 0);
        assert_eq!(pending_record(&state).spent, 1);
        assert_eq!(active_card_play_index(source.uid), None);
        assert_eq!(active_card_energy_spent(source.uid), None);

        resume_selection(
            &mut state,
            &catalog,
            crate::engine::SelectionAnswer::OptionIndex(0),
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(
            state.monsters[0].hp, 78,
            "resumed second body receives ordinary 9"
        );
        assert_eq!(pending_record(&state).play_index, 1);
        assert_eq!(pending_record(&state).spent, 1);
        assert_eq!(active_card_play_index(source.uid), None);
        assert_eq!(active_card_energy_spent(source.uid), None);

        resume_selection(
            &mut state,
            &catalog,
            crate::engine::SelectionAnswer::OptionIndex(0),
            &mut Vec::new(),
        )
        .unwrap();
        assert!(state.pending.is_none());
        assert_eq!(active_card_play_index(source.uid), None);
        assert_eq!(active_card_energy_spent(source.uid), None);
        assert!(
            state
                .piles
                .get(PileId::Discard)
                .as_slice()
                .contains(&source)
        );
    }

    #[test]
    fn ethereal_transaction_uses_the_frozen_256_body_count_without_overflow() {
        let identity = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(identity).unwrap();
        let catalog = builder.build();
        let card = HotCard {
            uid: 40,
            atom,
            flags: 0,
        };
        let source = PlaySource {
            pile: PileId::Hand,
            provenance: PlayProvenance::Manual,
            force_exhaust: false,
            frozen: None,
            allow_dead_target: false,
        };
        let mut state = HotState::at_defaults();
        state.hp = 50;
        let card = HotCard {
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            ..card
        };
        state.piles.get_mut(PileId::Hand).make_mut().push(card);
        let mut instance = state.card_states.get(card.uid);
        instance.set_local_ethereal(true);
        state.card_states.set(card.uid, instance);

        ETHEREAL_PLAN_SCANS.with(|scans| scans.set(0));
        assert!(!ethereal_history_needs_transaction(
            &state, &catalog, card.uid, source
        ));
        ETHEREAL_PLAN_SCANS.with(|scans| assert_eq!(scans.get(), 0));

        assert!(
            state
                .fanouts
                .set_ethereal_plays_finished_combat(i32::MAX - MAX_CARD_PLAY_BODIES_PER_ACTION)
        );
        assert!(!ethereal_history_needs_transaction(
            &state, &catalog, card.uid, source
        ));
        ETHEREAL_PLAN_SCANS.with(|scans| assert_eq!(scans.get(), 0));

        assert!(
            state
                .fanouts
                .set_ethereal_plays_finished_combat(i32::MAX - 255)
        );
        let mut instance = state.card_states.get(card.uid);
        instance.set_base_replay_count(Some(255)).unwrap();
        state.card_states.set(card.uid, instance);
        assert!(ethereal_history_needs_transaction(
            &state, &catalog, card.uid, source
        ));
        ETHEREAL_PLAN_SCANS.with(|scans| assert_eq!(scans.get(), 1));

        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 10_000));
        let before = state.clone();
        let mut events = Vec::new();
        assert_eq!(
            play_card(&mut state, &catalog, card.uid, Some(0), None, &mut events,),
            Err(EngineRefusal::CounterOverflow(
                "ethereal_plays_finished_combat"
            ))
        );
        assert_eq!(
            state, before,
            "local-Ethereal overflow is whole-action atomic"
        );
        assert!(events.is_empty());

        let mut malformed = before;
        assert!(malformed.fanouts.set_ethereal_plays_finished_combat(0));
        let mut instance = malformed.card_states.get(card.uid);
        instance.set_base_replay_count(Some(i32::MAX)).unwrap();
        malformed.card_states.set(card.uid, instance);
        let malformed_before = malformed.clone();
        let mut malformed_events = Vec::new();
        assert_eq!(
            play_card(
                &mut malformed,
                &catalog,
                card.uid,
                Some(0),
                None,
                &mut malformed_events,
            ),
            Err(EngineRefusal::CounterOverflow("play count"))
        );
        assert_eq!(malformed, malformed_before);
        assert!(malformed_events.is_empty());
    }

    #[test]
    fn hidden_gem_replayed_drum_folds_physical_count_again_on_forced_exhaust() {
        let mut builder = CatalogBuilder::new();
        let hidden = builder
            .intern_reachable(identity(CardId::HiddenGem, 0))
            .unwrap();
        let drum = builder
            .intern_reachable(identity(CardId::DrumOfBattle, 0))
            .unwrap();
        let defend = builder
            .intern_reachable(identity(CardId::DefendIronclad, 0))
            .unwrap();
        let catalog = builder.build();
        let hidden = HotCard {
            uid: 1,
            atom: hidden,
            flags: 0,
        };
        let drum = HotCard {
            uid: 2,
            atom: drum,
            flags: 0,
        };
        let mut state = HotState::at_defaults();
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.hp = 50;
        state.energy = 10;
        state.next_card_uid = 9;
        state.rng.set(
            RngStream::Sel,
            RngStreamState {
                words: [1, 2, 3, 4],
                counter: 0,
            },
        );
        state.piles.get_mut(PileId::Hand).make_mut().push(hidden);
        state.piles.get_mut(PileId::Draw).make_mut().push(drum);

        play_card(
            &mut state,
            &catalog,
            hidden.uid,
            None,
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(state.card_states.get(drum.uid).base_replay_count(), Some(2));
        let drum = state.piles.get_mut(PileId::Draw).make_mut().remove(0);
        state.piles.get_mut(PileId::Play).make_mut().push(drum);
        state
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .extend((3..9).map(|uid| HotCard {
                uid,
                atom: defend,
                flags: 0,
            }));

        let mut overflow = state.clone();
        overflow.energy = i16::MAX - 4;
        let overflow_before = overflow.clone();
        let mut overflow_events = vec![Event::CardResolved {
            uid: 99,
            pile: PileId::Discard,
        }];
        let overflow_events_before = overflow_events.clone();
        assert_eq!(
            play_card_with_work(
                &mut overflow,
                &catalog,
                drum.uid,
                None,
                None,
                &mut overflow_events,
                PlaySource {
                    pile: PileId::Play,
                    provenance: PlayProvenance::Auto,
                    force_exhaust: true,
                    frozen: Some(drum),

                    allow_dead_target: false,
                },
            ),
            Err(EngineRefusal::CounterOverflow("energy"))
        );
        assert_eq!(overflow, overflow_before);
        assert_eq!(overflow_events, overflow_events_before);

        play_card_with_work(
            &mut state,
            &catalog,
            drum.uid,
            None,
            None,
            &mut Vec::new(),
            PlaySource {
                pile: PileId::Play,
                provenance: PlayProvenance::Auto,
                force_exhaust: true,
                frozen: Some(drum),

                allow_dead_target: false,
            },
        )
        .unwrap();

        assert_eq!(
            state.piles.get(PileId::Hand).len(),
            6,
            "three Draw-2 bodies"
        );
        assert_eq!(state.piles.get(PileId::Exhaust).as_slice(), [drum]);
        assert_eq!(
            state.energy, 15,
            "one Hidden payment then three Drum +2 grants"
        );
        assert_eq!(state.history.card_plays_finished_combat, 4);
    }

    #[test]
    fn static_ethereal_attacks_run_their_exact_bodies_and_shared_completion_lifecycle() {
        for (id, upgrade, damage, target, stars, vuln, temp_strength) in [
            (CardId::Defile, 0, 13, Some(0), 0, 0, 0),
            (CardId::Defile, 1, 17, Some(0), 0, 0, 0),
            (CardId::Fear, 0, 7, Some(0), 0, 1, 0),
            (CardId::Fear, 1, 8, Some(0), 0, 2, 0),
            (CardId::DyingStar, 0, 9, None, 3, 0, 9),
            (CardId::DyingStar, 1, 11, None, 3, 0, 11),
        ] {
            let identity = identity(id, upgrade);
            let mut builder = CatalogBuilder::new();
            builder.intern(identity).unwrap();
            let catalog = builder.build();
            let mut state = state_with_card(&catalog, identity, 81);
            state.stars = stars;
            state.monsters_mut().extend([
                HotMonster::new(MonsterKind::Toadpole, 100),
                HotMonster::new(MonsterKind::Toadpole, 100),
            ]);

            play_card(&mut state, &catalog, 81, target, None, &mut Vec::new()).unwrap();

            assert_eq!(state.energy, 8, "{}+{upgrade}", id.as_str());
            assert_eq!(state.stars, 0, "{}+{upgrade}", id.as_str());
            assert_eq!(state.monsters[0].hp, 100 - damage);
            assert_eq!(
                state.monsters[1].hp,
                if id == CardId::DyingStar {
                    100 - damage
                } else {
                    100
                }
            );
            assert_eq!(state.monsters[0].powers.value(PowerId::Vuln), vuln);
            for monster in state.monsters.iter() {
                assert_eq!(monster.powers.value(PowerId::Strength), -temp_strength);
                assert_eq!(monster.powers.value(PowerId::TempStrength), -temp_strength);
            }
            assert_eq!(state.fanouts.ethereal_plays_finished_combat(), 1);
            assert_eq!(state.history.card_plays_finished_combat, 1);
            assert_eq!(
                state
                    .piles
                    .get(PileId::Discard)
                    .as_slice()
                    .iter()
                    .map(|card| card.uid)
                    .collect::<Vec<_>>(),
                [81]
            );
        }

        let identity = identity(CardId::Fear, 1);
        let mut builder = CatalogBuilder::new();
        builder.intern(identity).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, identity, 82);
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        assert!(state.fanouts.set_ethereal_plays_finished_combat(i32::MAX));
        let before = state.clone();
        let mut events = Vec::new();

        assert_eq!(
            play_card(&mut state, &catalog, 82, Some(0), None, &mut events),
            Err(EngineRefusal::CounterOverflow(
                "ethereal_plays_finished_combat"
            ))
        );
        assert_eq!(state, before);
        assert!(events.is_empty());
    }

    #[test]
    fn banshees_cry_attacks_all_and_observes_each_finished_ethereal_replay() {
        for (upgrade, cost) in [(0, 9), (1, 7)] {
            let banshee = identity(CardId::BansheesCry, upgrade);
            let ethereal = identity(CardId::StrikeIronclad, 0);
            let mut builder = CatalogBuilder::new();
            let banshee_atom = builder.intern(banshee).unwrap();
            let ethereal_atom = builder.intern(ethereal).unwrap();
            let catalog = builder.build();

            let source = HotCard {
                uid: 1,
                atom: banshee_atom,
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            };
            let mut body = HotState::at_defaults();
            body.hp = 50;
            body.energy = cost;
            body.next_card_uid = 2;
            body.piles.get_mut(PileId::Hand).make_mut().push(source);
            body.monsters_mut().extend([
                HotMonster::new(MonsterKind::Toadpole, 100),
                HotMonster::new(MonsterKind::Toadpole, 100),
            ]);

            play_card(&mut body, &catalog, source.uid, None, None, &mut Vec::new()).unwrap();
            assert_eq!(body.energy, 0);
            assert_eq!(body.monsters[0].hp, 67);
            assert_eq!(body.monsters[1].hp, 67);

            let ethereal_source = HotCard {
                uid: 10,
                atom: ethereal_atom,
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            };
            let listeners = PileId::ALL.map(|pile| {
                (
                    pile,
                    HotCard {
                        uid: 20 + pile as u32,
                        atom: banshee_atom,
                        flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
                    },
                )
            });
            let mut lifecycle = HotState::at_defaults();
            lifecycle.hp = 50;
            lifecycle.energy = 2;
            lifecycle.next_card_uid = 40;
            lifecycle.powers.set(PowerId::OneTwoPunch, SlotWire::Int, 1);
            hydrate_side_end_order(&mut lifecycle);
            lifecycle
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 1000));
            lifecycle
                .piles
                .get_mut(PileId::Hand)
                .make_mut()
                .push(ethereal_source);
            let mut instance = lifecycle.card_states.get(ethereal_source.uid);
            instance.set_local_ethereal(true);
            lifecycle.card_states.set(ethereal_source.uid, instance);
            for (pile, listener) in listeners {
                lifecycle.piles.get_mut(pile).make_mut().push(listener);
            }

            play_card(
                &mut lifecycle,
                &catalog,
                ethereal_source.uid,
                Some(0),
                None,
                &mut Vec::new(),
            )
            .unwrap();

            assert_eq!(lifecycle.fanouts.ethereal_plays_finished_combat(), 2);
            for pile in PileId::ALL {
                let listener = lifecycle
                    .piles
                    .get(pile)
                    .as_slice()
                    .iter()
                    .find(|card| (20..=24).contains(&card.uid))
                    .unwrap();
                assert_eq!(
                    lifecycle
                        .card_states
                        .get(listener.uid)
                        .local_cost_modifiers
                        .as_slice(),
                    [
                        LocalCostModifier {
                            kind: LocalCostModifierKind::Add,
                            amount: -2,
                            expiration: LocalCostExpiration::ThisCombat,
                            reduce_only: false,
                        },
                        LocalCostModifier {
                            kind: LocalCostModifierKind::Add,
                            amount: -2,
                            expiration: LocalCostExpiration::ThisCombat,
                            reduce_only: false,
                        }
                    ]
                );
            }
            assert!(lifecycle.exact_piles);
        }
    }

