    #[test]
    fn banshees_cry_fresh_entry_backfills_history_but_clones_do_not_reapply_it() {
        let banshee = identity(CardId::BansheesCry, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(banshee).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.next_card_uid = 10;
        assert!(state.fanouts.set_ethereal_plays_finished_combat(3));

        super::super::cards::inject_generated_bottom(
            &mut state,
            &catalog,
            banshee,
            1,
            PileId::Hand,
            &mut Vec::new(),
        )
        .unwrap();
        let fresh = state.piles.get(PileId::Hand).as_slice()[0];
        assert_eq!(fresh.atom, atom);
        assert_ne!(fresh.flags & CARD_FLAG_DEFAULT_PHYSICAL_STATE, 0);
        assert_eq!(
            state
                .card_states
                .get(fresh.uid)
                .local_cost_modifiers
                .as_slice(),
            [LocalCostModifier {
                kind: LocalCostModifierKind::Add,
                amount: -6,
                expiration: LocalCostExpiration::ThisCombat,
                reduce_only: false,
            }]
        );

        super::super::cards::inject_generated_clones_bottom(
            &mut state,
            &catalog,
            fresh,
            1,
            PileId::Hand,
            &mut Vec::new(),
        )
        .unwrap();
        let clone = state.piles.get(PileId::Hand).as_slice()[1];
        assert_eq!(
            state.card_states.get(clone.uid),
            state.card_states.get(fresh.uid),
            "IsClone returns before entry-history backfill"
        );
    }

