    #[test]
    fn sentry_mode_public_play_registers_and_signal_boost_late_overflow_rolls_back() {
        for upgrade in [0, 1] {
            let sentry = identity(CardId::SentryMode, upgrade);
            let mut builder = CatalogBuilder::new();
            builder.intern(sentry).unwrap();
            let catalog = builder.build();
            assert!(catalog.atom(&identity(CardId::SweepingGaze, 0)).is_some());
            let mut state = state_with_card(&catalog, sentry, 70 + u32::from(upgrade));
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));

            play_card(
                &mut state,
                &catalog,
                70 + u32::from(upgrade),
                None,
                None,
                &mut Vec::new(),
            )
            .unwrap();

            assert_eq!(state.powers.value(PowerId::SentryMode), 1);
            assert_eq!(
                state.fanouts.before_hand_draw_order(),
                [PowerId::SentryMode]
            );
        }

        let sentry = identity(CardId::SentryMode, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(sentry).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, sentry, 80);
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.powers.set(PowerId::SignalBoost, SlotWire::Int, 1);
        state
            .powers
            .set(PowerId::SentryMode, SlotWire::Int, i32::MAX - 1);
        assert!(
            state
                .fanouts
                .set_before_hand_draw_order(&[PowerId::SentryMode])
        );
        let before = state.clone();
        let mut events = vec![Event::TurnBegan { turn: 91 }];
        let before_events = events.clone();

        assert_eq!(
            play_card(&mut state, &catalog, 80, None, None, &mut events),
            Err(EngineRefusal::CounterOverflow("Sentry Mode"))
        );
        assert_eq!(state, before, "spend/source/first body all roll back");
        assert_eq!(events, before_events);
    }

    #[test]
    fn glimpse_beyond_is_live_party_only_and_burst_late_refusal_has_no_prefix() {
        for (upgrade, amount) in [(0, 3_usize), (1, 4)] {
            let glimpse = identity(CardId::GlimpseBeyond, upgrade);
            let mut builder = CatalogBuilder::new();
            builder.intern(glimpse).unwrap();
            let catalog = builder.build();
            assert!(catalog.atom(&identity(CardId::Soul, 0)).is_some());
            assert!(catalog.atom(&identity(CardId::Soul, 1)).is_none());

            let solo = state_with_card(&catalog, glimpse, 200 + u32::from(upgrade));
            let source = solo.piles.get(PileId::Hand).as_slice()[0];
            assert!(!can_play(
                &catalog,
                &solo,
                source,
                catalog.spec(source.atom).unwrap()
            ));

            let mut dead_remote = solo.clone();
            dead_remote.multiplayer_ally_key = 1;
            dead_remote
                .fanouts
                .set_multiplayer_ally(MultiplayerAllyState {
                    key: 1,
                    alive: false,
                    ..MultiplayerAllyState::default()
                });
            assert!(!can_play(
                &catalog,
                &dead_remote,
                source,
                catalog.spec(source.atom).unwrap()
            ));

            let mut state = solo;
            state.multiplayer_ally_key = 1;
            state.fanouts.set_multiplayer_ally(MultiplayerAllyState {
                key: 1,
                ..MultiplayerAllyState::default()
            });
            assert!(can_play(
                &catalog,
                &state,
                source,
                catalog.spec(source.atom).unwrap()
            ));

            play_card(
                &mut state,
                &catalog,
                200 + u32::from(upgrade),
                None,
                None,
                &mut Vec::new(),
            )
            .unwrap();
            assert_eq!(state.piles.get(PileId::Draw).len(), amount);
            assert_eq!(state.fanouts.multiplayer_ally().draw.len(), amount);
            assert_eq!(
                state.history.owner_generated_cards_combat,
                i32::try_from(amount * 2).unwrap()
            );
            assert_eq!(state.piles.get(PileId::Exhaust).len(), 1);
        }

        let glimpse = identity(CardId::GlimpseBeyond, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(glimpse).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, glimpse, 220);
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.multiplayer_ally_key = 1;
        state.fanouts.set_multiplayer_ally(MultiplayerAllyState {
            key: 1,
            ..MultiplayerAllyState::default()
        });
        state.powers.set(PowerId::Burst, SlotWire::Int, 1);
        hydrate_side_end_order(&mut state);
        state.next_generated_hook_uid = i32::MAX - 7;
        let before = state.clone();
        let mut events = vec![Event::TurnBegan { turn: 97 }];
        let before_events = events.clone();

        assert_eq!(
            play_card(&mut state, &catalog, 220, None, None, &mut events),
            Err(EngineRefusal::CounterOverflow("next_generated_hook_uid"))
        );
        assert_eq!(state, before, "rehearsal refuses before spend/source/body");
        assert_eq!(events, before_events);
    }

    #[test]
    fn glimpse_beyond_coexists_with_tender_and_sentry_but_refuses_solo_only_listeners() {
        let glimpse = identity(CardId::GlimpseBeyond, 0);
        let sentry = identity(CardId::SentryMode, 0);
        let mut builder = CatalogBuilder::new();
        let glimpse_atom = builder.intern(glimpse).unwrap();
        builder.intern(sentry).unwrap();
        builder.intern_private_tender_hunter().unwrap();
        let catalog = builder.build();
        assert!(catalog.atom(&identity(CardId::Soul, 0)).is_some());
        assert!(catalog.atom(&identity(CardId::SweepingGaze, 0)).is_some());

        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.next_card_uid = 301;
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 300,
            atom: glimpse_atom,
            flags: 0,
        });
        state.multiplayer_ally_key = 1;
        state.fanouts.set_multiplayer_ally(MultiplayerAllyState {
            key: 1,
            ..MultiplayerAllyState::default()
        });

        let mut hunter = HotMonster::new(MonsterKind::HunterKiller, 126);
        hunter.max_hp = 126;
        hunter.uid = 23;
        let mut hunter_ai = crate::hot::RandomAiState::new();
        assert!(hunter_ai.set_next(Some(crate::engine::turn::HUNTER_BITE_INDEX)));
        assert!(hunter_ai.set_log(&[
            crate::engine::turn::HUNTER_GOOP_INDEX,
            crate::engine::turn::HUNTER_BITE_INDEX,
        ]));
        hunter.random_ai = hunter_ai;
        state.monsters_mut().push(hunter);
        state.powers.set(PowerId::Tender, SlotWire::Int, 1);
        assert!(state.fanouts.set_tender_state(true, 0));
        hydrate_side_end_order(&mut state);

        state.energy = 9;
        state.powers.set(PowerId::SentryMode, SlotWire::Int, 1);
        assert!(
            state
                .fanouts
                .set_before_hand_draw_order(&[PowerId::SentryMode])
        );

        for (mut invalid, expected) in [
            {
                let mut invalid = state.clone();
                invalid.powers.set(PowerId::Monologue, SlotWire::Int, 1);
                assert!(invalid.fanouts.register_monologue_hooks());
                (
                    invalid,
                    EngineRefusal::MalformedArgs("monologue private state"),
                )
            },
            {
                let mut invalid = state.clone();
                invalid.powers.set(PowerId::VoidForm, SlotWire::Int, 1);
                invalid.fanouts.set_void_form_hooks_registered(true);
                assert!(invalid.fanouts.set_void_form_cards_played_this_turn(0));
                (
                    invalid,
                    EngineRefusal::MalformedArgs(
                        "ordinary AfterCardPlayed player-power object ledger",
                    ),
                )
            },
        ] {
            let before = invalid.clone();
            let mut events = vec![Event::TurnBegan { turn: 100 }];
            let before_events = events.clone();
            assert_eq!(
                play_card(&mut invalid, &catalog, 300, None, None, &mut events),
                Err(expected)
            );
            assert_eq!(invalid, before);
            assert_eq!(events, before_events);
        }

        play_card(&mut state, &catalog, 300, None, None, &mut Vec::new()).unwrap();

        assert_eq!(state.energy, 8);
        assert_eq!(state.piles.get(PileId::Draw).len(), 3);
        assert_eq!(state.fanouts.multiplayer_ally().draw.len(), 3);
        assert_eq!(state.powers.value(PowerId::Strength), -1);
        assert_eq!(state.powers.value(PowerId::Dexterity), -1);
        assert_eq!(state.fanouts.tender_cards_played(), 1);
        assert_eq!(state.powers.value(PowerId::SentryMode), 1);
        assert_eq!(
            state.fanouts.before_hand_draw_order(),
            [PowerId::SentryMode]
        );
    }

    #[test]
    fn sweeping_gaze_uses_only_the_target_stream_and_late_refusal_is_atomic() {
        for (upgrade, damage) in [(0, 10), (1, 15)] {
            let gaze = identity(CardId::SweepingGaze, upgrade);
            let mut builder = CatalogBuilder::new();
            builder.intern(gaze).unwrap();
            let catalog = builder.build();
            let mut state = state_with_card(&catalog, gaze, 90 + u32::from(upgrade));
            state.fanouts.mutate_pet(|pet| pet.summon(5)).unwrap();
            state.monsters_mut().extend([
                HotMonster::new(MonsterKind::Toadpole, 100),
                HotMonster::new(MonsterKind::Toadpole, 100),
            ]);
            state.rng.set(
                RngStream::Targets,
                RngStreamState {
                    words: [1, 2, 3, 4],
                    counter: 0,
                },
            );
            let rng_before = state.rng.clone();

            play_card(
                &mut state,
                &catalog,
                90 + u32::from(upgrade),
                None,
                None,
                &mut Vec::new(),
            )
            .unwrap();

            assert_eq!(
                state.monsters.iter().map(|monster| monster.hp).sum::<i32>(),
                200 - damage
            );
            assert_eq!(state.rng.get(RngStream::Targets).counter, 1);
            for stream in RngStream::ALL {
                if stream != RngStream::Targets {
                    assert_eq!(state.rng.get(stream), rng_before.get(stream));
                }
            }
        }

        let gaze = identity(CardId::SweepingGaze, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(gaze).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, gaze, 100);
        state.fanouts.mutate_pet(|pet| pet.summon(5)).unwrap();
        state.monsters_mut().extend([
            HotMonster::new(MonsterKind::Toadpole, 100),
            HotMonster::new(MonsterKind::Toadpole, 100),
        ]);
        for monster in state.monsters_mut() {
            monster.nonowner_same_side_powered_damage_results_this_turn = i32::MAX;
        }
        state.rng.set(
            RngStream::Targets,
            RngStreamState {
                words: [1, 2, 3, 4],
                counter: 0,
            },
        );
        let before = state.clone();
        let mut events = vec![Event::TurnBegan { turn: 92 }];
        let before_events = events.clone();

        assert_eq!(
            play_card(&mut state, &catalog, 100, None, None, &mut events),
            Err(EngineRefusal::CounterOverflow(
                "nonowner_same_side_powered_damage_results_this_turn"
            ))
        );
        assert_eq!(
            state, before,
            "target RNG and complete play prefix roll back"
        );
        assert_eq!(events, before_events);
    }

    #[test]
    fn lethality_power_play_records_exact_ethereal_history_and_removes_source() {
        for (upgrade, amount) in [(0, 50), (1, 75)] {
            let identity = identity(CardId::Lethality, upgrade);
            let mut builder = CatalogBuilder::new();
            let atom = builder.intern(identity).unwrap();
            let catalog = builder.build();
            let card = HotCard {
                uid: 41,
                atom,
                flags: 0,
            };
            let mut state = HotState::at_defaults();
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            state.hp = 50;
            state.energy = 3;
            state.next_card_uid = 42;
            state.piles.get_mut(PileId::Hand).make_mut().push(card);

            play_card(&mut state, &catalog, card.uid, None, None, &mut Vec::new()).unwrap();

            assert_eq!(state.powers.value(PowerId::Lethality), amount);
            assert_eq!(state.fanouts.ethereal_plays_finished_combat(), 1);
            assert!(
                PileId::ALL.into_iter().all(|pile| !state
                    .piles
                    .get(pile)
                    .as_slice()
                    .contains(&card))
            );

            let mut autoplay = HotState::at_defaults();

            autoplay.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            autoplay.hp = 50;
            autoplay.energy = 3;
            autoplay.next_card_uid = 42;
            autoplay
                .piles
                .get_mut(PileId::Discard)
                .make_mut()
                .push(card);
            autoplay_collected_cards(&mut autoplay, &catalog, &[card], &mut Vec::new()).unwrap();
            assert_eq!(autoplay.powers.value(PowerId::Lethality), amount);
            assert_eq!(autoplay.fanouts.ethereal_plays_finished_combat(), 1);
            assert_eq!(autoplay.history.card_plays_finished_combat, 1);
            assert!(
                PileId::ALL.into_iter().all(|pile| !autoplay
                    .piles
                    .get(pile)
                    .as_slice()
                    .contains(&card))
            );

            let mut generated = HotState::at_defaults();

            generated.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            generated.hp = 50;
            generated.energy = 3;
            generated.next_card_uid = 42;
            generated.powers.set(PowerId::SignalBoost, SlotWire::Int, 1);
            generated.piles.get_mut(PileId::Hand).make_mut().push(card);
            play_card(
                &mut generated,
                &catalog,
                card.uid,
                None,
                None,
                &mut Vec::new(),
            )
            .unwrap();
            assert_eq!(generated.powers.value(PowerId::Lethality), amount * 2);
            assert_eq!(generated.powers.value(PowerId::SignalBoost), 0);
            assert_eq!(generated.fanouts.ethereal_plays_finished_combat(), 2);
            assert_eq!(generated.history.card_plays_finished_combat, 2);
            assert!(
                PileId::ALL.into_iter().all(|pile| !generated
                    .piles
                    .get(pile)
                    .as_slice()
                    .contains(&card))
            );
        }

        let identity = identity(CardId::Lethality, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(identity).unwrap();
        let catalog = builder.build();
        let card = HotCard {
            uid: 42,
            atom,
            flags: 0,
        };
        let mut state = HotState::at_defaults();
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.hp = 50;
        state.energy = 3;
        state.next_card_uid = 43;
        assert!(state.fanouts.set_ethereal_plays_finished_combat(i32::MAX));
        state.piles.get_mut(PileId::Hand).make_mut().push(card);
        let before = state.clone();
        let mut events = Vec::new();
        assert_eq!(
            play_card(&mut state, &catalog, card.uid, None, None, &mut events),
            Err(EngineRefusal::CounterOverflow(
                "ethereal_plays_finished_combat"
            ))
        );
        assert_eq!(state, before);
        assert!(events.is_empty());

        let mut generated_overflow = HotState::at_defaults();

        generated_overflow
            .monsters_mut()
            .push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
        generated_overflow.hp = 50;
        generated_overflow.energy = 3;
        generated_overflow.next_card_uid = 43;
        assert!(
            generated_overflow
                .fanouts
                .set_ethereal_plays_finished_combat(i32::MAX - 1)
        );
        generated_overflow
            .powers
            .set(PowerId::SignalBoost, SlotWire::Int, 1);
        generated_overflow
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(card);
        let before = generated_overflow.clone();
        let mut events = Vec::new();
        assert_eq!(
            play_card(
                &mut generated_overflow,
                &catalog,
                card.uid,
                None,
                None,
                &mut events,
            ),
            Err(EngineRefusal::CounterOverflow(
                "ethereal_plays_finished_combat"
            ))
        );
        assert_eq!(generated_overflow, before);
        assert!(events.is_empty());

        let mut terminal_after_first = HotState::at_defaults();

        terminal_after_first.hp = 50;
        terminal_after_first.energy = 3;
        terminal_after_first.next_card_uid = 43;
        assert!(
            terminal_after_first
                .fanouts
                .set_ethereal_plays_finished_combat(i32::MAX - 1)
        );
        terminal_after_first
            .powers
            .set(PowerId::SignalBoost, SlotWire::Int, 1);
        install_panache_instance(&mut terminal_after_first, 10, 1);
        terminal_after_first
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 10));
        terminal_after_first
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(card);
        play_card(
            &mut terminal_after_first,
            &catalog,
            card.uid,
            None,
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert!(terminal_after_first.history.over);
        assert_eq!(terminal_after_first.monsters[0].hp, 0);
        assert_eq!(terminal_after_first.powers.value(PowerId::Lethality), 50);
        assert_eq!(terminal_after_first.powers.value(PowerId::SignalBoost), 0);
        assert_eq!(
            terminal_after_first
                .fanouts
                .ethereal_plays_finished_combat(),
            i32::MAX
        );
        assert_eq!(terminal_after_first.history.card_plays_finished_combat, 1);
    }

    #[test]
    fn terminal_autoplay_removes_power_and_dupe_but_retains_ordinary_source_in_play() {
        for pile in [PileId::Hand, PileId::Draw, PileId::Discard, PileId::Exhaust] {
            for (id, dupe, removed) in [
                (CardId::Inflame, false, true),
                (CardId::StrikeIronclad, true, true),
                (CardId::StrikeIronclad, false, false),
            ] {
                let mut builder = CatalogBuilder::new();
                let atom = builder.intern(identity(id, 0)).unwrap();
                let catalog = builder.build();
                let mut state = HotState::at_defaults();
                state.hp = 50;
                state.max_hp = 50;
                state.energy = 3;
                state.next_card_uid = 2;
                let card = HotCard {
                    uid: 1,
                    atom,
                    flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE
                        | if dupe { crate::hot::CARD_FLAG_DUPE } else { 0 },
                };
                state.piles.get_mut(pile).make_mut().push(card);
                state
                    .monsters_mut()
                    .push(HotMonster::new(MonsterKind::Toadpole, 10));
                install_panache_instance(&mut state, 10, 1);
                play_card_with_work(
                    &mut state,
                    &catalog,
                    1,
                    (id == CardId::StrikeIronclad).then_some(0),
                    None,
                    &mut Vec::new(),
                    PlaySource {
                        pile,
                        provenance: PlayProvenance::Auto,
                        force_exhaust: false,
                        frozen: Some(card),
                        allow_dead_target: false,
                    },
                )
                .unwrap();
                assert!(state.history.over, "{pile:?}/{id:?}/{dupe}");
                assert_eq!(state.history.card_plays_finished_combat, 1);
                assert!(state.piles.get(pile).is_empty());
                assert_eq!(state.piles.get(PileId::Play).len(), usize::from(!removed));
                assert_eq!(state.energy, 3);
            }
        }
    }

