        let played = play_first_card(&state, &catalog, None);
        assert_eq!(played.piles.get(PileId::Hand).len(), 2);
        assert_eq!(played.piles.get(PileId::Draw).len(), 2);
        assert_eq!(played.card_states.get(1).enchantment_state.get(), Some(1));
        assert_eq!(
            HotBoundary::to_canonical(&played, &catalog)
                .piles
                .get("discard")
                .unwrap()[0]
                .enchantment,
            Some(serde_json::json!(["SWIFT_USED", 2]))
        );

        let mut already_spent = state.clone();
        let mut instance = already_spent.card_states.get(1);
        instance.enchantment_state =
            crate::hot::OptionalNonNegativeI32::from_option(Some(1)).unwrap();
        already_spent.card_states.set(1, instance);
        let replayed = play_first_card(&already_spent, &catalog, None);
        assert_eq!(
            replayed.piles.get(PileId::Draw).len(),
            4,
            "a spent Swift draws nothing"
        );
