    #[test]
    fn corrupted_scales_the_powered_base_and_takes_two_hp_after_the_body() {
        let (plain, plain_catalog) = onplay_enchantment_state(
            crate::catalog::CardEnchantment {
                id: EnchantmentId::Steady,
                amount: 1,
            },
            CardId::StrikeIronclad,
            0,
        );
        let plain_played = play_first_card(&plain, &plain_catalog, Some(0));
        let plain_damage = 50 - plain_played.monsters[0].hp;
        assert_eq!(plain_played.hp, 50, "Steady costs the owner nothing");

        let (state, catalog) = onplay_enchantment_state(
            crate::catalog::CardEnchantment {
                id: EnchantmentId::Corrupted,
                amount: 0,
            },
            CardId::StrikeIronclad,
            0,
        );
        let played = play_first_card(&state, &catalog, Some(0));
        let damage = 50 - played.monsters[0].hp;
        // `EnchantDamageMultiplicative` RVA `0xd5eb5` is exactly 3/2 on the
        // raw DamageVar, before every additive and the one final floor.
        assert_eq!(damage, plain_damage * 3 / 2);
        assert_eq!(played.hp, 48, "the props-14 self hit is two HP");
        // Corrupted is not a one-shot: slot 5 stays vacant so every later
        // body hits again.
        assert!(!played.card_states.get(1).enchantment_state.is_some());
    }

    #[test]
    fn corrupted_still_takes_its_hp_after_a_body_that_won_the_fight() {
        let (mut state, catalog) = onplay_enchantment_state(
            crate::catalog::CardEnchantment {
                id: EnchantmentId::Corrupted,
                amount: 0,
            },
            CardId::StrikeIronclad,
            0,
        );
        state.monsters_mut()[0].hp = 1;
        let played = play_first_card(&state, &catalog, Some(0));
        assert!(played.history.over && played.monsters[0].hp <= 0);
        assert_eq!(
            played.hp, 48,
            "combat_sim.player_hp_loss has no `s.over` branch, so the \
             enchantment's OnPlay still lands after the winning body"
        );
    }

    fn adroit(amount: i32) -> crate::catalog::CardEnchantment {
        crate::catalog::CardEnchantment {
            id: EnchantmentId::Adroit,
            amount,
        }
    }

    /// #3220: `Adroit/<OnPlay>d__6::MoveNext` RVA `0x3880d8` gains `Amount`
    /// powered Block after the body, on a card whose body gains none, with no
    /// Status gate — so a second play gains it again and slot 5 stays vacant.
    #[test]
    fn adroit_gains_its_amount_as_block_after_every_play() {
        let (state, catalog) = onplay_enchantment_state(adroit(3), CardId::StrikeIronclad, 0);
        let played = play_first_card(&state, &catalog, Some(0));
        assert_eq!(played.block, 3);
        assert!(played.monsters[0].hp < 50, "the Strike body still lands");
        assert!(!played.card_states.get(1).enchantment_state.is_some());
        assert_eq!(played.history.card_block_gains, 1);

        let canonical = HotBoundary::to_canonical(&played, &catalog);
        let row = &canonical.piles.get("discard").unwrap()[0];
        assert_eq!(row.enchantment, Some(serde_json::json!(["ADROIT", 3])));
        assert_eq!(row.enchantment_state, None);
        let rebuilt = HotBoundary::catalog_from_canonical(&canonical).unwrap();
        let reloaded = HotBoundary::from_canonical(&canonical, &rebuilt).unwrap();
        crate::engine::admit(&canonical, &reloaded, &rebuilt).unwrap();

        // Stateless: the same card played again gains the Amount again.
        let mut again = played.clone();
        let card = again.piles.get_mut(PileId::Discard).make_mut().remove(0);
        again.piles.get_mut(PileId::Hand).make_mut().push(card);
        again.energy = 3;
        let replayed = play_first_card(&again, &catalog, Some(0));
        assert_eq!(replayed.block, 6);

        // `RecalculateValues` RVA `0xd5e7f`: Block.BaseValue = Amount, so a
        // zero Amount is a zero GainBlock and records no gain.
        let (zero, zero_catalog) = onplay_enchantment_state(adroit(0), CardId::StrikeIronclad, 0);
        let played = play_first_card(&zero, &zero_catalog, Some(0));
        assert_eq!(played.block, 0);
        assert_eq!(played.history.card_block_gains, 0);
    }

    /// #3220: the enchantment's Block is its own powered card GainBlock (props
    /// 8, `Adroit::get_CanonicalVars` RVA `0xd5e1f`), separate from the
    /// body's: Dexterity adds to each gain, Frail floors each gain, and an
    /// upgraded owner keeps the enchantment's Amount while its own Block rises.
    #[test]
    fn adroit_block_is_a_separate_powered_gain_on_an_upgraded_defend() {
        let (state, catalog) = onplay_enchantment_state(adroit(2), CardId::DefendIronclad, 0);
        assert_eq!(play_first_card(&state, &catalog, None).block, 5 + 2);

        let mut dexterity = state.clone();
        dexterity.powers.set(PowerId::Dexterity, SlotWire::Int, 2);
        let played = play_first_card(&dexterity, &catalog, None);
        assert_eq!(
            played.block,
            (5 + 2) + (2 + 2),
            "Dexterity folds into both gains"
        );
        assert_eq!(played.history.card_block_gains, 2);

        let mut frail = state.clone();
        frail.powers.set(PowerId::PlayerFrail, SlotWire::Int, 1);
        // floor(5 * 3/4) + floor(2 * 3/4), not floor(7 * 3/4).
        assert_eq!(play_first_card(&frail, &catalog, None).block, 3 + 1);

        let upgraded = CardIdentity {
            id: CardId::DefendIronclad,
            upgrade: 1,
            enchantment: Some(adroit(2)),
        };
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(upgraded).unwrap();
        let upgraded_catalog = builder.build();
        let mut upgraded_state = state.clone();
        upgraded_state.piles.get_mut(PileId::Hand).make_mut()[0].atom = atom;
        let played = play_first_card(&upgraded_state, &upgraded_catalog, None);
        assert_eq!(played.block, 8 + 2, "Defend+ gains 8; Adroit still 2");
        let canonical = HotBoundary::to_canonical(&played, &upgraded_catalog);
        let row = &canonical.piles.get("discard").unwrap()[0];
        assert_eq!(row.upgrade, 1);
        assert_eq!(row.enchantment, Some(serde_json::json!(["ADROIT", 2])));
    }

    /// #3220: Adroit's GainBlock passes the current `cardPlay`, so Unmovable's
    /// window (`entry.CardPlay != cardPlay`, RVA `0x34a534` IL_0051-0062)
    /// excludes the body's own gain and the enchantment's Block doubles too.
    #[test]
    fn adroit_block_shares_the_cardplay_unmovable_window() {
        let (mut state, catalog) = onplay_enchantment_state(adroit(2), CardId::DefendIronclad, 0);
        state.powers.set(PowerId::Unmovable, SlotWire::Int, 1);
        assert_eq!(play_first_card(&state, &catalog, None).block, 10 + 4);
    }

    /// #3220: the OnPlay runs once per replay body (`OnPlayWrapper` IL_06de-
    /// 06fa sits inside the replay loop), so a Burst-replayed Defend gains the
    /// enchantment's Block twice.
    #[test]
    fn adroit_gains_once_per_replay_body() {
        let (mut state, catalog) = onplay_enchantment_state(adroit(3), CardId::DefendIronclad, 0);
        state.powers.set(PowerId::Burst, SlotWire::Int, 1);
        hydrate_side_end_order(&mut state);
        let played = play_first_card(&state, &catalog, None);
        assert_eq!(played.block, 2 * (5 + 3));
        assert_eq!(played.powers.value(PowerId::Burst), 0);
    }

    /// #3220: the forwarded `<GainBlock>d__18` RVA `0x3eaec0` IL_0032 returns
    /// at IsOverOrEnding, so a body that wins the fight gains no Adroit Block.
    #[test]
    fn adroit_gains_nothing_after_a_body_that_won_the_fight() {
        let (mut state, catalog) = onplay_enchantment_state(adroit(3), CardId::StrikeIronclad, 0);
        state.monsters_mut()[0].hp = 1;
        let played = play_first_card(&state, &catalog, Some(0));
        assert!(played.history.over);
        assert_eq!(played.block, 0);
    }

    /// #3220: the payload gate. A negative Amount, or a Status/Curse owner
    /// the base `CanEnchant` (RVA `0x7f40c` IL_000c-0023) never enchants,
    /// stays refused by the enchantment's own name.
    #[test]
    fn adroit_identity_gate_refuses_what_native_cannot_carry() {
        let mut builder = CatalogBuilder::new();
        let good = builder
            .intern(CardIdentity {
                id: CardId::StrikeIronclad,
                upgrade: 0,
                enchantment: Some(adroit(4)),
            })
            .unwrap();
        let catalog = builder.build();
        let spec = *catalog.spec(good).unwrap();
        assert!(onplay_enchantment_identity_is_exact(&spec));
        assert!(body_enchantment_is_exact(&spec));
        let mut negative = spec;
        negative.identity.enchantment = Some(adroit(-1));
        assert!(!body_enchantment_is_exact(&negative));
        let mut status = spec;
        status.is_status_curse = true;
        assert!(!body_enchantment_is_exact(&status));
    }

    /// Spending a Glam does not by itself force exact piles (#1620 class A).
    ///
    /// Python routes the GLAM -> GLAM_USED rewrite through
    /// `_commit_live_card_piles` (frozen Python, deleted #2827). It promotes only
    /// when `_has_distinguishable_sort_ties` says the live cards carry a
    /// CompareTo tie the payload rewrite would make observable — the
    /// `promote`/`prospective_exact` pair inside `_commit_live_card_piles`.
    /// A fight whose Glam card is the only copy of its `(id, upgrade)` has no
    /// such tie, and Rust promoted anyway on 18 of 318 captured fights.
    ///
    /// Both halves are asserted here: the lone copy must NOT promote, and a
    /// payload-equal sibling — which is exactly the tie the predicate looks
    /// for — must.
    #[test]
    fn spending_a_glam_promotes_exact_piles_only_on_a_distinguishable_tie() {
        let glam_strike = CardIdentity {
            id: CardId::StrikeIronclad,
            upgrade: 0,
            enchantment: Some(crate::catalog::CardEnchantment {
                id: EnchantmentId::Glam,
                amount: 1,
            }),
        };
        let plain_strike = identity(CardId::StrikeIronclad, 0);
        let defend = identity(CardId::DefendIronclad, 0);

        for (sibling, promotes) in [(defend, false), (plain_strike, true)] {
            let mut builder = CatalogBuilder::new();
            let glam_atom = builder.intern_reachable(glam_strike).unwrap();
            let sibling_atom = builder.intern_reachable(sibling).unwrap();
            let catalog = builder.build();
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.energy = 3;
            state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
            state.next_card_uid = 9;
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 60));
            state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
                uid: 1,
                atom: glam_atom,
                flags: 0,
            });
            state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
                uid: 2,
                atom: sibling_atom,
                flags: 0,
            });
            assert!(!state.exact_piles);

            let mut events = Vec::new();
            let mut next = state.clone();
            play_card(&mut next, &catalog, 1, Some(0), None, &mut events).unwrap();

            assert_eq!(
                next.card_states.get(1).enchantment_state.get(),
                Some(1),
                "the spent bit is written either way"
            );
            assert_eq!(
                next.exact_piles, promotes,
                "promotion must follow the tie predicate, not the rewrite: \
                 sibling={sibling:?}"
            );
        }
    }

    #[test]
    fn fresh_glam_selecting_replay_spends_before_second_body_and_authenticates_wire() {
        let pact = CardIdentity {
            id: CardId::BurningPact,
            upgrade: 0,
            enchantment: Some(crate::catalog::CardEnchantment {
                id: EnchantmentId::Glam,
                amount: 1,
            }),
        };
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let pact_atom = builder.intern_reachable(pact).unwrap();
        let strike_atom = builder.intern_reachable(strike).unwrap();
        let catalog = builder.build();
        assert!(catalog.requires_action_replay());
        let active = HotCard {
            uid: 1,
            atom: pact_atom,
            flags: 0,
        };
        let mut state = HotState::at_defaults();
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.hp = 50;
        state.energy = 1;
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.next_card_uid = 7;
        state.exact_piles = true;
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            active,
            HotCard {
                uid: 2,
                atom: strike_atom,
                flags: 0,
            },
            HotCard {
                uid: 3,
                atom: strike_atom,
                flags: 0,
            },
        ]);
        for uid in 4..7 {
            state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
                uid,
                atom: strike_atom,
                flags: 0,
            });
        }

        let suspended = crate::engine::apply_action_into(
            &state,
            &catalog,
            &crate::engine::Action::Play {
                uid: 1,
                target: None,
                selection: crate::engine::SelectionRef::new(Some(2)),
            },
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(pending_record(&suspended).plays, 2);
        assert_eq!(pending_record(&suspended).play_index, 1);
        assert_eq!(pending_record(&suspended).glam, 1);
        assert_eq!(
            suspended.card_states.get(1).enchantment_state.get(),
            Some(1)
        );

        let canonical = HotBoundary::to_canonical(&suspended, &catalog);
        assert_eq!(
            canonical.piles.get("play").unwrap()[0].enchantment,
            Some(serde_json::json!(["GLAM_USED", 1]))
        );
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&canonical).unwrap();
        let reloaded = HotBoundary::from_canonical(&canonical, &rebuilt_catalog).unwrap();
        crate::engine::admit(&canonical, &reloaded, &rebuilt_catalog).unwrap();

        let mut tampered = canonical.clone();
        tampered.continuations[1]
            .fields
            .insert("plays".to_owned(), serde_json::json!(3));
        assert!(HotBoundary::from_canonical(&tampered, &rebuilt_catalog).is_err());

        let finished = crate::engine::apply_action_into(
            &reloaded,
            &rebuilt_catalog,
            &crate::engine::Action::Select {
                answer: crate::engine::SelectionAnswer::CardUid(3),
            },
            &mut Vec::new(),
        )
        .unwrap();
        assert!(finished.pending.is_none());
        assert_eq!(finished.history.card_plays_finished_combat, 2);
        let routed = finished.piles.get(PileId::Discard).as_slice();
        assert_eq!(routed.len(), 1);
        assert_eq!(routed[0].uid, active.uid);
        assert_eq!(rebuilt_catalog.spec(routed[0].atom).unwrap().identity, pact);
        assert_eq!(finished.card_states.get(1).enchantment_state.get(), Some(1));
    }

    fn glam_stone_armor_plus() -> CardIdentity {
        CardIdentity {
            id: CardId::StoneArmor,
            upgrade: 1,
            enchantment: Some(crate::catalog::CardEnchantment {
                id: EnchantmentId::Glam,
                amount: 1,
            }),
        }
    }

    fn glam_power_state(catalog: &Catalog, spent: bool) -> HotState {
        let mut state = state_with_card(catalog, glam_stone_armor_plus(), 1);
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 60));
        if spent {
            let mut physical = state.card_states.get(1);
            physical.enchantment_state =
                crate::hot::OptionalNonNegativeI32::from_option(Some(1)).unwrap();
            state.card_states.set(1, physical);
        }
        state
    }

    fn glam_power_catalog() -> Catalog {
        let mut builder = CatalogBuilder::new();
        builder.intern(glam_stone_armor_plus()).unwrap();
        builder.intern(identity(CardId::StoneArmor, 1)).unwrap();
        builder.build()
    }

    /// RemoveBottom resets the removed uid's instance state, so the spent
    /// Glam bit written between bodies leaves no slot-5 residue on a uid that
    /// no pile holds (the #3135 spec's removed-uid risk).
    #[track_caller]
    fn assert_removed_uid_carries_no_state(state: &HotState) {
        assert!(!card_in_any_pile(state, 1));
        assert_eq!(
            state.card_states.get(1),
            crate::hot::CardInstanceState::default()
        );
    }

    fn card_in_any_pile(state: &HotState, uid: u32) -> bool {
        PileId::ALL.iter().any(|pile| {
            state
                .piles
                .get(*pile)
                .as_slice()
                .iter()
                .any(|card| card.uid == uid)
        })
    }

    /// #3135 witnesses 2, 3 and 7 (play half): Glam on a Power runs the
    /// native serial series. `GeneratePlayCount` is snapshotted at
    /// `OnPlayWrapper` `0x31b8d0` IL_034a/03ac before body 0, so the spend
    /// Glam's `AfterCardPlayed` `0xd5fb7` writes after body 0 (IL_0023-002c)
    /// cannot shrink the running series; the Power then leaves combat through
    /// `GetResultLocationForCardPlay` `0x7e018` IL_0014-002a. An already-spent
    /// Glam (`EnchantPlayCount` `0xd5f94` IL_0007-000a) contributes zero.
    #[test]
    fn glam_power_runs_two_frozen_bodies_then_leaves_combat_spent() {
        let catalog = glam_power_catalog();
        for (spent, bodies) in [(false, 2_u8), (true, 1)] {
            let mut state = glam_power_state(&catalog, spent);
            let spec = *catalog
                .spec(catalog.atom(&glam_stone_armor_plus()).unwrap())
                .unwrap();
            assert_eq!(spec.card_type, crate::content_tables::CardType::Power);
            assert!(replay_enchantment_identity_is_exact(&spec));
            assert!(body_enchantment_is_exact(&spec));
            assert_eq!(
                effective_replay_count(&state, &spec, 1),
                Ok(i32::from(!spent)),
                "fresh Glam adds Times; spent Glam adds nothing"
            );

            reset_test_body_starts();
            let mut events = Vec::new();
            play_card(&mut state, &catalog, 1, None, None, &mut events).unwrap();

            for index in 0..bodies {
                assert!(test_body_started(1, index), "spent={spent} body {index}");
            }
            assert!(!test_body_started(1, bodies), "spent={spent}");
            assert_eq!(
                state.powers.value(PowerId::Plating),
                6 * i32::from(bodies),
                "spent={spent}: one Apply<PlatingPower> per body"
            );
            assert_eq!(state.history.card_plays_finished_combat, i32::from(bodies));
            assert_eq!(
                events
                    .iter()
                    .filter(|event| matches!(event, Event::CardPlayed { uid: 1, .. }))
                    .count(),
                1,
                "one public CardPlayed for the whole series"
            );
            assert!(
                !card_in_any_pile(&state, 1),
                "spent={spent}: a Power routes RemoveBottom"
            );
            assert_removed_uid_carries_no_state(&state);
        }
    }

    /// #3135 witness 4: Signal Boost and Glam are independent GeneratePlayCount
    /// terms, so a fresh Glam Power under Signal Boost runs `1 + 1 + 1` bodies
    /// and consumes exactly one Signal Boost stack.
    #[test]
    fn glam_power_stacks_with_signal_boost_to_three_bodies() {
        let catalog = glam_power_catalog();
        for stacks in [1, 2] {
            let mut state = glam_power_state(&catalog, false);
            state
                .powers
                .set(PowerId::SignalBoost, SlotWire::Int, stacks);
            reset_test_body_starts();
            play_card(&mut state, &catalog, 1, None, None, &mut Vec::new()).unwrap();
            for index in 0..3 {
                assert!(test_body_started(1, index), "stacks={stacks} body {index}");
            }
            assert!(!test_body_started(1, 3));
            assert_eq!(state.powers.value(PowerId::Plating), 18);
            assert_eq!(state.powers.value(PowerId::SignalBoost), stacks - 1);
            assert_removed_uid_carries_no_state(&state);
            assert!(!card_in_any_pile(&state, 1));
        }
    }

    /// #3135 witness 5: the `enchantment_replay` clause of the Throwing Axe
    /// Power guard. Physical BaseReplayCount alone is the admitted generic
    /// witness; the same card with Glam on top is an enchantment replay and
    /// refuses atomically. A Glam Power is the first reachable input here.
    #[test]
    fn glam_power_under_throwing_axe_refuses_while_base_replay_admits() {
        let catalog = glam_power_catalog();
        let plain = identity(CardId::StoneArmor, 1);
        for glam in [false, true] {
            let mut state = glam_power_state(&catalog, false);
            if !glam {
                state.piles.get_mut(PileId::Hand).make_mut()[0].atom =
                    catalog.atom(&plain).unwrap();
            }
            let mut physical = state.card_states.get(1);
            physical.set_base_replay_count(Some(1)).unwrap();
            state.card_states.set(1, physical);
            state.piles.get_mut(PileId::Hand).make_mut()[0].flags |=
                CARD_FLAG_DEFAULT_PHYSICAL_STATE;
            state.fanouts.set_throwing_axe_available(true);
            let before = state.clone();
            let result = play_card(&mut state, &catalog, 1, None, None, &mut Vec::new());
            if glam {
                assert_eq!(result, Err(EngineRefusal::ContinuationNotModeled));
                assert_eq!(state, before);
            } else {
                assert_eq!(result, Ok(()));
                assert!(!state.fanouts.throwing_axe_available());
            }
        }
    }

    /// #3135 witness 6: Glam is not an Echo Form Power-replay witness. Only
    /// BaseReplayCount, Signal Boost, or the Accelerant/Necro Mastery rows
    /// admit Echo on a Power, so Echo plus a Glam Power stays refused.
    #[test]
    fn glam_power_under_echo_form_stays_refused_without_signal_boost() {
        let catalog = glam_power_catalog();
        let mut state = glam_power_state(&catalog, false);
        state.powers.set(PowerId::EchoForm, SlotWire::Int, 1);
        let before = state.clone();
        assert_eq!(
            play_card(&mut state, &catalog, 1, None, None, &mut Vec::new()),
            Err(EngineRefusal::ContinuationNotModeled)
        );
        assert_eq!(state, before);

        state.powers.set(PowerId::SignalBoost, SlotWire::Int, 1);
        reset_test_body_starts();
        play_card(&mut state, &catalog, 1, None, None, &mut Vec::new()).unwrap();
        assert!(test_body_started(1, 3) && !test_body_started(1, 4));
        assert_eq!(state.powers.value(PowerId::Plating), 24);
    }

    fn plain_power_state(catalog: &Catalog) -> HotState {
        let mut state = state_with_card(catalog, identity(CardId::StoneArmor, 1), 1);
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 60));
        state
    }

    /// #3197: Echo Form and Throwing Axe replay an ordinary Power body. Neither
    /// `ModifyCardPlayCount` reads the card type (`0xa1f0c`, `0x9c7bf`) and the
    /// `OnPlayWrapper` body loop (`0x31b8d0`) is type-blind outside its VFX
    /// branch, so each adds one serial body and they add independently. The
    /// Axe is consumed; Echo's amount is a threshold, not a stack.
    #[test]
    fn echo_form_and_throwing_axe_replay_a_plain_power_body() {
        let catalog = glam_power_catalog();
        for (echo, axe, bodies) in [(true, false, 2_u8), (false, true, 2), (true, true, 3)] {
            let mut state = plain_power_state(&catalog);
            if echo {
                state.powers.set(PowerId::EchoForm, SlotWire::Int, 1);
            }
            state.fanouts.set_throwing_axe_available(axe);
            reset_test_body_starts();
            let mut events = Vec::new();
            play_card(&mut state, &catalog, 1, None, None, &mut events).unwrap();
            for index in 0..bodies {
                assert!(
                    test_body_started(1, index),
                    "echo={echo} axe={axe} body {index}"
                );
            }
            assert!(!test_body_started(1, bodies), "echo={echo} axe={axe}");
            assert_eq!(state.powers.value(PowerId::Plating), 6 * i32::from(bodies));
            assert_eq!(state.history.card_plays_finished_combat, i32::from(bodies));
            assert_eq!(state.history.plays_this_turn, 1);
            assert_eq!(state.powers.value(PowerId::EchoForm), i32::from(echo));
            assert!(!state.fanouts.throwing_axe_available());
            assert_eq!(
                events
                    .iter()
                    .filter(|event| matches!(event, Event::CardPlayed { uid: 1, .. }))
                    .count(),
                1,
                "one public CardPlayed for the whole series"
            );
            assert_removed_uid_carries_no_state(&state);
        }

        // Echo's threshold is spent by an earlier play this turn: one body.
        let mut state = plain_power_state(&catalog);
        state.powers.set(PowerId::EchoForm, SlotWire::Int, 1);
        state.history.plays_this_turn = 1;
        reset_test_body_starts();
        play_card(&mut state, &catalog, 1, None, None, &mut Vec::new()).unwrap();
        assert!(test_body_started(1, 0) && !test_body_started(1, 1));
        assert_eq!(state.powers.value(PowerId::Plating), 6);
    }

    /// #3197: a Throwing Axe series is one public action. Body 0 publishes
    /// its Plating Apply before body 1's checked write overflows, so the
    /// whole action (spend, source motion, Axe consumption, history, events)
    /// rolls back. The same holds under Echo.
    #[test]
    fn throwing_axe_or_echo_power_replay_overflow_rolls_back_the_action() {
        let catalog = glam_power_catalog();
        // #3208: Duplication is the same consumed GeneratePlayCount source.
        for (echo, axe, duplication) in [(false, true, 0), (true, false, 0), (false, false, 1)] {
            let mut state = plain_power_state(&catalog);
            state
                .powers
                .set(PowerId::Plating, SlotWire::Int, i32::MAX - 6);
            if echo {
                state.powers.set(PowerId::EchoForm, SlotWire::Int, 1);
            }
            state.fanouts.set_throwing_axe_available(axe);
            assert!(state.fanouts.set_duplication(duplication));
            hydrate_side_end_order(&mut state);
            let before = state.clone();
            let mut events = Vec::new();
            let result = play_card(&mut state, &catalog, 1, None, None, &mut events);
            assert!(
                matches!(result, Err(EngineRefusal::CounterOverflow(_))),
                "echo={echo} axe={axe} duplication={duplication}: {result:?}"
            );
            assert_eq!(
                state, before,
                "echo={echo} axe={axe} duplication={duplication}"
            );
            assert!(
                events.is_empty(),
                "echo={echo} axe={axe} duplication={duplication}"
            );
        }
    }

    /// #3197: the CardPlay frame an Echo/Axe-replayed Power parks is the
    /// ordinary two-body frame. Parked at either play index, it resumes hot
    /// and, after a canonical boundary round trip, cold, to the same state.
    #[test]
    fn persisted_replayed_plain_power_frame_round_trips_and_resumes() {
        let catalog = glam_power_catalog();
        let atom = catalog.atom(&identity(CardId::StoneArmor, 1)).unwrap();
        for (play_index, plating) in [(0_u32, 12), (1, 6)] {
            let mut parked = plain_power_state(&catalog);
            let card = parked.piles.get_mut(PileId::Hand).make_mut().remove(0);
            assert_eq!(card.atom, atom);
            parked.piles.get_mut(PileId::Play).make_mut().push(card);
            let mut record = finished_driver_record(1);
            record.stage = CardPlayStage::StartBody;
            record.latch_kind = CardPlayLatchKind::Empty;
            record.next_step = 0;
            record.result_route = CardResultRoute::RemoveBottom;
            record.plays = 2;
            record.play_index = play_index;
            parked.frames.push_card_play(&record).unwrap();

            let document = crate::boundary::HotBoundary::to_canonical(&parked, &catalog);
            let mut cold =
                crate::boundary::HotBoundary::from_canonical(&document, &catalog).unwrap();
            assert_eq!(cold, parked, "play index {play_index}: boundary round trip");

            let mut hot = parked;
            drive_until_depth(&mut hot, &catalog, &mut Vec::new(), 0).unwrap();
            drive_until_depth(&mut cold, &catalog, &mut Vec::new(), 0).unwrap();
            assert_eq!(cold, hot, "play index {play_index}: cold resume");
            assert!(hot.frames.is_empty());
            assert_eq!(hot.powers.value(PowerId::Plating), plating);
            assert_removed_uid_carries_no_state(&hot);
        }
    }

    /// #3197: an inline AutoPlay child's no-result Draw beneath its parent's
    /// persisted CardPlay (Havoc flipping Battle Trance). With no reachable
    /// suspending Draw hook the Draw cannot park, so it is the frameless
    /// command Draw and leaves the parent frame untouched. With Stratagem
    /// reachable the Draw could park, and the foreign owner still refuses.
    #[test]
    fn inline_autoplay_child_draw_beneath_a_foreign_cardplay_frame() {
        let havoc = identity(CardId::Havoc, 0);
        let trance = identity(CardId::BattleTrance, 1);
        let strike = identity(CardId::StrikeIronclad, 0);
        for stratagem in [false, true] {
            let mut builder = CatalogBuilder::new();
            for identity in [havoc, trance, strike] {
                builder.intern(identity).unwrap();
            }
            if stratagem {
                builder
                    .intern_reachable(identity(CardId::Stratagem, 0))
                    .unwrap();
            }
            let catalog = builder.build();
            assert_eq!(catalog.cardplay_draw_hook_can_suspend(), stratagem);
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
            state.next_card_uid = 10;
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 60));
            let card = |uid, identity: CardIdentity| HotCard {
                uid,
                atom: catalog.atom(&identity).unwrap(),
                flags: 0,
            };
            state
                .piles
                .get_mut(PileId::Play)
                .make_mut()
                .extend([card(1, havoc), card(2, trance)]);
            state
                .piles
                .get_mut(PileId::Draw)
                .make_mut()
                .extend((3..8).map(|uid| card(uid, strike)));
            let mut parent = crate::hot::CardPlayRecord::pending_for_test(1);
            parent.pending_choice = false;
            parent.selection_kind = None;
            parent.next_step = 1;
            assert_eq!(parent.stage, CardPlayStage::Body);
            state.frames.push_card_play(&parent).unwrap();
            let frames_before = state.frames.clone();
            let before = state.clone();

            let spec = *catalog.spec(catalog.atom(&trance).unwrap()).unwrap();
            let mut events = Vec::new();
            let mut ctx = StepCtx {
                state: &mut state,
                catalog: &catalog,
                spec: &spec,
                source_uid: 2,
                target: None,
                selection: None,
                x_value: 0,
                args: &[],
                events: &mut events,
            };
            let result = draw_cardplay_no_result(&mut ctx, 4);
            if stratagem {
                assert_eq!(result, Err(EngineRefusal::ContinuationNotModeled));
                assert_eq!(state, before);
            } else {
                assert_eq!(result, Ok(()));
                assert_eq!(
                    state
                        .piles
                        .get(PileId::Hand)
                        .as_slice()
                        .iter()
                        .map(|card| card.uid)
                        .collect::<Vec<_>>(),
                    vec![3, 4, 5, 6]
                );
                assert_eq!(state.piles.get(PileId::Draw).len(), 1);
                assert_eq!(state.frames, frames_before, "the parent frame is untouched");
            }
        }
    }

    /// #3135 witnesses 2 (timing) and 8: a persisted CardPlay frame for a
    /// Glam Power. Stepping the frame shows the spent bit is written only
    /// when body 0's AfterNormalHook stage completes, before body 1 starts
    /// (the second `spend_glam` site); `glam_snapshot_is_exact` admits the
    /// frame at play index 0 fresh and at play index 1 spent, refuses the two
    /// crossed states, and both resume to the straight-line end state.
    #[test]
    fn persisted_glam_power_frame_spends_between_bodies_and_resumes_exactly() {
        let catalog = glam_power_catalog();
        let atom = catalog.atom(&glam_stone_armor_plus()).unwrap();
        let parked = |play_index: u32, spent: bool| {
            let mut state = glam_power_state(&catalog, spent);
            let card = state.piles.get_mut(PileId::Hand).make_mut().remove(0);
            assert_eq!(card.atom, atom);
            state.piles.get_mut(PileId::Play).make_mut().push(card);
            let mut record = finished_driver_record(1);
            record.stage = CardPlayStage::StartBody;
            record.latch_kind = CardPlayLatchKind::Empty;
            record.next_step = 0;
            record.result_route = CardResultRoute::RemoveBottom;
            record.plays = 2;
            record.play_index = play_index;
            record.glam = 1;
            state.frames.push_card_play(&record).unwrap();
            state
        };
        let play_index_of = |state: &HotState| match state.frames.top() {
            Some(crate::frame::Frame::CardPlay { record }) => {
                Some(state.frames.card_play(record).unwrap().play_index)
            }
            _ => None,
        };

        // Stage-by-stage from body 0: fresh throughout body 0, spent on entry
        // to body 1, spent at the end.
        let mut state = parked(0, false);
        let active = PersistedActivePlayGuard::enter(&state).unwrap();
        let mut saw_body_one = false;
        for _ in 0..64 {
            let Some(index) = play_index_of(&state) else {
                break;
            };
            assert_eq!(
                state.card_states.get(1).enchantment_state.get(),
                (index > 0).then_some(1),
                "play index {index}"
            );
            saw_body_one |= index == 1;
            advance_top_card_play_one(&mut state, &catalog, &mut Vec::new(), &active).unwrap();
        }
        drop(active);
        assert!(saw_body_one);
        assert!(state.frames.is_empty());
        assert_eq!(state.powers.value(PowerId::Plating), 12);
        assert_removed_uid_carries_no_state(&state);
        assert!(!card_in_any_pile(&state, 1));

        for (play_index, spent, admitted, plating) in [
            (0, false, true, 12),
            (1, true, true, 6),
            (1, false, false, 0),
            (0, true, false, 0),
        ] {
            let mut state = parked(play_index, spent);
            let result = drive_until_depth(&mut state, &catalog, &mut Vec::new(), 0);
            if admitted {
                assert!(result.is_ok(), "{play_index}/{spent}: {result:?}");
                assert!(state.frames.is_empty());
                assert_eq!(state.powers.value(PowerId::Plating), plating);
                assert_removed_uid_carries_no_state(&state);
                assert!(!card_in_any_pile(&state, 1));
            } else {
                assert_eq!(
                    result,
                    Err(EngineRefusal::ContinuationNotModeled),
                    "{play_index}/{spent}"
                );
            }
        }
    }

    #[test]
    fn glam_havoc_nested_parent_round_trips_fresh_and_spent_then_resumes() {
        let havoc = CardIdentity {
            id: CardId::Havoc,
            upgrade: 0,
            enchantment: Some(crate::catalog::CardEnchantment {
                id: EnchantmentId::Glam,
                amount: 1,
            }),
        };
        let armaments = identity(CardId::Armaments, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        for identity in [havoc, armaments, strike] {
            builder.intern_reachable(identity).unwrap();
        }
        for identity in [
            identity(CardId::Havoc, 1),
            identity(CardId::Armaments, 1),
            identity(CardId::StrikeIronclad, 1),
        ] {
            builder.intern(identity).unwrap();
        }
        let catalog = builder.build();
        assert!(catalog.requires_action_replay());
        for already_spent in [false, true] {
            let source = HotCard {
                uid: 1,
                atom: catalog.atom(&havoc).unwrap(),
                flags: if already_spent {
                    CARD_FLAG_DEFAULT_PHYSICAL_STATE
                } else {
                    0
                },
            };
            let mut state = HotState::at_defaults();
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            state.hp = 50;
            state.energy = 1;
            state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
            state.next_card_uid = 5;
            state.exact_piles = true;
            state.piles.get_mut(PileId::Hand).make_mut().extend([
                source,
                HotCard {
                    uid: 3,
                    atom: catalog.atom(&strike).unwrap(),
                    flags: 0,
                },
                HotCard {
                    uid: 4,
                    atom: catalog.atom(&strike).unwrap(),
                    flags: 0,
                },
            ]);
            state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
                uid: 2,
                atom: catalog.atom(&armaments).unwrap(),
                flags: 0,
            });
            if already_spent {
                let mut replay = state.card_states.get(1);
                replay.enchantment_state =
                    crate::hot::OptionalNonNegativeI32::from_option(Some(1)).unwrap();
                replay.set_base_replay_count(Some(1)).unwrap();
                state.card_states.set(1, replay);
            }

            let parked = crate::engine::apply_action_into(
                &state,
                &catalog,
                &crate::engine::Action::Play {
                    uid: 1,
                    target: None,
                    selection: crate::engine::SelectionRef::NONE,
                },
                &mut Vec::new(),
            )
            .unwrap();
            assert!(parked.pending.is_some());
            assert_eq!(
                parked.card_states.get(1).enchantment_state.get(),
                already_spent.then_some(1)
            );
            let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
            assert_eq!(
                wire.piles.get("play").unwrap()[0].enchantment,
                Some(if already_spent {
                    serde_json::json!(["GLAM_USED", 1])
                } else {
                    serde_json::json!(["GLAM", 1])
                })
            );
            let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
            let reloaded = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
            crate::engine::admit(&wire, &reloaded, &rebuilt_catalog).unwrap();
            let choice = crate::engine::legal_actions(&reloaded, &rebuilt_catalog)[0];
            let finished = crate::engine::apply_action_into(
                &reloaded,
                &rebuilt_catalog,
                &choice,
                &mut Vec::new(),
            )
            .unwrap();
            assert!(finished.pending.is_none());
            assert!(finished.frames.is_empty());
            assert_eq!(finished.history.card_plays_finished_combat, 3);
            assert_eq!(finished.history.owner_cards_exhausted_combat, 1);
            assert_eq!(finished.card_states.get(1).enchantment_state.get(), Some(1));
            let [routed] = finished.piles.get(PileId::Discard).as_slice() else {
                panic!("Glam Havoc routes exactly once");
            };
            assert_eq!(routed.uid, source.uid);
            assert_eq!(rebuilt_catalog.spec(routed.atom).unwrap().identity, havoc);
        }
    }

    fn synchronous_play_action(uid: u32, target: Option<u8>) -> crate::engine::Action {
        crate::engine::Action::Play {
            uid,
            target,
            selection: crate::engine::SelectionRef::NONE,
        }
    }

    #[test]
    fn havoc_gathers_top_draw_and_forces_the_child_to_exhaust() {
        let havoc = identity(CardId::Havoc, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(havoc).unwrap();
        builder.intern(strike).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, havoc, 1);
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 30));
        state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
            uid: 2,
            atom: catalog.atom(&strike).unwrap(),
            flags: 0,
        });

        let next = crate::engine::apply_action_into(
            &state,
            &catalog,
            &synchronous_play_action(1, None),
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(next.monsters[0].hp, 24);
        assert!(next.piles.get(PileId::Draw).is_empty());
        assert_eq!(next.piles.get(PileId::Exhaust).as_slice()[0].uid, 2);
        assert_eq!(next.piles.get(PileId::Discard).as_slice()[0].uid, 1);
    }

    /// A forced Exhaust never reaches a Power's result location (#2484).
    ///
    /// `CardModel::GetResultLocationForCardPlay` RVA `0x7e018` returns
    /// Remove/Bottom on `Type == 3` at IL_001d, before it reads
    /// `get_ExhaustOnNextPlay` at IL_002b; Python's
    /// `_resolve_card_play_result_location` (frozen Python, deleted #2827) tests
    /// `spec.is_power` first for the same reason. Rust's route gated the Power
    /// arm on `!force_exhaust`, so Havoc flipping a Power put it in Exhaust —
    /// visible in the real-fight census as a Stone Armor that exists in Rust's
    /// Exhaust pile and nowhere in Python's document, plus the two exhaust
    /// counters it drags along.
    #[test]
    fn havoc_leaves_a_flipped_power_removed_rather_than_exhausted() {
        let havoc = identity(CardId::Havoc, 0);
        let armor = identity(CardId::StoneArmor, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(havoc).unwrap();
        builder.intern(armor).unwrap();
        let catalog = builder.build();
        assert!(
            catalog
                .spec(catalog.atom(&armor).unwrap())
                .unwrap()
                .is_power,
            "the fixture card must be a Power for this to test anything"
        );
        let mut state = state_with_card(&catalog, havoc, 1);
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 30));
        state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
            uid: 2,
            atom: catalog.atom(&armor).unwrap(),
            flags: 0,
        });

        let next = crate::engine::apply_action_into(
            &state,
            &catalog,
            &synchronous_play_action(1, None),
            &mut Vec::new(),
        )
        .unwrap();

        assert!(next.piles.get(PileId::Draw).is_empty());
        assert!(
            next.piles.get(PileId::Exhaust).is_empty(),
            "a Power routes to Remove even under Havoc's forced Exhaust"
        );
        for pile in [PileId::Hand, PileId::Draw, PileId::Play] {
            assert!(
                next.piles
                    .get(pile)
                    .as_slice()
                    .iter()
                    .all(|card| card.uid != 2),
                "the removed Power must leave every live pile ({pile:?})"
            );
        }
        assert_eq!(next.piles.get(PileId::Discard).as_slice()[0].uid, 1);
        assert_eq!(
            next.piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .filter(|card| card.uid == 2)
                .count(),
            0
        );
        assert!(
            !next.history.owner_card_exhausted_this_turn,
            "no Exhaust happened, so neither derived counter may move"
        );
        assert_eq!(next.history.owner_cards_exhausted_combat, 0);
    }

    #[test]
    fn eidolon_purity_exhaust_child_parks_roundtrips_and_routes_once() {
        let eidolon = identity(CardId::Eidolon, 0);
        let purity = identity(CardId::Purity, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        for card_identity in [eidolon, purity, strike] {
            builder.intern_reachable(card_identity).unwrap();
            builder
                .intern(identity(card_identity.id, 1))
                .unwrap_or_else(|error| panic!("upgrade row must intern: {error:?}"));
        }
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, eidolon, 1);
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        let purity_card = HotCard {
            uid: 2,
            atom: catalog.atom(&purity).unwrap(),
            flags: 0,
        };
        state
            .piles
            .get_mut(PileId::Exhaust)
            .make_mut()
            .push(purity_card);
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 3,
            atom: catalog.atom(&strike).unwrap(),
            flags: 0,
        });
        state.next_card_uid = 4;

        let start = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&start).unwrap();
        let state = HotBoundary::from_canonical(&start, &catalog).unwrap();
        crate::engine::admit(&start, &state, &catalog).unwrap();
        let play = crate::engine::legal_actions(&state, &catalog)
            .into_iter()
            .find(|action| matches!(action, crate::engine::Action::Play { uid: 1, .. }))
            .expect("the admitted Eidolon publishes its public Play");
        let parked =
            crate::engine::apply_action_into(&state, &catalog, &play, &mut Vec::new()).unwrap();
        assert!(parked.pending.is_some());
        assert_eq!(
            restricted_frozen_auto_batch_stack_is_exact(&parked, &catalog),
            Ok(())
        );

        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let batch = wire
            .continuations
            .iter()
            .find(|frame| matches!(frame.frame_type.as_str(), "FrozenAutoBatchFrame"))
            .expect("Eidolon persists its frozen Exhaust batch");
        assert_eq!(
            batch.fields.get("source"),
            Some(&serde_json::json!("Eidolon"))
        );
        assert_eq!(
            batch.fields.get("force_exhaust"),
            Some(&serde_json::json!(true))
        );
        assert_eq!(
            batch.fields["entries"][0]["uid"],
            serde_json::json!(purity_card.uid)
        );
        let child = wire
            .continuations
            .iter()
            .rev()
            .find(|frame| matches!(frame.frame_type.as_str(), "CardPlayFrame"))
            .expect("the selecting Purity child owns the pending choice");
        assert_eq!(
            child.fields.get("source"),
            Some(&serde_json::json!("Eidolon"))
        );
        assert_eq!(
            child.fields.get("result_location"),
            Some(&serde_json::json!(["exhaust", "bottom"]))
        );

        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let imported = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        crate::engine::admit(&wire, &imported, &rebuilt_catalog).unwrap();

        let before_bad = imported.clone();
        let mut bad_events = Vec::new();
        let events_before = bad_events.clone();
        assert!(
            crate::engine::apply_action_with_replay_witness(
                &imported,
                &rebuilt_catalog,
                &crate::engine::Action::Select {
                    answer: crate::engine::SelectionAnswer::CardUid(99),
                },
                &mut bad_events,
            )
            .is_err()
        );
        assert_eq!(imported, before_bad);
        assert_eq!(bad_events, events_before);

        for (label, field, value) in [
            ("batch source", "source", serde_json::json!("Beat Down")),
            ("batch route", "force_exhaust", serde_json::json!(false)),
        ] {
            let mut malformed = wire.clone();
            let batch = malformed
                .continuations
                .iter_mut()
                .find(|frame| matches!(frame.frame_type.as_str(), "FrozenAutoBatchFrame"))
                .unwrap();
            batch.fields.insert(field.to_owned(), value);
            assert!(
                HotBoundary::from_canonical(&malformed, &rebuilt_catalog).is_err(),
                "the wire rejects forged Eidolon {label}"
            );
        }

        let legal = crate::engine::legal_actions(&imported, &rebuilt_catalog);
        assert_eq!(
            legal,
            [
                crate::engine::Action::Select {
                    answer: crate::engine::SelectionAnswer::OptionIndex(0),
                },
                crate::engine::Action::Select {
                    answer: crate::engine::SelectionAnswer::OptionIndex(1),
                },
            ]
        );
        let select = legal
            .into_iter()
            .find(|action| {
                matches!(
                    action,
                    crate::engine::Action::Select {
                        answer: crate::engine::SelectionAnswer::OptionIndex(1)
                    }
                )
            })
            .expect("Purity exposes its exact Hand choice");
        let completed =
            crate::engine::apply_action_into(&imported, &rebuilt_catalog, &select, &mut Vec::new())
                .unwrap();
        assert!(completed.pending.is_none());
        assert!(completed.frames.is_empty());
        assert_eq!(completed.history.card_plays_finished_combat, 2);
        let routed: Vec<_> = completed
            .piles
            .get(PileId::Exhaust)
            .as_slice()
            .iter()
            .filter(|card| card.uid == purity_card.uid)
            .collect();
        assert_eq!(routed.len(), 1, "the frozen child routes exactly once");
        assert_eq!(
            rebuilt_catalog.spec(routed[0].atom).unwrap().identity,
            purity
        );
        assert!(
            completed
                .piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .any(|card| card.uid == 3),
            "Purity's selected Hand card exhausts exactly"
        );
    }

    #[test]
    fn havoc_armaments_l0_selecting_child_parks_roundtrips_and_force_exhausts() {
        let havoc = identity(CardId::Havoc, 0);
        let armaments = identity(CardId::Armaments, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let strike_plus = identity(CardId::StrikeIronclad, 1);
        let mut builder = CatalogBuilder::new();
        for identity in [havoc, armaments, strike] {
            builder.intern_reachable(identity).unwrap();
        }
        builder.intern(strike_plus).unwrap();
        builder.intern(identity(CardId::Armaments, 1)).unwrap();
        builder.intern(identity(CardId::Havoc, 1)).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, havoc, 1);
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
            uid: 2,
            atom: catalog.atom(&armaments).unwrap(),
            flags: 0,
        });
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 3,
            atom: catalog.atom(&strike).unwrap(),
            flags: 0,
        });
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 4,
            atom: catalog.atom(&strike).unwrap(),
            flags: 0,
        });
        state.next_card_uid = 5;
        let start_document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&start_document).unwrap();
        let state = HotBoundary::from_canonical(&start_document, &catalog).unwrap();
        crate::engine::admit(&start_document, &state, &catalog).unwrap();
        let before = state.clone();
        let mut events = Vec::new();
        for power in [
            PowerId::Burst,
            PowerId::EchoForm,
            PowerId::Rebound,
            PowerId::Nostalgia,
            PowerId::Corruption,
        ] {
            let mut replaying_parent = state.clone();
            let wire = if power == PowerId::Corruption {
                SlotWire::Bool
            } else {
                SlotWire::Int
            };
            replaying_parent.powers.set(power, wire, 1);
            if matches!(
                power,
                PowerId::Rebound | PowerId::Nostalgia | PowerId::Corruption
            ) {
                assert!(
                    replaying_parent
                        .fanouts
                        .register_result_location_power(power)
                );
            }
            assert_eq!(replaying_parent.powers.value(power), 1);
            let replaying_document =
                HotBoundary::try_to_canonical(&replaying_parent, &catalog).unwrap();
            crate::engine::admit(&replaying_document, &replaying_parent, &catalog)
                .unwrap_or_else(|error| panic!("ActionReplay must close {power:?}: {error:?}"));
        }
        let play = crate::engine::legal_actions(&state, &catalog)
            .iter()
            .find(|action| matches!(action, crate::engine::Action::Play { uid: 1, .. }))
            .copied()
            .expect("the admitted Havoc start advertises its public Play action");
        let parked =
            crate::engine::apply_action_into(&state, &catalog, &play, &mut events).unwrap();
        assert_eq!(state, before);
        assert!(parked.pending.is_some());
        assert_eq!(
            restricted_frozen_auto_batch_stack_is_exact(&parked, &catalog),
            Ok(())
        );
        let parked_document = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let imported = HotBoundary::from_canonical(&parked_document, &catalog).unwrap();
        crate::engine::admit(&parked_document, &imported, &catalog).unwrap();
        let mut second_parent = imported.clone();
        second_parent
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(HotCard {
                uid: 5,
                atom: catalog.atom(&havoc).unwrap(),
                flags: 0,
            });
        second_parent.next_card_uid = 6;
        let second_parent_document =
            HotBoundary::try_to_canonical(&second_parent, &catalog).unwrap();
        assert!(
            crate::engine::admit(&second_parent_document, &second_parent, &catalog)
                .unwrap_err()
                .contains(crate::engine::admission::MissingCapability::ContinuationFrame),
            "an exact active carrier cannot smuggle a second future Havoc parent"
        );
        for power in [PowerId::Burst, PowerId::Rebound] {
            let mut future_hazard = imported.clone();
            future_hazard.powers.set(power, SlotWire::Int, 1);
            let future_hazard_document =
                HotBoundary::try_to_canonical(&future_hazard, &catalog).unwrap();
            assert!(
                crate::engine::admit(&future_hazard_document, &future_hazard, &catalog)
                    .unwrap_err()
                    .contains(crate::engine::admission::MissingCapability::ContinuationFrame),
                "an active carrier cannot erase future {power:?} trajectory drift"
            );
        }
        let selection = crate::engine::legal_actions(&imported, &catalog)
            .iter()
            .find(|action| matches!(action, crate::engine::Action::Select { .. }))
            .copied()
            .unwrap();
        let completed = crate::engine::apply_action(&imported, &catalog, &selection)
            .unwrap()
            .state;
        assert!(completed.pending.is_none());
        assert!(completed.frames.is_empty());
        let completed_document = HotBoundary::try_to_canonical(&completed, &catalog).unwrap();
        crate::engine::admit(&completed_document, &completed, &catalog).unwrap();
        assert!(
            completed
                .piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .any(|card| card.uid == 2)
        );
    }

    #[test]
    fn action_replay_import_authenticates_zero_answer_havoc_publicly() {
        let havoc = identity(CardId::Havoc, 0);
        let armaments = identity(CardId::Armaments, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        for identity in [havoc, armaments, strike, defend] {
            builder.intern_reachable(identity).unwrap();
        }
        for identity in [
            identity(CardId::Havoc, 1),
            identity(CardId::Armaments, 1),
            identity(CardId::StrikeIronclad, 1),
            identity(CardId::DefendIronclad, 1),
        ] {
            builder.intern(identity).unwrap();
        }
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, havoc, 1);
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
            uid: 2,
            atom: catalog.atom(&armaments).unwrap(),
            flags: 0,
        });
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 3,
                atom: catalog.atom(&strike).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 4,
                atom: catalog.atom(&strike).unwrap(),
                flags: 0,
            },
        ]);
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 5,
            atom: catalog.atom(&defend).unwrap(),
            flags: 0,
        });
        state.next_card_uid = 6;
        let start_document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&start_document).unwrap();
        let state = HotBoundary::from_canonical(&start_document, &catalog).unwrap();
        let action = crate::engine::legal_actions(&state, &catalog)
            .into_iter()
            .find(|action| matches!(action, crate::engine::Action::Play { uid: 1, .. }))
            .unwrap();
        let public = crate::engine::apply_action(&state, &catalog, &action)
            .unwrap()
            .state;
        assert!(matches!(
            public.frames.as_slice().first(),
            Some(crate::frame::Frame::ActionReplay { .. })
        ));
        let mut events = Vec::new();
        let parked =
            crate::engine::apply_action_with_replay_witness(&state, &catalog, &action, &mut events)
                .unwrap();
        assert!(matches!(
            parked.frames.as_slice(),
            [crate::frame::Frame::ActionReplay { .. }, _, _, _]
        ));
        let crate::frame::Frame::ActionReplay { record } = parked.frames.as_slice()[0] else {
            unreachable!()
        };
        assert!(
            parked
                .frames
                .action_replay(record)
                .unwrap()
                .answers
                .is_empty()
        );

        let document = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        assert_eq!(rebuilt_catalog, catalog);
        let imported = HotBoundary::from_canonical(&document, &rebuilt_catalog).unwrap();
        assert_eq!(imported, parked);
        crate::engine::admit(&document, &imported, &rebuilt_catalog).unwrap();
        let select = crate::engine::legal_actions(&imported, &rebuilt_catalog)[0];
        let public_completed = crate::engine::apply_action(&imported, &rebuilt_catalog, &select)
            .unwrap()
            .state;
        let completed = crate::engine::apply_action_with_replay_witness(
            &imported,
            &rebuilt_catalog,
            &select,
            &mut events,
        )
        .unwrap();
        assert_eq!(public_completed, completed);
        assert!(completed.pending.is_none());
        assert!(completed.frames.is_empty());

        for (label, mutation) in [
            ("batch cursor", (2_usize, "cursor", serde_json::json!(2))),
            ("parent X", (1_usize, "x_value", serde_json::json!(1))),
            (
                "child source",
                (3_usize, "source", serde_json::json!("Sly discard")),
            ),
            (
                "child force route",
                (3_usize, "force_exhaust", serde_json::json!(false)),
            ),
            (
                "parent result route",
                (
                    1_usize,
                    "result_location",
                    serde_json::json!(["exhaust", "bottom"]),
                ),
            ),
            (
                "parent target",
                (1_usize, "target_identity", serde_json::json!([0, 0, null])),
            ),
        ] {
            let mut malformed = document.clone();
            malformed.continuations[mutation.0]
                .fields
                .insert(mutation.1.to_owned(), mutation.2);
            assert!(
                HotBoundary::from_canonical(&malformed, &rebuilt_catalog).is_err(),
                "rooted replay rejects correlated {label} drift"
            );
        }
        let mut latch_drift = document.clone();
        let latch = latch_drift.continuations[1]
            .fields
            .get_mut("latch")
            .unwrap()
            .as_array_mut()
            .expect("the parked parent publishes its exact raw latch");
        latch[0] = serde_json::json!(latch[0].as_i64().unwrap_or(0) + 1);
        assert!(
            HotBoundary::from_canonical(&latch_drift, &rebuilt_catalog).is_err(),
            "the replay receipt cannot authenticate a correlated parent latch mutation"
        );

        let mut correlated = document.clone();
        let energy = correlated
            .player
            .get("energy")
            .and_then(serde_json::Value::as_i64)
            .unwrap_or(0);
        correlated
            .player
            .insert("energy".to_owned(), serde_json::json!(energy + 1));
        assert!(HotBoundary::from_canonical(&correlated, &rebuilt_catalog).is_err());

        let mut illegal_root = document.clone();
        illegal_root.continuations[0].fields.insert(
            "action".to_owned(),
            serde_json::json!({
                "kind": "play",
                "uid": 999,
                "target": null,
                "selection_uid": null,
            }),
        );
        assert!(HotBoundary::from_canonical(&illegal_root, &rebuilt_catalog).is_err());

        let mut early_drain = document.clone();
        early_drain.continuations[0].fields.insert(
            "action".to_owned(),
            serde_json::json!({
                "kind": "play",
                "uid": 5,
                "target": null,
                "selection_uid": null,
            }),
        );
        assert!(HotBoundary::from_canonical(&early_drain, &rebuilt_catalog).is_err());

        let mut recursive = document.clone();
        recursive.continuations[0]
            .fields
            .get_mut("predecessor")
            .and_then(serde_json::Value::as_object_mut)
            .unwrap()
            .insert(
                "continuations".to_owned(),
                serde_json::json!([{
                    "type": "JossSideEndFrame",
                    "fields": {"tag": "joss_side_end"},
                }]),
            );
        assert!(HotBoundary::catalog_from_canonical(&recursive).is_err());

        let mut source_moved = document.clone();
        let parent = source_moved.piles.get_mut("play").unwrap().remove(0);
        source_moved
            .piles
            .entry("exhaust".to_owned())
            .or_default()
            .push(parent);
        assert_eq!(
            HotBoundary::catalog_from_canonical(&source_moved).unwrap(),
            rebuilt_catalog,
            "origin catalog authority survives current source movement"
        );
        assert!(
            HotBoundary::from_canonical(&source_moved, &rebuilt_catalog).is_err(),
            "the predecessor still authenticates the complete current state"
        );

        let mut mismatched_catalog = rebuilt_catalog.clone();
        mismatched_catalog
            .spec_mut_for_test(catalog.atom(&havoc).unwrap())
            .unwrap()
            .cost += 1;
        assert!(HotBoundary::from_canonical(&document, &mismatched_catalog).is_err());
    }

    #[test]
    fn action_replay_typed_sly_answer_is_exact_and_mutations_refuse() {
        let hidden_daggers = identity(CardId::HiddenDaggers, 0);
        let purity = identity(CardId::Purity, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        for identity in [hidden_daggers, purity, defend, identity(CardId::Shiv, 0)] {
            builder.intern_reachable(identity).unwrap();
        }
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.hp = 50;
        state.max_hp = 50;
        state.energy = 3;
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.next_card_uid = 5;
        state.powers.set(PowerId::MasterPlanner, SlotWire::Int, 1);
        hydrate_after_card_played_power_order_for_test(&mut state);
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 1,
                atom: catalog.atom(&hidden_daggers).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 2,
                atom: catalog.atom(&purity).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 3,
                atom: catalog.atom(&defend).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 4,
                atom: catalog.atom(&defend).unwrap(),
                flags: 0,
            },
        ]);
        state.card_states.set_local_sly(2);
        let start_document = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&start_document).unwrap();
        let state = HotBoundary::from_canonical(&start_document, &catalog).unwrap();
        let root = crate::engine::Action::Play {
            uid: 1,
            target: None,
            selection: crate::engine::SelectionRef::NONE,
        };
        let mut events = Vec::new();
        let parent =
            crate::engine::apply_action_with_replay_witness(&state, &catalog, &root, &mut events)
                .unwrap();
        let parked = crate::engine::legal_actions(&parent, &catalog)
            .into_iter()
            .filter_map(|answer| {
                crate::engine::apply_action_with_replay_witness(
                    &parent,
                    &catalog,
                    &answer,
                    &mut Vec::new(),
                )
                .ok()
            })
            .find(|candidate| restricted_frozen_batch_pending(candidate, &catalog).is_some())
            .expect("one exact Hidden Daggers answer starts the local-Sly child batch");
        let document = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&document).unwrap();
        let imported = HotBoundary::from_canonical(&document, &rebuilt_catalog).unwrap();
        let crate::frame::Frame::ActionReplay { record } = imported.frames.as_slice()[0] else {
            unreachable!()
        };
        assert_eq!(
            imported.frames.action_replay(record).unwrap().answers.len(),
            1
        );
        crate::engine::admit(&document, &imported, &rebuilt_catalog).unwrap();

        let mut mutations = Vec::new();
        let mut missing = document.clone();
        missing.continuations[0]
            .fields
            .insert("answers".to_owned(), serde_json::json!([]));
        mutations.push(missing);
        let mut wrong_value = document.clone();
        wrong_value.continuations[0].fields.insert(
            "answers".to_owned(),
            serde_json::json!([{"kind": "option_index", "value": 999}]),
        );
        mutations.push(wrong_value);
        let mut wrong_type = document.clone();
        wrong_type.continuations[0].fields.insert(
            "answers".to_owned(),
            serde_json::json!([{"kind": "card_uid", "value": 2}]),
        );
        mutations.push(wrong_type);
        let valid_answer = document.continuations[0].fields["answers"][0].clone();
        let mut extra = document.clone();
        extra.continuations[0].fields.insert(
            "answers".to_owned(),
            serde_json::json!([valid_answer.clone(), valid_answer.clone()]),
        );
        mutations.push(extra);
        let mut reordered = document.clone();
        reordered.continuations[0].fields.insert(
            "answers".to_owned(),
            serde_json::json!([
                {"kind": "option_index", "value": 999},
                valid_answer,
            ]),
        );
        mutations.push(reordered);
        for mutation in mutations {
            let mutation_catalog = HotBoundary::catalog_from_canonical(&mutation).unwrap();
            assert!(HotBoundary::from_canonical(&mutation, &mutation_catalog).is_err());
        }

        let mut plural_start = state.clone();
        plural_start.card_states.set_local_sly(3);
        let plural_hand = plural_start.piles.get_mut(PileId::Hand).make_mut();
        plural_hand
            .iter_mut()
            .find(|card| card.uid == 2)
            .unwrap()
            .atom = catalog.atom(&defend).unwrap();
        plural_hand
            .iter_mut()
            .find(|card| card.uid == 3)
            .unwrap()
            .atom = catalog.atom(&purity).unwrap();
        let plural_parent = crate::engine::apply_action_with_replay_witness(
            &plural_start,
            &catalog,
            &root,
            &mut Vec::new(),
        )
        .unwrap();
        let plural_parked = crate::engine::legal_actions(&plural_parent, &catalog)
            .into_iter()
            .filter_map(|answer| {
                crate::engine::apply_action_with_replay_witness(
                    &plural_parent,
                    &catalog,
                    &answer,
                    &mut Vec::new(),
                )
                .ok()
            })
            .find(|candidate| {
                candidate.pending.is_some()
                    && candidate.frames.as_slice().iter().any(|frame| {
                        let crate::frame::Frame::FrozenAutoBatch { record } = *frame else {
                            return false;
                        };
                        candidate
                            .frames
                            .frozen_auto_batch(record)
                            .is_some_and(|batch| batch.len() == 2)
                    })
            })
            .expect("the private driver parks the plural Sly batch");
        let mut captured_batch = plural_parked
            .frames
            .as_slice()
            .iter()
            .find_map(|frame| {
                let crate::frame::Frame::FrozenAutoBatch { record } = *frame else {
                    return None;
                };
                Some(plural_parked.frames.frozen_auto_batch(record)?.to_owned())
            })
            .unwrap();
        captured_batch.cursor = 1;
        let missing_entry = captured_batch.entries[1].clone();

        let missing_answer = crate::engine::legal_actions(&plural_parked, &catalog)[0];
        let mut missing_successor = plural_parked.clone();
        for pile in PileId::ALL {
            missing_successor
                .piles
                .get_mut(pile)
                .make_mut()
                .retain(|card| card.uid != missing_entry.card.uid);
        }
        let missing_before = missing_successor.clone();
        let mut missing_events = vec![Event::TurnBegan { turn: 91 }];
        assert_eq!(
            crate::engine::apply_action_with_replay_witness(
                &missing_successor,
                &catalog,
                &missing_answer,
                &mut missing_events,
            ),
            Err(EngineRefusal::ContinuationNotModeled),
            "a missing later Sly sibling refuses the complete replay transition"
        );
        assert_eq!(missing_successor, missing_before);
        assert!(
            missing_events.is_empty(),
            "refusal rolls back emitted events"
        );

        let mut missing_sly = plural_parked.clone();
        missing_sly.pending = None;
        missing_sly.frames = crate::hot::Frames::new();
        missing_sly
            .frames
            .push_frozen_auto_batch(&captured_batch)
            .unwrap();
        for pile in PileId::ALL {
            missing_sly
                .piles
                .get_mut(pile)
                .make_mut()
                .retain(|card| card.uid != missing_entry.card.uid);
        }
        assert_eq!(
            advance_top_replay_frozen_auto_batch_one(&mut missing_sly, &catalog, &mut Vec::new(),),
            Err(EngineRefusal::ContinuationNotModeled),
            "a missing Sly sibling never falls back to its captured payload"
        );

        let mut missing_draw = plural_parked.clone();
        missing_draw.pending = None;
        missing_draw.frames = crate::hot::Frames::new();
        captured_batch.source = crate::hot::FrozenAutoBatchSource::DrawPileFlip;
        missing_draw
            .frames
            .push_frozen_auto_batch(&captured_batch)
            .unwrap();
        for pile in PileId::ALL {
            missing_draw
                .piles
                .get_mut(pile)
                .make_mut()
                .retain(|card| card.uid != missing_entry.card.uid);
        }
        advance_top_replay_frozen_auto_batch_one(&mut missing_draw, &catalog, &mut Vec::new())
            .unwrap();
        assert_eq!(
            missing_draw
                .pending
                .as_deref()
                .map(|pending| pending.frame_uid),
            Some(missing_entry.card.uid)
        );
        assert!(
            missing_draw
                .piles
                .get(PileId::Play)
                .as_slice()
                .contains(&missing_entry.card)
        );
        assert_eq!(
            missing_draw.card_states.get_ref(missing_entry.card.uid),
            Some(&missing_entry.state)
        );

        let batch_only = |source| {
            let mut state = plural_parked.clone();
            state.pending = None;
            state.frames = crate::hot::Frames::new();
            let mut batch = captured_batch.clone();
            batch.source = source;
            state.frames.push_frozen_auto_batch(&batch).unwrap();
            state
        };
        let mut recurring = batch_only(crate::hot::FrozenAutoBatchSource::DrawPileFlip);
        let recurring_before = recurring.clone();
        let mut recurring_events = vec![Event::TurnBegan { turn: 92 }];
        let recurring_events_before = recurring_events.clone();
        let recurring_uid = captured_batch.entries[1].card.uid;
        let recurring_result = with_test_active_play(recurring_uid, || {
            advance_top_replay_frozen_auto_batch_one(
                &mut recurring,
                &catalog,
                &mut recurring_events,
            )
        });
        assert_eq!(
            recurring_result,
            Err(EngineRefusal::ContinuationNotModeled),
            "a batch cannot recursively reactivate its already-active physical uid"
        );
        assert_eq!(recurring, recurring_before);
        assert_eq!(recurring_events, recurring_events_before);

        let mut terminal_draw = batch_only(crate::hot::FrozenAutoBatchSource::DrawPileFlip);
        terminal_draw.history.over = true;
        let terminal_draw_piles = terminal_draw.piles.clone();
        advance_top_replay_frozen_auto_batch_one(&mut terminal_draw, &catalog, &mut Vec::new())
            .unwrap();
        assert_eq!(terminal_draw.piles, terminal_draw_piles);
        let crate::frame::Frame::FrozenAutoBatch { record } = terminal_draw.frames.top().unwrap()
        else {
            panic!("draw terminal retains the precommitted batch until its next drive")
        };
        assert_eq!(
            terminal_draw
                .frames
                .frozen_auto_batch(record)
                .unwrap()
                .cursor,
            2
        );

        let mut terminal_sly = batch_only(crate::hot::FrozenAutoBatchSource::SlyDiscard);
        terminal_sly.history.over = true;
        advance_top_replay_frozen_auto_batch_one(&mut terminal_sly, &catalog, &mut Vec::new())
            .unwrap();
        assert!(terminal_sly.frames.is_empty());

        for source in [
            crate::hot::FrozenAutoBatchSource::DrawPileFlip,
            crate::hot::FrozenAutoBatchSource::SlyDiscard,
        ] {
            let mut dead = batch_only(source);
            dead.hp = 0;
            advance_top_replay_frozen_auto_batch_one(&mut dead, &catalog, &mut Vec::new()).unwrap();
            assert!(dead.frames.is_empty(), "player death pops {source:?}");
        }
    }

    #[test]
    fn action_replay_later_selecting_batch_child_parks_twice_and_reloads_publicly() {
        let cascade = identity(CardId::Cascade, 0);
        let armaments = identity(CardId::Armaments, 0);
        let apotheosis = identity(CardId::Apotheosis, 0);
        let true_grit = identity(CardId::TrueGrit, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        for identity in [cascade, armaments, apotheosis, true_grit, defend] {
            builder.intern_reachable(identity).unwrap();
        }
        for identity in [
            identity(CardId::Armaments, 1),
            identity(CardId::Apotheosis, 1),
            identity(CardId::TrueGrit, 1),
            identity(CardId::DefendIronclad, 1),
        ] {
            builder.intern(identity).unwrap();
        }
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, cascade, 1);
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.energy = 3;
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.piles.get_mut(PileId::Draw).make_mut().extend([
            HotCard {
                uid: 2,
                atom: catalog.atom(&armaments).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 3,
                atom: catalog.atom(&apotheosis).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 4,
                atom: catalog.atom(&true_grit).unwrap(),
                flags: 0,
            },
        ]);
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 5,
                atom: catalog.atom(&defend).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 6,
                atom: catalog.atom(&defend).unwrap(),
                flags: 0,
            },
        ]);
        state.next_card_uid = 7;
        let start = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&start).unwrap();
        let state = HotBoundary::from_canonical(&start, &catalog).unwrap();
        let mut events = vec![Event::TurnBegan { turn: 77 }];
        let action = crate::engine::legal_actions(&state, &catalog)
            .into_iter()
            .find(|action| matches!(action, crate::engine::Action::Play { uid: 1, .. }))
            .unwrap();
        let first =
            crate::engine::apply_action_with_replay_witness(&state, &catalog, &action, &mut events)
                .unwrap();
        assert_eq!(first.pending.as_deref().unwrap().frame_uid, 2);
        let crate::frame::Frame::ActionReplay { record } = first.frames.as_slice()[0] else {
            unreachable!()
        };
        let expected_root = first.frames.action_replay(record).unwrap();
        crate::engine::rehearse_pending_replay_tree(
            first.clone(),
            &catalog,
            &expected_root,
            &state,
        )
        .expect("the shared cold DFS carries the replay transcript through both parks");
        let first_document = HotBoundary::try_to_canonical(&first, &catalog).unwrap();
        let reloaded = HotBoundary::from_canonical(&first_document, &catalog).unwrap();
        crate::engine::admit(&first_document, &reloaded, &catalog).unwrap();
        let first_answer = crate::engine::legal_actions(&first, &catalog)[0];
        let mut proof_events = Vec::new();
        let second = crate::engine::apply_action_with_replay_witness(
            &first,
            &catalog,
            &first_answer,
            &mut proof_events,
        )
        .unwrap();
        assert_eq!(second.pending.as_deref().unwrap().frame_uid, 4);
        assert!(
            proof_events
                .iter()
                .any(|event| matches!(event, Event::CardPlayed { uid: 3, .. })),
            "the first answer really completes Armaments and plays Apotheosis before the later active-uid guard"
        );
        assert_eq!(
            second
                .piles
                .get(PileId::Play)
                .as_slice()
                .iter()
                .find(|card| card.uid == 4)
                .unwrap()
                .atom,
            catalog.atom(&identity(CardId::TrueGrit, 1)).unwrap(),
            "the earlier sibling mutates the later live child before it parks"
        );
        let first_before_recurring = first.clone();
        let mut recurring_events = Vec::new();
        let recurring_events_before = recurring_events.clone();
        assert_eq!(
            with_test_active_play(4, || {
                crate::engine::apply_action_with_replay_witness(
                    &first,
                    &catalog,
                    &first_answer,
                    &mut recurring_events,
                )
            }),
            Err(EngineRefusal::ContinuationNotModeled),
            "after Armaments resolves and Apotheosis mutates the later child, its already-active uid still refuses the whole transcript"
        );
        assert_eq!(first, first_before_recurring);
        assert_eq!(recurring_events, recurring_events_before);
        let crate::frame::Frame::ActionReplay { record } = second.frames.as_slice()[0] else {
            unreachable!()
        };
        assert_eq!(
            second.frames.action_replay(record).unwrap().answers.len(),
            1
        );
        let second_document = HotBoundary::try_to_canonical(&second, &catalog).unwrap();
        let reloaded = HotBoundary::from_canonical(&second_document, &catalog).unwrap();
        crate::engine::admit(&second_document, &reloaded, &catalog).unwrap();
        let second_answer = crate::engine::legal_actions(&second, &catalog)[0];
        let public_completed = crate::engine::apply_action(&second, &catalog, &second_answer)
            .unwrap()
            .state;
        let completed = crate::engine::apply_action_with_replay_witness(
            &second,
            &catalog,
            &second_answer,
            &mut events,
        )
        .unwrap();
        assert_eq!(public_completed, completed);
        assert!(completed.pending.is_none());
        assert!(completed.frames.is_empty());
    }

    #[test]
    fn action_replay_nested_cascade_havoc_parks_lifo_and_drains_once() {
        let cascade = identity(CardId::Cascade, 0);
        let havoc = identity(CardId::Havoc, 0);
        let armaments = identity(CardId::Armaments, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        for identity in [cascade, havoc, armaments, strike, defend] {
            builder.intern_reachable(identity).unwrap();
        }
        for identity in [
            identity(CardId::Armaments, 1),
            identity(CardId::StrikeIronclad, 1),
            identity(CardId::DefendIronclad, 1),
        ] {
            builder.intern(identity).unwrap();
        }
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, cascade, 1);
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.energy = 2;
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.piles.get_mut(PileId::Draw).make_mut().extend([
            HotCard {
                uid: 2,
                atom: catalog.atom(&havoc).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 3,
                atom: catalog.atom(&defend).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 4,
                atom: catalog.atom(&armaments).unwrap(),
                flags: 0,
            },
        ]);
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 5,
                atom: catalog.atom(&defend).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 6,
                atom: catalog.atom(&defend).unwrap(),
                flags: 0,
            },
        ]);
        state.next_card_uid = 7;
        let action = crate::engine::Action::Play {
            uid: 1,
            target: None,
            selection: crate::engine::SelectionRef::NONE,
        };
        let mut events = Vec::new();
        let parked =
            crate::engine::apply_action_with_replay_witness(&state, &catalog, &action, &mut events)
                .unwrap();
        assert_eq!(parked.pending.as_deref().unwrap().frame_uid, 4);
        assert_eq!(parked.frames.len(), 6);
        let card_uids: Vec<_> = parked
            .frames
            .as_slice()
            .iter()
            .filter_map(|frame| match *frame {
                crate::frame::Frame::CardPlay { record } => {
                    parked.frames.card_play(record).map(|play| play.uid)
                }
                _ => None,
            })
            .collect();
        assert_eq!(card_uids, vec![1, 2, 4]);
        let answer = crate::engine::legal_actions(&parked, &catalog)[0];
        let completed = crate::engine::apply_action_with_replay_witness(
            &parked,
            &catalog,
            &answer,
            &mut events,
        )
        .unwrap();
        assert!(completed.pending.is_none());
        assert!(completed.frames.is_empty());
        assert!(
            completed
                .piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .any(|card| card.uid == 4),
            "Havoc force-exhausts its nested selecting child exactly once"
        );
    }

    #[test]
    fn action_replay_calculated_gamble_and_scrape_own_selecting_sly_batches() {
        let purity = identity(CardId::Purity, 0);
        let defend = identity(CardId::DefendSilent, 0);

        for level in [0, 1] {
            let mut gamble_builder = CatalogBuilder::new();
            for identity in [identity(CardId::CalculatedGamble, level), purity, defend] {
                gamble_builder.intern_reachable(identity).unwrap();
            }
            let gamble_catalog = gamble_builder.build();
            let mut gamble = state_with_card(
                &gamble_catalog,
                identity(CardId::CalculatedGamble, level),
                1,
            );
            gamble.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            gamble.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
            gamble.piles.get_mut(PileId::Hand).make_mut().extend([
                HotCard {
                    uid: 2,
                    atom: gamble_catalog.atom(&purity).unwrap(),
                    flags: 0,
                },
                HotCard {
                    uid: 3,
                    atom: gamble_catalog.atom(&defend).unwrap(),
                    flags: 0,
                },
            ]);
            gamble.piles.get_mut(PileId::Draw).make_mut().extend([
                HotCard {
                    uid: 4,
                    atom: gamble_catalog.atom(&defend).unwrap(),
                    flags: 0,
                },
                HotCard {
                    uid: 5,
                    atom: gamble_catalog.atom(&defend).unwrap(),
                    flags: 0,
                },
            ]);
            gamble.card_states.set_local_sly(2);
            gamble.next_card_uid = 6;
            let root = crate::engine::Action::Play {
                uid: 1,
                target: None,
                selection: crate::engine::SelectionRef::NONE,
            };
            let public_gamble = crate::engine::apply_action(&gamble, &gamble_catalog, &root)
                .unwrap()
                .state;
            assert_eq!(public_gamble.pending.as_deref().unwrap().frame_uid, 2);
            assert!(matches!(
                public_gamble.frames.as_slice().first(),
                Some(crate::frame::Frame::ActionReplay { .. })
            ));
            let gamble_parked = crate::engine::apply_action_with_replay_witness(
                &gamble,
                &gamble_catalog,
                &root,
                &mut Vec::new(),
            )
            .unwrap();
            assert_eq!(gamble_parked.pending.as_deref().unwrap().frame_uid, 2);
            assert!(matches!(
                gamble_parked.frames.as_slice(),
                [
                    crate::frame::Frame::ActionReplay { .. },
                    crate::frame::Frame::CardPlay { .. },
                    crate::frame::Frame::FrozenAutoBatch { .. },
                    crate::frame::Frame::CardPlay { .. }
                ]
            ));
            let answer = crate::engine::legal_actions(&gamble_parked, &gamble_catalog)[0];
            let gamble_completed = crate::engine::apply_action_with_replay_witness(
                &gamble_parked,
                &gamble_catalog,
                &answer,
                &mut Vec::new(),
            )
            .unwrap();
            assert!(gamble_completed.pending.is_none());
            assert!(gamble_completed.frames.is_empty());
        }
        let scrape = identity(CardId::Scrape, 0);
        let mut scrape_builder = CatalogBuilder::new();
        for identity in [scrape, purity, defend] {
            scrape_builder.intern_reachable(identity).unwrap();
        }
        scrape_builder
            .intern_monster(MonsterKind::Toadpole)
            .unwrap();
        scrape_builder.intern_monster(MonsterKind::Axebot).unwrap();
        let scrape_catalog = scrape_builder.build();
        let mut scrape_state = state_with_card(&scrape_catalog, scrape, 1);
        scrape_state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        scrape_state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 50));
        scrape_state
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .extend((2..=5).map(|uid| {
                HotCard {
                    uid,
                    atom: scrape_catalog
                        .atom(&if uid == 2 { purity } else { defend })
                        .unwrap(),
                    // The cost row below lives in slot 7 (#3629).
                    flags: if uid == 2 {
                        CARD_FLAG_DEFAULT_PHYSICAL_STATE
                    } else {
                        0
                    },
                }
            }));
        scrape_state.card_states.set_local_sly(2);
        scrape_state.card_states.append_local_cost_modifier(
            2,
            LocalCostModifier {
                kind: LocalCostModifierKind::Set,
                amount: 1,
                expiration: LocalCostExpiration::ThisTurnOrPlayed,
                reduce_only: false,
            },
        );
        scrape_state
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(HotCard {
                uid: 6,
                atom: scrape_catalog.atom(&defend).unwrap(),
                flags: 0,
            });
        scrape_state.next_card_uid = 7;
        let scrape_root = crate::engine::Action::Play {
            uid: 1,
            target: Some(0),
            selection: crate::engine::SelectionRef::NONE,
        };
        let public_scrape =
            crate::engine::apply_action(&scrape_state, &scrape_catalog, &scrape_root)
                .unwrap()
                .state;
        assert_eq!(public_scrape.pending.as_deref().unwrap().frame_uid, 2);
        let scrape_parked = crate::engine::apply_action_with_replay_witness(
            &scrape_state,
            &scrape_catalog,
            &scrape_root,
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(scrape_parked.pending.as_deref().unwrap().frame_uid, 2);
        let answer = crate::engine::legal_actions(&scrape_parked, &scrape_catalog)[0];
        let mut replaced_target = scrape_parked.clone();
        replaced_target.monsters_mut()[0].hp = 0;
        replaced_target.monsters_mut()[0].uid = 99;
        let replacement_before = replaced_target.clone();
        let mut replacement_events = Vec::new();
        let replacement_events_before = replacement_events.clone();
        assert_eq!(
            crate::engine::apply_action_with_replay_witness(
                &replaced_target,
                &scrape_catalog,
                &answer,
                &mut replacement_events,
            ),
            Err(EngineRefusal::ContinuationNotModeled),
            "a lethal replacement in Scrape's persisted target slot cannot inherit the parent's awaited suffix"
        );
        assert_eq!(replaced_target, replacement_before);
        assert_eq!(replacement_events, replacement_events_before);
        let scrape_completed = crate::engine::apply_action_with_replay_witness(
            &scrape_parked,
            &scrape_catalog,
            &answer,
            &mut Vec::new(),
        )
        .unwrap();
        assert!(scrape_completed.pending.is_none());
        assert!(scrape_completed.frames.is_empty());

        let mut lethal_stock = state_with_card(&scrape_catalog, scrape, 1);
        lethal_stock.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        let mut axebot = HotMonster::new(MonsterKind::Axebot, 1);
        axebot.max_hp = 76;
        axebot.powers.set(PowerId::Stock, SlotWire::Int, 2);
        lethal_stock.monsters_mut().push(axebot);
        lethal_stock
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .extend((2..=5).map(|uid| {
                HotCard {
                    uid,
                    atom: scrape_catalog
                        .atom(&if uid == 2 { purity } else { defend })
                        .unwrap(),
                    flags: 0,
                }
            }));
        lethal_stock.card_states.set_local_sly(2);
        lethal_stock.card_states.append_local_cost_modifier(
            2,
            LocalCostModifier {
                kind: LocalCostModifierKind::Set,
                amount: 1,
                expiration: LocalCostExpiration::ThisTurnOrPlayed,
                reduce_only: false,
            },
        );
        lethal_stock
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .push(HotCard {
                uid: 6,
                atom: scrape_catalog.atom(&defend).unwrap(),
                flags: 0,
            });
        lethal_stock.next_card_uid = 7;
        let lethal_before = lethal_stock.clone();
        let mut lethal_events = Vec::new();
        assert_eq!(
            crate::engine::apply_action_with_replay_witness(
                &lethal_stock,
                &scrape_catalog,
                &scrape_root,
                &mut lethal_events,
            ),
            Err(EngineRefusal::ContinuationNotModeled),
            "Scrape's real lethal hit replaces Stock uid 0 before its Sly child parks, so the stale targeted parent refuses atomically"
        );
        assert_eq!(lethal_stock, lethal_before);
        assert!(lethal_events.is_empty());
    }

    #[test]
    fn scrape_result_draw_survives_a_selecting_hellraiser_child_once() {
        let scrape = identity(CardId::Scrape, 0);
        let seeker = identity(CardId::SeekerStrike, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let zero = identity(CardId::Zap, 1);
        let x = identity(CardId::Tempest, 0);
        let mut builder = CatalogBuilder::new();
        for card in [scrape, seeker, defend, zero, x] {
            builder.intern_reachable(card).unwrap();
        }
        builder.mark_live_hellraiser_reachable();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, scrape, 1);
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.exact_piles = true;
        state.powers.set(PowerId::Hellraiser, SlotWire::Int, 1);
        state.rng.set(
            RngStream::Sel,
            RngStreamState {
                words: [1, 2, 3, 4],
                counter: 0,
            },
        );
        state
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .extend((2..=7).map(|uid| {
                HotCard {
                    uid,
                    atom: catalog
                        .atom(&match uid {
                            2 => zero,
                            3 => x,
                            4 => seeker,
                            _ => defend,
                        })
                        .unwrap(),
                    flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
                }
            }));
        state.next_card_uid = 8;
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 100);
        monster.max_hp = 100;
        state.monsters_mut().push(monster);
        hydrate_side_end_order(&mut state);

        let root = synchronous_play_action(1, Some(0));
        let parked = crate::engine::apply_action(&state, &catalog, &root)
            .unwrap()
            .state;
        assert_eq!(parked.pending.as_deref().unwrap().frame_uid, 4);
        assert!(matches!(
            parked.frames.as_slice(),
            [
                crate::frame::Frame::ActionReplay { .. },
                crate::frame::Frame::CardPlay { .. },
                crate::frame::Frame::Draw { .. },
                crate::frame::Frame::CardPlay { .. },
            ]
        ));
        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let mut wrong_requested = wire.clone();
        wrong_requested.continuations[2]
            .fields
            .insert("requested".to_owned(), serde_json::json!(3));
        let mut duplicate_prefix = wire.clone();
        let authentic_prefix = wire.continuations[2].fields["drawn"]
            .as_array()
            .unwrap()
            .clone();
        assert_eq!(authentic_prefix.len(), 3);
        let mut duplicate = authentic_prefix.clone();
        duplicate[1] = duplicate[0].clone();
        duplicate_prefix.continuations[2]
            .fields
            .insert("drawn".to_owned(), serde_json::Value::Array(duplicate));
        let mut reordered_prefix = wire.clone();
        let mut reordered = authentic_prefix.clone();
        reordered.swap(0, 1);
        reordered_prefix.continuations[2]
            .fields
            .insert("drawn".to_owned(), serde_json::Value::Array(reordered));
        let mut dropped_prefix = wire.clone();
        let mut dropped = authentic_prefix.clone();
        dropped.remove(1);
        dropped_prefix.continuations[2]
            .fields
            .insert("drawn".to_owned(), serde_json::Value::Array(dropped));
        let mut payload_prefix = wire.clone();
        let mut payload = authentic_prefix.clone();
        payload[0][0] = serde_json::json!("payload");
        payload_prefix.continuations[2]
            .fields
            .insert("drawn".to_owned(), serde_json::Value::Array(payload));
        let mut wrong_caller = wire.clone();
        wrong_caller.continuations[2]
            .fields
            .insert("caller".to_owned(), serde_json::json!("pillage"));
        for forged in [
            wrong_requested,
            duplicate_prefix,
            reordered_prefix,
            dropped_prefix,
            payload_prefix,
            wrong_caller,
        ] {
            let forged_catalog = HotBoundary::catalog_from_canonical(&forged).unwrap();
            assert!(HotBoundary::from_canonical(&forged, &forged_catalog).is_err());
        }
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let rebuilt = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        crate::engine::admit(&wire, &rebuilt, &rebuilt_catalog).unwrap();
        let answer = crate::engine::legal_actions(&rebuilt, &rebuilt_catalog)[0];
        let completed = crate::engine::apply_action(&rebuilt, &rebuilt_catalog, &answer)
            .unwrap()
            .state;
        assert!(completed.pending.is_none() && completed.frames.is_empty());
        assert_eq!(completed.history.card_plays_finished_combat, 2);
        assert_eq!(
            completed
                .piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .filter_map(|card| matches!(card.uid, 2 | 3).then_some(card.uid))
                .collect::<Vec<_>>(),
            vec![3],
            "the cold owned Draw return applies Scrape's native nonzero-or-X predicate exactly once"
        );
        assert_eq!(completed.history.discarded_cards_this_turn, 3);
    }

    #[test]
    fn standalone_scrape_stratagem_reshuffle_is_action_replay_rooted() {
        let scrape = identity(CardId::Scrape, 0);
        let zero = identity(CardId::Zap, 1);
        let x = identity(CardId::Tempest, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        for card in [scrape, zero, x, defend] {
            builder.intern_reachable(card).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let no_hook = builder.clone().build();
        assert!(
            !no_hook.requires_action_replay(),
            "Scrape alone has no blocking Draw child"
        );
        builder.mark_live_stratagem_reachable();
        let catalog = builder.build();
        assert!(catalog.requires_action_replay());

        let mut state = state_with_card(&catalog, scrape, 1);
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.exact_piles = true;
        state.next_card_uid = 7;
        state.powers.set(PowerId::Stratagem, SlotWire::Int, 1);
        for (uid, card) in [(2, zero), (3, x), (4, defend), (5, defend)] {
            state
                .piles
                .get_mut(PileId::Discard)
                .make_mut()
                .push(HotCard {
                    uid,
                    atom: catalog.atom(&card).unwrap(),
                    flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
                });
        }
        state.rng.set(
            RngStream::Rng,
            RngStreamState {
                words: [1, 2, 3, 4],
                counter: 0,
            },
        );
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 100);
        monster.max_hp = 100;
        state.monsters_mut().push(monster);

        let root = synchronous_play_action(1, Some(0));
        let parked = crate::engine::apply_action(&state, &catalog, &root)
            .unwrap()
            .state;
        assert!(matches!(
            parked.frames.as_slice().first(),
            Some(crate::frame::Frame::ActionReplay { .. })
        ));
        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        assert!(rebuilt_catalog.requires_action_replay());
        let rebuilt = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        crate::engine::admit(&wire, &rebuilt, &rebuilt_catalog).unwrap();
        let answer = crate::engine::legal_actions(&rebuilt, &rebuilt_catalog)[0];
        let completed = crate::engine::apply_action(&rebuilt, &rebuilt_catalog, &answer)
            .unwrap()
            .state;
        assert!(completed.pending.is_none() && completed.frames.is_empty());
        assert_eq!(completed.history.discarded_cards_this_turn, 3);
        assert_eq!(
            completed
                .piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .filter(|card| matches!(card.uid, 2..=5))
                .count(),
            3,
            "the native nonzero-or-X Scrape result is discarded exactly once; the adjacent Hellraiser matrix pins the returned identities"
        );
        assert_eq!(completed.history.card_plays_finished_combat, 1);
    }

