        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, pact, 1);
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.exact_piles = true;
        state.powers.set(PowerId::DarkEmbrace, SlotWire::Int, 1);
        state.powers.set(PowerId::Hellraiser, SlotWire::Int, 1);
        assert!(
            state
                .fanouts
                .set_after_card_exhausted_order(&[PowerId::DarkEmbrace])
        );
        state.rng.set(
            RngStream::Sel,
            RngStreamState {
                words: [1, 2, 3, 4],
                counter: 0,
            },
        );
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 2,
            atom: catalog.atom(&defend).unwrap(),
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        });
        state.piles.get_mut(PileId::Draw).make_mut().extend([
            HotCard {
                uid: 3,
                atom: catalog.atom(&seeker).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 4,
                atom: catalog.atom(&defend).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 5,
                atom: catalog.atom(&defend).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 6,
                atom: catalog.atom(&defend).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
        ]);
        state.next_card_uid = 7;
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 100);
        monster.max_hp = 100;
        state.monsters_mut().push(monster);
        hydrate_side_end_order(&mut state);

        let root = crate::engine::Action::Play {
            uid: 1,
            target: None,
            selection: crate::engine::SelectionRef::new(Some(2)),
        };
        let parked = crate::engine::apply_action(&state, &catalog, &root)
            .unwrap()
            .state;
        assert_eq!(parked.pending.as_deref().unwrap().frame_uid, 3);
        assert!(matches!(
            parked.frames.as_slice(),
            [
                crate::frame::Frame::ActionReplay { .. },
                crate::frame::Frame::CardPlay { .. },
                crate::frame::Frame::AfterCardExhaustedPower { .. },
                crate::frame::Frame::Draw { .. },
                crate::frame::Frame::CardPlay { .. },
            ]
        ));
        let crate::frame::Frame::AfterCardExhaustedPower {
            record: owner_record,
        } = parked.frames.as_slice()[2]
        else {
            unreachable!()
        };
        assert_eq!(
            parked
                .frames
                .after_card_exhausted_power(owner_record)
                .unwrap()
                .return_kind,
            crate::hot::AfterCardExhaustedReturnKind::BurningPact
        );
        let crate::frame::Frame::Draw {
            record: draw_record,
        } = parked.frames.as_slice()[3]
        else {
            unreachable!()
        };
        assert_eq!(
            parked.frames.draw(draw_record).unwrap().caller,
            DrawCaller::AfterCardExhaustedPower
        );
        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let mut forged = wire.clone();
