    #[test]
    fn havoc_attack_child_generates_hive_dazed_before_forced_exhaust_routing() {
        let havoc = identity(CardId::Havoc, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let dazed = identity(CardId::Dazed, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Entomancer).unwrap();
        builder.intern(havoc).unwrap();
        builder.intern(strike).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, havoc, 5);
        add_entomancer(&mut state, 1);
        state.next_card_uid = 100;
        state.next_generated_hook_uid = 200;
        state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
            uid: 6,
            atom: catalog.atom(&strike).unwrap(),
            flags: 0,
        });
        let rng_before = state.rng.get(RngStream::Rng).counter;
        let mut events = Vec::new();

        let next = crate::engine::apply_action_into(
            &state,
            &catalog,
            &synchronous_play_action(5, None),
            &mut events,
        )
        .unwrap();

        assert_eq!(next.monsters[0].hp, 159);
        assert_eq!(next.rng.get(RngStream::Rng).counter, rng_before + 1);
        assert_eq!(next.next_card_uid, 101);
        assert_eq!(next.next_generated_hook_uid, 201);
        assert_eq!(next.piles.get(PileId::Draw).len(), 1);
        assert_eq!(next.piles.get(PileId::Draw).as_slice()[0].uid, 100);
        assert_eq!(
            next.piles.get(PileId::Draw).as_slice()[0].atom,
            catalog.atom(&dazed).unwrap()
        );
        assert_eq!(next.piles.get(PileId::Exhaust).as_slice()[0].uid, 6);
        let hive_entry = events
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Event::CardResolved {
                        uid: 100,
                        pile: PileId::Draw
                    }
                )
            })
            .unwrap();
        let child_exhaust = events
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Event::CardResolved {
                        uid: 6,
                        pile: PileId::Exhaust
                    }
                )
            })
            .unwrap();
        assert!(hive_entry < child_exhaust);
    }

