    #[test]
    fn uproar_hive_insertions_precede_attack_selection_and_stay_out_of_its_pool() {
        let uproar = identity(CardId::Uproar, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let strike_silent = identity(CardId::StrikeSilent, 0);
        let dazed = identity(CardId::Dazed, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Entomancer).unwrap();
        builder.intern(uproar).unwrap();
        builder.intern(strike).unwrap();
        builder.intern(strike_silent).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, uproar, 10);
        add_entomancer(&mut state, 1);
        state.next_card_uid = 100;
        state.next_generated_hook_uid = 200;
        state.piles.get_mut(PileId::Draw).make_mut().extend([
            HotCard {
                uid: 11,
                atom: catalog.atom(&strike).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 12,
                atom: catalog.atom(&strike_silent).unwrap(),
                flags: 0,
            },
        ]);
        let rng_before = state.rng.get(RngStream::Rng).counter;
        let mut events = Vec::new();

        let next = crate::engine::apply_action_into(
            &state,
            &catalog,
            &synchronous_play_action(10, Some(0)),
            &mut events,
        )
        .unwrap();

        assert_eq!(next.monsters[0].hp, 147);
        assert_eq!(next.rng.get(RngStream::Rng).counter, rng_before + 4);
        assert_eq!(next.next_card_uid, 103);
        assert_eq!(next.next_generated_hook_uid, 203);
        assert_eq!(
            next.piles
                .get(PileId::Draw)
                .as_slice()
                .iter()
                .filter(|card| card.atom == catalog.atom(&dazed).unwrap())
                .count(),
            3,
        );
        assert_eq!(
            next.piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .filter(|card| matches!(card.uid, 11 | 12))
                .count(),
            1,
            "exactly one original Attack is selected after the two Hive insertions",
        );
        assert_eq!(
            next.piles
                .get(PileId::Draw)
                .as_slice()
                .iter()
                .filter(|card| matches!(card.uid, 11 | 12))
                .count(),
            1,
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(
                    event,
                    Event::CardResolved {
                        uid: 100..=102,
                        pile: PileId::Draw
                    }
                ))
                .count(),
            3,
        );
        let first_hive = events
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Event::CardResolved {
                        uid: 100,
                        pile: PileId::Draw
                    }
                )
            })
            .unwrap();
        let second_hive = events
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Event::CardResolved {
                        uid: 101,
                        pile: PileId::Draw
                    }
                )
            })
            .unwrap();
        let selected_play = events
            .iter()
            .position(|event| matches!(event, Event::CardPlayed { uid: 11 | 12, .. }))
            .unwrap();
        let child_hive = events
            .iter()
            .position(|event| {
                matches!(
                    event,
                    Event::CardResolved {
                        uid: 102,
                        pile: PileId::Draw
                    }
                )
            })
            .unwrap();
        assert!(
            first_hive < second_hive && second_hive < selected_play && selected_play < child_hive
        );
    }

