    #[test]
    fn end_of_days_late_failure_is_atomic_for_manual_and_direct_autoplay() {
        let end = identity(CardId::EndOfDays, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(end).unwrap();
        let catalog = builder.build();

        for (manual, source_pile) in [(true, PileId::Hand), (false, PileId::Draw)] {
            let source = HotCard {
                uid: 70,
                atom,
                flags: 0,
            };
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.energy = 3;
            state.history.owner_card_plays_finished_this_turn = 4;
            state.powers.set(PowerId::SerpentForm, SlotWire::Int, 1);
            state.powers.set(PowerId::PaleBlueDot, SlotWire::Int, 1);
            hydrate_after_card_played_power_order_for_test(&mut state);
            state
                .powers
                .set(PowerId::DrawNextTurn, SlotWire::Int, i32::MAX);
            state.piles.get_mut(source_pile).make_mut().push(source);
            let mut first = HotMonster::new(MonsterKind::Toadpole, 100);
            first.uid = 41;
            let mut late = HotMonster::new(MonsterKind::Toadpole, 100);
            late.uid = 42;
            state.monsters_mut().extend([first, late]);
            let before = state.clone();
            let mut events = Vec::new();

            assert_eq!(
                play_card_with_work(
                    &mut state,
                    &catalog,
                    source.uid,
                    None,
                    None,
                    &mut events,
                    PlaySource {
                        pile: source_pile,
                        provenance: if manual {
                            PlayProvenance::Manual
                        } else {
                            PlayProvenance::Auto
                        },
                        force_exhaust: false,
                        frozen: (!manual).then_some(source),

                        allow_dead_target: false,
                    },
                ),
                Err(EngineRefusal::CounterOverflow("pale blue dot"))
            );
            assert_eq!(state, before, "state and every RNG stream roll back");
            assert!(events.is_empty());
        }

        let source = include_str!("play.rs");
        assert!(source.contains("CardId::EndOfDays => {\n            // #3209 class"));
        assert!(source.contains(
            "crate::steps::necrobinder_rare::preflight_end_of_days(state, catalog, uid, &spec)\n            })?"
        ));
        assert!(source.contains("| CardId::EndOfDays"));
    }

