    #[test]
    fn undeath_burst_and_echo_clone_each_body_and_late_series_failure_is_atomic() {
        let undeath = identity(CardId::Undeath, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(undeath).unwrap();
        let catalog = builder.build();
        for power in [PowerId::Burst, PowerId::EchoForm] {
            let source = HotCard {
                uid: 70,
                atom,
                flags: 0,
            };
            let mut state = HotState::at_defaults();
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            state.hp = 50;
            state.energy = 3;
            state.next_card_uid = 100;
            state.powers.set(power, SlotWire::Int, 1);
            hydrate_side_end_order(&mut state);
            state.piles.get_mut(PileId::Hand).make_mut().push(source);

            play_card(
                &mut state,
                &catalog,
                source.uid,
                None,
                None,
                &mut Vec::new(),
            )
            .unwrap();

            assert_eq!(state.block, 14);
            assert_eq!(state.history.owner_generated_cards_combat, 2);
            assert_eq!(state.next_generated_hook_uid, 2);
            assert_eq!(state.next_card_uid, 102);
            assert_eq!(
                state
                    .piles
                    .get(PileId::Discard)
                    .as_slice()
                    .iter()
                    .map(|card| card.uid)
                    .collect::<Vec<_>>(),
                [100, 101, 70]
            );
            assert_eq!(state.history.card_plays_finished_combat, 2);
            if power == PowerId::Burst {
                assert_eq!(state.powers.value(PowerId::Burst), 0);
            }
        }

        let source = HotCard {
            uid: 70,
            atom,
            flags: 0,
        };
        let mut state = HotState::at_defaults();
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.hp = 50;
        state.energy = 3;
        state.next_card_uid = u32::MAX - 1;
        state.powers.set(PowerId::Burst, SlotWire::Int, 1);
        hydrate_side_end_order(&mut state);
        state.piles.get_mut(PileId::Hand).make_mut().push(source);
        let before = state.clone();
        let mut events = Vec::new();

        assert_eq!(
            play_card(&mut state, &catalog, source.uid, None, None, &mut events),
            Err(EngineRefusal::CounterOverflow("next_card_uid"))
        );
        assert_eq!(state, before, "the first completed body also rolls back");
        assert!(events.is_empty());
    }

    #[test]
    fn catastrophe_direct_draw_apotheosis_excludes_and_routes_the_live_source() {
        let catastrophe = identity(CardId::Catastrophe, 0);
        let catastrophe_up = identity(CardId::Catastrophe, 1);
        let apotheosis = identity(CardId::Apotheosis, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(catastrophe).unwrap();
        builder.intern(apotheosis).unwrap();
        builder.intern_all_card_upgrade_closure().unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, catastrophe, 30);
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
            uid: 31,
            atom: catalog.atom(&apotheosis).unwrap(),
            flags: 0,
        });

        let mut events = Vec::new();
        let next = crate::engine::apply_action_into(
            &state,
            &catalog,
            &synchronous_play_action(30, None),
            &mut events,
        )
        .unwrap();

        assert!(next.piles.get(PileId::Draw).is_empty());
        assert_eq!(
            next.piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .find(|card| card.uid == 31)
                .map(|card| catalog.spec(card.atom).unwrap().identity),
            Some(apotheosis),
            "the direct-Draw source remains in Draw during its body, is excluded by uid, then exhausts"
        );
        assert_eq!(
            next.piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .find(|card| card.uid == 30)
                .map(|card| catalog.spec(card.atom).unwrap().identity),
            Some(catastrophe_up),
            "the inner pass upgrades the exact outer physical source and the live loop observes L1"
        );
        assert_eq!(next.history.card_plays_finished_combat, 2);
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, Event::CardPlayed { uid: 30 | 31, .. }))
                .count(),
            2
        );
    }

    #[test]
    fn storm_local_sly_apotheosis_upgrades_the_outer_but_keeps_its_frozen_suffix() {
        let storm = identity(CardId::StormOfSteel, 0);
        let storm_up = identity(CardId::StormOfSteel, 1);
        let apotheosis = identity(CardId::Apotheosis, 0);
        let shiv = identity(CardId::Shiv, 0);
        let mut builder = CatalogBuilder::new();
        for identity in [storm, apotheosis, shiv] {
            builder.intern(identity).unwrap();
        }
        builder.intern_all_card_upgrade_closure().unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, storm, 30);
        // A live enemy: with none, combat is ending and plural Shiv
        // creation is IsOverOrEnding-gated (`0x3bb20c` IL_0031).
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        state.next_card_uid = 32;
        state.powers.set(PowerId::MasterPlanner, SlotWire::Int, 1);
        hydrate_after_card_played_power_order_for_test(&mut state);
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 31,
            atom: catalog.atom(&apotheosis).unwrap(),
            flags: 0,
        });
        state.card_states.set_local_sly(31);

        let mut events = Vec::new();
        play_card(&mut state, &catalog, 30, None, None, &mut events).unwrap();

        assert_eq!(state.history.card_plays_finished_combat, 2);
        assert_eq!(
            state
                .piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .find(|card| card.uid == 31)
                .map(|card| catalog.spec(card.atom).unwrap().identity),
            Some(apotheosis),
            "Apotheosis excludes its own live uid and routes after its nested body"
        );
        assert_eq!(
            state
                .piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .find(|card| card.uid == 30)
                .map(|card| catalog.spec(card.atom).unwrap().identity),
            Some(storm_up),
            "the nested all-pile walk upgrades the exact active outer object"
        );
        let generated = state.piles.get(PileId::Hand).as_slice();
        assert_eq!(generated.len(), 1);
        assert_eq!(
            catalog.spec(generated[0].atom).unwrap().identity,
            shiv,
            "Storm L0 froze its one-card/L0-Shiv suffix before the awaited Sly child"
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, Event::CardPlayed { uid: 30 | 31, .. }))
                .count(),
            2
        );
    }

