    #[test]
    fn catastrophe_smog_lock_does_not_filter_the_live_keyword_pool() {
        let catastrophe = identity(CardId::Catastrophe, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(catastrophe).unwrap();
        builder.intern(defend).unwrap();
        builder.intern(strike).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, catastrophe, 35);
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::FuzzyWurmCrawler, 40));
        state.powers.set(PowerId::Smoggy, SlotWire::Int, 1);
        state.powers.set(PowerId::SmogLock, SlotWire::Bool, 1);
        hydrate_after_card_played_power_order_for_test(&mut state);
        state.rng.set(
            RngStream::Rng,
            RngStreamState {
                words: [
                    8_999_366_892_653_588_108,
                    16_478_790_771_768_674_216,
                    7_190_703_300_741_581_586,
                    11_205_253_249_702_154_886,
                ],
                counter: 0,
            },
        );
        let defend_atom = catalog.atom(&defend).unwrap();
        let strike_atom = catalog.atom(&strike).unwrap();
        state.piles.get_mut(PileId::Draw).make_mut().extend([
            HotCard {
                uid: 36,
                atom: defend_atom,
                flags: 0,
            },
            HotCard {
                uid: 37,
                atom: strike_atom,
                flags: 0,
            },
        ]);
        let rng_before = state.rng.get(RngStream::Rng).counter;
        let targets_before = state.rng.get(RngStream::Targets).counter;

        let spec = *catalog.spec(catalog.atom(&catastrophe).unwrap()).unwrap();
        let mut events = Vec::new();
        let mut ctx = StepCtx {
            state: &mut state,
            catalog: &catalog,
            spec: &spec,
            source_uid: 35,
            target: None,
            selection: None,
            x_value: 0,
            args: &[],
            events: &mut events,
        };
        catastrophe_live_auto_plays(&mut ctx, 2).unwrap();

        assert_eq!(state.rng.get(RngStream::Rng).counter, rng_before + 1);
        assert_eq!(
            state.rng.get(RngStream::Targets).counter,
            targets_before + 1
        );
        assert_eq!(
            state.block, 0,
            "Smog blocks the selected Skill only at AutoPlay"
        );
        assert_eq!(state.monsters[0].hp, 34);
        assert_eq!(state.history.card_plays_finished_combat, 1);
        assert_eq!(
            state
                .piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            vec![36, 37],
            "the preferred pool selects Defend first; Smog routes it, then Strike plays",
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event, Event::CardPlayed { uid: 36 | 37, .. }))
                .count(),
            1,
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| {
                    matches!(
                        event,
                        Event::CardResolved {
                            uid: 36 | 37,
                            pile: PileId::Discard,
                        }
                    )
                })
                .count(),
            2,
        );
    }

