    #[test]
    fn catastrophe_selecting_child_parks_roundtrips_and_resumes_live_owner_once() {
        let catastrophe = identity(CardId::Catastrophe, 0);
        let armaments = identity(CardId::Armaments, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        for card in [catastrophe, armaments, strike] {
            builder.intern_reachable(card).unwrap();
            builder.intern(identity(card.id, card.upgrade + 1)).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        assert!(catalog.requires_action_replay());
        let mut state = state_with_card(&catalog, catastrophe, 1);
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.exact_piles = true;
        state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
            uid: 2,
            atom: catalog.atom(&armaments).unwrap(),
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        });
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 3,
                atom: catalog.atom(&strike).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 4,
                atom: catalog.atom(&strike).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
        ]);
        state.next_card_uid = 5;
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 100);
        monster.max_hp = 100;
        state.monsters_mut().push(monster);

        let start = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&start).unwrap();
        let state = HotBoundary::from_canonical(&start, &catalog).unwrap();
        crate::engine::admit(&start, &state, &catalog).unwrap();
        let parked =
            crate::engine::apply_action(&state, &catalog, &synchronous_play_action(1, None))
                .unwrap()
                .state;
        assert_eq!(parked.pending.as_deref().unwrap().frame_uid, 2);
        assert!(matches!(
            parked.frames.as_slice(),
            [
                crate::frame::Frame::ActionReplay { .. },
                crate::frame::Frame::CardPlay { .. },
                crate::frame::Frame::LiveListener { .. },
                crate::frame::Frame::CardPlay { .. },
            ]
        ));

        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        assert_eq!(
            wire.continuations[2].fields["work_key"],
            "catastrophe_draw_cards"
        );
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let rebuilt = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        crate::engine::admit(&wire, &rebuilt, &rebuilt_catalog).unwrap();
        let answer = crate::engine::legal_actions(&rebuilt, &rebuilt_catalog)[0];
        let completed = crate::engine::apply_action(&rebuilt, &rebuilt_catalog, &answer)
            .unwrap()
            .state;
        assert!(completed.pending.is_none());
        assert!(completed.frames.is_empty());
        assert_eq!(completed.history.card_plays_finished_combat, 2);
        assert_eq!(
            completed
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .filter(|card| {
                    rebuilt_catalog.spec(card.atom).unwrap().identity
                        == identity(CardId::StrikeIronclad, 1)
                })
                .count(),
            1
        );
    }

    #[test]
    fn nested_beat_down_uproar_cardplay_draw_roundtrips_recursively() {
        let beat_down = identity(CardId::BeatDown, 0);
        let uproar = identity(CardId::Uproar, 0);
        let pommel = identity(CardId::PommelStrike, 0);
        let seeker = identity(CardId::SeekerStrike, 0);
        let defenses = [
            identity(CardId::DefendIronclad, 0),
            identity(CardId::DefendSilent, 0),
            identity(CardId::DefendDefect, 0),
        ];
        let mut builder = CatalogBuilder::new();
        for card in [beat_down, uproar, pommel, seeker]
            .into_iter()
            .chain(defenses)
        {
            builder.intern_reachable(card).unwrap();
            builder.intern(identity(card.id, card.upgrade + 1)).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        assert!(catalog.requires_action_replay());

        let mut state = state_with_card(&catalog, beat_down, 1);
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.exact_piles = true;
        state.powers.set(PowerId::Hellraiser, SlotWire::Int, 1);
        state
            .piles
            .get_mut(PileId::Discard)
            .make_mut()
            .push(HotCard {
                uid: 2,
                atom: catalog.atom(&uproar).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            });
        let seeker_card = HotCard {
            uid: 3,
            atom: catalog.atom(&seeker).unwrap(),
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        };
        let pommel_card = HotCard {
            uid: 4,
            atom: catalog.atom(&pommel).unwrap(),
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        };
        state.piles.get_mut(PileId::Draw).make_mut().extend([
            seeker_card,
            pommel_card,
            HotCard {
                uid: 5,
                atom: catalog.atom(&defenses[0]).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 6,
                atom: catalog.atom(&defenses[1]).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 7,
                atom: catalog.atom(&defenses[2]).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
        ]);
        state.next_card_uid = 8;
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 1_000);
        monster.max_hp = 1_000;
        state.monsters_mut().push(monster);

        let selected_seed = (0..10_000_u64)
            .find(|seed| {
                let mut probe = state.clone();
                let rng = Xoshiro256StarStar::from_seed(*seed);
                probe.rng.set(
                    RngStream::Rng,
                    RngStreamState {
                        words: rng.words,
                        counter: rng.counter,
                    },
                );
                shuffled_cards_by_identity(&probe, &catalog, &[seeker_card, pommel_card])
                    .is_ok_and(|(cards, _)| cards.first() == Some(&pommel_card))
            })
            .expect("one Uproar shuffle selects Pommel Strike");
        let rng = Xoshiro256StarStar::from_seed(selected_seed);
        state.rng.set(
            RngStream::Rng,
            RngStreamState {
                words: rng.words,
                counter: rng.counter,
            },
        );
        state.rng.set(
            RngStream::Sel,
            RngStreamState {
                words: [1, 2, 3, 4],
                counter: 0,
            },
        );

        hydrate_side_end_order(&mut state);
        let start = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&start).unwrap();
        let state = HotBoundary::from_canonical(&start, &catalog).unwrap();
        crate::engine::admit(&start, &state, &catalog).unwrap();
        let parked =
            crate::engine::apply_action(&state, &catalog, &synchronous_play_action(1, None))
                .unwrap()
                .state;
        assert_eq!(parked.pending.as_deref().unwrap().frame_uid, 3);
        assert!(matches!(
            parked.frames.as_slice(),
            [
                crate::frame::Frame::ActionReplay { .. },
                crate::frame::Frame::CardPlay { .. },
                crate::frame::Frame::FrozenAutoBatch { .. },
                crate::frame::Frame::CardPlay { .. },
                crate::frame::Frame::CardPlay { .. },
                crate::frame::Frame::Draw { .. },
                crate::frame::Frame::CardPlay { .. },
            ]
        ));
        let active_uids = parked
            .frames
            .as_slice()
            .iter()
            .filter_map(|frame| match *frame {
                crate::frame::Frame::CardPlay { record } => {
                    parked.frames.card_play(record).map(|play| play.uid)
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(active_uids, [1, 2, 4, 3]);

        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let mut wrong_requested = wire.clone();
        wrong_requested.continuations[5]
            .fields
            .insert("requested".to_owned(), serde_json::json!(2));
        let wrong_catalog = HotBoundary::catalog_from_canonical(&wrong_requested).unwrap();
        assert!(HotBoundary::from_canonical(&wrong_requested, &wrong_catalog).is_err());
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let rebuilt = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        crate::engine::admit(&wire, &rebuilt, &rebuilt_catalog).unwrap();
        let answer = crate::engine::legal_actions(&rebuilt, &rebuilt_catalog)[0];
        let completed = crate::engine::apply_action(&rebuilt, &rebuilt_catalog, &answer)
            .unwrap()
            .state;
        assert!(completed.pending.is_none());
        assert!(completed.frames.is_empty());
        assert_eq!(completed.history.card_plays_finished_combat, 4);
    }

    #[test]
    fn uproar_draw_reshuffle_stratagem_keeps_the_live_child_in_play() {
        let uproar = identity(CardId::Uproar, 0);
        let pommel = identity(CardId::PommelStrike, 1);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        for card in [uproar, pommel, defend] {
            builder.intern_reachable(card).unwrap();
        }
        builder.mark_live_stratagem_reachable();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        assert!(catalog.requires_action_replay());

        let mut state = state_with_card(&catalog, uproar, 0);
        state.max_hp = 50;
        state.energy = 3;
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.exact_piles = true;
        state.next_card_uid = 4;
        state.powers.set(PowerId::Stratagem, SlotWire::Int, 1);
        state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
            uid: 1,
            atom: catalog.atom(&pommel).unwrap(),
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        });
        state.piles.get_mut(PileId::Discard).make_mut().extend([
            HotCard {
                uid: 2,
                atom: catalog.atom(&defend).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 3,
                atom: catalog.atom(&defend).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
        ]);
        let rng = RngStreamState {
            words: [1, 2, 3, 4],
            counter: 0,
        };
        state.rng.set(RngStream::Rng, rng);
        state.rng.set(RngStream::Targets, rng);
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 50);
        monster.max_hp = 50;
        state.monsters_mut().push(monster);

        let start = HotBoundary::try_to_canonical(&state, &catalog).unwrap();
        let catalog = HotBoundary::catalog_from_canonical(&start).unwrap();
        let state = HotBoundary::from_canonical(&start, &catalog).unwrap();
        crate::engine::admit(&start, &state, &catalog).unwrap();
        let parked =
            crate::engine::apply_action(&state, &catalog, &synchronous_play_action(0, Some(0)))
                .unwrap()
                .state;
        assert!(parked.pending.is_some());
        assert!(parked.piles.get(PileId::Hand).is_empty());
        let pommel_owner = parked
            .frames
            .as_slice()
            .iter()
            .find_map(|frame| match *frame {
                Frame::CardPlay { record } => parked
                    .frames
                    .card_play(record)
                    .filter(|play| play.source == CardPlaySource::Uproar),
                _ => None,
            })
            .expect("Uproar owns the live Pommel Strike child");
        assert_eq!(pommel_owner.uid, 1);
        assert_eq!(pommel_owner.source_pile, PileId::Play);

        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let rebuilt = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        crate::engine::admit(&wire, &rebuilt, &rebuilt_catalog).unwrap();
        let actions = crate::engine::legal_actions(&rebuilt, &rebuilt_catalog);
        assert_eq!(actions.len(), 2);
        let completed = crate::engine::apply_action(&rebuilt, &rebuilt_catalog, &actions[0])
            .unwrap()
            .state;
        assert!(completed.pending.is_none());
        assert!(completed.frames.is_empty());
        assert_eq!(completed.monsters[0].hp, 28);
        assert_eq!(
            completed
                .piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [1, 0]
        );
        assert_eq!(
            completed
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [2, 3]
        );
    }

    #[test]
    fn all_for_one_excludes_the_active_sly_catastrophe_owner() {
        let all_for_one = identity(CardId::AllForOne, 0);
        let catastrophe = identity(CardId::Catastrophe, 0);
        let mut builder = CatalogBuilder::new();
        let all_for_one_atom = builder.intern(all_for_one).unwrap();
        let catastrophe_atom = builder.intern(catastrophe).unwrap();
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.max_hp = 50;
        state.exact_piles = true;
        state.next_card_uid = 3;
        state.piles.get_mut(PileId::Draw).make_mut().push(HotCard {
            uid: 1,
            atom: all_for_one_atom,
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        });
        state
            .piles
            .get_mut(PileId::Discard)
            .make_mut()
            .push(HotCard {
                uid: 2,
                atom: catastrophe_atom,
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            });
        state.card_states.set_to_free_this_combat(2, 2).unwrap();
        state.card_states.set_local_sly(2);
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 50);
        monster.max_hp = 50;
        state.monsters_mut().push(monster);
        let owner_index = push_live_nonmanual_owner(
            &mut state,
            2,
            CardPlaySource::SlyDiscard,
            PileId::Discard,
            None,
        );
        let spec = *catalog.spec(all_for_one_atom).unwrap();
        let [step] = catalog.steps(&spec) else {
            panic!("All for One keeps one compiled step")
        };
        let mut events = Vec::new();
        let mut ctx = StepCtx {
            state: &mut state,
            catalog: &catalog,
            spec: &spec,
            source_uid: 1,
            target: Some(0),
            selection: None,
            x_value: 0,
            args: catalog.args(step.args),
            events: &mut events,
        };

        crate::steps::defect_rare::all_for_one_exact(&mut ctx).unwrap();

        assert!(state.piles.get(PileId::Hand).is_empty());
        let owner = state.frames.card_play(owner_index).unwrap();
        assert_eq!(owner.source, CardPlaySource::SlyDiscard);
        assert_eq!(owner.source_pile, PileId::Play);
        assert!(owner.active_play_member);
        persisted_card_play_context(&state, &catalog, owner).unwrap();
    }

    #[test]
    fn discard_hand_excludes_a_live_catastrophe_owner() {
        let catastrophe = identity(CardId::Catastrophe, 0);
        let gamble = identity(CardId::CalculatedGamble, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        for identity in [catastrophe, gamble, defend] {
            builder.intern(identity).unwrap();
        }
        let catalog = builder.build();
        let card = |uid, identity| HotCard {
            uid,
            atom: catalog.atom(&identity).unwrap(),
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        };

        let mut discarded = HotState::at_defaults();
        discarded.hp = 50;
        discarded.max_hp = 50;
        discarded.exact_piles = true;
        discarded.next_card_uid = 5;
        discarded
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .extend([card(1, catastrophe), card(2, defend)]);
        discarded
            .piles
            .get_mut(PileId::Draw)
            .make_mut()
            .extend([card(3, defend), card(4, defend)]);
        let discarded_owner = push_live_nonmanual_owner(
            &mut discarded,
            1,
            CardPlaySource::Catastrophe,
            PileId::Hand,
            None,
        );
        let gamble_spec = *catalog.spec(catalog.atom(&gamble).unwrap()).unwrap();
        let [gamble_step] = catalog.steps(&gamble_spec) else {
            panic!("Calculated Gamble keeps one compiled step")
        };
        let mut discard_events = Vec::new();
        let mut gamble_ctx = StepCtx {
            state: &mut discarded,
            catalog: &catalog,
            spec: &gamble_spec,
            source_uid: 20,
            target: None,
            selection: None,
            x_value: 0,
            args: catalog.args(gamble_step.args),
            events: &mut discard_events,
        };
        crate::steps::ironclad_uncommon::discard_hand_draw(&mut gamble_ctx).unwrap();
        assert!(
            discarded
                .piles
                .get(PileId::Play)
                .as_slice()
                .iter()
                .any(|card| card.uid == 1)
        );
        assert_eq!(
            discarded
                .frames
                .card_play(discarded_owner)
                .unwrap()
                .source_pile,
            PileId::Play
        );

        // The same repair under a complete public ActionReplay root is pinned
        // by `calculated_gamble_batch_repairs_two_admitted_catastrophe_owners_before_sly_choice`
        // and `catastrophe_scrape_owner_relocations_roundtrip_through_a_sly_purity_choice`.
    }

