    #[test]
    fn catastrophe_scrape_active_owners_roundtrip_through_a_sly_purity_choice() {
        let catastrophe = identity(CardId::Catastrophe, 0);
        let scrape = identity(CardId::Scrape, 0);
        let purity = identity(CardId::Purity, 0);
        let defend = identity(CardId::DefendDefect, 0);
        let mut builder = CatalogBuilder::new();
        for identity in [catastrophe, scrape, purity, defend] {
            builder.intern_reachable(identity).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        assert!(catalog.requires_action_replay());

        let mut state = state_with_card(&catalog, catastrophe, 1);
        state.hp = 50;
        state.max_hp = 50;
        state.energy = 3;
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.exact_piles = true;
        state.next_card_uid = 7;
        state.piles.get_mut(PileId::Draw).make_mut().extend([
            HotCard {
                uid: 2,
                atom: catalog.atom(&catastrophe).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 3,
                atom: catalog.atom(&scrape).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 4,
                atom: catalog.atom(&purity).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 5,
                atom: catalog.atom(&defend).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
        ]);
        state.card_states.set_to_free_this_combat(3, 1).unwrap();
        state.card_states.set_local_sly(4);
        state.card_states.append_local_cost_modifier(
            4,
            LocalCostModifier {
                kind: LocalCostModifierKind::Set,
                amount: 1,
                expiration: LocalCostExpiration::ThisTurnOrPlayed,
                reduce_only: false,
            },
        );
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 6,
            atom: catalog.atom(&defend).unwrap(),
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        });
        state.powers.set(PowerId::MasterPlanner, SlotWire::Int, 1);
        hydrate_after_card_played_power_order_for_test(&mut state);
        let seeded = Xoshiro256StarStar::from_seed(0);
        state.rng.set(
            RngStream::Targets,
            RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 500);
        monster.max_hp = 500;
        state.monsters_mut().push(monster);

        let parked = (0..10_000_u64)
            .find_map(|seed| {
                let mut probe = state.clone();
                let rng = Xoshiro256StarStar::from_seed(seed);
                probe.rng.set(
                    RngStream::Rng,
                    RngStreamState {
                        words: rng.words,
                        counter: rng.counter,
                    },
                );
                crate::engine::apply_action(&probe, &catalog, &synchronous_play_action(1, None))
                    .ok()
                    .map(|transition| transition.state)
                    .filter(|candidate| {
                        candidate
                            .pending
                            .as_deref()
                            .is_some_and(|pending| pending.frame_uid == 4)
                            && candidate.frames.as_slice().iter().any(|frame| {
                                matches!(*frame, Frame::CardPlay { record }
                                    if candidate.frames.card_play(record).is_some_and(|play| play.uid == 3))
                            })
                    })
            })
            .expect("one exact nested Catastrophe order reaches Scrape then Sly Purity");

        let owner = |uid| {
            parked
                .frames
                .as_slice()
                .iter()
                .find_map(|frame| match *frame {
                    Frame::CardPlay { record } => parked
                        .frames
                        .card_play(record)
                        .filter(|play| play.uid == uid),
                    _ => None,
                })
        };
        let inner_catastrophe = owner(2).expect("inner Catastrophe remains active");
        assert_eq!(inner_catastrophe.source, CardPlaySource::Catastrophe);
        assert_eq!(inner_catastrophe.source_pile, PileId::Play);
        assert!(inner_catastrophe.active_play_member);
        let scrape_owner = owner(3).expect("Scrape remains active below Sly Purity");
        assert_eq!(scrape_owner.source, CardPlaySource::Catastrophe);
        assert_eq!(scrape_owner.source_pile, PileId::Play);
        assert!(scrape_owner.active_play_member);
        let purity_owner = owner(4).expect("Sly Purity owns the pending choice");
        assert_eq!(purity_owner.source, CardPlaySource::SlyDiscard);
        assert_eq!(purity_owner.source_pile, PileId::Play);
        assert!(purity_owner.active_play_member);
        assert_eq!(
            parked
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [6]
        );
        assert_eq!(
            parked
                .piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [5],
            "Scrape parks the native-positive returned Defend before its Sly Purity child"
        );
        assert!(persisted_card_play_stack_is_exact(&parked, &catalog).is_ok());

        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let rebuilt = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        crate::engine::admit(&wire, &rebuilt, &rebuilt_catalog).unwrap();
        let completed = crate::engine::legal_actions(&rebuilt, &rebuilt_catalog)
            .into_iter()
            .find_map(|action| {
                crate::engine::apply_action(&rebuilt, &rebuilt_catalog, &action)
                    .ok()
                    .filter(|transition| {
                        transition.events.iter().any(|event| {
                            matches!(
                                event,
                                Event::CardResolved {
                                    uid: 6,
                                    pile: PileId::Exhaust,
                                }
                            )
                        })
                    })
            })
            .expect("Purity exhausts the remaining Hand card, never an active owner")
            .state;
        assert!(completed.pending.is_none());
        assert!(completed.frames.is_empty());
        assert_eq!(completed.history.card_plays_finished_combat, 6);
        assert!(
            completed
                .piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .any(|card| card.uid == 4)
        );
        for uid in [2, 3] {
            assert_eq!(
                completed
                    .piles
                    .get(PileId::Discard)
                    .as_slice()
                    .iter()
                    .filter(|card| card.uid == uid)
                    .count(),
                1,
                "active owner {uid} routes exactly once"
            );
        }
    }

    #[test]
    fn calculated_gamble_excludes_two_active_catastrophe_owners_before_sly_choice() {
        let catastrophe = identity(CardId::Catastrophe, 0);
        let scrape = identity(CardId::Scrape, 0);
        let gamble = identity(CardId::CalculatedGamble, 0);
        let purity = identity(CardId::Purity, 0);
        let defend = identity(CardId::DefendDefect, 0);
        let mut builder = CatalogBuilder::new();
        for identity in [catastrophe, scrape, gamble, purity, defend] {
            builder.intern_reachable(identity).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();
        assert!(catalog.requires_action_replay());

        let mut state = state_with_card(&catalog, catastrophe, 1);
        state.hp = 50;
        state.max_hp = 50;
        state.energy = 3;
        state.player_phase = crate::engine::admission::PHASE_ORDINARY_ACTIONS;
        state.exact_piles = true;
        state.next_card_uid = 16;
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 7,
            atom: catalog.atom(&purity).unwrap(),
            flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
        });
        state.piles.get_mut(PileId::Draw).make_mut().extend([
            HotCard {
                uid: 2,
                atom: catalog.atom(&catastrophe).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 3,
                atom: catalog.atom(&catastrophe).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 4,
                atom: catalog.atom(&scrape).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 5,
                atom: catalog.atom(&defend).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
            HotCard {
                uid: 6,
                atom: catalog.atom(&gamble).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            },
        ]);
        state
            .piles
            .get_mut(PileId::Discard)
            .make_mut()
            .extend((8..16).map(|uid| HotCard {
                uid,
                atom: catalog.atom(&defend).unwrap(),
                flags: CARD_FLAG_DEFAULT_PHYSICAL_STATE,
            }));
        state.card_states.set_to_free_this_combat(4, 1).unwrap();
        state.card_states.set_local_sly(7);
        state.powers.set(PowerId::MasterPlanner, SlotWire::Int, 1);
        hydrate_after_card_played_power_order_for_test(&mut state);
        let seeded = Xoshiro256StarStar::from_seed(0);
        state.rng.set(
            RngStream::Targets,
            RngStreamState {
                words: seeded.words,
                counter: seeded.counter,
            },
        );
        let mut monster = HotMonster::new(MonsterKind::Toadpole, 500);
        monster.max_hp = 500;
        state.monsters_mut().push(monster);

        let owner = |candidate: &HotState, uid| {
            candidate
                .frames
                .as_slice()
                .iter()
                .find_map(|frame| match *frame {
                    Frame::CardPlay { record } => candidate
                        .frames
                        .card_play(record)
                        .filter(|play| play.uid == uid)
                        .map(|play| (play.source, play.source_pile, play.active_play_member)),
                    _ => None,
                })
        };
        let parked_transition = (0..1_000_u64)
            .find_map(|seed| {
                let mut probe = state.clone();
                let rng = Xoshiro256StarStar::from_seed(seed);
                probe.rng.set(
                    RngStream::Rng,
                    RngStreamState {
                        words: rng.words,
                        counter: rng.counter,
                    },
                );
                crate::engine::apply_action(&probe, &catalog, &synchronous_play_action(1, None))
                    .ok()
                    .filter(|transition| {
                        let candidate = &transition.state;
                        candidate
                            .pending
                            .as_deref()
                            .is_some_and(|pending| pending.frame_uid == 7)
                            && [2, 3].into_iter().all(|uid| {
                                owner(candidate, uid).is_some_and(|play| {
                                    play.0 == CardPlaySource::Catastrophe
                                        && play.1 == PileId::Play && play.2
                                })
                            })
                    })
            })
            .expect(
                "one exact recursive order runs Calculated Gamble while both Catastrophe owners remain active",
            );
        let parked = parked_transition.state;

        for uid in [2, 3] {
            assert_eq!(
                PileId::ALL
                    .into_iter()
                    .flat_map(|pile| parked.piles.get(pile).as_slice())
                    .filter(|card| card.uid == uid)
                    .count(),
                1,
                "the live Catastrophe owner {uid} remains one physical object after Gamble and its paired draw"
            );
        }
        let sly_owner = owner(&parked, 7).expect("Sly Purity owns the pending choice");
        assert_eq!(sly_owner.0, CardPlaySource::SlyDiscard);
        assert_eq!(sly_owner.2, sly_owner.1 == PileId::Play);
        assert_eq!(sly_owner.1, PileId::Play);
        assert!(persisted_card_play_stack_is_exact(&parked, &catalog).is_ok());

        let wire = HotBoundary::try_to_canonical(&parked, &catalog).unwrap();
        let rebuilt_catalog = HotBoundary::catalog_from_canonical(&wire).unwrap();
        let rebuilt = HotBoundary::from_canonical(&wire, &rebuilt_catalog).unwrap();
        crate::engine::admit(&wire, &rebuilt, &rebuilt_catalog).unwrap();
        let completed = crate::engine::legal_actions(&rebuilt, &rebuilt_catalog)
            .into_iter()
            .find_map(|action| {
                crate::engine::apply_action(&rebuilt, &rebuilt_catalog, &action)
                    .ok()
                    .filter(|transition| {
                        transition.state.pending.is_none() && transition.state.frames.is_empty()
                    })
            })
            .expect("one exact Purity answer drains every recursive owner")
            .state;
        assert_eq!(completed.history.card_plays_finished_combat, 6);
        for uid in 1..=7 {
            assert_eq!(
                PileId::ALL
                    .into_iter()
                    .flat_map(|pile| completed.piles.get(pile).as_slice())
                    .filter(|card| card.uid == uid)
                    .count(),
                1,
                "physical uid {uid} routes exactly once"
            );
        }
    }

