    #[test]
    fn knife_trap_keeps_its_frozen_exhaust_batch_and_target_across_hive_insertions() {
        let knife = identity(CardId::KnifeTrap, 0);
        let shiv = identity(CardId::Shiv, 0);
        let dazed = identity(CardId::Dazed, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern_monster(MonsterKind::Entomancer).unwrap();
        builder.intern(knife).unwrap();
        builder.intern(shiv).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, knife, 50);
        add_entomancer(&mut state, 1);
        state.next_card_uid = 100;
        state.next_generated_hook_uid = 200;
        for uid in 51..53 {
            state
                .piles
                .get_mut(PileId::Exhaust)
                .make_mut()
                .push(HotCard {
                    uid,
                    atom: catalog.atom(&shiv).unwrap(),
                    flags: 0,
                });
        }
        let rng_before = state.rng.get(RngStream::Rng).counter;
        let targets_before = state.rng.get(RngStream::Targets).counter;
        let mut events = Vec::new();

        let next = crate::engine::apply_action_into(
            &state,
            &catalog,
            &synchronous_play_action(50, Some(0)),
            &mut events,
        )
        .unwrap();

        assert_eq!(next.monsters[0].hp, 157);
        assert_eq!(next.rng.get(RngStream::Rng).counter, rng_before + 2);
        assert_eq!(next.rng.get(RngStream::Targets).counter, targets_before);
        assert_eq!(
            next.piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [51, 52],
        );
        assert_eq!(
            next.piles
                .get(PileId::Draw)
                .as_slice()
                .iter()
                .filter(|card| card.atom == catalog.atom(&dazed).unwrap())
                .count(),
            2,
        );
        assert_eq!(next.history.card_plays_finished_combat, 3);
        let cross_slice = events
            .iter()
            .filter_map(|event| match event {
                Event::MonsterDamaged { .. } => Some("hit"),
                Event::CardResolved {
                    uid: 100..=101,
                    pile: PileId::Draw,
                } => Some("hive"),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(cross_slice, ["hit", "hive", "hit", "hive"]);
    }

