    #[test]
    fn primal_force_manual_and_direct_autoplay_share_atomic_transform_routing() {
        let primal = identity(CardId::PrimalForce, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let primal_atom = builder.intern(primal).unwrap();
        let strike_atom = builder.intern(strike).unwrap();
        let catalog = builder.build();

        for manual in [true, false] {
            let source_pile = if manual { PileId::Hand } else { PileId::Draw };
            let source = HotCard {
                uid: 70,
                atom: primal_atom,
                flags: 0,
            };
            let attack = HotCard {
                uid: 71,
                atom: strike_atom,
                flags: 0,
            };
            let mut state = HotState::at_defaults();
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            state.hp = 50;
            state.energy = 3;
            state.next_card_uid = 100;
            state.ps_strikes = 1;
            state.piles.get_mut(source_pile).make_mut().push(source);
            state.piles.get_mut(PileId::Hand).make_mut().push(attack);
            let before_rng = state.rng.clone();
            let mut events = Vec::new();

            play_card_with_work(
                &mut state,
                &catalog,
                source.uid,
                None,
                None,
                &mut events,
                PlaySource {
                    pile: source_pile,
                    provenance: if manual {
                        PlayProvenance::Manual
                    } else {
                        PlayProvenance::Auto
                    },
                    force_exhaust: !manual,
                    frozen: (!manual).then_some(source),

                    allow_dead_target: false,
                },
            )
            .unwrap();

            let hand = state.piles.get(PileId::Hand).as_slice();
            assert_eq!(hand.len(), 1);
            assert_eq!(hand[0].uid, 100);
            assert_eq!(
                catalog.spec(hand[0].atom).unwrap().identity,
                identity(CardId::GiantRock, 0)
            );
            let result_pile = if manual {
                PileId::Discard
            } else {
                PileId::Exhaust
            };
            assert_eq!(state.piles.get(result_pile).as_slice(), &[source]);
            assert_eq!(state.history.owner_generated_cards_combat, 1);
            assert_eq!(state.ps_strikes, 0);
            assert_eq!(state.rng, before_rng);
        }

        for power in [PowerId::Burst, PowerId::EchoForm] {
            let source = HotCard {
                uid: 70,
                atom: primal_atom,
                flags: 0,
            };
            let attack = HotCard {
                uid: 71,
                atom: strike_atom,
                flags: 0,
            };
            let mut state = HotState::at_defaults();
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            state.hp = 50;
            state.energy = 3;
            state.next_card_uid = 100;
            state.ps_strikes = 1;
            state
                .piles
                .get_mut(PileId::Hand)
                .make_mut()
                .extend([source, attack]);
            state.powers.set(power, SlotWire::Int, 1);
            hydrate_side_end_order(&mut state);
            let mut events = Vec::new();
            play_card(&mut state, &catalog, source.uid, None, None, &mut events).unwrap();
            let hand = state.piles.get(PileId::Hand).as_slice();
            assert_eq!(hand.len(), 1);
            assert_eq!(hand[0].uid, 101);
            assert_eq!(
                catalog.spec(hand[0].atom).unwrap().identity,
                identity(CardId::GiantRock, 0)
            );
            assert_eq!(state.next_card_uid, 102);
            assert_eq!(state.history.owner_generated_cards_combat, 2);
            assert_eq!(state.next_generated_hook_uid, 2);
            assert_eq!(state.ps_strikes, 0);
            if power == PowerId::Burst {
                assert_eq!(state.powers.value(PowerId::Burst), 0);
            }
        }

        for legacy_source in [true, false] {
            let source = HotCard {
                uid: 70,
                atom: primal_atom,
                flags: u16::from(legacy_source) * CARD_FLAG_LEGACY,
            };
            let attack = HotCard {
                uid: 71,
                atom: strike_atom,
                flags: u16::from(!legacy_source) * CARD_FLAG_LEGACY,
            };
            let mut state = HotState::at_defaults();
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            state.hp = 50;
            state.energy = 3;
            state.next_card_uid = 100;
            state.ps_strikes = 1;
            state
                .piles
                .get_mut(PileId::Hand)
                .make_mut()
                .extend([source, attack]);
            let before = state.clone();
            let mut events = Vec::new();
            assert!(matches!(
                play_card(&mut state, &catalog, source.uid, None, None, &mut events),
                Err(EngineRefusal::MalformedArgs(_))
            ));
            assert_eq!(state, before);
            assert!(events.is_empty());
        }

        let source = HotCard {
            uid: 70,
            atom: primal_atom,
            flags: 0,
        };
        let attack = HotCard {
            uid: 71,
            atom: strike_atom,
            flags: 0,
        };
        let mut overflow = HotState::at_defaults();
        overflow.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            100,
        ));
        overflow.hp = 50;
        overflow.energy = 3;
        overflow.next_card_uid = 100;
        overflow.ps_strikes = 1;
        overflow.history.owner_generated_cards_combat = i32::MAX;
        overflow
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .extend([source, attack]);
        let before = overflow.clone();
        let mut events = Vec::new();
        assert_eq!(
            play_card(&mut overflow, &catalog, source.uid, None, None, &mut events,),
            Err(EngineRefusal::CounterOverflow(
                "owner_generated_cards_combat"
            ))
        );
        assert_eq!(overflow, before);
        assert!(events.is_empty());
    }

    #[test]
    fn feral_returns_only_the_live_zero_spend_attack_and_consumes_one_use() {
        let feral = identity(CardId::Feral, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(feral).unwrap();
        builder.intern(strike).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, feral, 90);
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 91,
            atom: catalog.atom(&strike).unwrap(),
            flags: 0,
        });
        let mut events = Vec::new();

        play_card(&mut state, &catalog, 90, None, None, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::Feral), 1);
        assert_eq!(
            state.fanouts.result_location_power_order(),
            [PowerId::Feral]
        );
        state.powers.set(PowerId::FreeAttack, SlotWire::Int, 1);
        play_card(&mut state, &catalog, 91, Some(0), None, &mut events).unwrap();

        assert_eq!(state.powers.value(PowerId::FeralUsed), 1);
        assert_eq!(state.history.zero_energy_attack_plays_started_this_turn, 1);
        assert_eq!(state.piles.get(PileId::Hand).as_slice()[0].uid, 91);
        assert!(state.piles.get(PileId::Discard).is_empty());

        state.powers.set(PowerId::FreeAttack, SlotWire::Int, 1);
        play_card(&mut state, &catalog, 91, Some(0), None, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::FeralUsed), 1);
        assert_eq!(state.history.zero_energy_attack_plays_started_this_turn, 2);
        assert_eq!(
            state
                .piles
                .get(PileId::Discard)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [91]
        );
    }

    /// #3355: `FeralPower::ModifyCardPlayResultLocation` RVA `0xa23f8` never
    /// loads the incoming `pileType`, so every route a qualifying Attack can
    /// reach is redirected to Hand/Top, and each redirect advances the cursor.
    #[test]
    fn feral_redirects_every_incoming_attack_route_and_counts_each_use() {
        let shiv = identity(CardId::Shiv, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let shining = identity(CardId::ShiningStrike, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        let shiv_atom = builder.intern(shiv).unwrap();
        let strike_atom = builder.intern(strike).unwrap();
        let shining_atom = builder.intern(shining).unwrap();
        let defend_atom = builder.intern(defend).unwrap();
        let catalog = builder.build();
        let shiv_spec = catalog.spec(shiv_atom).unwrap();
        let strike_spec = catalog.spec(strike_atom).unwrap();
        let shining_spec = catalog.spec(shining_atom).unwrap();
        let defend_spec = catalog.spec(defend_atom).unwrap();
        assert!(shiv_spec.exhausts && shiv_spec.is_attack);

        let feral_state = |amount: i32, order: &[PowerId]| {
            let mut state = HotState::at_defaults();
            state.hp = 50;
            state.powers.set(PowerId::Feral, SlotWire::Int, amount);
            for &power in order {
                if power != PowerId::Feral {
                    state.powers.set(power, SlotWire::Int, 1);
                }
            }
            hydrate_side_end_order(&mut state);
            assert!(state.fanouts.set_result_location_power_order(order));
            state
        };
        let route = |state: &mut HotState, spec: &CardSpec, energy: i16, force: bool| {
            resolve_card_result_route(state, spec, energy, force, &mut Vec::new()).unwrap()
        };

        // Keyword Exhaust (the TJ2YUJJXHPZD n47 Shatter shape).
        let mut state = feral_state(2, &[PowerId::Feral]);
        assert_eq!(
            route(&mut state, shiv_spec, 0, false),
            CardResultRoute::HandTop
        );
        assert_eq!(state.powers.value(PowerId::FeralUsed), 1);
        // Forced Exhaust (Havoc/Mayhem-shaped AutoPlay) is redirected too.
        assert_eq!(
            route(&mut state, strike_spec, 0, true),
            CardResultRoute::HandTop
        );
        assert_eq!(state.powers.value(PowerId::FeralUsed), 2);
        // The cursor now equals Amount (IL_0046-IL_005b): the route stands.
        assert_eq!(
            route(&mut state, shiv_spec, 0, false),
            CardResultRoute::ExhaustBottom
        );
        assert_eq!(
            route(&mut state, strike_spec, 0, false),
            CardResultRoute::DiscardBottom
        );
        assert_eq!(state.powers.value(PowerId::FeralUsed), 2);

        // A positive EnergyValue (IL_002e-IL_003a) leaves Exhaust alone.
        let mut state = feral_state(1, &[PowerId::Feral]);
        assert_eq!(
            route(&mut state, shiv_spec, 1, false),
            CardResultRoute::ExhaustBottom
        );
        assert_eq!(state.powers.value(PowerId::FeralUsed), 0);
        // A Skill is never redirected (IL_0022-IL_002d).
        assert_eq!(
            route(&mut state, defend_spec, 0, true),
            CardResultRoute::ExhaustBottom
        );
        assert_eq!(
            route(&mut state, defend_spec, 0, false),
            CardResultRoute::DiscardBottom
        );
        assert_eq!(state.powers.value(PowerId::FeralUsed), 0);

        // Shining Strike's Draw/Top card virtual precedes the listener fold.
        let mut state = feral_state(1, &[PowerId::Feral]);
        assert_eq!(
            route(&mut state, shining_spec, 0, false),
            CardResultRoute::HandTop
        );
        assert_eq!(state.powers.value(PowerId::FeralUsed), 1);

        // Rebound first: it writes Draw/Top and consumes; Feral then sees
        // Draw/Top and still redirects (both listeners changed the location).
        let mut state = feral_state(1, &[PowerId::Rebound, PowerId::Feral]);
        assert_eq!(
            route(&mut state, strike_spec, 0, false),
            CardResultRoute::HandTop
        );
        assert_eq!(state.powers.value(PowerId::Rebound), 0);
        assert_eq!(state.powers.value(PowerId::FeralUsed), 1);
        // Feral first: Rebound then sees Hand, not Discard, and stays armed.
        let mut state = feral_state(1, &[PowerId::Feral, PowerId::Rebound]);
        assert_eq!(
            route(&mut state, strike_spec, 0, false),
            CardResultRoute::HandTop
        );
        assert_eq!(state.powers.value(PowerId::Rebound), 1);
        assert_eq!(state.powers.value(PowerId::FeralUsed), 1);
        // Nostalgia first likewise hands Feral a Draw/Top input.
        let mut state = feral_state(1, &[PowerId::Nostalgia, PowerId::Feral]);
        assert_eq!(
            route(&mut state, strike_spec, 0, false),
            CardResultRoute::HandTop
        );
        assert_eq!(state.powers.value(PowerId::FeralUsed), 1);
        // Corruption is Skill-only and Feral Attack-only: an Attack under
        // both still returns to Hand, a Skill still exhausts.
        let mut state = feral_state(1, &[PowerId::Feral, PowerId::Corruption]);
        assert_eq!(
            route(&mut state, shiv_spec, 0, false),
            CardResultRoute::HandTop
        );
        assert_eq!(
            route(&mut state, defend_spec, 0, false),
            CardResultRoute::ExhaustBottom
        );

        // A dupe keeps Remove (IL_003b-IL_0045) and consumes nothing.
        let mut state = feral_state(1, &[PowerId::Feral]);
        assert_eq!(
            resolve_card_result_route_inner(&mut state, shiv_spec, true, 0, false, &mut Vec::new())
                .unwrap(),
            CardResultRoute::RemoveBottom
        );
        assert_eq!(state.powers.value(PowerId::FeralUsed), 0);

        // The restricted-carrier predicate agrees for every natural route.
        for (spec, force) in [
            (shiv_spec, false),
            (strike_spec, true),
            (strike_spec, false),
            (shining_spec, false),
        ] {
            assert!(restricted_batch_result_writer_changes_route(
                spec,
                force,
                PowerId::Feral
            ));
        }
        assert!(!restricted_batch_result_writer_changes_route(
            defend_spec,
            true,
            PowerId::Feral
        ));
    }

    /// #3355 end to end: a free keyword-Exhaust Attack played under Feral goes
    /// to the top of the Hand and never reaches the Exhaust pile.
    #[test]
    fn feral_returns_a_free_exhausting_attack_to_hand_top() {
        let feral = identity(CardId::Feral, 0);
        let shiv = identity(CardId::Shiv, 0);
        let strike = identity(CardId::StrikeIronclad, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(feral).unwrap();
        builder.intern(shiv).unwrap();
        builder.intern(strike).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, feral, 90);
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 91,
                atom: catalog.atom(&strike).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 92,
                atom: catalog.atom(&shiv).unwrap(),
                flags: 0,
            },
        ]);
        let mut events = Vec::new();
        play_card(&mut state, &catalog, 90, None, None, &mut events).unwrap();
        play_card(&mut state, &catalog, 92, Some(0), None, &mut events).unwrap();

        assert_eq!(state.powers.value(PowerId::FeralUsed), 1);
        assert_eq!(state.piles.get(PileId::Hand).as_slice()[0].uid, 92);
        assert!(state.piles.get(PileId::Exhaust).is_empty());
        assert!(events.contains(&Event::CardResolved {
            uid: 92,
            pile: PileId::Hand
        }));

        // The one use is spent: the next free Shiv exhausts.
        play_card(&mut state, &catalog, 92, Some(0), None, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::FeralUsed), 1);
        assert_eq!(
            state
                .piles
                .get(PileId::Exhaust)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [92]
        );
    }

    /// #3355: The Ball's virtual has already drawn its remote recipient when
    /// Feral would hand it back to its owner; that route refuses by name.
    #[test]
    fn feral_over_the_ball_remote_route_refuses_by_name() {
        let ball = identity(CardId::TheBall, 0);
        let mut builder = CatalogBuilder::new();
        let ball_atom = builder.intern(ball).unwrap();
        let catalog = builder.build();
        let ball_spec = catalog.spec(ball_atom).unwrap();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.powers.set(PowerId::Feral, SlotWire::Int, 1);
        assert!(
            state
                .fanouts
                .set_result_location_power_order(&[PowerId::Feral])
        );
        state.multiplayer_ally_key = 1;
        state.fanouts.set_multiplayer_ally(MultiplayerAllyState {
            key: 1,
            shuffle_rng: Some(RngStreamState {
                words: [31, 32, 33, 34],
                counter: 0,
            }),
            ..MultiplayerAllyState::default()
        });
        assert_eq!(
            resolve_card_result_route(&mut state, ball_spec, 0, false, &mut Vec::new()),
            Err(EngineRefusal::PowerOrderNotModeled(
                "Feral over The Ball's remote result route"
            ))
        );
        // A paid Ball does not qualify and keeps its remote route.
        assert_eq!(
            resolve_card_result_route(&mut state, ball_spec, 1, false, &mut Vec::new()).unwrap(),
            CardResultRoute::RemoteDrawRandom
        );
        assert_eq!(state.powers.value(PowerId::FeralUsed), 0);
    }

    #[test]
    fn nostalgia_and_rebound_fold_in_acquisition_order_with_exact_consumption() {
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(defend).unwrap();
        let catalog = builder.build();
        let spec = catalog.spec(catalog.atom(&defend).unwrap()).unwrap();

        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.powers.set(PowerId::Nostalgia, SlotWire::Int, 1);
        state.powers.set(PowerId::Rebound, SlotWire::Int, 1);
        hydrate_side_end_order(&mut state);
        assert!(
            state
                .fanouts
                .set_result_location_power_order(&[PowerId::Nostalgia, PowerId::Rebound,])
        );
        assert_eq!(
            resolve_card_result_route(&mut state, spec, 1, false, &mut Vec::new()).unwrap(),
            CardResultRoute::DrawTop
        );
        assert_eq!(state.powers.value(PowerId::Rebound), 1);
        assert_eq!(
            state.fanouts.result_location_power_order(),
            [PowerId::Nostalgia, PowerId::Rebound]
        );

        state.history.attack_skill_plays_started_this_turn = 1;
        assert_eq!(
            resolve_card_result_route(&mut state, spec, 1, false, &mut Vec::new()).unwrap(),
            CardResultRoute::DrawTop
        );
        assert_eq!(state.powers.value(PowerId::Rebound), 0);
        assert_eq!(
            state.fanouts.result_location_power_order(),
            [PowerId::Nostalgia]
        );

        let mut reverse = HotState::at_defaults();
        reverse.hp = 50;
        reverse.powers.set(PowerId::Nostalgia, SlotWire::Int, 1);
        reverse.powers.set(PowerId::Rebound, SlotWire::Int, 1);
        hydrate_side_end_order(&mut reverse);
        assert!(
            reverse
                .fanouts
                .set_result_location_power_order(&[PowerId::Rebound, PowerId::Nostalgia,])
        );
        assert_eq!(
            resolve_card_result_route(&mut reverse, spec, 1, false, &mut Vec::new()).unwrap(),
            CardResultRoute::DrawTop
        );
        assert_eq!(reverse.powers.value(PowerId::Rebound), 0);
        assert_eq!(
            reverse.fanouts.result_location_power_order(),
            [PowerId::Nostalgia]
        );

        let mut terminal = HotState::at_defaults();
        terminal.hp = 50;
        terminal.history.over = true;
        terminal.powers.set(PowerId::Rebound, SlotWire::Int, 1);
        hydrate_side_end_order(&mut terminal);
        assert!(
            terminal
                .fanouts
                .set_result_location_power_order(&[PowerId::Rebound])
        );
        assert_eq!(
            resolve_card_result_route(&mut terminal, spec, 1, false, &mut Vec::new()).unwrap(),
            CardResultRoute::DiscardBottom
        );
        assert_eq!(terminal.powers.value(PowerId::Rebound), 1);
    }

    #[test]
    fn card_virtual_result_locations_precede_global_listeners_and_terminal_gate() {
        let shining = identity(CardId::ShiningStrike, 0);
        let wall = identity(CardId::ParticleWall, 0);
        let ball = identity(CardId::TheBall, 0);
        let mut builder = CatalogBuilder::new();
        let shining_atom = builder.intern(shining).unwrap();
        let wall_atom = builder.intern(wall).unwrap();
        let ball_atom = builder.intern(ball).unwrap();
        let catalog = builder.build();
        let shining_spec = catalog.spec(shining_atom).unwrap();
        let wall_spec = catalog.spec(wall_atom).unwrap();
        let ball_spec = catalog.spec(ball_atom).unwrap();

        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.powers.set(PowerId::Rebound, SlotWire::Int, 1);
        state.powers.set(PowerId::Nostalgia, SlotWire::Int, 1);
        assert!(
            state
                .fanouts
                .set_result_location_power_order(&[PowerId::Rebound, PowerId::Nostalgia])
        );
        assert_eq!(
            resolve_card_result_route(&mut state, shining_spec, 1, false, &mut Vec::new()).unwrap(),
            CardResultRoute::DrawTop
        );
        assert_eq!(state.powers.value(PowerId::Rebound), 1);
        assert_eq!(
            resolve_card_result_route(&mut state, wall_spec, 0, false, &mut Vec::new()).unwrap(),
            CardResultRoute::HandBottom
        );
        assert_eq!(state.powers.value(PowerId::Rebound), 1);
        state.multiplayer_ally_key = 1;
        state.fanouts.set_multiplayer_ally(MultiplayerAllyState {
            key: 1,
            shuffle_rng: Some(RngStreamState {
                words: [31, 32, 33, 34],
                counter: 0,
            }),
            ..MultiplayerAllyState::default()
        });
        assert_eq!(
            resolve_card_result_route(&mut state, ball_spec, 1, false, &mut Vec::new()).unwrap(),
            CardResultRoute::RemoteDrawRandom
        );
        assert_eq!(state.powers.value(PowerId::Rebound), 1);
        assert!(!restricted_batch_result_writer_changes_route(
            ball_spec,
            false,
            PowerId::Rebound
        ));
        // Feral would change The Ball's remote route too (#3355).
        assert!(restricted_batch_result_writer_changes_route(
            ball_spec,
            false,
            PowerId::Feral
        ));

        state.powers.set(PowerId::Corruption, SlotWire::Bool, 1);
        assert!(state.fanouts.set_result_location_power_order(&[
            PowerId::Rebound,
            PowerId::Nostalgia,
            PowerId::Corruption,
        ]));
        assert_eq!(
            resolve_card_result_route(&mut state, wall_spec, 0, false, &mut Vec::new()).unwrap(),
            CardResultRoute::ExhaustBottom,
            "Corruption observes Particle Wall's Hand/Bottom virtual result"
        );

        state.history.over = true;
        assert_eq!(
            resolve_card_result_route(&mut state, shining_spec, 1, false, &mut Vec::new()).unwrap(),
            CardResultRoute::DrawTop,
            "the card virtual still runs when the global listener walk is suppressed"
        );
        assert_eq!(
            resolve_card_result_route(&mut state, wall_spec, 0, true, &mut Vec::new()).unwrap(),
            CardResultRoute::ExhaustBottom,
            "forced Exhaust is never rewritten by either virtual"
        );
    }

    #[test]
    fn shining_strike_and_particle_wall_route_exact_physical_cards_once() {
        let shining = identity(CardId::ShiningStrike, 0);
        let wall = identity(CardId::ParticleWall, 0);
        let defend = identity(CardId::DefendRegent, 0);
        let mut builder = CatalogBuilder::new();
        for identity in [shining, wall, defend] {
            builder.intern(identity).unwrap();
        }
        builder.intern_monster(MonsterKind::Toadpole).unwrap();
        let catalog = builder.build();

        let mut shining_state = state_with_card(&catalog, shining, 400);
        shining_state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        play_card(
            &mut shining_state,
            &catalog,
            400,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert_eq!(shining_state.stars, 2);
        assert_eq!(shining_state.piles.get(PileId::Draw).as_slice()[0].uid, 400);
        assert!(shining_state.piles.get(PileId::Discard).is_empty());

        let mut lethal = state_with_card(&catalog, shining, 405);
        lethal
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 1));
        play_card(&mut lethal, &catalog, 405, Some(0), None, &mut Vec::new()).unwrap();
        assert!(lethal.history.over);
        assert_eq!(
            lethal.stars, 0,
            "the awaited PlayerCmd::GainStars suffix observes terminal combat"
        );
        assert_eq!(lethal.piles.get(PileId::Play).as_slice()[0].uid, 405);
        assert!(lethal.piles.get(PileId::Draw).is_empty());

        let mut wall_state = state_with_card(&catalog, wall, 410);
        wall_state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        wall_state.stars = 2;
        wall_state.powers.set(PowerId::Burst, SlotWire::Int, 1);
        hydrate_side_end_order(&mut wall_state);
        wall_state
            .piles
            .get_mut(PileId::Hand)
            .make_mut()
            .extend([411, 412].map(|uid| HotCard {
                uid,
                atom: catalog.atom(&defend).unwrap(),
                flags: 0,
            }));
        play_card(&mut wall_state, &catalog, 410, None, None, &mut Vec::new()).unwrap();
        assert_eq!(wall_state.block, 18, "Burst repeats the body, not routing");
        assert_eq!(wall_state.stars, 0);
        assert_eq!(
            wall_state
                .piles
                .get(PileId::Hand)
                .as_slice()
                .iter()
                .map(|card| card.uid)
                .collect::<Vec<_>>(),
            [411, 412, 410],
            "Particle Wall returns once at Hand/Bottom after every replay"
        );
    }

    #[test]
    fn shining_strike_late_star_overflow_rolls_back_the_whole_action() {
        for upgrade in [0, 1] {
            let shining = identity(CardId::ShiningStrike, upgrade);
            let mut builder = CatalogBuilder::new();
            builder.intern(shining).unwrap();
            builder.intern_monster(MonsterKind::Toadpole).unwrap();
            let catalog = builder.build();
            let mut state = state_with_card(&catalog, shining, 420 + u32::from(upgrade));
            state.stars = i16::MAX;
            state
                .monsters_mut()
                .push(HotMonster::new(MonsterKind::Toadpole, 100));
            let before = state.clone();
            let mut events = vec![Event::TurnBegan { turn: 91 }];
            let before_events = events.clone();

            assert_eq!(
                play_card(
                    &mut state,
                    &catalog,
                    420 + u32::from(upgrade),
                    Some(0),
                    None,
                    &mut events,
                ),
                Err(EngineRefusal::CounterOverflow("stars"))
            );
            assert_eq!(state, before, "Shining Strike+{upgrade} state leaked");
            assert_eq!(
                events, before_events,
                "Shining Strike+{upgrade} events leaked"
            );
        }
    }

