    #[test]
    fn public_nostalgia_and_rebound_sources_stack_and_route_manual_cards() {
        let nostalgia0 = identity(CardId::Nostalgia, 0);
        let nostalgia1 = identity(CardId::Nostalgia, 1);
        let rebound0 = identity(CardId::Rebound, 0);
        let defend = identity(CardId::DefendIronclad, 0);
        let mut builder = CatalogBuilder::new();
        for identity in [nostalgia0, nostalgia1, rebound0, defend] {
            builder.intern(identity).unwrap();
        }
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.energy = 9;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 100));
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 300,
                atom: catalog.atom(&nostalgia0).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 301,
                atom: catalog.atom(&nostalgia1).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 302,
                atom: catalog.atom(&rebound0).unwrap(),
                flags: 0,
            },
            HotCard {
                uid: 303,
                atom: catalog.atom(&defend).unwrap(),
                flags: 0,
            },
        ]);
        let mut events = Vec::new();

        play_card(&mut state, &catalog, 300, None, None, &mut events).unwrap();
        play_card(&mut state, &catalog, 301, None, None, &mut events).unwrap();
        play_card(&mut state, &catalog, 302, Some(0), None, &mut events).unwrap();
        assert_eq!(state.powers.value(PowerId::Nostalgia), 2);
        assert_eq!(state.powers.value(PowerId::Rebound), 1);
        assert_eq!(
            state.fanouts.result_location_power_order(),
            [PowerId::Nostalgia, PowerId::Rebound]
        );

        play_card(&mut state, &catalog, 303, None, None, &mut events).unwrap();
        assert_eq!(state.piles.get(PileId::Draw).as_slice()[0].uid, 303);
        assert_eq!(state.powers.value(PowerId::Rebound), 1);
        assert_eq!(state.history.attack_skill_plays_started_this_turn, 2);
    }

    #[test]
    fn lethal_rebound_attack_skips_its_ending_gated_power_suffix() {
        // `Rebound/<OnPlay>d__5::MoveNext` (RVA `0x3b63fc`) awaits the attack
        // (IL_004c), then `PowerCmd.Apply<ReboundPower>` (IL_00fd), which
        // returns at its IsEnding gate (RVA `0x3ef988` IL_0020-0x0034). This
        // test used to pin the frozen Python's ungated write (#3183).
        let rebound = identity(CardId::Rebound, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(rebound).unwrap();
        let catalog = builder.build();
        let mut state = HotState::at_defaults();
        state.hp = 50;
        state.energy = 3;
        state
            .monsters_mut()
            .push(HotMonster::new(MonsterKind::Toadpole, 1));
        state.piles.get_mut(PileId::Hand).make_mut().push(HotCard {
            uid: 304,
            atom: catalog.atom(&rebound).unwrap(),
            flags: 0,
        });

        play_card(&mut state, &catalog, 304, Some(0), None, &mut Vec::new()).unwrap();

        assert!(state.history.over);
        assert_eq!(state.powers.value(PowerId::Rebound), 0);
        assert!(state.fanouts.result_location_power_order().is_empty());
        assert_eq!(state.piles.get(PileId::Play).as_slice()[0].uid, 304);
    }

