    #[test]
    fn trash_to_treasure_public_levels_register_once_and_overflow_is_atomic() {
        for (upgrade, cost) in [(0, 1), (1, 0)] {
            let identity = identity(CardId::TrashToTreasure, upgrade);
            let mut builder = CatalogBuilder::new();
            builder.intern(identity).unwrap();
            let catalog = builder.build();
            let mut state = state_with_card(&catalog, identity, 220 + u32::from(upgrade));
            // A live enemy keeps `damage_combat_is_ending` false (#3183).
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                99,
            ));
            let mut events = Vec::new();

            play_card(
                &mut state,
                &catalog,
                220 + u32::from(upgrade),
                None,
                None,
                &mut events,
            )
            .unwrap();

            assert_eq!(state.energy, 9 - cost);
            assert_eq!(state.powers.value(PowerId::TrashToTreasure), 1);
            assert_eq!(
                state.fanouts.local_generated_power_order(),
                [PowerId::TrashToTreasure]
            );
            assert!(events.iter().any(|event| matches!(
                event,
                Event::PowerChanged {
                    subject: Subject::Player,
                    power: PowerId::TrashToTreasure,
                    amount: 1,
                }
            )));
        }

        let identity = identity(CardId::TrashToTreasure, 0);
        let mut builder = CatalogBuilder::new();
        builder.intern(identity).unwrap();
        let catalog = builder.build();
        let mut state = state_with_card(&catalog, identity, 230);
        // A live enemy keeps `damage_combat_is_ending` false (#3183).
        state.monsters_mut().push(crate::hot::HotMonster::new(
            crate::ids::MonsterKind::Toadpole,
            99,
        ));
        state
            .powers
            .set(PowerId::TrashToTreasure, SlotWire::Int, i32::MAX);
        assert!(
            state
                .fanouts
                .set_local_generated_power_order(&[PowerId::TrashToTreasure])
        );
        let before = state.clone();
        let mut events = vec![Event::TurnBegan { turn: 99 }];
        let before_events = events.clone();

        assert_eq!(
            play_card(&mut state, &catalog, 230, None, None, &mut events),
            Err(EngineRefusal::CounterOverflow("trash_to_treasure"))
        );
        assert_eq!(state, before);
        assert_eq!(events, before_events);
    }

    #[test]
    fn spectrum_shift_manual_and_direct_overflow_roll_back_the_whole_action() {
        let identity = identity(CardId::SpectrumShift, 0);
        let mut builder = CatalogBuilder::new();
        let atom = builder.intern(identity).unwrap();
        let catalog = builder.build();
        let source = HotCard {
            uid: 260,
            atom,
            flags: 0,
        };
        for direct in [false, true] {
            let mut state = HotState::at_defaults();
            state.monsters_mut().push(crate::hot::HotMonster::new(
                crate::ids::MonsterKind::Toadpole,
                100,
            ));
            state.hp = 50;
            state.energy = 9;
            state.next_card_uid = 261;
            state.reward_card_pool = Some(crate::catalog::RewardPool::Regent);
            state.entropy_card_pool = Some(crate::catalog::RewardPool::Regent);
            state.set_spectrum_shift_generation_pool(true);
            state.fully_unlocked_card_pool_epochs = true;
            state.rng.set(
                RngStream::Generation,
                crate::hot::RngStreamState {
                    words: [1, 2, 3, 4],
                    counter: 0,
                },
            );
            state
                .powers
                .set(PowerId::SpectrumShift, SlotWire::Int, i32::MAX);
            assert!(
                state
                    .fanouts
                    .set_before_hand_draw_order(&[PowerId::SpectrumShift])
            );
            let pile = if direct { PileId::Draw } else { PileId::Hand };
            state.piles.get_mut(pile).make_mut().push(source);
            let before = state.clone();
            let mut events = vec![Event::TurnBegan { turn: 88 }];
            let before_events = events.clone();

            let result = if direct {
                play_card_with_work(
                    &mut state,
                    &catalog,
                    source.uid,
                    None,
                    None,
                    &mut events,
                    PlaySource {
                        pile,
                        provenance: PlayProvenance::Auto,
                        force_exhaust: false,
                        frozen: Some(source),

                        allow_dead_target: false,
                    },
                )
            } else {
                play_card(&mut state, &catalog, source.uid, None, None, &mut events)
            };
            assert_eq!(
                result,
                Err(EngineRefusal::CounterOverflow("spectrum_shift"))
            );
            assert_eq!(state, before);
            assert_eq!(events, before_events);
        }
    }

    #[test]
    fn tender_completed_local_card_increments_before_signed_stats() {
        let (mut state, catalog, source) =
            tender_card_fixture(identity(CardId::DefendIronclad, 0), 2);
        let mut events = Vec::new();
        play_card(&mut state, &catalog, source.uid, None, None, &mut events).unwrap();

        assert_eq!(state.fanouts.tender_cards_played(), 3);
        assert!(state.fanouts.tender_is_active());
        assert_eq!(state.powers.value(PowerId::Tender), 1);
        assert_eq!(state.powers.value(PowerId::Strength), -1);
        assert_eq!(state.powers.value(PowerId::Dexterity), -1);
        let strength = events.iter().position(|event| {
            matches!(
                event,
                Event::PowerChanged {
                    subject: Subject::Player,
                    power: PowerId::Strength,
                    amount: -1,
                }
            )
        });
        let dexterity = events.iter().position(|event| {
            matches!(
                event,
                Event::PowerChanged {
                    subject: Subject::Player,
                    power: PowerId::Dexterity,
                    amount: -1,
                }
            )
        });
        assert!(
            strength
                .zip(dexterity)
                .is_some_and(|(strength, dexterity)| strength < dexterity)
        );
    }

