    #[test]
    fn tender_resumed_body_and_later_synchronous_replay_each_complete_once() {
        let (mut state, catalog, source) = tender_card_fixture(identity(CardId::DaggerThrow, 0), 0);
        state.powers.set(PowerId::OneTwoPunch, SlotWire::Int, 1);
        hydrate_side_end_order(&mut state);
        state.piles.get_mut(PileId::Hand).make_mut().extend([
            HotCard {
                uid: 8,
                atom: source.atom,
                flags: 0,
            },
            HotCard {
                uid: 9,
                atom: source.atom,
                flags: 0,
            },
        ]);
        state.next_card_uid = 10;

        play_card(
            &mut state,
            &catalog,
            source.uid,
            Some(0),
            None,
            &mut Vec::new(),
        )
        .unwrap();
        assert!(state.pending.is_some());
        assert_eq!(state.fanouts.tender_cards_played(), 0);
        let removed = state.piles.get_mut(PileId::Hand).make_mut().pop().unwrap();
        state
            .piles
            .get_mut(PileId::Discard)
            .make_mut()
            .push(removed);

        resume_selection(
            &mut state,
            &catalog,
            crate::engine::SelectionAnswer::OptionIndex(0),
            &mut Vec::new(),
        )
        .unwrap();

        assert!(state.pending.is_none());
        assert_eq!(state.history.card_plays_finished_combat, 2);
        assert_eq!(state.fanouts.tender_cards_played(), 2);
        assert_eq!(state.powers.value(PowerId::Strength), -2);
        assert_eq!(state.powers.value(PowerId::Dexterity), -2);
    }

    #[test]
    fn tender_terminal_callback_keeps_counter_write_and_suppresses_stat_commands() {
        let (mut state, _catalog, _) = tender_card_fixture(identity(CardId::DefendIronclad, 0), 4);
        state.history.over = true;
        let mut latch = CardPlayedPowerLatch {
            tender_latched: true,
            ..CardPlayedPowerLatch::default()
        };
        let mut events = Vec::new();

        apply_active_tender_after_card_played(&mut state, &mut latch, &mut events).unwrap();

        assert_eq!(state.fanouts.tender_cards_played(), 5);
        assert_eq!(state.powers.value(PowerId::Strength), 0);
        assert_eq!(state.powers.value(PowerId::Dexterity), 0);
        assert!(events.is_empty());
        assert!(!latch.tender_latched);
    }

